INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('8906796300054631801', 'tea_longjing', 'xihu-longjing', '西湖龙井', '["龙井茶"]', 'green', '浙江省', '杭州市', '西湖区及西湖风景名胜区', '扁平挺直、色泽糙米，豆香与嫩栗香清晰，入口鲜醇甘爽、收敛适中，是炒青绿茶的代表。', '["鲜叶摊放","青锅杀青","回潮","辉锅做形提香","筛分定级"]', '["豆香","嫩栗香","兰花香"]', '["鲜醇","甘爽","收敛适中"]', '["明前尝鲜","上午办公","午后清饮","餐后解腻"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["透明玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"后续每泡延长10至15秒","infusionCount":{"min":3,"max":4},"methodTip":"沿杯壁缓慢注水，不要直冲芽心；芽头细嫩的明前茶可再降到75至80℃。"}', '密封、避光、防潮、防异味，短期喝不完的建议冷藏。', '新茶密封放一两周再喝香气更协调；绿茶不耐存，当年内喝完为宜。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920875.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"西湖龙井出自浙江省杭州市西湖区，核心产区落在西湖风景名胜区一带。传统上，人们按山头与品质把这一带的龙井分为「狮、龙、云、虎、梅」五个字号，其中「狮」字号指狮峰山周边。它属于炒青绿茶，加工中不经过氧化工序，茶多酚氧化程度接近零，所以汤色与叶底都保持绿色。名字里的「龙井」既是当地泉名，也是这一带茶区的通称。作为受保护的区域公共品牌，只有在规定产区、按规定工艺做出来的茶，才能使用「西湖龙井」这个名称。采制期集中在清明前后到谷雨，春季气温平稳、雨水适中，芽叶的氨基酸积累得好，这也是春茶普遍比夏秋茶鲜爽的原因。产区内的微环境差异也不小，不同山头、不同朝向的茶园，成品的香气会有些出入。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["鲜叶摊放：让一部分水分和青气散掉，为炒制做准备。","青锅杀青：高温快速钝化多酚氧化酶，把绿色和鲜爽锁住。","回潮：让茶叶内部的水分重新分布均匀，便于后续做形。","辉锅做形提香：在锅里反复压、磨、推，压出扁平挺直的形状，豆香也在这步生成。","筛分定级：按外形与匀整度分级。","十大手法：全程手工炒制，搭、拓、甩、扣等手法交替使用，不经过揉捻。"]},{"type":"paragraph","text":"最关键的是青锅与辉锅这两步。青锅负责「定」，用高温把酶钝化掉，鲜叶的绿色与鲜爽风味就此固定下来；辉锅负责「形与香」，在较低温度下反复压磨，茶叶被压成扁平挺直的样子，豆香与嫩栗香也在这一步形成。龙井不揉捻，条索的扁平完全靠手法在锅里压出来，这也是它外形辨识度高的原因。炒制时锅温与手势的变化，直接决定成品是润泽的糙米色还是发暗的黄绿色。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，龙井扁平挺直、光滑匀齐，色泽是带黄调的糙米色，而不是鲜绿。汤色杏绿明亮。香气以豆香、嫩栗香为主，做得好的会透出一点兰花香。滋味鲜醇甘爽，收敛性适中——入口有轻微涩感，但很快化开，回甘明显。冲泡后叶底细嫩成朵，颜色嫩绿。需要注意的是，龙井的「糙米色」是工艺特征，不是陈茶或受潮的表现。成分上，绿茶含茶多酚（干茶约18%至36%，以儿茶素类为主）、L-茶氨酸（约1%至2%）与咖啡因（约2%至4%）。传统经验认为龙井性寒味甘苦，有清热解暑、生津止渴、提神醒脑的说法——这属于传统表述，不宜与现代研究结论混同。有初步研究提示，茶氨酸可能有助于放松而不嗜睡，但相关人体试验样本较小，结论还需更大规模的验证。"},{"type":"tip","tone":"info","title":"识茶提示","text":"干茶偏黄绿而非鲜绿，是炒青与辉锅留下的痕迹。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯与投茶","text":"用热水温一遍玻璃杯或白瓷盖碗，倒掉水后投入3克干茶，茶水比约1:50。"},{"title":"控制水温","text":"水烧开后静置2至3分钟，降到80至85℃再注水；芽头特别细嫩的明前茶可以再降到75至80℃。"},{"title":"注水与出汤","text":"沿杯壁缓慢注水，不要直冲芽心。第一泡20至30秒出汤，之后每泡延长10至15秒。"},{"title":"续泡","text":"一般可冲3到4泡，喝到杯中剩三分之一时就续水，避免久闷。"}]},{"type":"paragraph","text":"配茶点上，绿豆糕、藕粉这类清淡点心最合适，不会盖住茶香；挤几滴新鲜柠檬汁可以提香，但不宜久泡。不建议加牛奶或奶盖，乳蛋白会和儿茶素结合，把鲜爽感压下去，浓糖浆果汁也会抵消它清饮的优势。存放上，绿茶最怕氧化和受潮，要密封、避光、防异味，短期喝不完的放冷藏。刚炒好的新茶常带一点火气和生青气，密封放一两周再喝，香气会更协调；绿茶不耐存，最好当年喝完。夏天可以试试冷泡：按1克茶兑100毫升凉白开或冷藏纯净水的比例，密封冷藏约4小时。绿茶是六大茶类里冷泡时间最短的——氧化程度越低，苦涩物质越容易浸出，时间必须最短，建议8小时内喝完。"},{"type":"tip","tone":"warning","title":"两个常见说法","text":"一是「越新鲜越好」。刚出锅的龙井香气还没稳定，放一两周反而更顺口。二是「好茶要用100℃沸水才泡得开」。对龙井恰好相反，沸水会让苦涩的儿茶素抢先大量溶出，还会烫熟嫩芽，80至85℃才是它合适的水温。另外，不要用茶水送服药物，服药与饮茶建议间隔1至2小时。特殊人群方面，严重失眠、心律失常、胃溃疡活动期以及孕期哺乳期人群都需要限量；孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际还要按茶汤浓度折算。"}]', '["product_longjing_50"]', 1, 100, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1666143067241565070', 'tea_biluochun', 'dongting-biluochun', '洞庭碧螺春', '["碧螺春"]', 'green', '江苏省', '苏州市', '吴中区洞庭东山、洞庭西山', '条索纤细卷曲如螺、满披白毫，花果香轻盈，滋味鲜爽甘醇几乎无苦涩，是绿茶里性子最嫩的一款。', '["拣剔","摊放","高温杀青","揉捻做形","搓团显毫","烘干"]', '["花果香","清香"]', '["鲜爽","甘醇","轻柔"]', '["春茶尝鲜","上午提神","午后清口","待客"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":75,"max":80},"vessel":["透明玻璃杯"],"firstSteepSeconds":{"min":15,"max":25},"laterSteepTip":"后续每泡适当延长约10秒","infusionCount":{"min":3,"max":3},"methodTip":"采用上投法，先注水后投茶，白毫不易脱落。"}', '密封、低温、避光、防潮，并远离气味浓烈的食材。', '花果香最易散失，开封后宜尽快喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；极嫩茶更忌沸水与久闷；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164918988.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"洞庭碧螺春产自江苏省苏州市吴中区的洞庭东山与洞庭西山，两座山伸进太湖里，茶园长年与水汽和果树为邻。它属于炒青绿茶，采摘极嫩，标准通常是一芽一叶初展。名字里的「碧」指色泽翠绿，「螺」指条索卷曲如螺，「春」指采制季节。当地还流传着一个更朴素的旧称——「吓煞人香」，说的就是它香气浓烈得让人意外。春分到谷雨是它最好的采制期，此时新茶的鲜爽度正处在峰值。洞庭山的茶园多为茶果间作，茶树与枇杷、杨梅、柑橘一类果树长在同一片山坡上，采茶季往往也是花果季；这种种植方式并不能直接改变茶叶的成分，但当地普遍认为它与碧螺春偏花果香的风格有关。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["拣剔：剔除不符合标准的芽叶，保证原料匀整。","摊放：散失部分水分与青气。","高温杀青：钝化多酚氧化酶，固定绿色与鲜爽。","揉捻做形：在锅中边炒边揉，让条索卷曲如螺。","搓团显毫：把茶叶拢成团轻搓再抖散，让白毫显露出来。","烘干：定型并锁定花果香。"]},{"type":"paragraph","text":"碧螺春的看家本领是「搓团显毫」。炒制时讲究「手不离茶、茶不离锅、揉中带炒、炒中带揉」，师傅一边用锅温继续杀青，一边把茶叶拢成团轻轻搓揉，再抖散、再搓团，反复多次。白毫就是在这个过程里被完整保留下来的，条索也顺势卷成螺旋状。因为原料极嫩，锅温与手势都要拿捏得很准，稍重一点就会把芽叶压碎或者炒焦，花果香也就跟着散了。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索纤细卷曲像螺，满身披着白色茸毛，颜色是银绿隐翠。汤色浅绿明亮。香气以花果香为主，这与洞庭山茶果间作的种植方式有关——茶树和枇杷、杨梅、柑橘等果树长在一起，香气里常带一点清甜。滋味鲜爽甘醇，几乎不带苦涩，因为一芽一叶初展的原料氨基酸含量高、酚氨比低，刺激性相对更小。叶底嫩匀明亮，芽叶完整舒展。成分上，它的茶多酚、茶氨酸与咖啡因水平与其他绿茶一致，但因为采摘极嫩，氨基酸含量高、酚氨比低，鲜爽度更高、刺激性相对更小。传统经验认为碧螺春性寒味甘，有清热降火、生津止渴、提神的说法，这属于传统表述，不能改用现代研究结论的语气来写。"},{"type":"tip","tone":"info","title":"识茶提示","text":"白毫是否完整，是判断碧螺春原料嫩度与炒制手法的一个直观线索。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯备水","text":"先用热水把玻璃杯温一遍，水烧开后静置到75至80℃，这是碧螺春最合适的水温，也是绿茶里要求最低的一档。"},{"title":"上投法投茶","text":"先往杯中注水至七分满，再投入3克干茶。茶叶会缓缓下沉舒展，白毫不易脱落。"},{"title":"出汤节奏","text":"第一泡15至25秒即可品饮，之后每泡适当延长约10秒，一般冲到第3泡滋味就明显减弱。"}]},{"type":"paragraph","text":"碧螺春适合用透明玻璃杯冲泡，看芽叶在水中一根根舒展开来，本身就是它的一半乐趣。配茶点可以选松子糖、枣泥糕这类苏式清甜点心，甜度不过分，不夺茶香。不建议加牛奶，也不建议与浓香型的香精果茶同饮。存放上要密封、低温、避光、防潮，并远离气味浓烈的食材——茶叶极易吸附异味；开封后尽量尽快喝完，因为花果香是最先跑掉的那部分。夏天也可以冷泡：1克茶兑100毫升水，密封冷藏约4小时，低温下苦涩感明显降低、花果香反而更清楚，8小时内喝完为宜。冷泡时咖啡因浸出较少，对睡眠的影响相对更小，但茶汤里仍然含咖啡因。"},{"type":"tip","tone":"warning","title":"比多数绿茶更怕高温","text":"碧螺春的水温要求是绿茶里最低的，75至80℃即可，用沸水会直接烫熟嫩芽、加重苦涩，久闷同样如此。另外不要长时间泡着柠檬片，酸性环境久泡会让叶绿素脱镁变褐，观感和风味都会下降，少量柠檬现调则不受影响。还有一点常被忽略：水温越高、浸泡越久，苦涩越明显。它的原料本身就是一芽一叶初展，宁可水温低一点、出汤快一点，也不要为了「泡开」而延长时间。含咖啡因，睡眠敏感的人下午之后宜少饮；孕期哺乳期、严重失眠与胃溃疡活动期人群也建议限量。"}]', '["product_biluochun_50"]', 0, 110, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('6404999874162051223', 'tea_huangshan_maofeng', 'huangshan-maofeng', '黄山毛峰', '["毛峰"]', 'green', '安徽省', '黄山市', '黄山风景区及周边汤口、充川、岗村一带', '形似雀舌、白毫披身、色如象牙，兰花香与清鲜栗香并存，滋味鲜浓醇和且回甘持久，是烘青绿茶的代表。', '["杀青","揉捻","毛火","足火"]', '["兰花香","清鲜栗香"]', '["鲜浓","醇和","回甘持久"]', '["上午工作学习","午后清口解腻","春游户外后温饮"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"后续每泡延长10至15秒","infusionCount":{"min":3,"max":4},"methodTip":"水烧开后静置2至3分钟再注水，沿杯壁缓注，便于观赏白毫与芽叶舒展。"}', '密封、避光、防潮、防异味，短期喝不完的建议冷藏。', '绿茶氧化快，开封后当年内喝完为宜。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164919677.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"黄山毛峰产自安徽省黄山市，主产区在黄山风景区及周边的汤口、充川、岗村一带。它属于烘青绿茶，也就是干燥环节靠烘焙而不是靠炒锅做形，所以外形不像龙井那样被压扁。名字里的「毛」指白毫，「峰」既指黄山山峰，也暗合它形似雀舌、微微卷曲的芽叶。清明到谷雨是它的主要采制期，这一季的芽叶最嫩，白毫也最完整。黄山一带山高谷深，云雾多、漫射光足，茶树的氮代谢旺盛、氨基酸积累较好；加上昼夜温差大，芽叶生长节奏慢，内含物积累得更充分。这些条件共同构成了毛峰清鲜花香的底子。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定绿色与鲜爽。","揉捻：轻轻揉出茶汁，让条索成形。","毛火：第一次烘焙，散去大部分水分。","足火：低温慢烘，把水分降到安全线并把香气定下来。"]},{"type":"paragraph","text":"烘青工艺里，杀青之后的两次烘焙是决定风味的关键。毛火温度较高，目的是快速失水；足火温度较低、时间较长，一方面把含水量降到安全水平，另一方面让香气物质在缓慢受热中形成并固定下来。有研究提示，这套做法对芳樟醇及其氧化物等香气成分的保留比较有利，氨基酸的损失也相对少。所以黄山毛峰的香气走的是清鲜花香的路子，而不是炒青茶那种豆香、栗香。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，芽叶微卷，形似雀舌，白毫披身，色泽是带象牙感的黄绿，而不是翠绿。汤色清碧微黄。香气以兰花香和清鲜的栗香为主，闻起来清透不闷。滋味鲜浓醇和，回甘持久，刺激性不强，适合慢慢喝。叶底嫩黄明亮，芽叶成朵。因为不经炒锅压扁，它的条索比龙井松散一些，这是工艺决定的，不是品质问题。成分上，黄山毛峰具备绿茶的共性成分：茶多酚（干茶约18%至36%）、L-茶氨酸（约1%至2%）与咖啡因（约2%至4%）。传统经验认为它性寒味甘，有清热、生津、提神、消食的说法，属传统表述。由于烘青工艺的氨基酸损失相对少，这也是它滋味偏醇和、刺激性不强的一个原因。"},{"type":"tip","tone":"info","title":"识茶提示","text":"烘青茶不经炒锅做形，条索自然微卷，白毫完整是它的看点。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"玻璃杯或白瓷盖碗先用热水温过，投入3克干茶，茶水比约1:50。"},{"title":"注水","text":"水烧开后静置2至3分钟，待水温降到80至85℃，沿杯壁缓缓注入。"},{"title":"出汤","text":"第一泡20至30秒出汤，之后每泡延长10至15秒，可冲3到4泡。"}]},{"type":"paragraph","text":"黄山毛峰用玻璃杯冲泡最能欣赏它的芽叶形态，白毫在水里根根分明。配茶点可以选黄山烧饼、徽墨酥这类徽州点心，或者一小把淡味坚果；不建议搭配重糖重油的甜点和牛奶，奶香与糖会盖掉它清透的花香。存放上要密封、避光、防潮、防异味，短期喝不完的建议冷藏。绿茶氧化很快，开封后最好在当年内喝完。如果偏爱清凉口感，可以冷泡：1克茶兑100毫升水，冷藏约4小时，鲜甜与清香会更突出，建议8小时内喝完。传统上绿茶多在春夏饮用，温饮淡茶比冰镇浓茶更合适。"},{"type":"tip","tone":"warning","title":"别按龙井的标准看它","text":"有人觉得绿茶要喝刚出锅的，其实新炒制的绿茶常带火气和生青气，密封放一两周，香气和滋味会更协调。另外，黄山毛峰是烘青茶，条索没有被压扁，不要用龙井的扁平外形去衡量它。含咖啡因，空腹浓饮容易引起胃部不适，睡前4至6小时也不宜再喝。还有一点要留意：缺铁性贫血人群不宜在餐中或餐后立刻喝浓茶，茶多酚会与食物中的非血红素铁结合、影响铁吸收，建议餐间间隔1小时以上再饮；孕期与哺乳期人群也建议减量。"}]', '["product_huangshan_maofeng_50"]', 0, 120, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2426254520602417580', 'tea_taiping_houkui', 'taiping-houkui', '太平猴魁', '["猴魁","尖茶"]', 'green', '安徽省', '黄山市', '黄山区新明乡猴坑、猴岗、颜家一带', '两叶抱一芽、扁平挺直，兰花香高长持久，滋味鲜爽醇厚而极耐泡，外形在绿茶中独树一帜。', '["拣尖","杀青","捏尖整形","头烘","二烘","三烘三晾"]', '["兰花香"]', '["鲜爽醇厚","猴韵","耐泡"]', '["待客","长时间办公","餐后解腻"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":85,"max":90},"vessel":["高身透明玻璃杯"],"firstSteepSeconds":{"min":30,"max":40},"laterSteepTip":"后续每泡逐次延长，耐泡度好","infusionCount":{"min":4,"max":5},"methodTip":"根朝下、叶朝上直立投放，沿杯壁注水，避免把茶条冲倒。"}', '密封、避光、防潮、防异味，冷藏保存更好。', '内含物丰富、相对耐存，但开封后仍建议当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；茶多酚总量相对偏高，胃敏感者宜淡饮；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920874.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"太平猴魁产自安徽省黄山市黄山区，也就是原来的太平县，核心产区在新明乡的猴坑、猴岗、颜家一带。它属于烘青绿茶里的尖茶类，采摘标准很特别——不是单芽，而是两叶抱一芽，叶片成熟度比多数名优绿茶高。名字里的「猴」来自猴坑的地名，「魁」有魁首、第一的意思。谷雨前后是它的采制期，比大多数绿茶都晚，也正因为采得晚，叶片长得更充分。猴坑一带海拔较高、林密雾重，茶园多藏在山谷与林间，漫射光充足，芽叶的内含物积累得好，这也是它耐泡度高的原因之一。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["拣尖：把采下的一芽二叶拣成匀整的标准，去杂去劣。","杀青：高温钝化酶活性，固定绿色。","捏尖整形：趁热把芽叶一根根理直捏平，这是形成独特外形的关键。","头烘：第一次烘焙失水。","二烘、三烘：烘焙与摊晾交替，让水分和香气逐层稳定。","全程不揉捻：两叶抱一芽的完整形态因此得以保留。"]},{"type":"paragraph","text":"猴魁有两道工序最要紧。第一道是「捏尖」，师傅要在杀青后趁热把芽叶一根根理直、捏平，让两叶紧抱一芽，最终做成扁平挺直、两端略尖的形状。第二道是烘焙，讲究「三烘三晾」——头烘、二烘、三烘之间都要摊晾回软，让水分从叶内慢慢走到叶表再被烘干。这套节奏比一次烘透更慢，但成品的兰花香更持久，也更耐存放。因为全程不揉捻，条索始终保持完整。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，猴魁扁平挺直，两叶抱一芽，当地用「猴魁两头尖，不散不翘不卷边」来形容它，色泽苍绿。汤色清绿明亮。香气以兰花香为主，高长持久，这是它最出名的特点。滋味鲜爽醇厚，老茶客常说的「猴韵」，指的正是那种厚实、回甘绵长的尾韵。因为叶片成熟度较高、内含物丰富，它的耐泡度在绿茶里相当突出。叶底肥厚成朵，颜色嫩绿。成分上，它的茶多酚、茶氨酸与咖啡因与绿茶共性一致，但茶多酚总量相对偏高，滋味浓强度因此在绿茶里很突出。传统经验认为猴魁性寒味甘，有清热、生津、提神、化痰的说法，这属于传统表述，不宜写成现代科学结论。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看两头是否尖、叶缘是否平展，是辨认猴魁外形的直观方法。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"选器","text":"用高身的透明直杯，杯身够高，长条状的茶叶才能立起来。"},{"title":"投茶","text":"投入3至5克干茶，注意根朝下、叶朝上，让茶条直立着放进杯中。"},{"title":"注水","text":"水温85至90℃，沿杯壁注水，避免把茶条冲倒。"},{"title":"出汤","text":"第一泡30至40秒，之后逐泡延长，可以冲到4至5泡。"}]},{"type":"paragraph","text":"猴魁的外形极有辨识度，待客时很拿得出手，冲泡时一根根立在水里，被形容为「刀枪云集」。配淡味茶点即可，不建议搭配牛奶和浓香调味品，会压掉它细致的兰花香。存放要求与一般绿茶一致：密封、避光、防潮、防异味，冷藏更好，开封后尽量当年喝完。因为它耐泡且内含物丰富，一次投茶量可以比普通绿茶略少一些。想换口味可以冷泡：1克茶兑100毫升水，冷藏约4小时。因为它的叶片成熟度高、内含物丰富，冷泡出来的滋味依然有厚度，不像嫩芽茶那样容易寡淡，8小时内喝完为宜。"},{"type":"tip","tone":"warning","title":"浓强度偏高，宜淡饮","text":"猴魁的茶多酚总量在绿茶里相对偏高，滋味浓强度也大，胃比较敏感的人建议减少投茶量、喝淡一些，更不要空腹浓饮。另外，「猴魁」是产地与工艺共同定义的名称，市面上外形相似但产区不同的尖茶，风味差别可能不小。空腹时也不宜喝浓茶，容易刺激胃黏膜；服药前后1小时不宜饮茶，建议用温白开水送服。含咖啡因，睡前4至6小时不宜饮用；严重失眠、心律失常与孕期哺乳期人群建议限量。"}]', '["product_taiping_houkui_50"]', 0, 130, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('540863087991848985', 'tea_luan_guapian', 'luan-guapian', '六安瓜片', '["瓜片"]', 'green', '安徽省', '六安市', '裕安区、金寨县、霍山县，齐头山与鲜花岭为核心', '唯一无芽无梗的单片叶绿茶，瓜子形、宝绿上霜，高火香与栗炭香突出，滋味浓醇鲜爽、回甘强而耐泡。', '["采摘扳片","炒生锅","炒熟锅","毛火","小火","拉老火"]', '["高火香","栗炭香"]', '["浓醇","鲜爽","回甘强"]', '["夏季消暑","餐后解腻","长时间办公","熬夜后次日上午温饮"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":85,"max":90},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":30,"max":30},"laterSteepTip":"后续每泡逐次延长，可冲4至5泡","infusionCount":{"min":4,"max":5},"methodTip":"不要长时间高温闷泡，闷久了苦涩会明显上升。"}', '密封、避光、防潮、防异味，远离气味浓烈食材。', '拉老火后含水量很低，相对耐存，但仍建议当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用，且不能替代睡眠；火香型滋味浓，胃敏感者宜减量；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164919679.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"六安瓜片产自安徽省六安市，核心产区在裕安区、金寨县和霍山县一带，其中齐头山、鲜花岭最为有名。它是中国绿茶里唯一无芽无梗的片茶——采摘时只取单片叶，把芽和梗都去掉。名字里的「瓜片」来自外形：叶片像瓜子，边缘向背面卷曲。它属于烘青绿茶，但工艺里有一道极为特别的高温工序，让它的香气完全走出另一条路。六安一带山高林密、云雾较多，齐头山与鲜花岭的茶园多分布在坡地与林间。它谷雨前后采制，只取成熟度较高的单片叶，这与多数名优绿茶抢早、抢嫩的做法正好相反，也决定了它滋味更厚、更耐泡。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["采摘与扳片：只取单片叶，去芽去梗，再把叶片与嫩茎分开。","炒生锅：高温杀青，钝化酶活性。","炒熟锅：继续炒制并初步做形，让叶缘向背面卷曲。","毛火：第一次烘焙去水。","小火：中温慢烘，让水分继续均匀散出。","拉老火：约160至180℃的极高温短烘，是形成独特火香的关键。"]},{"type":"paragraph","text":"「拉老火」是六安瓜片最与众不同的一步。烘焙时温度高达约160至180℃，烘笼在炭火上快速来回抬放，茶叶在极短时间内受到高温冲击，部分成分发生美拉德反应，于是形成了那种独特的焦香与栗炭香，当地也叫高火香。这一步既提香，又把含水量压得很低，所以瓜片特别耐存、耐泡。另一处特别在于无芽无梗：只取成熟叶片，可溶性糖与茶多酚的含量相对较高，滋味因此更浓醇。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，叶片呈瓜子形，叶缘向背面卷曲，色泽宝绿，表面带着一层白霜。汤色黄绿清亮。香气是高火香与栗炭香的组合，和常见绿茶的清香路数完全不同，闻起来有热力感。滋味浓醇鲜爽，回甘强，耐泡度好，冲到第四五泡仍然有味道。叶底黄绿明亮，叶片完整。第一次喝的人常会觉得它不像印象里的绿茶，这正是拉老火留下的印记。成分上，因为它无芽无梗、叶片成熟，茶多酚与可溶性糖的含量相对较高，浓醇感与回甘都由此而来。传统经验认为瓜片性寒味甘，有清热解暑、生津止渴、清心明目的说法，这属于传统表述，不能当作现代研究结论。"},{"type":"tip","tone":"info","title":"识茶提示","text":"没有芽头、没有茶梗，是辨认六安瓜片最直接的一眼。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温器投茶","text":"白瓷盖碗或瓷壶用热水温过，投入3克干茶。"},{"title":"注水","text":"水温85至90℃，沿碗壁注水，让叶片充分浸润。"},{"title":"出汤","text":"第一泡约30秒出汤，之后每泡延长，可冲4至5泡。"},{"title":"避免闷泡","text":"不要长时间高温闷泡，闷久了苦涩会明显上升。"}]},{"type":"paragraph","text":"瓜片的火香和浓醇感不挑器皿，白瓷盖碗、瓷壶甚至紫砂壶都能用。配茶点适合徽式咸香点心或淡味坚果，不建议搭配牛奶和甜腻点心，容易显得腻口。因为经过高温老火，它的含水量很低，相对其他绿茶更耐存放，但仍要密封、避光、防潮、防异味。传统上六安瓜片被当作夏天的消暑茶，也常被留到秋天再喝，风味依然稳定。夏天冷泡也很合适：1克茶兑100毫升水，冷藏约4小时。它本身滋味浓，冷泡之后收敛感会柔化不少，清爽度反而更明显，建议8小时内喝完。"},{"type":"tip","tone":"warning","title":"浓茶配酒不可取","text":"瓜片属于火香型、滋味浓，胃比较敏感的人建议减量、喝淡一些。熬夜后第二天上午喝一杯温热的瓜片可以提神，但它不能替代睡眠。民间有用浓茶配酒后的做法，这个做法并不成立——咖啡因与酒精叠加反而会加重心脏与肾脏的负担，不建议这样做。另外提醒，孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际需按茶汤浓度折算；严重失眠、心律失常与胃溃疡活动期人群都应限量饮用。"}]', '["product_luan_guapian_50"]', 0, 140, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1141951895934751295', 'tea_xinyang_maojian', 'xinyang-maojian', '信阳毛尖', '["豫毛峰"]', 'green', '河南省', '信阳市', '浉河区、平桥区、罗山县、光山县等，五云两潭一寨为核心山头', '细圆光直多白毫，熟栗香清晰，滋味浓醇鲜爽、回甘明显，是北方茶区炒青针形绿茶的代表。', '["摊放","生锅杀青","熟锅理条抓条","初烘","摊凉","复烘","拣剔"]', '["熟栗香","清香"]', '["浓醇","鲜爽","回甘明显"]', '["上午提神","午后抗困倦","餐后解腻","出差办公常备"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"后续每泡延长10至15秒","infusionCount":{"min":3,"max":4},"methodTip":"先注少量水润茶，再沿杯壁注满，避免沸水直冲使毫香尽失。"}', '密封、避光、防潮、防异味，冷藏可延长保鲜期。', '白毫与栗香易散失，开封后建议当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920307.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"信阳毛尖产自河南省信阳市，主产区包括浉河区、平桥区、罗山县、光山县等地，传统上以「五云两潭一寨」几处山头最为有名。它属于炒青绿茶里的针形茶，条索细、圆、光、直。名字里的「毛」指白毫，「尖」指细嫩的芽尖。信阳地处偏北的茶区，茶树生长期长，芽叶积累的内含物更多，谷雨前采制的品质通常最好，鲜爽度与回甘都更突出。信阳纬度偏北，茶树休眠期长、开采晚，芽叶在枝头停留的时间久，氨基酸积累得更充分，这正是它鲜爽与回甘表现突出的底子；谷雨前采制的那一批，芽叶细嫩、白毫完整，通常被认为是品质最好的。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["摊放：散失部分水分，让内含物开始转化。","生锅：高温杀青，钝化酶活性。","熟锅：理条抓条做形，把条索搓成细圆挺直。","初烘：第一次烘焙去水。","摊凉：让水分重新分布均匀。","复烘：低温烘干定香。","拣剔：剔除黄片与茶梗，保证匀整。"]},{"type":"paragraph","text":"毛尖的形状是在熟锅里「抓」出来的。杀青之后，师傅在锅中反复理条、抓条，用手掌把茶叶搓成细圆挺直的一根根针形，这一步叫理条抓条。手势轻重要均匀：重了条索会断，轻了条索松泡、白毫也立不住。之后还要经过初烘、摊凉、复烘，让水分缓慢走掉，白毫才能完整保留，熟栗香也在这两次烘焙中固定下来。整个过程里，火候与手势的配合比原料本身更考验功夫。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索细、圆、光、直，白毫明显，色泽翠绿。汤色嫩绿明亮。香气以熟栗香和清香为主，闻起来干净利落。滋味浓醇鲜爽，回甘明显——信阳茶区纬度偏北、生长期长，氨基酸积累较多，鲜爽和回甘的表现因此比较突出。叶底嫩绿匀整，芽叶成朵。它的白毫很显眼，冲泡时汤面浮一层细毫属于正常现象。成分上，它具备绿茶共性的茶多酚（干茶约18%至36%）、L-茶氨酸（约1%至2%）与咖啡因（约2%至4%），产区偏北、生长期长让氨基酸占比更高。传统经验认为毛尖性寒味甘，有清热、生津、提神、消食、明目的说法，属传统表述，不宜与现代研究结论混写。"},{"type":"tip","tone":"info","title":"识茶提示","text":"白毫是嫩度的标志，不是灰尘，浮在汤面属正常。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"玻璃杯或白瓷盖碗温过，投入3克干茶，茶水比约1:50。"},{"title":"注水","text":"水烧开后静置到80至85℃，先注少量水润茶，再沿杯壁注满。"},{"title":"出汤","text":"第一泡20至30秒出汤，之后每泡延长10至15秒，可冲3到4泡。"}]},{"type":"paragraph","text":"信阳毛尖适合配中原面点或淡味茶点，日常用玻璃杯随手泡也很方便，出差办公常备一罐，续水两三次都还有味道。不建议加牛奶，也不要用沸水直冲——沸水会让毫香尽失、苦涩上扬；重口味的卤味也会夺走它的清香。存放上要密封、避光、防潮、防异味，冷藏可以延长保鲜期，开封后仍建议当年喝完。习惯喝凉的可以冷泡：1克茶兑100毫升水，冷藏约4小时，苦涩感降低、栗香更清楚，8小时内喝完。日常用玻璃杯随手泡时，喝到剩三分之一就续水，滋味会更稳定。"},{"type":"tip","tone":"warning","title":"细毫不是灰尘","text":"毛尖的白色茸毛是原料细嫩的表现，冲泡时浮在汤面或沉在杯底都属于正常，不必担心。另外，绿茶含咖啡因，空腹浓饮容易刺激胃黏膜；服药前后1小时也不宜饮茶，建议用温白开水送服药物。严重失眠的人下午之后就不建议再喝；孕期与哺乳期人群需要限量，孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际还要按茶汤浓度折算。"}]', '["product_xinyang_maojian_50"]', 0, 150, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('477226015314239603', 'tea_duyun_maojian', 'duyun-maojian', '都匀毛尖', '["白毛尖","细毛尖"]', 'green', '贵州省', '黔南布依族苗族自治州都匀市', '团山、哨脚、大槽一带', '条索紧结卷曲、满披白毫，嫩香带栗香与花香，滋味鲜浓、回甘持久，是典型的高海拔云雾产区风格。', '["杀青","揉捻搓团提毫","做形","干燥"]', '["嫩香","栗香","花香"]', '["鲜浓","回甘持久"]', '["上午提神","午后清口","待客","春茶尝鲜"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"后续每泡延长10至15秒","infusionCount":{"min":3,"max":4},"methodTip":"沿杯壁缓缓注水，避免直冲茸毛。"}', '密封、避光、防潮、防异味，冷藏保存更好。', '绿茶不耐存，开封后尽量当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；饮酒后不建议立刻喝浓绿茶；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831383.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"都匀毛尖产自贵州省黔南布依族苗族自治州都匀市，核心产区在团山、哨脚、大槽一带。它属于炒青绿茶，条索紧结卷曲、满披白毫，兼有针形与卷曲形的特点。贵州茶区海拔高、云雾多、日照柔和，茶树在这样的环境里长得慢，芽叶的氨基酸积累较多、酚氨比低，滋味因此偏鲜爽。明前到谷雨是它的主要采制期，其中明前茶的嫩香最清晰。都匀一带海拔较高、云雾多、日照柔和，茶树在这样的环境里生长节奏慢，芽叶的氨基酸积累得好、酚氨比低，所以滋味偏鲜爽、苦涩感弱。当地茶园多分布在坡地与山谷之间，不同地块的成品香气会有些出入。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定绿色与鲜爽。","揉捻：以搓团为主，边搓边抖，让条索卷曲并保住白毫。","做形：进一步整形，让条索紧结匀整。","干燥：定香并把含水量降到安全线。"]},{"type":"paragraph","text":"当地传统工艺讲究「火中取宝、一锅到底」，意思是杀青、揉捻、做形尽量在同一口锅里连贯完成，中间不停顿、不换锅。揉捻时手法以搓团为主，一边搓成团一边抖散，白毫被完整保留下来，条索也顺势卷曲。因为锅温一直在变化，师傅要随时调整手势，这套连贯操作很考验经验，也是都匀毛尖外形紧结、茸毛显露的原因。因为全程在一口锅里完成，锅温的每一次调整都会直接影响成品，手法熟练的师傅能让条索更紧、白毫更完整。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索紧结卷曲，满披白毫，颜色绿中带翠。汤色清澈明亮。香气以嫩香、栗香为主，有时透出一点花香。滋味鲜浓，回甘持久——高海拔、多云雾的产区让氨基酸含量偏高，鲜爽度好，苦涩感不强。叶底嫩绿明亮，芽叶完整。整体风格清新鲜活，适合作为日常口粮绿茶。成分上，它具备绿茶共性的茶多酚、L-茶氨酸与咖啡因，高海拔云雾产区的氨基酸含量相对更高。传统经验认为都匀毛尖性寒味甘，有清热、生津、提神、明目的说法，属于传统表述，不能写成现代科学结论。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"玻璃杯或白瓷盖碗温过，投入3克干茶。"},{"title":"注水","text":"水温80至85℃，沿杯壁缓缓注入，避免直冲茸毛。"},{"title":"出汤","text":"第一泡20至30秒出汤，之后每泡延长10至15秒，可冲3到4泡。"}]},{"type":"paragraph","text":"都匀毛尖适合餐后饮用。贵州本地口味偏酸辣，吃完酸汤类菜肴之后来一杯清口的毛尖很舒服。配淡味茶点即可，不建议与重辣重油的菜同时入口——刺激叠加之外，麻辣也容易掩盖茶香。器皿用玻璃杯最能看茸毛与芽叶舒展。存放要密封、避光、防潮、防异味，冷藏更好，开封后尽量当年喝完。夏天冷泡也合适：1克茶兑100毫升水，冷藏约4小时，鲜甜感更突出，建议8小时内喝完。冷泡时咖啡因浸出较少，对睡眠的影响相对更小，但茶汤里仍含咖啡因。"},{"type":"tip","tone":"warning","title":"酒后别急着喝浓茶","text":"毛尖类茶叶上的白毫是嫩度的标志，冲泡时浮在汤面属于正常。另外要提醒，饮酒之后不建议立刻喝浓绿茶——咖啡因与酒精叠加会加重心脏与肾脏的负担，浓茶并不能抵消酒精带来的影响。另外，严重失眠、心律失常、胃溃疡活动期以及孕期哺乳期人群都建议限量；孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际需按茶汤浓度折算。含咖啡因，睡前4至6小时不宜饮用，空腹时也不宜喝浓茶。"}]', '[]', 0, 160, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2591583283907543658', 'tea_lushan_yunwu', 'lushan-yunwu', '庐山云雾', '["云雾茶"]', 'green', '江西省', '九江市', '庐山风景区五老峰、汉阳峰、含鄱口一带', '条索粗壮、青翠多毫，豆花香清透不冲，滋味醇厚鲜爽、回甘带甜，是高山云雾茶区的炒青绿茶。', '["杀青","抖散","揉捻","炒二青","搓条","提毫","烘干"]', '["豆花香","清香"]', '["醇厚","鲜爽","回甘带甜"]', '["上午或午后","夏季消暑","待客","品高山茶风味"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":85,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":25,"max":35},"laterSteepTip":"后续每泡适当延长","infusionCount":{"min":3,"max":4},"methodTip":"水烧开后静置到85℃左右再注水，避免沸水久闷。"}', '密封、避光、防潮、防异味，冷藏保存更好。', '条索较粗壮略耐存，开封后仍建议当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831905.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"庐山云雾产自江西省九江市庐山风景区，核心产区在五老峰、汉阳峰、含鄱口一带。它属于炒青绿茶，条索粗壮、青翠多毫。庐山山高雾重，茶园常年处在漫射光下——漫射光多，茶树合成氨基酸和芳香物质的条件就好，酚氨比低，所以它的滋味偏醇厚鲜爽。谷雨前后是它的主要采制期，这一季的芽叶肥壮，白毫也足。庐山海拔高、云雾重，茶园多分布在坡地与林间，日照以漫射光为主；漫射光多、昼夜温差大，茶树的氮代谢旺盛，氨基酸与芳香物质积累得好，酚氨比低，所以滋味偏醇厚、苦涩感弱。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定绿色。","抖散：及时抖散降温，防止叶片被余温焖黄。","揉捻：轻揉成形，避免条索破碎。","炒二青：继续炒制并进一步失水。","搓条：把条索搓紧搓直。","提毫：让白毫显露并附着在条索表面。","烘干：定香并降低含水量。"]},{"type":"paragraph","text":"庐山云雾的传统做法是六道工序、全手工完成。其中「提毫」这一步比较关键：在茶叶将干未干时用手轻搓，把茸毛提起来，让它附着在条索表面而不是脱落。另外「抖散」看着简单，作用却不小——杀青后如果不及时抖散散热，叶片会被余温焖到发黄，清汤绿叶的特点就保不住了。这道工序考验的是手上的节奏感，快慢都要看叶子的状态来调整。六道工序全手工完成，产量不高，但每一步都能按叶子的状态随时调整，这是机器很难替代的部分。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索粗壮，颜色青翠，白毫明显。汤色清亮。香气以豆花香和清香为主，是高山茶常见的清透路数，闻起来不冲。滋味醇厚鲜爽，回甘里带一点甜。因为生长在漫射光充足的环境里，它的酚氨比低，苦涩感弱、口感顺，即使稍多泡一会儿也不容易发苦。叶底嫩绿明亮。成分上，它具备绿茶共性的茶多酚、L-茶氨酸与咖啡因；高山云雾环境让氨基酸占比更高、酚氨比更低。传统经验认为庐山云雾性寒味甘，有清热、生津、提神、化痰、明目的说法，这属于传统表述，不宜与现代研究结论混同。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"玻璃杯或白瓷盖碗温过，投入3克干茶。"},{"title":"注水","text":"水温85℃左右，沿杯壁缓缓注入，避免直冲芽心。"},{"title":"出汤","text":"第一泡25至35秒出汤，之后每泡适当延长，可冲3到4泡。"}]},{"type":"paragraph","text":"庐山云雾适合搭配江西米粉这类咸鲜口味的餐食，餐后一杯很清口；配淡味茶点、用玻璃杯冲泡也都合适。不建议加牛奶或重香精饮品，也不要用沸水久闷。存放上，绿茶的通则是密封、避光、防潮、防异味，最好冷藏保存。它的条索较粗壮，比细嫩的芽茶稍耐存一点，但开封后仍建议当年喝完。想喝凉的可以冷泡：1克茶兑100毫升水，冷藏约4小时，鲜甜与清香会更突出，建议8小时内喝完。传统上绿茶适合春夏饮用，温饮淡茶比冰镇浓茶更稳妥。"},{"type":"tip","tone":"warning","title":"高山茶的两个提醒","text":"「高山云雾出好茶」有它的道理：高山漫射光多、昼夜温差大，氨基酸与芳香物质积累较好。但这不是说海拔越高越好，产区、品种与工艺同样重要。另外，空腹浓饮容易引起胃部不适，睡前4至6小时也不宜饮茶；严重失眠的人下午之后应停饮，孕期哺乳期、胃溃疡活动期与心律失常人群都需要限量。缺铁性贫血人群不宜在餐中或餐后立即喝浓茶，建议餐间间隔1小时以上再饮。"}]', '[]', 0, 170, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('613158839178518598', 'tea_enshi_yulu', 'enshi-yulu', '恩施玉露', '["玉露茶"]', 'green', '湖北省', '恩施土家族苗族自治州恩施市', '芭蕉侗族乡为核心产区', '中国现存少数的蒸青绿茶代表，条索紧圆光滑、色泽翠绿油润，三绿一爽，海苔香清新甘醇。', '["蒸汽杀青","扇凉","铲头毛火","揉捻","铲二毛火","整形上光","拣选焙火"]', '["海苔香","清香"]', '["鲜爽","甘醇"]', '["上午提神","午后清口","夏季消暑","偏好海苔香者尝鲜"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":75,"max":80},"vessel":["透明玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":20},"laterSteepTip":"后续每泡适当延长","infusionCount":{"min":3,"max":3},"methodTip":"蒸青茶比炒青茶更怕高温，水温压到75至80℃再注水。"}', '密封、避光、防潮、防异味，冷藏保存更好。', '叶绿素保留多，但同样不耐存，开封后尽快喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；缺铁性贫血人群不宜餐中或餐后立即饮浓茶；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831384.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"恩施玉露产自湖北省恩施土家族苗族自治州恩施市，核心产区在芭蕉侗族乡一带。它属于蒸青绿茶，是中国现存少数保留蒸青工艺的绿茶代表。所谓蒸青，就是用蒸汽而不是锅炒来杀青，这是它和绝大多数中国绿茶最根本的区别。恩施茶区的土壤富硒，明前到谷雨是主要采制期，这一季的芽叶最匀整，色泽也最翠。恩施地处武陵山区，云雾多、湿度大，茶树生长节奏平稳、芽叶持嫩性好；蒸青工艺加上这样的原料条件，才有了它标志性的「三绿」。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["蒸汽杀青：用蒸汽快速钝化酶活性，代替锅炒。","扇凉：迅速散热，保住翠绿。","铲头毛火：第一次烘焙去水。","揉捻：轻轻揉捻成形。","铲二毛火：第二次烘焙。","整形上光：搓条整形，让条索紧圆光滑。","拣选与焙火：分级并最终烘干定香。"]},{"type":"paragraph","text":"蒸青是恩施玉露的立身之本。蒸汽杀青时间短、热作用温和，叶绿素和维生素C的保留量在绿茶里相对突出，所以它的干茶、茶汤、叶底都能保持翠绿，当地把这概括为「三绿一爽」——茶绿、汤绿、叶底绿，滋味鲜爽。杀青之后的「整形上光」也很重要，通过搓条把条索做紧、做圆、做出光泽，同时把蒸青茶特有的海苔香保留下来。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索紧圆光滑，色泽翠绿油润。汤色同样是绿色的，清澈明亮。香气以海苔香和清香为标志，这是蒸青工艺留下的独特气息，和炒青茶的豆香、栗香完全不同。滋味鲜爽甘醇，刺激性不强。叶底翠绿明亮，芽叶完整。整体给人的印象是「绿得很彻底」，第一次喝的人往往会先注意到它的颜色，然后才是那股海苔般的香气。成分上，它与其他绿茶一样含茶多酚、L-茶氨酸与咖啡因；因为蒸青杀青时间短、热作用温和，叶绿素与维生素C的保留量在绿茶中相对突出。传统经验认为恩施玉露性寒味甘，有清热、生津、提神、消食的说法，属传统表述。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"透明玻璃杯或白瓷盖碗温过，投入3克干茶。"},{"title":"注水","text":"水温75至80℃。蒸青茶比炒青茶更怕高温，水温一定要压低。"},{"title":"出汤","text":"第一泡约20秒出汤，之后每泡适当延长，一般可冲3泡。"}]},{"type":"paragraph","text":"恩施玉露的风味偏清淡雅致，配清淡的中式或日式茶点都合适，用玻璃杯冲泡能欣赏它翠绿的汤色。不建议加牛奶，也不建议配浓甜点心，甜味会盖住海苔香；同样不建议用沸水，蒸青茶对高温尤其敏感。存放要密封、避光、防潮、防异味；绿茶都不耐存，开封后建议冷藏并尽快喝完。冷泡同样可以：1克茶兑100毫升水，冷藏约4小时，海苔香会更清爽，建议8小时内喝完。只是它的香气本就清淡，冷泡时不宜再久放，否则清鲜感会明显减弱。"},{"type":"tip","tone":"warning","title":"蒸青与炒青只是方式不同","text":"蒸青和炒青只是杀青方式不同，没有高下之分。区别在于蒸青茶保留了更多叶绿素，汤色更绿；炒青茶在锅中受热，会形成豆香、栗香一类香气。另外提醒，绿茶含咖啡因，睡前4至6小时不宜饮用；缺铁性贫血人群不宜在餐中或餐后立刻喝浓茶，茶多酚会与食物中的非血红素铁结合、影响铁吸收，建议餐间间隔1小时以上再饮。孕期与哺乳期人群建议限量，孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际需按茶汤浓度折算。"}]', '[]', 0, 180, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('6061920329024784346', 'tea_anji_baicha', 'anji-baicha', '安吉白茶', '[]', 'green', '浙江省', '湖州市', '安吉县溪龙乡、天荒坪等', '名为白茶实为绿茶，白化品种配绿茶杀青工艺，滋味极鲜爽几乎无苦涩，是入门绿茶的友好选择。', '["摊放","杀青","理条做形","初烘","摊凉","复烘"]', '["清香","兰花香"]', '["极鲜爽","甘甜","几乎无苦涩"]', '["怕苦涩人群入门","上午提神","午后清口","待客"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":75,"max":80},"vessel":["透明玻璃杯"],"firstSteepSeconds":{"min":20,"max":25},"laterSteepTip":"后续每泡适当延长","infusionCount":{"min":3,"max":4},"methodTip":"水温75至80℃，过高的水温会破坏它的鲜甜感。"}', '密封、避光、防潮、防异味，冷藏可延长保鲜期。', '鲜爽是它的核心优势，开封后建议当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；刺激性相对普通绿茶更低，但并非没有咖啡因；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164918987.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：名为白茶，实为绿茶"},{"type":"paragraph","text":"安吉白茶产自浙江省湖州市安吉县，主产区在溪龙乡、天荒坪等地。它虽然名字里带「白茶」，实际上是不折不扣的绿茶——按绿茶工艺杀青制作，茶多酚氧化程度接近零，与靠萎凋和干燥做成的不发酵白茶类完全是两回事。这个名称来自它的原料特征：茶树品种「白叶一号」在春季低温时，新梢的叶绿素合成受阻，芽叶会变成玉白色，气温升高后又转回绿色。清明前后正是白化期，也是品质最好的时候。白化期的长短与当年的气温直接相关：春季低温持续得久，白化就充分，氨基酸积累得更多；气温回升快，芽叶转绿也快，白化期相应缩短。这也是同一款茶不同年份喝起来，鲜甜程度会有差别的原因。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["摊放：散失部分水分，为杀青做准备。","杀青：高温钝化酶活性——这一步决定了它是绿茶而不是白茶。","理条：做形，让条索挺直显芽。","初烘：第一次烘焙去水。","摊凉：让水分重新分布均匀。","复烘：低温烘干定香。"]},{"type":"paragraph","text":"安吉白茶的品质，一半靠原料、一半靠工艺。原料的特殊之处在于白化期：叶片发白时，游离氨基酸的含量显著高于普通绿茶，白化期可以达到普通绿茶的1.5至2倍以上，而茶多酚相对较低，酚氨比极低，所以喝起来特别鲜甜，几乎尝不到苦涩。工艺上则必须走绿茶的路子，杀青这一步不能省——正是这道工序把它和真正的不发酵白茶类区分开来。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索挺直显芽，颜色翠绿之间带一点金黄。汤色清澈浅绿。香气是清香高长，往往带兰花香。滋味极鲜爽，几乎喝不出苦涩，这是它最讨喜的地方，也让它成为怕苦人群和不常喝茶者的入门首选。叶底玉白透绿，很有辨识度——芽叶泡开之后，白化的痕迹仍然看得出来。成分上，它的游离氨基酸含量显著高于普通绿茶，白化期可达普通绿茶的1.5至2倍以上，茶多酚与咖啡因则相对低于普通绿茶，酚氨比极低。传统经验认为它性寒味甘，有清热、生津、提神的说法，属传统表述，不宜写成现代研究结论。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看叶底最直观：白化过的芽叶冲泡后仍偏玉白，这是品种留下的痕迹。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"透明玻璃杯温过，投入3克干茶。"},{"title":"注水","text":"水温75至80℃，沿杯壁注入。过高的水温会破坏它的鲜甜感。"},{"title":"出汤","text":"第一泡20至25秒出汤，之后每泡适当延长，可冲3到4泡。"}]},{"type":"paragraph","text":"安吉白茶适合配极清淡的茶点，别用浓香或高糖的东西压它的鲜爽；用玻璃杯冲泡还能看到玉白色的叶底，是它的一大看点。不建议加牛奶，那等于浪费了它最大的优势。存放与其他绿茶一致：密封、避光、防潮、防异味，冷藏可延长保鲜期，开封后建议当年内喝完。夏天冷泡尤其合适：1克茶兑100毫升水，冷藏约4小时，鲜甜会被进一步放大，几乎喝不出苦涩，建议8小时内喝完。它也很适合作为不常喝茶的人的第一杯绿茶。"},{"type":"tip","tone":"warning","title":"最常见的误会","text":"最容易搞错的一点就是把它当成白茶。「白茶」是六大茶类里的一类，工艺是不炒不揉、以萎凋和干燥为主；安吉白茶用的是白化品种加绿茶杀青工艺，属性上属于绿茶。另外，它的刺激性相对普通绿茶更低，但并不是没有咖啡因，睡前4至6小时仍不宜饮用，也不建议用茶水送服药物。另外，孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际需按茶汤浓度折算；严重失眠与胃溃疡活动期人群建议限量，空腹时也不宜喝浓茶。"}]', '["product_anji_baicha_50"]', 0, 190, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('841804795849658707', 'tea_emei_zhuyeqing', 'emei-zhuyeqing', '峨眉竹叶青', '["竹叶青"]', 'green', '四川省', '乐山市峨眉山市', '峨眉山海拔800至1200米区域', '扁平挺直、两端尖细似竹叶，嫩栗香清雅内敛，滋味鲜醇爽口、回甘明显，是高海拔炒青绿茶。', '["摊放","杀青","理条整形","挥锅做形","筛分定级"]', '["嫩栗香","清香"]', '["鲜醇","爽口","回甘明显"]', '["上午提神","川菜餐后解腻","办公常备","待客"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"后续每泡延长10至15秒","infusionCount":{"min":3,"max":4},"methodTip":"沿杯壁缓缓注水，避免直冲芽心。"}', '密封、避光、防潮、防异味，冷藏更好。', '绿茶不耐存，开封后尽量当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；不宜与重麻辣菜同饮；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920876.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"峨眉竹叶青产自四川省乐山市峨眉山市，茶园多分布在峨眉山海拔800至1200米的区域。它属于炒青绿茶，外形扁平挺直，两端尖细，形状像竹叶，名字由此而来。峨眉山高海拔、云雾多，氨基酸含量较高，鲜爽度因此表现不错。明前是它的主要采制期，这一季的芽叶细嫩匀整，做出来的条索最挺直漂亮。峨眉山海拔800至1200米这一带，云雾多、漫射光足、昼夜温差大，茶树的氨基酸积累较好、酚氨比低，所以滋味偏鲜醇、苦涩感弱。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["摊放：散失部分水分与青气。","杀青：高温钝化酶活性，固定绿色与鲜爽。","理条整形：压扁做形，让条索扁平挺直。","挥锅做形：进一步整形并发展香气。","筛分定级：按外形匀整度分级。"]},{"type":"paragraph","text":"竹叶青的工艺接近龙井，都要在锅里把茶叶压扁，区别在于它压得更挺直，两端收成尖细的形状，看起来像一片片竹叶。理条整形与挥锅做形这两步决定外形，锅温与手掌的压力要配合得刚好：压力不足条索会松泡，压力过大则容易压碎芽叶、香气发闷。整个过程中不揉捻，扁平的外形完全靠手法完成，这也是它和揉捻类绿茶在口感上分道扬镳的原因。因为原料细嫩，杀青与理条之间衔接得很快，锅温一旦掉下来，芽叶就容易发暗，成品的嫩绿色泽也就保不住了。峨眉山的高海拔原料加上这套工艺，才有了它扁平挺直、清鲜爽口的样子。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，扁平挺直光滑，两端尖细似竹叶，色泽嫩绿。汤色黄绿明亮。香气以嫩栗香和清香为主，比较内敛，不张扬。滋味鲜醇爽口，回甘明显——峨眉山高海拔产区的氨基酸含量较高，鲜爽度是它的强项。叶底嫩绿匀整，芽叶成朵。它和龙井同属扁平形，但喝起来要更清淡一些。成分上，它具备绿茶共性的茶多酚（干茶约18%至36%）、L-茶氨酸（约1%至2%）与咖啡因（约2%至4%），高海拔产区让氨基酸占比更高。传统经验认为竹叶青性寒味甘，有清热、生津、提神、明目的说法，属于传统表述，不能当作现代研究结论来写。"},{"type":"tip","tone":"info","title":"识茶提示","text":"两端是否收成尖细，是竹叶青外形上与龙井最直观的区别。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯投茶","text":"玻璃杯或白瓷盖碗温过，投入3克干茶，茶水比约1:50。"},{"title":"注水","text":"水温80至85℃，沿杯壁缓缓注入。"},{"title":"出汤","text":"第一泡20至30秒出汤，之后每泡延长10至15秒，可冲3到4泡。"}]},{"type":"paragraph","text":"竹叶青在川渝一带很常见，配川式清淡茶点、办公时常备一杯都合适，川菜餐后用来清口也不错。不建议与重麻辣的菜同时入口，刺激叠加之外，麻辣也容易把茶香盖住；加牛奶同样不推荐。存放要密封、避光、防潮、防异味，冷藏更好，开封后尽量当年喝完。夏天可以冷泡：1克茶兑100毫升水，冷藏约4小时，鲜醇与回甘会更清楚，建议8小时内喝完。办公时常备一罐，用玻璃杯随手泡，喝到剩三分之一就续水，一天下来滋味也比较稳定。"},{"type":"tip","tone":"warning","title":"外形相似不等于同一款茶","text":"竹叶青和龙井外形相似，都是扁平挺直，但两者产区、品种不同，风味路数也不完全一样，不必按同一个标准去比。另外，空腹时不宜喝浓茶，容易刺激胃黏膜；服药前后1小时也不宜饮茶，建议用温白开水送服。另外，严重失眠、心律失常、胃溃疡活动期与孕期哺乳期人群建议限量；缺铁性贫血人群不宜在餐中或餐后立刻喝浓茶，建议间隔1小时以上再饮。"}]', '["product_zhuyeqing_50"]', 0, 200, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2465751228784604345', 'tea_rizhao_lvcha', 'rizhao-lvcha', '日照绿茶', '["日照绿"]', 'green', '山东省', '日照市', '东港区、岚山区、莒县等', '中国最北的高纬度茶区之一，条索紧结深绿，豌豆香突出，滋味浓醇耐泡，收敛性强于南方绿茶。', '["摊放","杀青","揉捻","做形","干燥"]', '["豌豆香","栗香"]', '["浓醇","耐泡","收敛明显"]', '["上午提神","餐后解腻","日常口粮"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":85,"max":85},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":30,"max":30},"laterSteepTip":"后续每泡逐次延长，可冲4至5泡","infusionCount":{"min":4,"max":5},"methodTip":"觉得偏浓可减少投茶量或缩短浸泡时间；忌沸水直冲与闷盖久泡。"}', '密封、避光、防潮、防异味，冷藏保存更好。', '浓强度高、内含物多，开封后仍建议当年内喝完。', '含咖啡因，避免空腹浓饮，睡前4至6小时不宜饮用；茶多酚含量较高，胃敏感者与缺铁性贫血人群更应淡饮；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831906.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"日照绿茶产自山东省日照市，主要产区在东港区、岚山区、莒县等地，是中国最北的高纬度茶区之一。它属于炒青绿茶，原料多为一芽一叶或一芽二叶。因为纬度高、生长期长、昼夜温差大，茶树积累的内含物多、氨基酸相对少，酚氨比偏高，所以它的滋味比南方绿茶更浓、更耐泡。也正因为生长期长，春茶上市比南方产区晚，大约在4月中下旬。高纬度带来的另一面是采摘期集中：茶树在漫长冬季休眠之后，春季萌发的芽叶内含物积累充分，这也是它滋味比南方绿茶更厚、更耐泡的原因之一。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["摊放：散失部分水分与青气。","杀青：高温钝化酶活性，固定绿色。","揉捻：揉出茶汁，让条索紧结、滋味更浓。","做形：进一步整形，让条索匀整。","干燥：定香并降低含水量。"]},{"type":"paragraph","text":"对日照绿茶来说，杀青和揉捻的分寸格外重要。它的鲜叶内含物多、叶片相对厚实，杀青要透但不能过：杀不透会留青气，杀过了香气发闷。揉捻则决定条索的紧结程度和滋味的浓强度——揉得充分，茶汁附在叶表，冲泡时浸出快，浓醇感更强。干燥环节把含水量降到安全线，同时把豌豆香固定下来，这也是它辨识度最高的一个特征。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形上，条索紧结，色泽深绿。汤色黄绿明亮。香气以豌豆香和栗香为主，是北方绿茶辨识度很高的特征。滋味浓醇耐泡，收敛性明显强于南方绿茶——也就是说，入口的涩感更明显一些，但回甘也跟着上来。可冲4到5泡，在绿茶里属于比较耐泡的。叶底黄绿明亮。喜欢「重口绿茶」的人，通常很容易接受它。成分上，它具备绿茶共性的儿茶素、茶氨酸与咖啡因；高纬度、生长期长、昼夜温差大，让茶多酚等内含物积累多、氨基酸相对少，酚氨比偏高，因此滋味浓强、耐泡度高。传统经验认为日照绿茶性寒味甘，有清热、生津、提神、消食的说法，属传统表述。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温器投茶","text":"白瓷盖碗或瓷壶用热水温过，投入3克干茶。"},{"title":"注水","text":"水温85℃，沿碗壁注水，不要用沸水直冲。"},{"title":"出汤","text":"第一泡约30秒出汤，之后每泡延长，可冲4至5泡。"},{"title":"控制浓度","text":"如果觉得偏浓，可以减少投茶量或缩短浸泡时间。"}]},{"type":"paragraph","text":"日照绿茶滋味浓强，配北方面食或咸鲜口味的餐后饮用很合适，也适合作为日常口粮茶，瓷壶、盖碗都能用。不建议加牛奶，不建议空腹浓饮，睡前也不宜喝——它浓强度高，同样体积下咖啡因摄入相对更多。存放要密封、避光、防潮、防异味，冷藏保存更好，开封后建议当年内喝完。如果觉得浓，除了减少投茶量，也可以试试冷泡：1克茶兑100毫升水，冷藏约4小时，浓强感会柔和不少，清爽度反而上升，建议8小时内喝完。"},{"type":"tip","tone":"warning","title":"浓醇是特点，但要淡饮","text":"日照绿茶的浓醇来自产区条件，不是缺点，但它的茶多酚含量较高、滋味浓，胃比较敏感的人和缺铁性贫血人群更应淡饮，也不要在餐中或餐后立刻喝浓茶。另外，绿茶不宜用100℃沸水直冲，也不宜闷盖久泡，这两点对浓强度高的北方绿茶尤其重要。另外，严重失眠的人下午之后应停饮；孕期哺乳期与心律失常人群建议限量，孕妇按国际主流建议每日咖啡因摄入不超过200毫克，实际需按茶汤浓度折算。含咖啡因，睡前4至6小时不宜饮用。"}]', '[]', 0, 210, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1923150703997483324', 'tea_baihao_yinzhen', 'baihao-yinzhen', '白毫银针', '["银针白毫"]', 'white', '福建省', '宁德市、南平市', '福鼎（太姥山、磻溪、点头）、政和等传统产区', '全芽披毫、色白如银，毫香与蜜韵清晰，汤色浅杏黄，滋味清鲜醇爽、甜感明显，是白茶里最清淡的一路。', '["采摘单芽","日光萎凋或室内自然萎凋","长时间缓慢失水","文火烘焙","不炒不揉"]', '["毫香","蜜香","清花香"]', '["清鲜","醇爽","清甜"]', '["夏季消暑","午后清口","待客赏形","清淡口味入门"]', '{"teaGrams":4,"waterMl":150,"ratio":"约1:38","temperatureC":{"min":85,"max":90},"vessel":["透明玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":15,"max":30},"laterSteepTip":"之后每泡顺延10至15秒，观察汤色与甜感变化。","infusionCount":{"min":4,"max":5},"methodTip":"嫩芽怕烫，水温不超过90℃，水流沿杯壁轻柔注入，不要直冲芽头。"}', '常温密封、避光、干燥、无异味保存，多层包装隔绝潮气与杂味。', '是否适合长期存放取决于原料、含水率与仓储条件，年份不能替代品质判断。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164921463.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：单芽做的白茶"},{"type":"paragraph","text":"白毫银针是白茶中唯一以单芽为原料的品类。国家标准 GB/T 22291 规定的白茶产品类别为白毫银针、白牡丹、贡眉、寿眉四类，它排在第一位。主产区在福建，福鼎的太姥山、磻溪、点头一带与南平市政和县都是传统产地，两地风格有别：福鼎偏清鲜，政和偏醇厚。名字直接来自外形——芽头满披白毫、色白如银，芽形挺直似针。它属微发酵茶，茶多酚氧化程度约 5%–10%，核心工序只有萎凋和干燥，不炒不揉，是六大茶类里做法最简单的一类。从传统经验的角度，新白茶性偏凉，更贴合暑热季节饮用；传统表述里有清热降火、润肺、退热的说法，这属于传统经验表述，不能当作现代研究结论。"},{"type":"heading","level":3,"text":"萎凋与干燥：两道工序定风格"},{"type":"list","ordered":false,"items":["采摘单芽：只取肥壮芽头，用料精细，是外形挺直匀整的基础。","日光萎凋或室内自然萎凋：让芽头在长时间缓慢失水中完成轻微氧化。","长时间缓慢失水：萎凋时长与温湿度控制，是这道茶最关键的技术点。","文火烘焙：低温收干水分，固定毫香与清甜。","不炒不揉：不做杀青、不做揉捻，保留芽头完整与满身白毫。"]},{"type":"paragraph","text":"这几道工序里，真正决定风格的是萎凋。白茶不靠炒锅和揉捻去塑造滋味，全靠萎凋过程中内源酶的缓慢作用——时间给够，青草气才散得掉，毫香与甜感才出得来；失水过快，香气就单薄。也正因为工艺简单、不炒不揉，白毫银针的茶多酚与儿茶素保留量较高；芽头本身富集游离氨基酸，所以它喝起来是鲜甜而不是浓强。研究还提示，黄酮类在白茶中的含量相对突出。工艺简单不等于成分单薄：不炒不揉让芽头的内含物保留得比较完整，这也是它滋味清甜却不寡淡的原因。"},{"type":"heading","level":3,"text":"识茶要点：看芽、看汤、闻毫香"},{"type":"paragraph","text":"外形看三点：芽头是否肥壮挺直、白毫是否满披、色泽是否银白匀净。汤色是浅杏黄，要清亮。香气以毫香为主，也就是常说的「毫香蜜韵」，细闻有清花香和淡淡蜜香。滋味清鲜醇爽，甜感明显，几乎没有苦涩，叶底肥嫩、芽形完整。它是白茶里最清淡的一路，但不要因此以为它咖啡因低——恰恰相反，咖啡因在芽头部位含量高，银针的咖啡因含量在同类中偏高。用一句话概括它的风格：白茶里最清淡、也最考验原料与萎凋功夫的一路。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看芽头是否挺直匀整、白毫是否满披，这是判断银针外形的第一步。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"用透明玻璃杯或白瓷盖碗，投茶 3–5 g、水 150 ml，茶水比约 1:30 到 1:50。"},{"title":"控温注水","text":"水温 85–90 ℃，嫩芽怕烫；水流沿杯壁轻柔注入，不要直冲芽头。"},{"title":"出汤节奏","text":"第一泡 15–30 秒，之后每泡顺延 10–15 秒，可冲 4–5 泡。"},{"title":"不要煮饮","text":"银针宜泡不宜煮。嫩芽高温久煮会发闷、出苦涩，把毫香煮没了。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"两个误解最常见。一是「白茶没有咖啡因，晚上也能喝」——不对，白茶的咖啡因含量与绿茶相当甚至更高，芽头部位尤其高，睡眠敏感者晚上不宜多饮。二是「银针清淡，空腹喝也没关系」——新白茶性偏凉，空腹饮用容易不舒服，建议餐后喝；脾胃虚寒者也不宜喝冷泡的新茶。日常建议餐后饮用、控制浓度，晚间尽量早饮或减量。"},{"type":"paragraph","text":"品鉴时，银针最好的搭配是极清淡的茶点；用玻璃杯冲泡还能看芽头在水中舒展的「茶舞」，待客时很有观赏性。冷泡时加一片梨或蜜桃，甜感会更突出；不建议加牛奶，奶味会盖掉毫香，也不宜与咖啡、能量饮料等高咖啡因饮品叠加。存放按避光、密封、干燥、无异味来做，多层包装即可。夏季消暑、午后清口、待客赏形都是它的主场；入门者想了解白茶里最清淡的一路，也可以从它开始。要提醒的是：是否适合长期存放取决于原料、含水率与仓储条件，年份不能替代品质判断。"}]', '["product_baihao_yinzhen_50"]', 1, 200, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('5945416550361215560', 'tea_baimudan', 'baimudan', '白牡丹', '[]', 'white', '福建省', '宁德市、南平市', '福鼎、政和、建阳，以及松溪、建瓯等地', '绿叶夹银白毫心，形似花朵，毫香与花香兼具，滋味清甜醇和有层次，比银针更丰富、比寿眉更清雅。', '["采摘一芽一叶或一芽二叶","日光或室内萎凋","复式萎凋","干燥","不炒不揉"]', '["毫香","花香","清甜香"]', '["清甜","醇和","有层次"]', '["午后清口","餐后解腻","夏季冷泡","白茶入门"]', '{"teaGrams":4,"waterMl":150,"ratio":"约1:38","temperatureC":{"min":85,"max":90},"vessel":["白瓷盖碗","玻璃杯"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡顺延10至20秒，可冲5至6泡。","infusionCount":{"min":5,"max":6},"methodTip":"水温不宜超过90℃；冷泡时按1 g茶比100 ml水冷藏约6小时，甜感更突出。"}', '常温密封、避光、干燥、无异味保存，整饼或整袋存放时注意防潮。', '原料有一定成熟度，较适宜存放观察风味变化；能否陈化良好取决于仓储条件。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164921465.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：一芽一二叶的「花」"},{"type":"paragraph","text":"白牡丹属芽叶类白茶，采的是一芽一叶或一芽二叶，主产福建福鼎、政和、建阳，松溪、建瓯等地也有生产。名字来自外形——绿叶夹着银白毫心，冲泡后像一朵初开的花，行内称「绿叶抱银心」。它同样是国家标准 GB/T 22291 白茶产品类别中的一员，茶多酚氧化程度约 5%–10%，核心工序仍是萎凋加干燥，不炒不揉。不同之处在原料：有芽有叶，成分比银针更均衡，既有芽头带来的氨基酸，也有叶片带来的茶多酚。采摘标准比银针宽，芽叶兼取，产量与价格都更友好，是很多人认识白茶的第一支。"},{"type":"heading","level":3,"text":"工艺路径：萎凋方式决定风格"},{"type":"list","ordered":false,"items":["采摘一芽一叶或一芽二叶：芽叶兼取，是「绿叶抱银心」外形的前提。","萎凋：有日光萎凋、室内自然萎凋、复式萎凋几种做法，风格差异多来自这一步。","干燥：收干水分，固定花香与甜感。","不炒不揉：保留芽叶完整，白毫不损。"]},{"type":"paragraph","text":"白牡丹的风格差异，多半来自萎凋方式的选择：日光萎凋香气更外扬，室内自然萎凋更清幽，复式萎凋介于两者之间。同样因为不炒不揉，儿茶素、黄酮类、茶氨酸都有检出，成分比银针均衡；而芽的比例比银针低，咖啡因含量通常低于白毫银针。这也是很多入门推荐从白牡丹开始的原因——它比银针更有层次，比寿眉更清雅。顺带一提，白牡丹的「花」是外形给人的联想，不是花茶——它的花香来自品种与萎凋工艺，全程没有窨花这一步。"},{"type":"heading","level":3,"text":"识茶要点：看叶、闻香、尝层次"},{"type":"paragraph","text":"外形看芽叶比例和毫心是否明显：好的白牡丹毫心银白、叶片灰绿或深灰绿、叶缘略垂。汤色杏黄明亮。香气是毫香加花香，常见栀子、桂花一类的清花香。滋味清甜醇和，比银针有层次、比寿眉清雅，涩感轻。它还有一个实用优势：甜感突出，冷泡表现好，常被认为是白茶里最适合冷泡的一款。季节上，新茶性偏凉，适合暑热与秋燥；传统经验里有清热、润肺、生津的表述，这属于传统经验，不是现代研究结论。"},{"type":"tip","tone":"info","title":"识茶提示","text":"注意看芽与叶的比例：毫心越明显，外形越接近「绿叶抱银心」。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"白瓷盖碗或玻璃杯，投茶 3–5 g、水 150 ml，茶水比约 1:30 到 1:50。"},{"title":"水温","text":"85–90 ℃。嫩芽嫩叶怕烫，水温过高苦涩感会明显。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡顺延 10–20 秒，可冲 5–6 泡。"},{"title":"试试冷泡","text":"按 1 g 茶比 100 ml 水，密封冷藏约 6 小时，滤出茶叶即可，甜感突出、几乎无苦涩。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"一是把「绿叶抱银心」当成等级越高越好——外形只是参考，香气与滋味同样重要。二是以为白茶性凉只能夏天喝：新茶偏凉适合暑热，陈化后性转平和，秋冬同样可以喝，真正要区分的是新茶与陈茶，以及个人体质。另外，不建议加牛奶或浓糖浆，会盖掉花香，也不适合高温久煮，嫩芽久煮容易发苦涩。还有一点值得记住：白茶的咖啡因含量与绿茶相当甚至更高，白牡丹也不例外，晚间饮用同样要留意。"},{"type":"paragraph","text":"搭配上，冷泡白牡丹加雪梨、青柠和少量蜂蜜是接受度很高的喝法，加一点桂花可以增花香，配清淡茶点也合适。存放同样按避光、密封、干燥、无异味处理，注意含水率与仓储条件。它的原料有一定成熟度，比较适合放着观察风味变化，但年份本身不代表品质：能不能陈化得好，要看工艺与仓储是否到位。如果一次买得多，建议分成小份存放，减少开袋次数，避免反复受潮与串味。"}]', '["product_baimudan_100"]', 0, 210, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7078515458289597997', 'tea_gongmei', 'gongmei', '贡眉', '[]', 'white', '福建省', '南平市、宁德市', '建阳（传统主产）、政和、福鼎等地', '以有性系群体种菜茶为原料，毫心较小、叶片粗大，带品种香与野韵，滋味醇厚甜润，层次强于寿眉。', '["采摘菜茶一芽二叶或三叶","日光或室内萎凋","干燥","不炒不揉"]', '["清花香","野韵","甜香"]', '["醇厚","甜润","有层次"]', '["餐后解腻","日常口粮","秋冬煮饮","办公室焖泡"]', '{"teaGrams":6,"waterMl":150,"ratio":"约1:25","temperatureC":{"min":95,"max":100},"vessel":["白瓷盖碗","煮茶壶"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡顺延10至20秒，可冲6至8泡；陈茶可闷30至45秒。","infusionCount":{"min":6,"max":8},"methodTip":"叶张较成熟，用95–100℃高温激发；陈化后的贡眉适合煮饮，5 g茶加500 ml水煮沸后转小火3–5分钟。"}', '常温避光、密封、干燥、无异味、低湿保存，避免与气味浓重的物品同放。', '原料成熟度较好，较适宜长期存放；霉变、酸馊或刺鼻异味的茶不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195830533.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：菜茶做的白茶"},{"type":"paragraph","text":"贡眉是芽叶类白茶，在国家标准 GB/T 22291 的白茶产品类别中与白毫银针、白牡丹、寿眉并列。它与其他三款最不一样的地方在原料：贡眉用的是有性系群体种「菜茶」，也就是以种子繁殖、遗传背景多样的一类茶树，而不是无性系的大白茶、大毫茶。传统主产地在福建建阳，政和、福鼎等地也有生产。茶多酚氧化程度约 5%–10%，工艺与白茶通则一致：萎凋加干燥，不炒不揉。购买时可以看两件事：原料是不是菜茶群体种，以及产地与年份标注是否清楚。"},{"type":"heading","level":3,"text":"工艺路径：工艺同通则，差异在原料"},{"type":"list","ordered":false,"items":["采摘菜茶一芽二叶或一芽三叶：原料比白牡丹粗大，毫心较小。","萎凋：日光或室内自然萎凋，散去青气、转出甜香。","干燥：收干水分，稳定香气。","不炒不揉：与白茶通则一致，保留白毫与叶片完整。"]},{"type":"paragraph","text":"贡眉的工序没有特别之处，它的个性来自茶树本身。菜茶是群体种，遗传多样性丰富，内含物组成比单一无性系品种更复杂，茶多酚、黄酮类、可溶性糖的比例相对均衡，因此常带一种清花香里混着野韵的品种香。随着陈化，茶褐素与黄酮类上升，滋味从清鲜转向醇和。它的醇厚度通常好于寿眉，层次感也更强一些。换句话说，贡眉的个性不是工序做出来的，而是原料本身带来的。"},{"type":"heading","level":3,"text":"识茶要点：比白牡丹粗，比寿眉细"},{"type":"paragraph","text":"外形上，贡眉毫心较小、叶片比白牡丹粗大，色泽偏灰绿带褐。汤色橙黄明亮。香气是菜茶特有的品种香，清花香里带野韵。滋味醇厚、甜感好，层次感强于寿眉，苦涩不重。它的定位大致在中间：比白牡丹粗犷，比寿眉细腻。存放几年之后，香气里会逐渐出现枣香、药香、陈香这类陈化香，汤色也会加深。冲泡后的叶底偏黄绿，叶张比白牡丹更宽、梗也更多，这些都是正常表现。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"比银针、白牡丹加量：投茶 5–7 g、水 150 ml，茶水比约 1:20 到 1:30。"},{"title":"水温","text":"95–100 ℃。叶张较成熟，需要高温才能把甜醇感激发出来。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡顺延 10–20 秒，可冲 6–8 泡。"},{"title":"陈茶可煮","text":"陈化后的贡眉适合煮饮：5 g 茶加 500 ml 水，煮沸后转小火 3–5 分钟，可复煮 2–3 次。"}]},{"type":"list","ordered":false,"items":["餐后解腻：醇厚度好，适合饭后煮一壶。","日常口粮：产量充足、价格友好，适合每天喝。","秋冬煮饮：陈化之后煮饮是它的高光场景。","办公室焖泡：抓一把放进养生壶，久泡也不容易发苦。"]},{"type":"tip","tone":"warning","title":"常见误区与存放提醒","text":"关于贡眉有两个说法要澄清。其一，把它和寿眉当作「只是叫法不同」并不准确——在 GB/T 22291 体系中，贡眉以有性系群体种菜茶为原料，寿眉采自大白茶、大毫茶等无性系品种的较成熟叶片，标准定义上存在原料差异（该标准历经 2008、2017 版本修订，引用时建议核对现行版本条款）。其二，「越陈越好」不成立：能否陈化出好风味，取决于原料成熟度、工艺与仓储是否规范，年份不能替代品质判断。霉变、酸馊或刺鼻异味的茶一律不可饮用。"},{"type":"paragraph","text":"搭配上，贡眉最经典的是配陈皮煮饮，秋冬很受欢迎；加红枣可以增甜，加桂花增香，陈白茶加少量蜂蜜也可以。要注意陈皮性温，阴虚火旺、口舌生疮者不宜多饮。日常也可以抓一把放进办公室养生壶焖泡，或餐后煮一壶解腻。它的咖啡因并不会随陈化消失，睡前仍不宜多饮。如果买到的是散茶，建议按每次用量分装，减少开袋次数。"}]', '[]', 0, 220, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('5117341104257652868', 'tea_shoumei', 'shoumei', '寿眉', '[]', 'white', '福建省', '宁德市、南平市', '福鼎、政和、建阳等地', '白茶中产量最大的品类，梗叶连枝、甜水感突出，新茶清甜带青草香，陈茶转枣香药香，汤色由浅黄转橙红。', '["采摘一芽三叶至四叶或抽针后的对夹叶","日光或室内萎凋","干燥","压制成饼"]', '["青草香","枣香","陈香"]', '["醇厚","顺滑","甜水感"]', '["秋冬煮饮","油腻餐后","冷泡","围炉煮茶"]', '{"teaGrams":6,"waterMl":150,"ratio":"约1:25","temperatureC":{"min":95,"max":100},"vessel":["白瓷盖碗","煮茶壶"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡顺延10至20秒；陈茶可闷30至45秒，可冲6至8泡。","infusionCount":{"min":6,"max":8},"methodTip":"煮饮是陈寿眉最好的呈现方式之一：5 g茶加500 ml水，煮沸后转小火3–5分钟，可复煮2–3次。"}', '常温避光、密封、干燥、无异味、低湿保存；茶饼与散茶都要防潮，避免与气味浓重物品同放。', '原料成熟度较高，较适宜长期存放；霉变、酸馊或刺鼻异味的茶必须丢弃，不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922012.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：产量最大的白茶"},{"type":"paragraph","text":"寿眉是白茶里产量占比最大的品类，主产福建福鼎、政和、建阳等地。它的原料在四类白茶中最成熟：采摘一芽三叶至四叶，或者用抽针后的对夹叶——也就是芽头被采去做银针之后留下的叶片。它是国家标准 GB/T 22291 白茶四类产品（白毫银针、白牡丹、贡眉、寿眉）之一，茶多酚氧化程度约 5%–10%，陈化后仍在持续转化，工序同样是萎凋加干燥。也因为它粗枝大叶、产量充足，常作为日常口粮茶。市面上常见的白茶饼，多数就是寿眉压制而成的。"},{"type":"heading","level":3,"text":"工艺路径：萎凋之后，多压成饼"},{"type":"list","ordered":false,"items":["采摘一芽三叶至四叶或抽针后的对夹叶：原料成熟度高，是醇甜汤感的来源。","萎凋：日光或室内自然萎凋，散去青草气、累积甜感。","干燥：收干水分，稳定香气。","压制成饼：多数寿眉会压成茶饼，便于长期存放，也是市场上最常见的陈化形态。"]},{"type":"paragraph","text":"寿眉最值得说的是原料与陈化。原料成熟度高，可溶性糖与茶多糖含量相对较高，这就是它「甜水感」突出的物质基础。随着存放时间延长，儿茶素下降，茶褐素与部分黄酮类上升，香气从新茶的清甜青草香转为枣香、药香、陈香，汤色由浅黄转橙红。压饼既省空间，也让茶体内部的温湿度变化更缓，是市场上最常见的陈化形态。这也是为什么很多人第一次喝老白茶是从寿眉开始的：它的甜是原料自带的，不靠工艺修饰。压饼后的茶需要撬开，撬茶时尽量保持叶张完整，碎末过多会让汤色变浑。"},{"type":"heading","level":3,"text":"识茶要点：梗叶连枝，先看汤色"},{"type":"paragraph","text":"外形叶张稍肥嫩、芽心小、梗叶连枝，色泽偏褐绿。新茶汤色浅黄，陈茶转橙红甚至深红。香气分两段：新茶清甜带青草香，存放三年以上逐渐出现枣香、药香、陈香。滋味醇厚顺滑，甜水感突出，涩感低。选购时要区分「陈」与「坏」——香气干净、汤色透亮、滋味醇和的是正常陈化；有霉味、酸馊味的属于贮存事故，不是陈香。冲泡后的叶底偏黄褐、叶张宽大、梗叶相连，是它的常态。"},{"type":"tip","tone":"info","title":"识茶提示","text":"寿眉常压成茶饼存放；看饼面是否匀整、有无霉斑，是选购时的第一眼判断。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"盖碗或煮茶壶，投茶 5–7 g、水 150 ml，茶水比约 1:20 到 1:30。"},{"title":"水温","text":"95–100 ℃，粗老叶需要高温才能出味。"},{"title":"出汤","text":"第一泡 20–30 秒，陈茶可闷 30–45 秒，可冲 6–8 泡。"},{"title":"秋冬煮饮","text":"5 g 茶加 500 ml 水，煮沸后转小火 3–5 分钟，可复煮 2–3 次。"}]},{"type":"tip","tone":"warning","title":"常见误区与安全提示","text":"第一，「所有白茶都越陈越好」不成立。存放陈化需要三个条件：原料有一定成熟度（寿眉、贡眉、白牡丹更适宜）、工艺到位、贮存环境规范；贮存不当的白茶会霉变，时间越长越危险。第二，「白茶没有咖啡因」是错的，寿眉晚上喝同样可能影响入睡，晚间宜淡饮或选冷泡。第三，也是最重要的一条：霉变、酸馊或有刺鼻异味的茶绝对不可饮用，必须丢弃。另外，晚间若要喝，优先选冷泡并减少投茶量。"},{"type":"paragraph","text":"寿眉是白茶里最百搭的一款。秋冬用陈皮一起煮是经典组合，也可以加红枣、桂圆做暖饮；冷泡的甜水感强，是年轻人接受度很高的喝法，加雪梨或蜜桃都不错；火锅、烧烤这类油腻餐后喝一杯也舒服。不建议加牛奶，会盖掉陈香，也不要用浓糖浆或强香精调味。存放要避光、密封、干燥、无异味、低湿，不要与气味重的东西放在一起。它也是白茶里最适合当口粮的一款：产量足、价格友好、耐泡，煮一壶能喝一整天。"}]', '["product_shoumei_100"]', 0, 230, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7323095087867215048', 'tea_xingongyi_baicha', 'xingongyi-baicha', '新工艺白茶', '[]', 'white', '福建省', '宁德市', '福鼎市为主', '20 世纪 60 年代为适应外销市场创制，以萎凋后加轻揉捻为标志，汤色更深、滋味浓强。', '["采摘","萎凋","轻揉捻","干燥"]', '["高火香","熟甜香","淡陈香"]', '["浓强","醇厚","汤感厚"]', '["日常口粮","餐后解腻","偏好浓强口感","秋冬饮用"]', '{"teaGrams":5,"waterMl":150,"ratio":"约1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡递增10至20秒，坐杯时间不宜过长，可冲5至7泡。","infusionCount":{"min":5,"max":7},"methodTip":"揉捻后成分浸出快，出汤要利落，避免过浓发苦。"}', '常温密封、避光、干燥、无异味保存。', '陈化走向与传统白茶不同，是否长期存放建议以实际品饮表现判断，不以年份为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195830536.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：多了一道揉捻的白茶"},{"type":"paragraph","text":"新工艺白茶是白茶中一个特殊的类别，20 世纪 60 年代为适应外销市场创制，主产地在福建福鼎。它和传统白茶最大的区别，是在萎凋之后增加了一道轻揉捻。多这一道工序，茶叶细胞的破损程度提高，氧化程度也略高于传统白茶，茶多酚氧化程度约 8%–12%。因为工艺路线不同，它的风味走向也随之分开：条索略卷缩、色泽深灰绿带褐，香气偏浓，滋味更浓强，汤色更深。它的出现有明确的时代背景：为适应外销市场的口味偏好，福鼎在传统白茶工艺上做了这一步调整。"},{"type":"heading","level":3,"text":"工艺路径：萎凋之后加一道轻揉捻"},{"type":"list","ordered":false,"items":["萎凋：与传统白茶一致，先散去青气、降低水分。","轻揉捻：关键差异工序，轻度破坏细胞结构，让成分更容易浸出。","干燥：收干水分，形成偏浓的香气，常被形容为「高火香」。","与传统白茶的区别：传统白茶不炒不揉、细胞完整，新工艺白茶在萎凋后多了轻揉捻这一步。"]},{"type":"paragraph","text":"这道轻揉捻是理解新工艺白茶的钥匙。传统白茶不炒不揉，细胞完整，成分浸出慢，所以汤感清鲜、毫香明显；轻揉捻让细胞破损，成分浸出更快、茶汤浓度更高，儿茶素部分氧化，刺激性低于绿茶，但仍高于传统白茶。代价是少了传统白茶那种清鲜的毫香。它适合想从「浓一点」的路线开始接触白茶的人，也适合当日常口粮。从分类上说，它仍然属于白茶，只是工艺路线不同；把它理解成「白茶里的另一个做法」，比理解成「另一种茶」更准确。"},{"type":"heading","level":3,"text":"识茶要点：条索、汤色与高火香"},{"type":"paragraph","text":"外形看两点：条索略卷缩，不是传统白茶那种舒展的芽叶；色泽深灰绿带褐。汤色比传统白茶深。香气偏浓，常被形容为「高火香」，与传统白茶的毫香、花香是两条路线。滋味浓强、醇厚，比传统白茶更「有劲」，耐泡度不错。如果你习惯了绿茶的浓强度，新工艺白茶可能是更容易上手的一支。叶底偏深、色泽褐绿，与传统白茶的嫩绿芽叶差别明显。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"白瓷盖碗或瓷壶，投茶 5 g、水 150 ml。"},{"title":"水温","text":"90–95 ℃，比银针、白牡丹高，比寿眉略低。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡递增 10–20 秒，可冲 5–7 泡。"},{"title":"注意浓度","text":"成分浸出快，坐杯时间别太长，否则容易过浓发苦。"}]},{"type":"list","ordered":false,"items":["咸香茶点：滋味浓强，与咸味茶点比较对等。","陈皮：陈香与柑香搭在一起，秋冬也合适。","餐后：浓强度高，餐后一杯比较解腻。","器皿：白瓷盖碗或瓷壶都可，但不适合配过于清淡的茶点。"]},{"type":"tip","tone":"warning","title":"常见误区","text":"第一个误解是把「新工艺」当成「品质更好」或「更新鲜」。它指的只是一条工艺路线，是为适应外销市场而创制的做法，不是等级名称。第二个误解是「白茶都不揉捻」——传统白茶确实不炒不揉，但新工艺白茶恰恰以轻揉捻为标志。另外要提醒：它的咖啡因与茶多酚浸出都更快，空腹浓饮更容易不舒服，睡前也不宜喝浓茶。还有一点：它的汤色深、滋味浓，容易被误当成发酵度很高的茶，其实茶多酚氧化程度只是略高于传统白茶。"},{"type":"paragraph","text":"新工艺白茶适合配咸香茶点，滋味浓的茶点与它比较对等；配陈皮也不错，瓷壶或盖碗冲泡都合适。不建议加牛奶，也不建议配过于清淡的茶点——它的浓强会把淡味茶点压住。存放要求与白茶通则相同：避光、密封、干燥、无异味。它的陈化走向与寿眉、贡眉不同，是否长期存放建议以实际品饮表现来判断，而不是只看年份。"}]', '[]', 0, 240, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4388138651903206775', 'tea_huangye_baicha', 'huangye-baicha', '荒野白茶', '[]', 'white', '福建省', '宁德市、南平市', '福鼎、政和的高山抛荒茶园', '采自无人为干预的抛荒茶园，工艺同白茶通则，山野气突出、汤感醇厚饱满，耐泡度明显高于台地茶。', '["抛荒茶园采摘","日光或室内萎凋","不炒不揉","干燥"]', '["山野气","野韵","木质香"]', '["醇厚","饱满","回甘深长"]', '["进阶品鉴","秋冬煮饮","餐后解腻","送礼"]', '{"teaGrams":6,"waterMl":150,"ratio":"约1:25","temperatureC":{"min":100,"max":100},"vessel":["白瓷盖碗","紫砂壶","煮茶壶"],"firstSteepSeconds":{"min":15,"max":20},"laterSteepTip":"之后每泡顺延10至20秒，可冲8泡以上，仍有余味。","infusionCount":{"min":8,"max":10},"methodTip":"叶张厚实，用沸水冲泡才能充分展开；陈化后可煮饮。"}', '常温避光、密封、干燥、无异味、低湿保存。', '是否长期存放取决于原料与仓储条件；霉变、酸馊或刺鼻异味的茶不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195830534.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：按原料来源划分的概念"},{"type":"paragraph","text":"先说清楚身份：荒野白茶不是国家标准里的独立类别，而是按原料来源划分的一个概念。它指采自高山抛荒茶园的茶青——茶园长期无人为干预，不施肥、不打药，与林木杂草共生。产区集中在福建福鼎、政和的高山地带。它的工艺与白茶通则完全一致，萎凋加干燥；差别全在原料那一端，不因「荒野」二字改变工序。判断一款茶是不是真的来自抛荒茶园，最终还是要看风味表现：山野气是否清晰、耐泡度是否足够，而不是包装上的两个字。"},{"type":"heading","level":3,"text":"工艺路径：工序不变，差别在原料"},{"type":"list","ordered":false,"items":["原料来自抛荒茶园：无人为干预，不施肥不打药，与林木杂草共生。","发芽晚、产量低：荒野茶树发芽时间晚于台地茶园，可采的量也少。","叶张厚实：生长缓慢，叶片更厚，是耐泡度的物质基础。","萎凋与干燥：与白茶通则一致，工艺本身没有特殊之处。"]},{"type":"paragraph","text":"抛荒环境对茶树的影响缓慢而实在：茶树根系扎得更深、生长节律更慢，内含物积累更充分，多酚类与可溶性糖含量相对高，通常表现为更高的耐泡度与更饱满的醇厚度。有一层需要说清楚：市场常说「荒野茶功效更强」，这一说法缺乏对照研究支持，属于存疑的表述；荒野白茶目前能被说明的优势，主要体现在风味与耐泡度上，而不是功效。再加上产量低、稀缺性高，这类茶在市场上的溢价普遍明显；它更适合用沸水、快出汤的方式冲泡，把厚度和层次一泡一泡地打开。"},{"type":"heading","level":3,"text":"识茶要点：山野气与耐泡度"},{"type":"paragraph","text":"荒野白茶的开汤香气，最典型的是山野气或丛林气息，市场上通俗称为「野韵」「枞味」——这是风味描述，不是品质等级。滋味醇厚饱满，回甘深长，耐泡度明显高于普通台地茶园的白茶。汤色橙黄。判断真伪时要有心理准备：真正产量极低的茶，市面上流通量却远超真实产量，是常见现象；溢价又高，购买时更需要看具体风味表现，而不是只听名字。汤感的饱满与回甘的持久，是它区别于普通白茶最直接的两点；如果只是香气好听、喝起来却单薄，就要多留个心眼。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"盖碗、紫砂或煮茶壶，投茶 5–7 g、水 150 ml。"},{"title":"水温","text":"100 ℃ 沸水。叶张厚实，需要足够温度才能充分展开。"},{"title":"出汤","text":"第一泡 15–20 秒，之后每泡顺延 10–20 秒，可冲 8 泡以上。"},{"title":"陈化后煮饮","text":"存放后的荒野白茶可以煮：5 g 加 500 ml 水，煮沸转小火 3–5 分钟。"}]},{"type":"list","ordered":false,"items":["单独品饮：最能体会山野气与回甘的方式。","秋冬煮饮：陈化后煮一壶，汤感更饱满。","淡味坚果：不抢香气，搭配起来比较克制。","陈皮：喜欢醇厚路线可以试试。"]},{"type":"tip","tone":"warning","title":"常见误区与提示","text":"不要把「荒野」当成一个等级名称——它不是国标类别，也没有对应的官方分级，它描述的是原料来源。也不要把市场说法「荒野茶功效更强」当成结论，这一说法缺乏对照研究支持。此外要留意真伪与溢价：产量极低的茶却大量流通，是这类茶最常见的问题。荒野白茶的咖啡因与其他白茶相当，晚间同样不宜浓饮。"},{"type":"paragraph","text":"荒野白茶更适合单独品饮——加奶、加糖或强香配料都会盖住山野气，反而浪费了它的稀缺性。如果要搭配，淡味坚果、陈皮比较合适，秋冬煮饮也很出彩。存放按避光、密封、干燥、无异味处理；霉变、酸馊或刺鼻异味的茶一律不可饮用。进阶茶友常把它当作对比样本：同一产区、同一年份的台地茶与荒野茶对冲，差别会比较清楚。"}]', '[]', 0, 250, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7401155051300925453', 'tea_laobaicha', 'lao-baicha', '老白茶（陈年白茶）', '["陈年白茶"]', 'white', '福建省', '宁德市、南平市', '福鼎、政和等，原料多为寿眉、贡眉，亦有白牡丹', '白茶经规范贮存陈化后的状态，枣香、药香与陈香交织，汤感醇厚顺滑、几乎无涩，年份不能替代品质判断。', '["采摘","萎凋","干燥","规范贮存陈化"]', '["枣香","药香","陈香"]', '["醇厚","顺滑","汤感稠"]', '["秋冬煮饮","油腻餐后","围炉煮茶","办公室养生壶"]', '{"teaGrams":6,"waterMl":150,"ratio":"约1:25","temperatureC":{"min":100,"max":100},"vessel":["煮茶壶","紫砂壶","白瓷盖碗"],"firstSteepSeconds":{"min":15,"max":30},"laterSteepTip":"醒茶后第一泡15至30秒，之后每泡顺延，可冲8泡以上。","infusionCount":{"min":8,"max":10},"methodTip":"煮饮是它最常见的呈现方式：5 g茶加500 ml水，煮沸后转小火3–5分钟，可复煮2–3次。"}', '避光、密封、干燥、无异味、相对湿度低；这是陈化能往好的方向走的唯一前提。', '年份不能替代品质判断。出现霉味、酸馊味或霉斑的茶必须丢弃，绝对不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；贮存不当出现霉变、酸馊或刺鼻异味的茶不可饮用。内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195830535.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：一个市场通行的概念"},{"type":"paragraph","text":"先明确一点：「老白茶」目前是市场通行的概念，不是国家标准中的独立产品类别。GB/T 22291 规定的白茶产品类别是白毫银针、白牡丹、贡眉、寿眉四类；所谓老白茶，指的是白茶经过若干年规范贮存后陈化的状态。市场通常以 3 年以上作为「老白茶」的说法，这一年限界定来自市场习惯，并无国家标准依据。原料多为寿眉、贡眉，也有用白牡丹的，产区仍在福建福鼎、政和一带。换句话说，「老」描述的是一段时间与一种仓储结果，而不是一个可以印在包装上的等级。"},{"type":"heading","level":3,"text":"工艺路径：基础工艺加规范贮存"},{"type":"list","ordered":false,"items":["萎凋与干燥：先按白茶通则做成新茶，这是陈化的起点。","规范贮存：避光、密封、干燥、无异味、低湿，这一步决定陈化结果。","时间：市场通常以 3 年以上称老白茶，属市场通行说法，不是国标界定。","持续转化：贮存期间成分缓慢变化，香气与滋味随之改变。"]},{"type":"paragraph","text":"老白茶最容易讲错的地方在这里：陈化不是「放着就会变好」。它是基础工艺与仓储共同作用的结果——原料要有一定成熟度（寿眉、贡眉、白牡丹更适宜），工艺要到位，贮存环境要规范。成分上，陈化过程中儿茶素总量下降，茶褐素与部分黄酮类上升，滋味由清鲜转向醇和，汤感变稠。需要说明的是，这些成分变化与健康效应的关系，还需要更多研究才能讲清楚。还有一个常被忽略的点：陈化并不会让咖啡因消失，只是香气与滋味变了，睡前饮用仍要留意。所以「存了多少年」只能当作背景信息，开汤之后香气是否干净、汤感是否顺滑，才是判断依据。"},{"type":"heading","level":3,"text":"识茶要点：枣香、药香与汤感的稠"},{"type":"paragraph","text":"香气是枣香、药香、陈香、木质香，与新年份白茶的清鲜花香完全不同。汤色由橙黄转橙红，年份更长的可以到深红。滋味醇厚顺滑，汤感稠，几乎无涩。判断时要看整体：香气干净、汤色透亮、滋味醇和，是正常陈化；有霉味、酸馊味则是贮存事故。市场上还有用高温高湿催陈的「做旧」茶，这类茶存在品质劣变风险，选购时要留意气味是否自然。叶底偏深褐、叶张柔软，也是年份带来的正常变化。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"醒茶","text":"先快速润茶一遍，让紧压或存放较久的茶叶舒展，再正式出汤。"},{"title":"冲泡","text":"投茶 5–7 g、水 150 ml，100 ℃ 沸水，第一泡 15–30 秒，可冲 8 泡以上。"},{"title":"煮饮","text":"5 g 茶加 500 ml 水，煮沸后转小火 3–5 分钟，可复煮 2–3 次。"},{"title":"选器","text":"煮茶壶、紫砂或盖碗都可以，煮饮是它最常见的呈现方式。"}]},{"type":"list","ordered":false,"items":["秋冬煮饮：最常见的喝法，适合寒季。","配陈皮：经典组合，陈香与柑香交织。","配红枣桂圆：冬季暖饮，甜感更足。","油腻餐后：火锅、烧烤之后煮一壶。"]},{"type":"tip","tone":"warning","title":"常见误区与安全提示","text":"第一，「一年茶、三年药、七年宝」是民间谚语，属传统经验表述，不构成功效承诺；茶叶是食品，任何年份的白茶都不能替代药物。「年份越久功效越强」也缺乏高质量人体研究支持。第二，年份不能替代品质判断——仓储良好的三年茶，可能明显好过仓储失控的十年茶。第三，贮存不当发霉的茶绝对不可饮用，出现霉味、酸馊味或霉斑必须丢弃。"},{"type":"paragraph","text":"老白茶最常见的喝法是秋冬煮饮，配陈皮是经典组合，也可以加红枣、桂圆，或少量蜂蜜。它很适合火锅、烧烤这类油腻餐后的场景，也常出现在围炉煮茶和办公室养生壶里。不建议加牛奶，蛋白与茶多酚结合会造成成分损失，也会盖掉陈香；更不要用强香精调味去掩盖异味——那是霉变茶常见的处理方式，遇到要警惕。咖啡因在陈化中并不会消失，睡前仍不宜多饮。"}]', '[]', 0, 260, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('6682326238763754120', 'tea_yunnan_yueguangbai', 'yunnan-yueguangbai', '云南月光白', '["月光美人"]', 'white', '云南省', '普洱市', '景谷、澜沧等，临沧、西双版纳亦有产区', '云南大叶种按白茶工艺制成，叶面黑、叶背白，蜜香与花果香突出，滋味醇厚甘甜，汤感饱满，风格甜醇。', '["采摘一芽一叶或一芽二叶","室内自然萎凋并避光","阴干或低温干燥","不炒不揉"]', '["蜜香","花果香","甜香"]', '["醇厚","甘甜","汤感饱满"]', '["午后清口","夏季冷泡","餐后饮用","偏好甜醇口感"]', '{"teaGrams":4,"waterMl":150,"ratio":"约1:38","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","玻璃杯"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡顺延10至15秒，可冲5至7泡，不要高温久闷。","infusionCount":{"min":5,"max":7},"methodTip":"大叶种内含物丰富，投茶量可比福建白茶略减；冷泡按1 g茶比100 ml水冷藏约6小时。"}', '常温密封、避光、干燥、无异味保存。', '可存放观察风味变化，但能否陈化良好取决于原料与仓储条件，年份不能替代品质判断。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831381.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：云南大叶种做的白茶"},{"type":"paragraph","text":"月光白又叫月光美人，是用云南大叶种茶青、按白茶的萎凋干燥工艺做成的一支茶，主产云南普洱市景谷县、澜沧县一带，临沧、西双版纳也有产区。它的原料是云南大叶种，与福建白茶的中小叶种体系不同，风格也因此自成一派。名字有来由：传统说法称采用夜间采摘、月光下萎凋的方式，故名月光白——这属于传统说法，不必当作工艺定论来理解。它的风格和福建白茶差别明显：少了毫香的清冷，多了蜜香与花果香的甜润，更接近「甜醇型白茶」这一路。"},{"type":"heading","level":3,"text":"工艺路径：避光萎凋与低温干燥"},{"type":"list","ordered":false,"items":["采摘一芽一叶或一芽二叶：大叶种芽叶肥壮，内含物丰富。","室内自然萎凋并避光：这是它颜色与风味形成的关键环节。","阴干或低温干燥：不用高温，保住甜感与花果香。","不炒不揉：与白茶通则一致。"]},{"type":"paragraph","text":"月光白最有辨识度的是颜色：叶面黑、叶背白，黑白相间。这个特征来自避光萎凋——不直接晒，叶面与叶背的色差被保留下来。工艺上它比福建白茶更强调低温，因为云南大叶种的茶多酚与内含物总量高于中小叶种，若用强日晒或偏高温度处理，苦涩感容易突出。氨基酸与可溶性糖共同贡献了它甜醇的汤感，成分特征介于白茶与其他云南茶之间。也正因为大叶种的内含物总量高，它比中小叶种白茶更容易泡浓，投茶量可以适当减少。"},{"type":"heading","level":3,"text":"识茶要点：先看黑白，再尝甜度"},{"type":"paragraph","text":"外形第一眼就看黑白相间：叶面深黑、叶背满披白毫。汤色金黄透亮。香气以蜜香和花果香为主，比福建白茶更甜香外放，少了毫香的清冷感。滋味醇厚甘甜，汤感饱满，这也是大叶种内含物丰富带来的结果。需要注意的是，大叶种茶多酚含量高，胃敏感的人宜淡饮，别因为甜感好就泡得太浓。叶底颜色偏深、叶片宽大，是大叶种的正常特征。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"白瓷盖碗或玻璃杯，投茶 4–5 g、水 150 ml，大叶种内含物多，可略减量。"},{"title":"水温","text":"90–95 ℃，不要用沸水猛冲，也不要高温久闷。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡顺延 10–15 秒，可冲 5–7 泡。"},{"title":"冷泡也好喝","text":"按 1 g 茶比 100 ml 水，密封冷藏约 6 小时，蜜香与甜感更清透。"}]},{"type":"list","ordered":false,"items":["冷泡加蜜桃或荔枝：呼应蜜香，夏季很受欢迎。","加桂花：增花香，甜感更立体。","清淡茶点：不压花果香。","餐后饮用：汤感饱满，适合饭后。"]},{"type":"tip","tone":"warning","title":"常见误区","text":"第一个误解是把月光白当成「月光下晒出来的茶」。夜间采摘、月光萎凋是传统说法，实际工艺核心是避光萎凋与阴干、低温干燥，不必把传说当成定论。第二个误解是以为「甜就不刺激」——大叶种茶多酚含量高于中小叶种，胃敏感者、缺铁性贫血人群更应淡饮，空腹也不合适。另外，它和云南普洱茶是两回事，工艺与分类都不同。还有一点：它虽然名字里带「月光」，但并不是只在夜里做茶，白天同样可以萎凋，关键在避光。"},{"type":"paragraph","text":"搭配上，冷泡月光白加蜜桃或荔枝最呼应它的蜜香，加桂花也不错，配清淡茶点很合适。不建议加牛奶或浓糖浆，会压住花果香。存放按避光、密封、干燥、无异味处理。它新茶清甜，也可以放着观察风味变化，但同样要记住：能不能存出好风味取决于仓储条件与原料本身，年份不能替代品质判断。喜欢甜醇风格的人，通常会在它和白牡丹之间找到自己的偏好。"}]', '[]', 0, 270, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2842500579233261260', 'tea_zhenghe_baicha', 'zhenghe-baicha', '政和白茶', '[]', 'white', '福建省', '南平市', '政和县铁山、东平、石屯等高山区', '以产地立名，含银针、白牡丹、贡眉、寿眉等品类，香气清芬、滋味醇厚，陈化潜力突出。', '["采摘政和大白茶","室内自然萎凋","阴干","干燥"]', '["清芬香","毫香","陈香"]', '["醇厚","顺滑","耐泡"]', '["餐后解腻","长期存放陈化","秋冬煮饮","办公室焖泡"]', '{"teaGrams":5,"waterMl":150,"ratio":"约1:30","temperatureC":{"min":85,"max":100},"vessel":["白瓷盖碗","煮茶壶"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡顺延10至20秒，可冲5至8泡；陈化后可煮饮。","infusionCount":{"min":5,"max":8},"methodTip":"按品类定水温：银针类85–90℃，寿眉类95–100℃。"}', '常温避光、密封、干燥、无异味、低湿保存，高山产区茶尤其要注意防潮。', '醇厚度与陈化潜力较突出，适合存放观察变化；霉变、酸馊或刺鼻异味的茶不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831382.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份：以产地立名的一支"},{"type":"paragraph","text":"政和白茶是以产地立名的说法，指福建南平市政和县出产的白茶，铁山、东平、石屯等高山区是主要产地。它不是单一品类，而是涵盖白毫银针、白牡丹、贡眉、寿眉等品类的产地品牌。原料以政和大白茶品种为主，这个品种芽叶肥壮、内含物丰富，茶多酚与氨基酸总量较高，风味研究普遍认为政和系白茶的醇厚度与陈化潜力突出。茶多酚氧化程度约 5%–10%，属微发酵茶。同一片政和茶园里，芽头可以做成银针，芽叶可以做成白牡丹，粗一些的叶张做成贡眉与寿眉——它们共享同一个产地风格。"},{"type":"heading","level":3,"text":"工艺路径：室内萎凋与阴干"},{"type":"list","ordered":false,"items":["原料为政和大白茶：芽叶肥壮，是醇厚风格的底子。","室内自然萎凋为主：区别于福鼎常用的日光萎凋，萎凋时间更长。","阴干：不走强日晒，香气更内敛。","干燥：收干水分，完成定型。"]},{"type":"paragraph","text":"政和与福鼎的差别，很大程度上是萎凋方式的差别。福鼎多用日光萎凋，风格偏清鲜；政和传统上以室内自然萎凋加阴干为主，萎凋时间长，水分走得更慢更匀，成茶香气更清芬内敛，滋味更醇厚，耐泡度也好。这两种路线没有高下之分，只是两种风格取向：喜欢清爽鲜灵可以选福鼎，喜欢醇厚饱满可以选政和。所以「福鼎」与「政和」更像是两种风味取向的标签，而不是品质高低的排序。如果拿不准自己的偏好，可以两款对冲喝一次，差别会非常直观。"},{"type":"heading","level":3,"text":"识茶要点：毫色略灰、汤色杏黄"},{"type":"paragraph","text":"外形上，政和白茶的芽肥壮，毫色偏灰而不是纯银白，这是品种特征，不是品质问题。汤色杏黄。香气清芬，不张扬。滋味醇厚——相对福鼎白茶的「清鲜」，政和更偏「醇厚」，耐泡度好。如果是政和产的寿眉、贡眉，陈化后同样会出现枣香、药香这类陈香，汤色加深。选购时可以把「毫色灰」与「毫色差」区分开：前者是品种特点，后者才涉及原料与工艺。叶底偏黄绿、叶张较厚，是政和大白茶的特征之一。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"按品类定水温","text":"银针类 85–90 ℃，寿眉类 95–100 ℃。同是政和白茶，嫩度不同水温也不同。"},{"title":"投茶","text":"投茶 5 g、水 150 ml；嫩芽类可略减，粗老叶可略增。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡顺延 10–20 秒，可冲 5–8 泡。"},{"title":"陈化后煮饮","text":"存放后的政和白茶适合煮饮：5 g 加 500 ml 水，煮沸转小火 3–5 分钟。"}]},{"type":"list","ordered":false,"items":["餐后解腻：醇厚度好，适合饭后一壶。","长期存放：醇厚度与陈化潜力突出，适合观察变化。","秋冬煮饮：陈化后煮一壶，汤感更厚。","办公室焖泡：粗老叶久泡也不容易发苦。"]},{"type":"tip","tone":"warning","title":"常见误区","text":"第一个误解是把「政和白茶」当成一个具体品类——它是产地概念，下面包含银针、白牡丹、贡眉、寿眉多个品类，买的时候要看具体品类与年份，而不是只看「政和」两个字。第二个误解是以为毫色越白越好：政和大白茶的毫色本来就偏灰，纯白多是品种差异，不宜简单当作等级判断。另外别把政和白茶与安吉白茶混为一谈——安吉白茶是绿茶，不是白茶。还有一点：政和白茶下面有多个品类，冲泡参数要跟着品类走，不能一套参数用到底。"},{"type":"paragraph","text":"政和白茶很适合长期存放观察变化，也适合日常餐后解腻、办公室焖泡。搭配上，陈皮、红枣都很合适，冷泡加梨也不错；不建议加牛奶或强香精调味。存放要求与其他白茶一致：避光、密封、干燥、无异味、低湿。霉变、酸馊或刺鼻异味的茶不可饮用。"}]', '[]', 0, 280, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2443959781945548466', 'tea_junshan_yinzhen', 'junshan-yinzhen', '君山银针', '["君山茶"]', 'yellow', '湖南省', '岳阳市', '君山区洞庭湖君山岛', '全芽肥壮挺直、满披白毫，甜香与嫩香里带一丝锅巴香，茶汤浅黄明亮，是黄芽茶里最有观赏性的一款。', '["采摘单芽","杀青","摊凉","初包闷黄","复炒","复包闷黄","足火干燥"]', '["甜香","嫩香","淡锅巴香"]', '["甜醇","鲜爽","苦涩轻"]', '["茶龄短者入门","上午清饮","待客观形","餐后淡饮"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["透明玻璃杯"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡延长约 10 秒","infusionCount":{"min":3,"max":4},"methodTip":"用透明玻璃杯冲泡便于观察芽头沉浮，芽头细嫩，忌沸水、忌久闷。"}', '密封、避光、防潮、防异味，短期喝不完可冷藏，取出后回到室温再开封。', '以清甜鲜醇为品饮目标，开封后宜尽早喝完。', '含咖啡因，避免空腹浓饮与睡前饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922601.jpg', '[]', '[{"type":"heading","level":3,"text":"洞庭湖心的君山岛"},{"type":"paragraph","text":"君山银针出自湖南省岳阳市君山区的君山岛，一座立在洞庭湖里的小岛，四面环水，水体调节着岛上的气温，常年湿度偏高，茶园散布在岛上的缓坡与林间。它是黄茶里黄芽茶的代表，名字用形状命名：「银针」说的是全用单芽做成、芽身挺直、满披白毫的样子，旧时也称君山茶。黄茶的「黄」来自闷黄工序，不是原料本身的颜色，所以它的干茶并不是亮黄色，而是银白里透出微黄。黄茶是六大茶类里产量最小的一类，很多人喝过绿茶、喝过红茶，却未必认真喝过一杯黄茶，君山银针常被当作认识黄茶的第一站。"},{"type":"heading","level":3,"text":"两闷两炒的工艺路径"},{"type":"list","ordered":false,"items":["采摘单芽：只取肥壮饱满的芽头，不带叶片。","杀青：高温钝化酶活性，固定芽头里的清鲜物质。","摊凉：让杀青后的芽头散热，水分分布均匀。","初包闷黄：趁热用纸包起保温，芽头在湿热里开始转黄。","复炒：再次加热翻炒，散去部分水气并重新整形。","复包闷黄：第二次包闷，甜醇感在这一步变得更完整。","足火干燥：低温慢烘至足干，固定香气与外形。"]},{"type":"paragraph","text":"君山银针最要紧的是「两闷两炒」——闷黄分两次做，中间夹一道复炒。第一次包闷紧接在杀青之后，芽头还带着湿气，属于湿坯闷黄：湿热作用下叶绿素被破坏、茶多酚发生非酶促氧化，苦涩的酯型儿茶素部分水解，简单儿茶素比例上升。复炒把水分收一收、形状理一理，第二次包闷再补一轮转色转味。所以它的甜醇不是靠原料自带，而是这两次包闷一点点攒出来的，刺激性也因此低于绿茶。这两次包闷的分寸相当难拿：第一次闷得短了转不过来，闷得久了会闷出浊味；复炒的火候又直接决定第二次包闷的起点。同一片茶园的单芽，做得好与做得一般，差别就落在这两次包闷的温度和时长上。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"干茶看三点：全芽、挺直、白毫明显，色泽是银白微黄而不是翠绿。注水后汤色浅黄明亮，香气以甜香、嫩香为主，尾上有一点淡淡的锅巴香。入口甜醇鲜爽，几乎没有苦涩，汤感细软，叶底嫩黄、芽头完整。用透明玻璃杯冲泡还有一层趣味：芽头在杯中会反复沉浮，传统上称为「三起三落」，属观赏性的传统经验描述，不必当成固定的物理规律去验证。这种沉浮之所以常被提起，是因为只有全芽、挺直、毫毛密的茶才容易在杯中呈现；芽头断碎、毫毛稀疏的茶，观赏效果会弱很多。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看毫毛的密度和芽身的挺直程度，这是判断黄芽茶嫩度最直观的线索。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"温杯与投茶","text":"玻璃杯先用热水烫过，倒掉水再投茶 3 g，配 150 ml 水，约 1:50。"},{"title":"注水","text":"水温控制在 80–85℃，先注少量水没过芽头，稍等十几秒再续到七分满；芽头细嫩，不要用持续沸腾的水，也别一次注满。"},{"title":"出汤节奏","text":"第一泡 20–30 秒即可出汤，之后每泡延长约 10 秒，通常可冲 3–4 泡。"},{"title":"赏形与续水","text":"全程不盖盖子，方便观察芽头沉浮；喝到剩三分之一时续水，不要等见底。"}]},{"type":"tip","tone":"warning","title":"两个常见误区","text":"一是把「绿茶放黄了」当成黄茶。黄茶的黄来自主动的闷黄工艺，是有控制的结果；绿茶变黄属于存放中的氧化劣变，往往伴随陈味、香气散失，是品质下降而不是换了茶类。二是「黄茶养胃」的说法，闷黄让儿茶素刺激性相对降低只是成分层面的相对温和，属传统经验表述，茶不是胃药，胃部不适仍应遵医嘱，也别空腹喝浓茶。"},{"type":"paragraph","text":"搭配上，清淡茶点、少量桂花都能顺着它的甜香走，蜂蜜要等茶汤降温后再加。不建议加牛奶，奶味会压掉清雅的香气和甜醇感，也不建议与肉桂、八角一类重香料同饮。季节上春与初夏最应景，甜醇清爽、刺激性低，适合换季的过渡期；它也是茶龄短、怕苦怕涩的人比较容易接受的一款。存放只要密封、避光、防潮、防异味即可，量大可以冷藏，取出后回到室温再开封，免得水汽凝结。它以清甜鲜醇见长，香气散得比较快，开封后宜尽早喝完。"}]', '["product_junshan_yinzhen_50"]', 1, 300, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('6201100048852134144', 'tea_mengding_huangya', 'mengding-huangya', '蒙顶黄芽', '[]', 'yellow', '四川省', '雅安市', '名山区蒙顶山', '产自四川蒙顶山，扁直显毫、色泽嫩黄，甜香浓郁带花香，汤感甘醇，闷黄时间偏长的一款黄芽茶。', '["采摘单芽或一芽一叶初展","杀青","初包闷黄","复锅","复包闷黄","三炒","摊放","烘焙"]', '["甜香","花香","嫩香"]', '["甘醇","鲜爽","甜感明显"]', '["上午温和提神","下午茶","餐后淡饮","不常喝茶者入门"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡延长约 10 秒","infusionCount":{"min":3,"max":4},"methodTip":"嫩芽忌沸水、忌久闷；玻璃杯可观形，白瓷盖碗更衬黄亮汤色。"}', '密封、避光、防潮、防异味，短期喝不完可冷藏，避免与香料、咖啡同放。', '甜香与鲜爽是主要看点，宜趁鲜饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831908.jpg', '[]', '[{"type":"heading","level":3,"text":"蒙顶山上的早期茶事"},{"type":"paragraph","text":"蒙顶黄芽产自四川省雅安市名山区的蒙顶山。蒙顶山是中国有文字记载最早的种茶地之一，茶史脉络长，茶事延续千年，山上至今保留着成片茶园。当地海拔与云雾条件适合茶树生长，芽头肥壮、内含物足，这也是它敢把闷黄做得久的本钱。它是黄芽茶，原料取饱满的单芽或刚展开的一芽一叶初展，干茶扁直显毫、色泽嫩黄。黄茶在六大茶类里产量最小，蒙顶黄芽属于其中工艺最细的一路，闷黄时间拉得比多数同类更长，香气和甜感都更饱满。"},{"type":"heading","level":3,"text":"三炒三闷的工艺路径"},{"type":"list","ordered":false,"items":["采摘单芽或一芽一叶初展：嫩度是风味的地基。","杀青：高温钝化酶活性，固定清鲜。","初包闷黄：趁热包起保温，开启转黄与转甜。","复锅：再次加热翻炒，散去水气并整形。","复包闷黄：第二次包闷，甜香继续累积。","三炒：第三次炒制，把水气进一步收干、条索压扁。","摊放：让水分在芽叶之间重新分布均匀。","烘焙：低温烘干，定香定形。"]},{"type":"paragraph","text":"蒙顶黄芽的特点是闷黄「做得很足」。它的初包、复包都发生在杀青之后、茶叶还带湿气的阶段，属于湿坯闷黄；两次包闷之间用复锅和三炒反复调整水分与形状，时间比一般黄芽茶更长。湿坯闷黄的水分来自杀青后的余水，包起来之后堆内温度能维持一段时间，叶色由绿转黄、香气由青草气转向甜香，都发生在这段时间里。包得松紧、翻堆的时机、室温高低，都会影响最终转黄的程度。湿热环境下叶绿素被破坏、茶多酚发生非酶促氧化，苦涩的酯型儿茶素部分水解，可溶性糖和氨基酸相对留得更多，于是「黄汤黄叶」和明显的甜感一起出现。这道工序做轻了接近绿茶，做重了会闷出浊味，分寸全靠制茶时的经验——同样的原料，闷黄差上一两个小时，汤色与甜感就能喝出区别。黄茶整体产量小，闷黄又是费工费时的工序，这也是它在六大茶类里始终没能像绿茶那样普及的原因之一。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"干茶扁直、毫毛清晰，颜色是嫩黄而不是青绿。汤色黄亮，香气甜香浓郁，中段能闻到一点花香。入口甘醇鲜爽，甜感来得直接，咽下之后口腔里留着一层柔和的回甜，叶底嫩黄匀整。它和同为黄芽茶的君山银针放在一起比较容易分辨：蒙顶黄芽条索是扁的、香气更甜更浓，君山银针则是圆挺的芽头、走清雅一路。如果拿它和绿茶并排对比，差别也很明显：绿茶的鲜爽偏收敛，茶汤放凉后涩感更突出，蒙顶黄芽则从头到尾都在甜醇这一侧。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"透明玻璃杯或白瓷盖碗均可，投茶 3 g，配 150 ml 水，约 1:50。"},{"title":"水温","text":"80–85℃ 最合适，水烧开后稍晾一会再冲，别用沸水直接冲嫩芽；水温高了，甜香会被压成闷气。"},{"title":"出汤","text":"第一泡 20–30 秒出汤，之后每泡延长约 10 秒，可冲 3–4 泡。"},{"title":"续水","text":"喝到杯中剩三分之一时续水，全程不盖盖，避免闷出熟汤气。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"别把黄茶当成绿茶的「变种」——在通行的六大茶类分类体系里，黄茶与绿茶并列，分类依据正是独有的闷黄工序，不是汤色深浅，闷黄也不是「绿茶没做好」的补救办法。另外，「闷黄越久越好」同样不成立：闷过头会出浊味与闷气，蒙顶黄芽闷得久，靠的是制茶师在每一轮里对温度和时间的把控。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配上，川式清淡茶点、少量桂花都能接住它的甜香，蜂蜜降温后再加。不建议加牛奶，也不建议吃重麻辣的菜时同饮，强烈辛香会把甜香盖住。不常喝茶的人可以拿它入门：水温低一点、出汤快一点，几乎不会泡出苦味。存放讲究密封、避光、防潮、防异味，短期喝不完可以冷藏，但取出后要等回到室温再开封，免得水汽凝结；一次买得多时可以按一周的量分装，减少开袋后的空气交换。它以甜香和鲜爽见长，香气散得比较快，宜趁鲜喝完。买的时候可以留意采摘时间与嫩度，芽头越肥壮，香气越细，也越怕受潮；产地风味差异不大，工艺是否到位才是决定甜感的关键。"}]', '["product_mengding_huangya_50"]', 0, 310, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3272000355873956807', 'tea_huoshan_huangya', 'huoshan-huangya', '霍山黄芽', '[]', 'yellow', '安徽省', '六安市', '霍山县大化坪、漫水河、太阳乡等', '形似雀舌、色泽嫩黄，清香中带熟栗香与甜香，汤色黄绿明亮；闷黄在干坯阶段完成，鲜爽与甜醇兼具。', '["杀青","毛火","足火做形","摊放闷黄","拣剔","复火"]', '["清香","熟栗香","甜香"]', '["鲜醇","甘爽","甜感清晰"]', '["春日清饮","办公桌边","餐后淡饮","与绿茶对比品鉴"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","白瓷盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡延长约 10 秒","infusionCount":{"min":3,"max":4},"methodTip":"嫩芽忌沸水久闷；白瓷器皿衬底更易看出黄绿明亮的汤色。"}', '密封、干燥、避光、防异味，开封后尽量减少空气接触，量大可按周分装。', '以清新鲜甜为主要品饮目标，宜趁鲜饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922014.jpg', '[]', '[{"type":"heading","level":3,"text":"大别山北麓的黄芽"},{"type":"paragraph","text":"霍山黄芽产自安徽省六安市霍山县，大化坪、漫水河、太阳乡一带是传统产区，茶园多在大别山北麓的山坡上，云雾多、昼夜温差大，芽叶积累得比较足。它同属黄芽茶，外形像雀舌——一芽一叶初展压成小巧的扁平状，色泽嫩黄。霍山产茶的历史长，黄芽是其中名气最大的一支。需要分清的是，霍山黄芽与霍山黄大茶同出一个县却是两种茶：黄芽采的是细嫩芽叶，做出来清甜细腻；黄大茶用的是成熟大叶和茶梗，滋味浓烈。"},{"type":"heading","level":3,"text":"先做形，后闷黄"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定鲜叶本味。","毛火：初烘去水，让叶子柔软便于做形。","足火做形：边烘边压，把条索做成雀舌状。","摊放闷黄：在干坯阶段摊放，让茶叶缓慢转黄转甜。","拣剔：剔除杂物与不合格的条索。","复火：补火提香，稳定品质。"]},{"type":"paragraph","text":"霍山黄芽的闷黄不紧接在杀青之后做，而是放在足火做形之后、茶叶已经基本干燥的干坯阶段，属于干坯闷黄。干坯阶段的水分已经很少，转色靠的是堆内余温与少量水汽的配合，所以时间要拉长、动作要轻。这一步和君山银针的湿坯包闷是两条路：湿坯闷黄水分足、转色快，滋味柔和得早；干坯闷黄转色慢，却让熟栗香一类的香气物质形成得更好，氨基酸也留得比较多。同样是黄芽茶，两种闷黄做出来的风格是喝得出来的：一个更柔、更早出甜，一个更爽、香气更立体。所以霍山黄芽的味道是鲜爽和甜醇同时在——先是清鲜，接着是熟栗子般的甜香与回甘。闷黄之后的复火不能省，它把水分收干、把香气定住，也让成品更耐存放。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"干茶形似雀舌，色泽嫩黄，条索紧结匀整。汤色黄绿明亮，比君山银针的浅黄多一点绿意。香气以清香打底，带熟栗香和甜香。入口鲜醇甘爽，甜感清晰但不腻，汤感比一般黄芽茶更显爽利，叶底嫩黄。对比绿茶喝会更清楚：同样是一芽一叶的嫩度，绿茶的收敛感明显，霍山黄芽入口先鲜后甜，咽下去之后口腔里是暖的。辨认时可以记一句：高山、雀舌、栗香。黄茶整体产量小，能买到的霍山黄芽多为春茶，选新不选陈是稳妥的原则。"},{"type":"tip","tone":"info","title":"识茶提示","text":"留意条索的扁平度与色泽的嫩黄感，青绿色明显时多半是偏绿的工艺。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"3 g 茶配 150 ml 水，约 1:50；白瓷盖碗或玻璃杯都合适，一人独饮用小杯更好控量；若一次只泡一杯，投茶量可以减到 2 g，滋味更清淡。"},{"title":"水温","text":"80–85℃，水开后稍晾半分钟再注水，嫩芽怕烫。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡延长约 10 秒，可冲 3–4 泡；出汤要把水倒净再续水。"},{"title":"看汤色","text":"用白瓷器皿衬底，更容易看出它黄绿明亮的汤色。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"「绿茶放久了变黄就是黄茶」是流传最广的一条误传。黄茶的黄来自主动的闷黄工艺，是有控制的结果；绿茶变黄属于存放中的氧化劣变，往往带着陈味、香气也散了，是品质下降而不是换了茶类。另外别用沸水长时间闷泡它，嫩芽久闷会失去鲜爽，只剩闷味。还有一点值得记：黄芽茶与黄大茶虽然同出霍山，原料与工序都不同，风味更是两路，买的时候看清名字。"},{"type":"paragraph","text":"搭配徽式清淡茶点、少量桂花都合适，蜂蜜降温后再加。不建议加牛奶，也不建议配重糖点心，甜味叠甜味反而把栗香压住。想感受它和绿茶的区别，可以拿一杯同价位的绿茶并排冲：绿茶的鲜爽偏收敛，霍山黄芽的甜醇更靠后、更柔和。季节上春与初夏喝最应景，餐后淡饮也不抢味。存放上，密封、干燥、避光、防异味，开封后减少空气接触；一次买得多可以按一周的量分装，其余密封冷藏，趁鲜喝完香气最好。它与霍山黄大茶同产一县，若想一次喝懂黄茶的两端，可以把两款各买少量并排冲泡：一杯雀舌清甜，一杯大叶焦香，差别比名字看起来大得多。"}]', '["product_huoshan_huangya_50"]', 0, 320, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3667959876642043699', 'tea_weishan_maojian', 'weishan-maojian', '沩山毛尖', '[]', 'yellow', '湖南省', '长沙市', '宁乡市沩山乡', '条索微卷、色泽黄亮，带传统熏烟形成的独特烟香与甜香，滋味醇甜爽口、有回甘，是黄小茶里风味最有个性的一款。', '["杀青","揉捻","闷黄","烘焙","熏烟","拣剔"]', '["烟香","甜香","烘烤香"]', '["醇甜","爽口","有回甘"]', '["偏好烟香者品鉴","秋冬热饮","湘式重油餐后","餐后淡饮"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":85,"max":90},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":30,"max":30},"laterSteepTip":"之后每泡延长 10–15 秒","infusionCount":{"min":4,"max":5},"methodTip":"投茶 3–4 g 均可，宁少勿多；水温略高于黄芽茶，才能把烟香与甜香一起冲开。"}', '密封、避光、干燥、防异味；茶吸味强，不要与香料、咖啡同放。', '烟香与甜香是主要识别点，开封后宜尽快喝完。', '含咖啡因，避免空腹浓饮与睡前饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832432.jpg', '[]', '[{"type":"heading","level":3,"text":"沩山：一座佛山的茶"},{"type":"paragraph","text":"沩山毛尖产自湖南省长沙市宁乡市沩山乡。沩山是佛教名山，山上寺院与茶园相伴的历史很长，山中多云雾，寺院周边的茶园一直延续着比较传统的管理方式，茶在当地既是饮品也是待客的礼数。它属于黄小茶——用比黄芽稍成熟的原料做成，条索微卷、色泽黄亮。黄小茶的原料等级介于黄芽与大茶之间，做成之后汤感更厚、耐泡度也更好，适合当日常口粮茶，而不是偶尔赏玩的茶。黄茶在六大茶类里产量最小、认知度也最低，很多人喝过绿茶却没有认真喝过一杯黄茶，而沩山毛尖是黄茶里风味最有辨识度的一款。"},{"type":"heading","level":3,"text":"闷黄之后还有一道熏烟"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定鲜叶的本味。","揉捻：轻微破壁，让内含物更好浸出，条索成形。","闷黄：趁热堆积保温，在湿热中转黄转甜。","烘焙：散去水气，固定香气。","熏烟：传统上用枫球、黄藤熏制，烟气进入茶叶。","拣剔：拣去杂物，分级定等。"]},{"type":"paragraph","text":"沩山毛尖的闷黄发生在揉捻之后，茶坯还带着水分，属于湿坯闷黄：堆闷让叶绿素破坏、茶多酚发生非酶促氧化，苦涩感降下来、甜醇感升上去。湿坯闷黄的好处是转色快、甜醇来得直接，代价是水分高、不好控，堆温高了容易闷过头，所以翻堆的时机要盯得很紧。但它真正与众不同的一步是后面的熏烟——传统上以枫球或黄藤熏制，用的是当地山里的材料，烟气被茶叶吸附，形成独特的烟香，讲究「烟香入茶而不夺茶」，闻起来暖而不冲，喝下去甜味还在。这一步在另外五款黄茶里都没有，所以喝惯了清甜的君山银针，第一次喝沩山毛尖往往会被那股烟香提醒：原来这也是黄茶。它在湖南本地多作日常饮用，不必像黄芽茶那样讲究器皿，一把白瓷壶就够用。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"干茶条索微卷、色泽黄亮，能看到少量茶梗，不像全芽茶那样秀气。汤色橙黄明亮，比黄芽茶深一档。香气是烟香与甜香叠在一起，烟香不冲，是那种柴火烘过的暖香。入口醇甜爽口，有回甘，汤感比黄芽茶厚。它和同为黄茶的君山银针放在一起对比很有说服力：一个是全芽清甜，一个是带梗带烟香，同一类茶可以差这么远。喜欢的人很爱，不习惯烟香的人会觉得偏个性——这也正是它的辨识度所在。温杯之后先闻香再喝，烟香与甜香的层次会更清楚。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"3–4 g 茶配 150 ml 水，用白瓷盖碗或瓷壶，别用太小的杯子；它比黄芽茶耐泡，但投茶别过量。"},{"title":"水温","text":"85–90℃，比黄芽茶略高，才能把烟香和甜香一起冲开。"},{"title":"出汤","text":"第一泡约 30 秒出汤，之后每泡延长 10–15 秒，可冲 4–5 泡。"},{"title":"续水","text":"烟香类茶香气浓，末泡别泡太久，出现寡水味就停。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"它的烟香来自传统熏烟工艺，是当地一直以来的做法，不是「坏了」或串味，和缺陷茶里的烟焦味是两回事，不必按缺陷去理解；干茶闻起来烟香明显，冲泡之后烟香会退到背景里、甜香浮上来，这个先后顺序也是辨认它的方法。但也正因为烟香浓烈，不建议睡前饮用；空腹时也建议先吃点东西再喝，避免浓茶带来的不适。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"它适合配湘式咸鲜的餐后时光，也适合搭淡味坚果；湖南本地饮食偏重油重辣，餐后一壶这样的茶是传统上的搭配习惯。不建议配清淡茶点，风味不对等，也不建议与强香精饮品同饮；牛奶同样不合适，会遮掉烟香与甜香的层次。季节上春秋两季最舒服，秋冬热饮也不错。存放要格外注意防异味——茶吸味，和香料、咖啡放在一起，烟香与甜香很容易被串掉；密封、避光、干燥保存，开封后尽快喝完。买回来可以先闻干香：如果烟香里夹着霉味或酸味，那不是熏烟的效果，而是受潮了。黄茶整体产量小，熏烟类的黄茶更少见，它在六大茶类里几乎没有替代品——喜欢烟香的人往往一试就记住了。"}]', '[]', 0, 330, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4876252673234894013', 'tea_pingyang_huangtang', 'pingyang-huangtang', '平阳黄汤', '[]', 'yellow', '浙江省', '温州市', '平阳县及苍南、泰顺等浙南茶区', '浙江平阳的传统名茶，条索细紧、色泽黄绿，清香里带甜玉米香，汤感柔顺鲜甜，工艺讲究九烘九闷。', '["杀青","揉捻","九烘九闷","烘干"]', '["清香","甜玉米香","嫩香"]', '["鲜醇","甘甜","汤感柔顺"]', '["上午温和提神","午后清口","夏日冷泡","清淡茶点搭配"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:50","temperatureC":{"min":80,"max":85},"vessel":["玻璃杯","盖碗"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"之后每泡延长约 10 秒","infusionCount":{"min":3,"max":4},"methodTip":"嫩芽忌沸水久闷；也可冷泡，1 g 茶配 100 ml 凉白开，冷藏约 5 小时。"}', '密封、避光、防潮、防异味；冷藏前先分装，避免反复进出冰箱。', '以细柔的甜感见长，宜趁鲜饮用，开封后两三个月内喝完比较理想。', '含咖啡因，避免空腹浓饮与睡前饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832431.jpg', '[]', '[{"type":"heading","level":3,"text":"浙南平阳的「黄汤」"},{"type":"paragraph","text":"平阳黄汤产自浙江省温州市平阳县，苍南、泰顺一带的浙南茶区也有生产。名字里的「黄汤」直白地点出它的特征——汤色杏黄。浙南茶区山海相依、雨水充沛，茶树发芽早，芽叶含水量足，这也是它能把烘与闷反复交替做上多轮的底气。它属于黄小茶，原料等级介于黄芽与大茶之间，条索细紧、色泽黄绿，是浙江的传统名茶之一。黄茶整体产量在六大茶类里最小，这款茶长期只在产地及周边流通，很多茶客听说过黄茶，却未必见过平阳黄汤，更少有人知道它的闷黄要反反复复做上许多遍。它的香气不张扬，第一泡最干净、第二泡甜感最明显，这个变化值得留意。"},{"type":"heading","level":3,"text":"九烘九闷"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定鲜叶本味。","揉捻：轻度破壁，条索成形。","九烘九闷：烘一次、闷一次，反复交替进行多轮。","烘干：收干水分，固定香气与汤色。"]},{"type":"paragraph","text":"平阳黄汤的工艺特点写在名字里——「九烘九闷」，烘与闷交替进行、反复多遍。烘是散水气、定香气，闷是趁热保温让茶叶在湿热中继续转黄转甜；一烘一闷为一轮，轮次多，水分下降得慢，转色转味就走得格外均匀。一轮烘闷下来，水分只降一点，香气却往前走一小步，累积起来就是它的细腻。具体轮次各家略有差异，共同点是次数多、单次处理轻，宁可多来几轮，也不让茶叶在一轮里被逼得太急；「九」在这里是形容次数多，不必理解成精确的九次。多次烘闷让可溶性糖与氨基酸保留得比较好，甜醇度突出、刺激性更低，汤感也格外柔顺。对比来看，君山银针是两次包闷，霍山黄芽是干坯摊放闷黄，平阳黄汤走的是「少量多次」的中间路线，这也解释了它为什么甜得柔、汤感细。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"干茶条索细紧、色泽黄绿，比霍山黄芽更细更紧，芽毫不显。汤色杏黄明亮，清透不浑。香气以清香打底，带一点甜玉米香和嫩香，闻起来干净。入口鲜醇甘甜，汤感柔顺，几乎没有粗糙的收敛感，回甘平稳，叶底嫩黄匀整。它和霍山黄芽容易混：两者都偏细紧黄绿，区别在香气——霍山黄芽是熟栗香，平阳黄汤是甜玉米香，汤色上后者更偏杏黄。它不属于香气张扬的类型，胜在细、柔、甜这三个字，很适合第一次接触黄茶的人。它在冷泡里尤其讨喜，低温下甜感更突出、苦涩更少。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"3 g 茶配 150 ml 水，约 1:50；玻璃杯或盖碗均可。"},{"title":"水温","text":"80–85℃，水开后稍晾再冲，避免沸水久闷。"},{"title":"出汤","text":"第一泡 20–30 秒，之后每泡延长约 10 秒，可冲 3–4 泡；出汤时把水倒净再续水，免得留下的汤越泡越浓。水质偏硬的地区建议用纯净水，汤色与香气都会更干净。"},{"title":"冷泡","text":"按 1 g 茶配 100 ml 凉白开，密封冷藏约 5 小时，滤出茶叶即可，甜感柔和。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"「黄茶是绿茶的一种，只是颜色不同」并不成立。在通行的六大茶类分类体系里，黄茶与绿茶并列，分类依据正是独有的闷黄工序；工艺不同，成分与风味体系也不同——绿茶鲜爽偏收敛，黄茶甜醇偏柔和。另外，冷泡时间不必拖到跟白茶一样长，五小时左右甜感就出来了，泡太久反而会带出叶底的青气；冷泡虽顺口，也要计入当天的饮茶总量。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配清淡茶点和少量桂花都合适，蜂蜜降温后再加。夏天可以冷泡后加一片青柠或两片薄荷，风味清爽；不建议加牛奶，也不建议配重糖浆，都会把它的细甜压掉。四季里春夏两季最应季，午后清口也很合适。存放注意密封、避光、防潮、防异味，冷藏前先用密封袋分装，避免反复进出冰箱带来的温差与受潮；黄小茶比黄芽茶稍耐放一些，但香气同样会走，开封后两三个月内喝完比较理想。它的产量有限，买到时可以留意年份与密封状态；开袋后若有明显的陈味或酸味，多半是存放出了问题，而不只是香气变淡。"}]', '[]', 0, 340, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('8423885532150954755', 'tea_huoshan_huangdacha', 'huoshan-huangdacha', '霍山黄大茶', '[]', 'yellow', '安徽省', '六安市', '霍山县及金寨、岳西等大别山区', '黄茶里原料最成熟、滋味最浓烈的一款，叶片大而梗长，高火焦香突出，浓烈醇厚而耐泡，秋冬煮饮也合适。', '["杀青","揉捻","堆积闷黄","拉小火","拉老火"]', '["高火焦香","锅巴香","烘烤香"]', '["浓烈","醇厚","微苦回甘"]', '["重油餐后","秋冬热饮","办公室焖泡","偏好浓强焦香者"]', '{"teaGrams":4,"waterMl":150,"ratio":"1:38","temperatureC":{"min":90,"max":95},"vessel":["瓷壶","紫砂壶","盖碗"],"firstSteepSeconds":{"min":30,"max":40},"laterSteepTip":"之后每泡延长 10–15 秒","infusionCount":{"min":5,"max":7},"methodTip":"它是六款黄茶里最耐高温的一款，投茶可增至 5 g，也适合瓷壶焖泡。"}', '密封、避光、干燥、防异味；高温烘焙的茶香气稳定，但仍怕潮。', '出现霉味、酸馊味或刺鼻异味时不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195831907.jpg', '[]', '[{"type":"heading","level":3,"text":"霍山的另一种黄茶"},{"type":"paragraph","text":"霍山黄大茶产自安徽省六安市霍山县，金寨、岳西等大别山区也有生产。大别山区山高雾多，茶树长得慢、叶片厚实，做成大茶正合适。它与霍山黄芽同出一个县，却是两种完全不同的茶：黄芽采的是细嫩芽叶，做成雀舌状的小条，清甜细腻；黄大茶用的是成熟度高的大叶和茶梗，叶片大、梗长，色泽黄褐，是黄茶里原料最成熟、滋味最浓烈的一类。传统上大别山区把这类茶当作日常饮用的茶，用大壶冲泡，一家人喝一天。两杯茶并排放在一起，从外形就能一眼分开。"},{"type":"heading","level":3,"text":"堆积闷黄与拉老火"},{"type":"list","ordered":false,"items":["杀青：高温钝化酶活性，固定鲜叶本味。","揉捻：破壁出汁，为后续转化做准备。","堆积闷黄：成堆保温，时间较长，可达数天。","拉小火：中温烘焙去水，稳住内质。","拉老火：约 130–150℃ 的高温烘焙，形成焦香。"]},{"type":"paragraph","text":"霍山黄大茶有两道关键工序。第一道是堆积闷黄，茶叶成堆保温，时间可以拉长到数天，属于堆积闷黄一路；原料成熟、水分足，湿热中的非酶促氧化与美拉德反应都做得比较充分。堆积的时间以天计，堆内温度与湿度都要盯着，翻堆的时机决定了转色是否均匀，这一步做不好，后面拉老火再到位也补不回来。第二道是拉老火，用约 130–150℃ 的高温烘焙，这是黄茶里最高的火功，美拉德反应进一步推进，形成焦香类的香气物质与部分褐色聚合物；茶叶的香气在烘焙中被彻底重塑，从青气走向焦香，汤色也从浅黄转为深黄。原料成熟，茶多酚与可溶性糖的基数本来就大，所以它不需要靠工艺去「做甜」，甜是原料给的，工艺做的是把浓烈变得圆润。黄茶里以成熟叶为原料的本来就不多，黄大茶算是把这条路走到了极致。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"干茶叶片大、茶梗长，色泽黄褐，看上去粗犷，不像芽茶那般精致。汤色深黄明亮，比前几款都深。香气以高火焦香、锅巴香最突出，热闻时甚至有点像刚出锅的锅巴。入口浓烈醇厚，中段有一点微苦，苦很快化开，转成回甘，汤感厚实。它的耐泡度在黄茶里数一数二，泡到五六泡仍然有味，叶底黄褐、叶片大而完整，能看到明显的茶梗。它和霍山黄芽的差别，用一句话概括就是：一个吃嫩，一个吃火。如果平时喝惯了清香型的茶，第一口可能会觉得重，可以先把投茶量减半适应。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"4 g 茶配 150 ml 水，约 1:38；想喝得更浓可以加到 5 g。瓷壶、紫砂壶或盖碗都合适。"},{"title":"水温","text":"90–95℃。它是六款黄茶里最耐高温的一款，不必刻意降温。"},{"title":"出汤","text":"第一泡 30–40 秒出汤，之后每泡延长 10–15 秒，可冲 5–7 泡；觉得第一泡偏浓，可以把时间压到 30 秒以内。"},{"title":"焖泡","text":"办公室可用瓷壶一次投茶焖泡，随倒随续水，能撑过半天；用盖碗冲泡时可以适当加大投茶量、缩短出汤时间，滋味更集中。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"它的焦香来自拉老火的高温烘焙，是工艺特征，不是焙糊。但也正因为滋味浓，空腹时别喝浓茶汤，胃部容易反酸或有溃疡的人应避开浓饮；含咖啡因，睡前三到四小时也建议停饮。至于「消食化滞、暖胃」这类说法，属大别山区的传统经验表述，不能当作功效承诺。另外，浓不等于伤身，关键在浓度与时机：淡一点、饭后喝，比空腹来一大杯浓汤稳妥得多。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"它最合适的位置是重油餐后——火锅、烤肉之后来一壶，传统上就是大别山区解腻的主力场景，配咸香茶点也顺。不建议加牛奶，也不建议配甜腻点心，甜与焦香会互相打架。秋冬季喝最应景，在产地常被当作日常口粮茶，一壶能从早喝到晚。如果只喝过绿茶和红茶，它可以当作认识黄茶另一端的样本：同样是黄茶，也能做得这么浓。存放上，密封、干燥、避光、防异味；高温烘焙的茶香气稳定，但同样怕潮，一旦受潮出现霉味、酸馊味或刺鼻异味，就不要再喝了。它在产地还常被用来煮饮，天冷时投一小把进壶里慢煮，焦香会更浓，滚上两三分钟就够，别久煮。"}]', '[]', 0, 350, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4051196457869679063', 'tea_tieguanyin', 'anxi-tieguanyin', '安溪铁观音', '["铁观音"]', 'oolong', '福建省', '泉州市', '安溪县西坪、感德、祥华、剑斗等乡镇', '颗粒紧结砂绿，兰花香高扬；清香型鲜爽带音韵，浓香型焙火醇厚，靠反复摇青与包揉塑形。', '["晒青","晾青","摇青做青","杀青","揉捻","包揉","烘干","焙火（浓香型）"]', '["兰花香","焙火香","清花香"]', '["鲜爽","醇厚","回甘"]', '["秋日品饮","油腻餐后","功夫茶待客","午后专注"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["白瓷盖碗","紫砂壶"],"firstSteepSeconds":{"min":5,"max":15},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":7,"max":10},"methodTip":"球形茶第一泡可稍等舒展，全程沸水、快出汤。"}', '清香型密封后低温保存；浓香型密封、避光、防潮、防异味。', '不同焙火程度保存方式不同，以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925058.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"安溪铁观音产于福建省泉州市安溪县，西坪、感德、祥华、剑斗等乡镇是传统核心产区。它属闽南乌龙，氧化程度按类型分档：清香型约15%—25%，浓香型约25%—40%，陈香型更高。名字里的「铁」形容颗粒紧结重实，「观音」则来自当地流传的传说。产区常提的「音韵」，说的是兰花香与回甘在口腔里留下的综合感受，是一种风味描述，不是等级保证。传统上有「秋饮青茶」的说法，属传统经验表述：秋天干燥，半发酵茶性平，传统认为既清热又不至过于寒凉。实际选择更灵活，清香型适合春夏，浓香型适合秋冬。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["晒青：借日光与温度让鲜叶适度失水，为做青打底。","晾青：摊晾散热，让叶片水分重新分布，避免闷堆发热。","摇青做青：反复四到五次，摇动与摊晾交替，促使叶缘细胞破损、酶促氧化发生。","杀青：高温钝化酶活性，把做青形成的香气与滋味固定下来。","揉捻：初步塑形，并让内含物附着在叶表，冲泡时更容易释放。","包揉：用布巾包起反复揉压，把茶叶收成紧结的球形。","烘干：降低含水量，便于存放。","焙火：浓香型在烘干后再经焙火，得到焙火香与更醇厚的口感。"]},{"type":"paragraph","text":"做青是铁观音的分水岭。摇青时叶缘受摩擦破损，多酚类物质在酶的作用下缓慢氧化，香气物质随之生成并积累，摇与晾交替的节奏，很大程度上决定了成品是偏清花香还是偏熟果香。包揉则解决形态问题：闽南乌龙追求颗粒紧结，只有反复包揉才能把条索收成球状，冲泡时内含物的释放也更有层次。颗粒的紧结程度还会直接影响冲泡表现，包揉越紧实，前几泡释放越慢，可冲的泡数也越多，这也是它常被用来陪伴长时间专注的原因。还要提一句，现代清香型降低了发酵度与焙火度，叶缘红边常常不明显，所以「绿叶红镶边」并不是所有铁观音的必备特征。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形看颗粒与色泽，紧结重实、砂绿起霜是清香型常见的样子。汤色走两路：清香型金黄带绿，浓香型橙黄偏深。香气上，清香型以兰花香高扬为主，浓香型则是焙火香压着花香；闻香时不妨分两次比较，热嗅偏焙火与熟香，杯盖冷却后的冷香更容易显出清花香，这也是判断类型的实用方法。滋味方面，清香型鲜爽、回甘快，浓香型醇厚、喉韵更长。铁观音的香气物质含量丰富，橙花叔醇、吲哚、茉莉内酯等成分是它高香的物质基础，也正是它常被误认成绿茶、却始终属于乌龙茶的原因。"},{"type":"tip","tone":"info","title":"识茶提示","text":"抓一小撮看颗粒：紧结重实、色泽砂绿，是清香型铁观音常见的外形。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"白瓷盖碗最通用，不吸香；浓香型可用紫砂壶。投茶7—8克配100—120毫升水，球形茶可先温润一遍帮助舒展。"},{"title":"沸水高冲","text":"必须用100℃沸水。球形乌龙结构紧实，水温不足香气出不来，滋味也会显得水薄。"},{"title":"快出汤","text":"第一泡5—15秒即出，之后每泡延长5至10秒。宁可短一点，也不要闷出苦涩。"},{"title":"续水","text":"一般可冲7—10泡。后半程适当延长坐杯时间，滋味更完整。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是把清香型铁观音当绿茶。分类依据是工艺而不是汤色，它经过做青，属半发酵的乌龙茶。二是把「音韵」当成等级标签。它是对兰花香与回甘的综合描述，具体品质仍要看原料、工艺与保存。另外，清香型因茶多酚保留较多，空腹饮用容易胃部不适，建议放在餐后，睡前6小时也不宜再饮。"},{"type":"paragraph","text":"铁观音适合油腻餐后饮用，也是功夫茶待客的常见选择，耐泡的特点让它很适合慢慢续水。搭配上可以配闽南咸香茶点或淡味坚果，牛奶和厚奶会盖住兰花香，不建议。传统经验认为铁观音性味随类型而变，清香型偏凉、浓香型偏温，味甘微苦，归脾胃经，餐后饮用可去腻生津，这属于传统表述，不等同于现代研究结论。存放看类型：清香型密封后低温保存，浓香型密封、避光、防潮、防异味即可。无论哪种，都建议按包装标注的期限喝完，放久了香气会明显走低。"}]', '["product_tieguanyin_100"]', 1, 400, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4823801346719822543', 'tea_dahongpao', 'wuyi-dahongpao', '武夷大红袍', '["大红袍","武夷岩茶大红袍"]', 'oolong', '福建省', '南平市', '武夷山市，核心正岩产区为三坑两涧', '条索紧结乌润，焙火香与花香交融，滋味醇厚甘活、喉韵深长，是武夷岩茶岩韵的代表性表达。', '["萎凋","做青","杀青","揉捻","初焙","复焙","炖火"]', '["焙火香","焦糖香","花香"]', '["醇厚","甘活","喉韵绵长"]', '["大餐餐后","秋冬暖饮","商务待客","长时间品饮"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":8,"max":10},"methodTip":"醒茶后沸水高冲，激发焙火香。"}', '密封、避光、防潮、防异味，阴凉处存放。', '焙火型岩茶退火后香气更沉稳，具体期限以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923290.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"大红袍产于福建省南平市武夷山市，属闽北乌龙中的武夷岩茶。核心正岩产区集中在武夷山风景区的三坑两涧，即牛栏坑、慧苑坑、倒水坑、流香涧、悟源涧。市面上的大红袍主要有两类：一类是母树无性繁殖的纯种后代，一类是商品拼配大红袍，两者都属于正常且合规的商品。有一点必须说清楚，武夷山大红袍母树仅存6株于九龙窠，2006年起已停止采摘，任何以母树大红袍为名的销售都不可信。它适合秋冬，足火焙火型性偏温，寒季饮用更舒服。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：晒青或加温萎凋，让鲜叶失水软化。","做青：摇青与摊晾交替，做出岩茶特有的香气底子。","杀青：高温钝化酶活性，锁定做青的成果。","揉捻：塑形，并适度破坏叶细胞，让内含物更容易析出。","初焙：第一次烘焙，去除杂味、稳定品质。","复焙：再次焙火，让火香与花香逐步融合，走向醇厚。","炖火：传统炭焙的关键一步，低温长时间慢炖，形成足火风格。"]},{"type":"paragraph","text":"武夷岩茶的工艺重心在焙。多次焙火不只是为了干燥，更是让内部的香气与滋味重新排列：初焙去掉青杂气，复焙把火香压进茶骨，炖火用低温长时间的作用换来醇厚与耐泡。它的氧化程度约30%—50%，氧化与焙火并重，所以成品的风格既不似清香型乌龙那样锐利，也不像红茶那样甜熟，而是介于两者之间的一种沉稳。焙火后的茶通常需要一段退火期，刚焙好时火气偏重，放一段时间香气会由冲转沉，滋味也更顺，这也是同一款茶在不同时间喝会有差别的原因。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结，色泽乌润带宝光。汤色橙黄至橙红，清亮不浑。香气由焙火香打底，焦糖香、炭火香与花香叠在一起，冲泡两三次之后，花香会逐渐透出来，闻香时冷热两次的差别往往比前几泡更值得比较。滋味醇厚甘活，喉韵深长，而且极耐泡，八泡之后仍有余味。产区常说的「岩韵」，是对岩骨花香这一类综合感受的描述：汤感有骨力、回甘持久、香气清正。需要说明的是，岩韵的化学基础目前尚无统一结论，通常认为与正岩产区的丹霞地貌风化岩土壤、品种和焙火方式共同相关。它是一段风味描述，不是等级保证。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看条索与光泽：紧结匀整、乌润带光，是焙火型岩茶的常见外形。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器","text":"紫砂壶是经典选择，保温聚香；白瓷盖碗更便于观察汤色与香气变化。投茶7—8克配100—120毫升水。"},{"title":"醒茶","text":"第一遍用沸水快速润茶，3—5秒即出，让紧结的条索先舒展，也洗去表面浮尘。"},{"title":"沸水高冲","text":"用100℃沸水，高冲注水可以更好地激发焙火香。"},{"title":"快出汤再延长","text":"醒茶后第一泡5—10秒出汤，之后逐泡延长，可冲8—10泡以上。"}]},{"type":"tip","tone":"warning","title":"关于岩韵与火功","text":"岩韵是对综合感受的描述，不能用一句形容词代替品鉴，也不代表价格等级。另一个误区是把焙火味重当成品质好：焙火是为了融合香气，火气过重反而压住花香，通常需要一段退火期，口感才趋于稳定。此外，岩茶咖啡因含量偏高，睡前6小时不宜再饮，服药期与严重失眠人群也需要控制浓度与泡数。"},{"type":"paragraph","text":"大红袍适合大餐或重油餐后饮用，也是秋冬暖饮与商务待客的常见选择，耐泡的特点让它能贯穿整场谈话。搭配咸香卤味茶点、淡味坚果都合适，焙火香与黑糖、焦糖风味的甜点也能呼应；牛奶或厚奶不建议，会完全掩盖岩韵与焙火香。传统经验认为足火岩茶性温味甘微苦，餐后饮用可去腻生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味即可，足火茶退火之后香气会更沉稳。"}]', '["product_dahongpao_100"]', 0, 410, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2466608346967166575', 'tea_wuyi_rougui', 'wuyi-rougui', '武夷肉桂', '["肉桂","武夷岩茶肉桂"]', 'oolong', '福建省', '南平市', '武夷山市正岩产区，牛栏坑、马头岩、慧苑坑等', '条索紧结乌褐油润，桂皮香辛锐突出，滋味收敛性强、回甘快，是岩茶中最讲究品种香的当家品种。', '["萎凋","做青","杀青","揉捻","初焙","复焙","炭焙炖火"]', '["桂皮香","辛锐香","焙火香"]', '["辛锐","回甘快","收敛性强"]', '["重油餐后","秋冬暖饮","进阶品鉴","待客"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":8,"max":10},"methodTip":"沸水高冲激发桂皮香，前几泡出汤要快。"}', '密封、避光、防潮、防异味，阴凉处存放。', '焙火程度不同，退火时间也不同，以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；辛锐刺激感较强，胃敏感者宜减量。内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923894.jpg', '[]', '[{"type":"heading","level":3,"text":"品种与山场"},{"type":"paragraph","text":"武夷肉桂产于福建省南平市武夷山市，与大红袍、水仙同属武夷岩茶。它因茶树品种得名，成品最鲜明的标记就是那股类似桂皮的辛锐香气。正岩产区里牛栏坑、马头岩、慧苑坑等地出产的肉桂，茶圈习惯按山场起简称，牛栏坑的叫牛肉，马头岩的叫马肉。所谓山场，说的是具体茶园地块的小环境，朝向、土壤、遮阴与湿度都会影响成品风味，因此同一个品种种在不同地块，风格可以有明显差别。它适合秋冬饮用，辛锐温性的风格在寒季更显舒服。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：让鲜叶失水软化，为做青做准备。","做青：摇青与摊晾交替，这是香气形成的主要阶段。","杀青：高温钝化酶活性，固定做青结果。","揉捻：塑形并适度破坏叶细胞，便于冲泡时释放内含物。","初焙：去除青杂气，稳定品质。","复焙：让焙火香与品种香逐步融合。","炭焙炖火：低温长时间慢炖，做出足火岩茶的醇厚底子。"]},{"type":"paragraph","text":"肉桂的氧化程度约30%—50%，与大红袍、水仙同属一个工艺框架，区别主要来自品种本身。肉桂的香气成分以桂皮醛类等辛香物质为特征，这决定了它做青时更容易形成外放的辛锐香。工艺上真正的难点是平衡：焙火要压得住青气，又不能盖掉桂皮香；做青要让辛香充分形成，又不能过头变成苦涩。所以同一片茶园的肉桂，做青与焙火的分寸不同，成品风格可以差别很大。山场与工艺叠加之后，同名为肉桂的茶，可能一支锋芒毕露，另一支含蓄内敛。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结，色泽乌褐油润。汤色橙黄明亮。香气是肉桂最容易被认出的地方：桂皮香、辛锐香突出，属于品种特征香，冲泡三四泡后往往更清晰，冷香里也常留着一点辛甜的尾巴。滋味辛锐刺激、收敛性强、回甘快，岩韵明显，且极耐泡。和水仙放在一起对比最好记：肉桂的强项在香的锐度与前段的冲击力，水仙的强项在汤感的醇厚绵柔。一个偏张扬，一个偏内敛，同属岩茶却几乎没有重叠的品饮体验。另外，肉桂的香气在热嗅时最外放，等杯盖凉下来再闻，桂皮香会收成一点辛甜，这一冷一热的对比，也是判断做青与焙火是否到位的参考。冲泡到第五泡之后，辛锐感会明显转柔，汤感反而更顺，不妨耐心喝到后半程。"},{"type":"tip","tone":"info","title":"识茶提示","text":"对照着闻：干茶阶段的桂皮香通常已经能辨认出来。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"紫砂壶或白瓷盖碗均可，投茶7—8克配100—120毫升水。"},{"title":"沸水高冲","text":"必须用100℃沸水。高冲能让桂皮香更快释放。"},{"title":"前段快出汤","text":"第一泡5—10秒出汤，之后每泡延长5至10秒。肉桂辛锐，坐杯久了容易发苦。"},{"title":"续水","text":"可冲8—10泡。到中后段香气转柔，滋味反而更顺。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是把山场简称当成品质等级。简称只说明茶园地块，不构成等级保证，成品好不好还要看工艺与保存。二是把辛锐等同于苦涩。辛锐是品种香的感受，苦涩是坐杯过久或工艺失当的结果，两者不是一回事。另外肉桂刺激感较强，胃敏感的人建议减量、避开空腹，睡前6小时也不宜再饮。"},{"type":"paragraph","text":"肉桂适合卤味、烤肉这类咸香重味的餐后饮用，也是秋冬暖饮与进阶品鉴的常见选择。配淡味坚果、用紫砂壶冲泡都很合适；牛奶会磨掉桂皮香，甜腻点心则容易与辛锐感打架，清淡茶点又显得风味不对等，都不太建议。传统经验认为肉桂性温味辛甘，餐后饮用可去腻生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味即可，退火充分之后桂皮香会更清晰。"}]', '["product_rougui_100"]', 0, 420, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7680583177376719619', 'tea_wuyi_shuixian', 'wuyi-shuixian', '武夷水仙', '["水仙","武夷岩茶水仙"]', 'oolong', '福建省', '南平市', '武夷山市正岩及高山产区，老丛以树龄50年以上者为贵', '条索粗壮乌润，兰花香与粽叶香清正，汤感醇厚绵柔、稠滑耐泡，老丛还带独特的丛味。', '["萎凋","做青","杀青","揉捻","初焙","复焙","炭焙炖火"]', '["兰花香","粽叶香","木质香"]', '["醇厚","绵柔","稠滑"]', '["重油餐后","秋冬暖饮","静品慢饮","待客"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":8,"max":10},"methodTip":"沸水冲泡。水仙条索粗壮，第一泡可稍多等几秒再出汤。"}', '密封、避光、防潮、防异味，阴凉处存放。', '老丛与普通水仙的存放要求一致，具体期限以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164924482.jpg', '[]', '[{"type":"heading","level":3,"text":"品种与树龄"},{"type":"paragraph","text":"武夷水仙产于福建省南平市武夷山市，正岩产区与高山产区都有种植，同属武夷岩茶。它同样因茶树品种得名，与大红袍、肉桂共用一套工艺框架，区别落在品种个性上。水仙这个品种的特点是叶片大、内含物丰富，直接结果是汤感格外醇厚。产区里另有一个概念是「老丛水仙」，指树龄50年以上者，价格通常更高，因为树龄带来的风味变化确实能被喝出来。它适合秋冬饮用，醇厚绵柔的汤感在冷天里尤其舒服。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：让鲜叶失水软化，进入做青状态。","做青：摇青与摊晾交替，形成香气底子，力度要稳。","杀青：高温钝化酶活性，固定做青成果，杀透才能避免青气。","揉捻：塑形并破坏叶细胞，为醇厚汤感做准备。","初焙：去杂味、稳定品质。","复焙：让火香与品种香融合。","炭焙炖火：低温长时慢炖，把厚度做出来。"]},{"type":"paragraph","text":"水仙的关键在于把内含物的优势转化成汤感，而不是留在苦涩上。它叶片大、水浸出物与可溶性糖含量较高，这本是醇厚绵柔的来源，但做青时若控制不当，多酚类浸出过多就会显得粗糙。所以做青要稳，杀青要透，焙火则负责把厚度收拢。老丛水仙的「丛味」是另一层风味，通常被描述为木质香、青苔味与粽叶香的混合。需要说明的是，丛味的化学基础目前尚无统一结论，多认为与树龄、根系环境及共生微生物相关，因此它也不是能靠工艺简单复制的味道。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索粗壮，色泽乌润，粗细上比肉桂更容易分辨。汤色橙黄偏深，透亮度好。香气以兰花香、粽叶香为主，正岩水仙的香气通常不如肉桂外放，而是缓缓透出，老丛则多一层木质与青苔的气息，冷香阶段尤其明显。滋味醇厚绵柔、汤感稠滑，喉韵长，极耐泡。三款岩茶横向对比会更好记：大红袍讲综合平衡，肉桂讲香的锐度，水仙讲汤的厚度与顺滑，同一个山场、同一套工艺，喝起来是三张不同的面孔。另外，水仙的耐泡在中后段最能体现，第三到第五泡往往是汤感最稠的时候，急着换茶反而错过它的长处；如果觉得前两泡偏淡，多半是条索粗壮、还没完全舒展。用紫砂壶冲泡时，壶身保温好，出汤宜比盖碗更果断一些，避免闷出粗味。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看条索：水仙的条索通常比肉桂粗壮，这是品种叶片偏大的直接体现。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"紫砂壶尤其适合老丛，能聚香保温；白瓷盖碗便于观察汤色。投茶7—8克配100—120毫升水。"},{"title":"沸水高冲","text":"用100℃沸水，条索粗壮需要足够水温才能唤醒。"},{"title":"出汤节奏","text":"第一泡5—10秒出汤，之后每泡延长5至10秒。"},{"title":"续水","text":"可冲8—10泡以上。水仙耐泡度好，中后段汤感往往更顺。"}]},{"type":"tip","tone":"warning","title":"关于丛味与树龄","text":"丛味是一段风味描述，它的化学基础尚无统一结论，多认为与树龄、根系环境及共生微生物相关，不能简单等同于树龄证明。树龄不会写在包装上，判断仍需以实际品饮为准，看到「老丛」二字不必直接联想到等级保证。另外岩茶咖啡因含量偏高，睡前6小时不宜再饮，空腹也不建议。"},{"type":"paragraph","text":"水仙适合重油餐后与秋冬暖饮，老丛尤其适合静下来慢慢喝，几泡之间的变化比第一口更值得留意。搭配咸香茶点、淡味坚果都合适，紫砂壶冲泡更能体现它的厚度；牛奶与强香精调味都会压住兰花香与丛味，清淡茶点则与它的厚度不对等，都不建议。传统经验认为水仙性温味甘，餐后饮用可去腻生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味即可。"}]', '[]', 0, 430, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7565560547837918852', 'tea_fenghuang_dancong', 'fenghuang-dancong', '凤凰单丛', '["单丛","凤凰单枞","鸭屎香"]', 'oolong', '广东省', '潮州市', '潮安区凤凰镇凤凰山，乌岽山为核心产区', '条索紧结挺直，天然花果香极高长，蜜兰香、银花香等香型各成一格，滋味浓醇鲜爽、山韵明显。', '["晒青","晾青","碰青摇青","杀青","揉捻","初焙","复焙足火"]', '["蜜兰香","银花香","黄枝香"]', '["浓醇","鲜爽","回甘强"]', '["油腻餐后","下午提神","冷泡调饮","待客"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["薄胎白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":5},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":10,"max":12},"methodTip":"高香型宜极快出汤，薄胎白瓷盖碗最利显香。"}', '密封、避光、防潮、防异味，阴凉处存放。', '炭焙型退火后香气更稳，以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923893.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与香型体系"},{"type":"paragraph","text":"凤凰单丛产于广东省潮州市潮安区凤凰镇，凤凰山是主产区，乌岽山为核心地带。它属广东乌龙，氧化程度约25%—50%，因香型与工艺而异。单丛这个名字来自采制方式：传统上单株采制、单株命名，每一株香气特征明显的茶树都能自成一个名号，久而久之形成了庞大的香型体系，常见的有蜜兰香、黄枝香、芝兰香、银花香、姜花香等十大香型。银花香在市场上更响亮的名字是鸭屎香，这只是俗称，与香气本身无关。它四季皆宜，传统上以秋季为主推，属传统经验表述。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["晒青：日光下适度失水，启动香气前体物的转化。","晾青：摊晾散热，让水分重新分布。","碰青摇青：做青阶段，反复碰、摇与摊晾，形成花果香。","杀青：高温钝化酶活性，固定香气。","揉捻：塑形并让内含物附着叶表。","初焙：去除青杂气。","复焙足火：多为炭焙，分次烘焙，把香气与滋味收稳。"]},{"type":"paragraph","text":"单丛最容易被误会的一点是香气来源。它的花果香完全来自品种与做青，不是添加香精——同一片茶园里不同株系的茶树，做出来的香型就是不一样，这正是单株采制、单株命名的意义。做青决定了香气的丰富度，碰与摇的力度、次数和摊晾时间都要按当天的温湿度调整。炭焙则决定香气的稳定性：焙得透，香能落水，冲泡七八泡仍有内容；焙得急，香气浮在表面，两三泡就散了。同一株茶树，做青与焙火的分寸不同，成品可以是清锐的花香，也可以是沉稳的蜜香。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结挺直，色泽黄褐油润。汤色金黄明亮。香气是它最强的一项，天然花果香高长，不同香型之间差异明显：蜜兰香偏甜润的花蜜感，银花香清锐带凉，黄枝香近似栀子，芝兰香更清雅。滋味浓醇鲜爽，山韵明显，回甘强，极耐泡。单丛的香气物质含量在乌龙茶中尤为突出，萜烯类与芳香醇类丰富，多酚类保留也较好，因此它在冷泡里的表现力格外强，热泡时的高香会在冷水里转成清冽的花果香。另外，单丛的香气在热嗅时最完整，凉下来之后留下的多是甜香与山韵，两次闻香的差异本身就是品鉴它的一大乐趣；同一款茶在不同水温下，香气走向也会不一样。"},{"type":"tip","tone":"info","title":"识茶提示","text":"先闻干茶再闻盖香：单丛的香型差异在干茶阶段就已经能分辨。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"薄胎白瓷盖碗最利显香。投茶7—8克配100—120毫升水。"},{"title":"沸水高冲","text":"用100℃沸水，高冲注水让香气充分扬起。"},{"title":"极快出汤","text":"第一泡约5秒即出，之后每泡延长5至10秒。高香型坐杯一久，香气就闷住了。"},{"title":"续水","text":"可冲10泡以上。也可按1克比100毫升冷水冷藏约8小时做冷泡，香气转清冽。"}]},{"type":"tip","tone":"warning","title":"关于香型与冷泡","text":"香型名只是株系与风味的标注，不是品质等级，蜜兰香不比银花香高级，选哪个看口味。冷泡时如果想做柠檬茶，茶汤要比平时浓一些，否则容易被柠檬和冰稀释掉香气。另外冷泡茶必须冷藏，并在24小时内喝完，长时间常温放置有微生物繁殖风险。"},{"type":"paragraph","text":"单丛适合油腻餐后与下午提神，也是冷泡与调饮里最好用的一类乌龙：加柠檬做成鸭屎香柠檬茶是现象级的搭配，配无糖气泡水也能做出清爽的零糖饮。潮汕茶点、淡味坚果同样合适；牛奶会掩盖花果香，浓糖浆会压香，都不建议。传统经验认为单丛性平偏温味甘，餐后饮用可去腻生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味即可，炭焙型退火后香气更稳。"}]', '["product_dancong_100"]', 0, 440, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4126276344076852981', 'tea_dongding_oolong', 'dongding-oolong', '冻顶乌龙', '["冻顶茶","台湾冻顶乌龙"]', 'oolong', '台湾', '南投县', '鹿谷乡冻顶山，海拔约700—1200米', '半球形紧结墨绿，焙火香里带花香，滋味醇厚甘润、喉韵佳，是台湾中发酵中焙火的代表。', '["日光萎凋","室内萎凋与搅拌做青","杀青","揉捻","初干","布球揉捻","复干与焙火"]', '["焙火香","米香","花香"]', '["醇厚","甘润","喉韵佳"]', '["餐后解腻","下午提神","秋冬暖饮","待客"]', '{"teaGrams":7,"waterMl":120,"ratio":"约1:17","temperatureC":{"min":95,"max":100},"vessel":["白瓷盖碗","紫砂壶"],"firstSteepSeconds":{"min":10,"max":20},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":7,"max":8},"methodTip":"半球形茶第一泡可稍等舒展，水温保持95—100℃。"}', '密封、避光、防潮、防异味，阴凉处存放。', '焙火型退火后风味更稳，以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923291.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"冻顶乌龙产于台湾南投县鹿谷乡冻顶山，海拔约700—1200米，属台湾乌龙中发酵、中焙火的代表。名字里的「冻顶」来自地名，不是风味描述。台湾茶俗谚里有一句「北包种、南冻顶」，说的就是北部文山以轻发酵的包种茶见长，南部鹿谷一带以中焙火的冻顶乌龙见长，这一南一北正好覆盖了台湾乌龙的两种典型路线。它适合秋冬，中焙火的性格偏温，寒季热饮更舒服。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["日光萎凋：借日光让鲜叶适度失水，为做青打底。","室内萎凋与搅拌做青：在室内反复搅拌与静置，形成香气。","杀青：高温钝化酶活性，固定做青成果。","揉捻：初步塑形，让叶片卷成条索。","初干：降低部分水分，便于下一步成形。","布球揉捻：用布巾包起反复揉压，揉成半球形，这是冻顶乌龙最具辨识度的一道工序。","复干与焙火：干燥后再经焙火，做出焙火香与醇厚感。"]},{"type":"paragraph","text":"布球揉捻是冻顶乌龙形态的关键。它把茶叶收成半球形，颗粒紧结，冲泡时需要一点时间才能完全舒展，所以第一泡的坐杯时间通常比清香型乌龙长。焙火则是风味的另一根支柱：氧化程度约30%—40%，再经中焙火，儿茶素部分氧化，刺激性低于清香型乌龙，口感更圆润。焙火的程度在不同产品之间差别很大，轻的保留更多花香，重的米香、焦糖香更明显；刚焙好的茶通常需要一段退火期，火气会慢慢转柔，香气也从焦香转向米香，所以同一款茶在刚到手和放到一个月后喝，感受可能并不一样。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形半球形紧结，色泽墨绿油润，表面能看到揉捻留下的紧实感。汤色金黄至橙黄，清亮。香气是焙火香与花香的组合，常见米香、焦糖香，冲泡两三泡后花香会浮上来，冷香里通常留着清甜的那一层。滋味醇厚甘润，喉韵好，耐泡度属中上。整体风格介于清香与足火之间，比清香型乌龙温和，又比足火岩茶轻快，对第一次接触焙火型乌龙的人来说，是一条很好走的过渡路线。另外，冻顶乌龙的焙火程度跨度大，偏轻的批次花香更明显、汤色偏金黄，偏重的批次米香与焦糖香更足、汤色偏橙，选购时可以先问清焙火程度，再对号入座。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看形状：半球形紧结是冻顶乌龙的标志，与条索形或球形都能区分开。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"白瓷盖碗或紫砂壶都可，投茶6—8克配120毫升水。"},{"title":"温润舒展","text":"先用热水快速润一遍，帮助半球形颗粒舒展，为后续出味打底。"},{"title":"控制水温","text":"水温95—100℃。焙火型可以沸水，偏清香的批次用95℃左右更稳妥。"},{"title":"出汤节奏","text":"第一泡10—20秒，之后每泡延长5至10秒，可冲7—8泡。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是把「冻顶」当成等级。它是产地名，同一产地不同批次的品质仍有差别。二是把焙火香当成焦味。正常的焙火香是米香、焦糖香一类温和的香，焦糊味则是焙火失当，两者闻起来完全不同。另外它的刺激性虽然低于清香型乌龙，咖啡因含量依旧偏高，睡前6小时不宜再饮。"},{"type":"paragraph","text":"冻顶乌龙适合餐后解腻与下午提神，中焙火的性格也适合秋冬暖饮，待客时接受度很高，因为它既不苦也不冲。搭配台式糕点如凤梨酥、绿豆椪很合拍，配淡味坚果也稳妥；厚奶盖会盖住焙火香，浓糖浆与全糖奶茶则糖分过高，不建议。传统经验认为它性平偏温味甘，餐后饮用可提神、去腻生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味即可。"}]', '["product_dongding_100"]', 0, 450, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7765823229960762298', 'tea_wenshan_baozhong', 'wenshan-baozhong', '文山包种', '["包种茶","台湾包种茶"]', 'oolong', '台湾', '新北市', '坪林、石碇、深坑一带，即文山地区', '条索紧结深绿，兰花香与栀子花香清扬，滋味清新鲜爽、汤色金黄带绿，是发酵度最低的台湾乌龙。', '["萎凋","轻搅拌做青","杀青","揉捻","解块","烘干"]', '["兰花香","栀子花香","清香"]', '["清新","鲜爽","甘甜"]', '["上午提神","午后清口","冷泡","待客"]', '{"teaGrams":6,"waterMl":120,"ratio":"约1:20","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","玻璃杯"],"firstSteepSeconds":{"min":15,"max":25},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"轻发酵不宜全程沸水，90—95℃更利于保留清香。"}', '密封、避光、防潮、防异味，低温保存更利于保香。', '不焙火或极轻焙火，香气易散，建议按包装标注期限尽快喝完。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164924483.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"文山包种产于台湾新北市坪林、石碇、深坑一带，这一片合称文山地区，是台湾北部最主要的茶区。它是台湾乌龙里发酵度最低的一类，约15%—25%，工艺路线接近清香型。台湾茶俗谚中的「北包种、南冻顶」，说的就是它和南投冻顶乌龙一北一南的对应关系：一个走轻发酵、不焙火的清香路线，一个走中发酵、中焙火的醇厚路线。它适合春夏，清香型在温热季节里更显清爽。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：让鲜叶适度失水，进入做青状态。","轻搅拌做青：搅拌力度轻，只求形成清花香，不追求重发酵。","杀青：高温钝化酶活性，把清香固定下来。","揉捻：塑形，让叶片卷成条索。","解块：把揉捻后结团的茶叶打散，避免闷出杂味。","烘干：不焙火或极轻焙火，成品保持条索形，不揉成球。"]},{"type":"paragraph","text":"包种的工艺特点可以用两个字概括：轻与不。做青搅拌轻，氧化程度控制在约15%—25%；干燥环节不焙火或只极轻焙火，所以茶叶保留了最多的清香与鲜爽。代价是香气稳定性相对差，久放或存放不当，香气散得比焙火型快，买回来建议尽早喝完。形态上它保持条索形，不揉成球，这也是与冻顶乌龙、铁观音一眼可辨的差别。成分方面，轻发酵加不焙火，使它的儿茶素保留量在台湾乌龙中最高，茶氨酸含量也较高，鲜爽度好。也正因为不焙火，包种的条索比冻顶乌龙更松散一些，投茶时可以稍微多抓一点，滋味才够。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结呈条状，色泽深绿。汤色金黄带绿，清亮。香气以兰花香、栀子花香为主，清扬不厚重，杯盖上的香气往往比茶汤里更明显，冷却后的冷香也干净。滋味清新鲜爽，回甘干净，汤感比冻顶轻盈。整体表现更接近「清」而不是「厚」，冲泡时如果水温过高或坐杯过久，苦涩会立刻上来，把清香压掉，所以水温与时间是这款茶最需要留意的两件事。另外，包种的鲜爽来自较高的茶氨酸含量与较轻的发酵，这份鲜爽也最怕高温，冲泡时把水温压住，比任何技巧都管用；它也很适合用玻璃杯直冲，看条索在水中舒展的过程，本身就是一种清口的仪式。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看形态：条索形不揉球，是包种与冻顶乌龙最直观的区分点。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"白瓷盖碗或玻璃杯都合适，玻璃杯便于看汤色。投茶5—7克配120毫升水。"},{"title":"控制水温","text":"90—95℃，不宜全程沸水。轻发酵的茶用沸水容易把苦涩一并逼出来。"},{"title":"出汤时间","text":"第一泡15—25秒，之后每泡延长5至10秒，可冲5—7泡。"},{"title":"冷泡","text":"也可按1克比100毫升冷水冷藏约8小时冷泡，清香表现好，加青柠或薄荷更清爽。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是把包种当成绿茶。它虽然汤色偏绿，但经过做青工序，属半发酵的乌龙茶，分类依据是工艺而非汤色。二是用沸水久闷。轻发酵、儿茶素保留多，闷泡后苦涩上升很快，也会掩盖清花香。此外它对胃的刺激相对明显，空腹饮用容易不适，建议放在餐后。"},{"type":"paragraph","text":"包种适合上午提神与午后清口，冷泡表现也好，夏天做成冷泡茶尤其清爽。搭配清淡茶点最合适，牛奶与浓香调味都会压掉它细腻的香气，不建议；用玻璃杯冲泡时还能顺便看茶叶舒展的样子。传统经验认为它性平偏凉味甘，餐后饮用可提神、生津、去腻，这属于传统表述，不等同于现代研究结论。存放要格外注意：因为它不焙火，香气稳定性差，建议密封后低温保存，并按包装标注的期限尽快喝完。若一次买得多，可以分成小份密封，喝一份拆一份，减少反复开袋带来的香气流失。"}]', '[]', 0, 460, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3100822536207478336', 'tea_dongfang_meiren', 'dongfang-meiren', '东方美人', '["白毫乌龙","膨风茶","椪风茶"]', 'oolong', '台湾', '新竹县', '北埔、峨眉一带，苗栗县头屋、三湾亦有产区', '芽叶肥壮白毫显，白绿黄红褐五色相间，蜜香与熟果香突出，滋味醇厚甜润几乎无苦涩。', '["采摘受小绿叶蝉叮咬的芽叶","萎凋","重搅拌做青","杀青","揉捻","干燥"]', '["蜜香","熟果香","花香"]', '["醇厚","甜润","几乎无苦涩"]', '["餐后","下午茶","入门品饮","待客"]', '{"teaGrams":6,"waterMl":120,"ratio":"约1:20","temperatureC":{"min":85,"max":90},"vessel":["白瓷盖碗","玻璃杯"],"firstSteepSeconds":{"min":20,"max":30},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"重发酵且芽叶嫩，不宜沸水，85—90℃更能保留蜜香。"}', '密封、避光、防潮、防异味，低温保存更利于保香。', '不焙火或极轻焙火，香气易散，建议按包装标注期限尽快喝完。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832433.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"东方美人产于台湾新竹县北埔、峨眉一带，苗栗县头屋、三湾也有产区，别名白毫乌龙。它是乌龙茶里发酵度最重的一类，约50%—70%，部分资料因此把它归为接近红茶，也常有第一次喝到的人误以为它是红茶。产地流传的说法是，早年茶农因茶园受虫害而仍照常制茶，意外做出蜜香风味，这个说法属于当地传说，不必当作定论，但它指向的工艺事实是明确的：这款茶确实以被小绿叶蝉叮咬过的芽叶为原料。它适合秋冬，性偏温、滋味醇甜，冷天饮用更顺口。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["采摘受小绿叶蝉叮咬的芽叶：这是决定风味的前提，也是它区别于其他乌龙的根本。","萎凋：让鲜叶失水软化，为做青做准备。","重搅拌做青：搅拌力度大，氧化程度高，形成熟果香与甜感。","杀青：高温钝化酶活性，固定蜜香。","揉捻：塑形，白毫在这一步被保留下来。","干燥：不焙火或极轻焙火，避免火气盖掉蜜香。"]},{"type":"paragraph","text":"小绿叶蝉的着涎是东方美人的核心识别点。被叮咬的芽叶会诱导植物次生代谢物生成，其中包含萜烯类等成分，这些物质正是蜜香与熟果香的关键成因，因此它的香气无法靠普通原料复制。同一片茶园里，叮咬程度不同，成品的香气浓度差异极大，这也是它品质波动明显、好茶难得的原因。工艺上做青用重搅拌，氧化程度推到约50%—70%，儿茶素大量氧化聚合，苦涩感极低，再配合不焙火或极轻焙火，蜜香得以完整保留。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形芽叶肥壮，白毫显著，干茶呈现白、绿、黄、红、褐五色相间，这是它最容易辨认的外貌特征，也是别名白毫乌龙的由来。汤色琥珀橙红，清透。香气以蜜香、熟果香为主，甜感明显，冲泡时香气不冲但很扎实，冷香里蜜味更集中。滋味醇厚甜润，几乎无苦涩，重发酵使儿茶素大量氧化聚合，刺激性在乌龙茶中最小，对不习惯苦涩的人来说是很好的入口选择。需要留意的是，甜润是风味描述，不代表可以无限制饮用，它同样含咖啡因。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"白瓷盖碗或玻璃杯，投茶5—7克配120毫升水。白瓷不吸香，最容易还原蜜香。"},{"title":"控制水温","text":"85—90℃。重发酵且原料偏嫩，用沸水会把蜜香冲散，也容易出闷味。"},{"title":"出汤时间","text":"第一泡20—30秒，之后每泡延长5至10秒，可冲5—7泡。"},{"title":"冷泡","text":"也可按1克比100毫升冷水冷藏约8小时冷泡，蜜香转为清透，甜感更突出。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是把它当红茶。它是乌龙茶，而且正好是乌龙茶里发酵度最重的一类，常被误解正是因为这一点。二是以为被虫咬过是瑕疵。小绿叶蝉的叮咬恰恰是蜜香的来源，没有叮咬就做不出这个风味。此外不建议用沸水冲泡，虽然它的刺激性在乌龙茶中最小，睡前6小时仍不宜再饮。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"东方美人适合餐后与下午茶，外形与风味都很特别，用来待客也容易留下印象；对不喜苦涩的人来说，它是乌龙茶里门槛最低的一款。搭配上可以配微甜茶点，或用果干呼应它的蜜香，白瓷盖碗最能还原香气，冷泡也值得一试。牛奶会掩盖蜜香，浓糖浆与重口味咸点也都不合适。传统经验认为它性温味甘，餐后饮用可提神、生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味，条件允许时低温保存，并尽量在包装标注的期限内喝完，因为它的香气散得比焙火型乌龙快。"}]', '[]', 0, 470, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1731993738358817660', 'tea_zhangping_shuixian', 'zhangping-shuixian', '漳平水仙', '["漳平水仙茶饼"]', 'oolong', '福建省', '龙岩市', '漳平市南洋镇、双洋镇等', '乌龙茶里唯一的紧压形态，方形小茶饼，兰花香与桂花香清雅，滋味醇厚甘爽、一块一泡方便携带。', '["晒青","做青","杀青","揉捻","压模成型","烘焙","纸包"]', '["兰花香","桂花香","清香"]', '["醇厚","甘爽","耐泡"]', '["办公室焖泡","餐后解腻","出差携带","待客"]', '{"teaGrams":8,"waterMl":150,"ratio":"约1:19","temperatureC":{"min":100,"max":100},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":15,"max":20},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":7,"max":10},"methodTip":"一块约8克配150毫升水，沸水冲泡。"}', '密封、避光、防潮、防异味，阴凉处存放，注意纸包不受潮。', '紧压形态相对稳定，具体期限以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832434.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"漳平水仙产于福建省龙岩市漳平市，南洋镇、双洋镇等地是主要产区，属闽南乌龙。它有一个别款都没有的身份：乌龙茶里唯一的紧压茶。成品被压成小方块茶饼，传统上再以白纸包裹。名字里的水仙指茶树品种，与武夷水仙同属一个品种名，但两者产区与工艺路线不同，风味也不一样，一个走紧压的中发酵路线，一个走条索的岩茶焙火路线，选购时看清产区就不会混。它四季皆宜，传统上以秋季为主推，属传统经验表述。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["晒青：日光下适度失水，启动香气前体物转化。","做青：摇青与摊晾交替，形成兰花香、桂花香的底子。","杀青：高温钝化酶活性，固定做青成果。","揉捻：塑形并破坏叶细胞，为紧压做准备。","压模成型：把茶叶压成方形茶饼，这是它最具辨识度的一道工序。","烘焙：低温烘干定形，稳定品质。","纸包：传统以白纸包裹，既是包装也参与定型。"]},{"type":"paragraph","text":"压模成型决定了漳平水仙的一切使用体验。紧压之后，茶叶与水的接触面积变小，内含物释放比散茶缓慢，所以滋味显得浓厚、耐泡，也更不容易一次泡苦。这块茶饼通常重约5—10克，刚好一块一泡，不用称量，出差或办公室冲泡都很方便。代价是前一两泡需要多等一会，让茶饼吸水松散；如果整块投入又不肯等，汤感就会偏淡，掰散一小半再泡则出味更快，可以按场景取舍。纸包除了定型，也起到一定的防潮与避光作用，拆开后如果一次喝不完，建议重新密封，不要直接敞放。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形是小方块茶饼，一块约5—10克，色泽乌褐，表面能看出压制的紧实感。汤色橙黄明亮。香气以兰花香、桂花香为主，清雅不张扬，随冲泡次数缓缓释放，冷香里带一点清甜。滋味醇厚甘爽，汤感顺，耐泡度好。它的整体风格介于清香与焙火之间，比铁观音清香型多一些厚度，又比岩茶轻快，加上一块一泡的便利，很适合当作日常口粮茶，也适合刚开始接触乌龙茶的人。另外，紧压茶的外层与内层出味速度不同，第一泡偏清淡、第三泡之后才进入状态，判断它的品质最好不要只看头一泡。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"投茶","text":"一块约8克配150毫升水。整块投入即可，也可轻轻掰散，掰散出味更快。"},{"title":"沸水冲泡","text":"用100℃沸水。紧压茶需要足够水温才能从外层向内层浸润。"},{"title":"第一泡稍等","text":"第一泡15—20秒出汤，让茶饼充分吸水松散；之后每泡延长5至10秒。"},{"title":"续水","text":"可冲7—10泡。中后段出味反而更均匀，是紧压茶的一个特点。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是以为紧压就一定耐闷。紧压只是让释放变慢，长时间闷泡依然会苦涩，出汤节奏还是要控制。二是把漳平水仙与武夷水仙混为一谈。两者品种名相同，但产区、工艺与风味路线都不同，是两款各自独立的茶。此外它同样含咖啡因，睡前6小时不宜再饮。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"漳平水仙特别适合办公室焖泡与出差携带，一块一泡不用称量；餐后解腻、待客也都能胜任，而且它耐泡、出味稳，一泡能陪伴大半天。搭配咸香茶点与淡味坚果最稳，白瓷盖碗或瓷壶冲泡都合适。牛奶和浓糖浆会盖掉清雅的兰花香，不建议。传统经验认为它性平味甘，餐后饮用可提神、去腻生津，这属于传统表述，不等同于现代研究结论。存放上注意密封、避光、防潮、防异味，纸包受潮后容易串味，这一点比散茶更需要注意。"}]', '[]', 0, 480, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2143286490671301799', 'tea_yongchun_foshou', 'yongchun-foshou', '永春佛手', '["佛手茶","永春佛手茶"]', 'oolong', '福建省', '泉州市', '永春县苏坑、玉斗等乡镇', '颗粒紧结砂绿，雪梨香清雅持久，滋味醇厚甘甜、汤感柔顺，是闽南乌龙里以柔顺回甘见长的一款。', '["晒青","做青","杀青","揉捻","包揉成球","烘干","焙火（部分）"]', '["雪梨香","佛手香","清香"]', '["醇厚","甘甜","柔顺"]', '["餐后解腻","下午提神","秋冬暖饮","待客"]', '{"teaGrams":7,"waterMl":120,"ratio":"约1:17","temperatureC":{"min":100,"max":100},"vessel":["白瓷盖碗","紫砂壶"],"firstSteepSeconds":{"min":10,"max":20},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":6,"max":8},"methodTip":"沸水冲泡，球形茶第一泡可稍等舒展。"}', '密封、避光、防潮、防异味；清香型可低温保存。', '焙火程度不同保存方式不同，以产品包装标注为准。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923891.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"永春佛手产于福建省泉州市永春县，苏坑、玉斗等乡镇是主要产区，属闽南乌龙。它因茶树品种得名，这个品种的叶片偏大、内含物丰富，成品因此以汤感醇厚见长。永春与安溪同属泉州，两地都是闽南乌龙的重要产区，但主栽品种不同，风格也分得开：铁观音以兰花香与音韵为标记，佛手则以雪梨香与柔顺甘甜为标记，放在一起对比喝，差别相当明显。它适合秋冬，醇厚柔顺的汤感在冷天里更受欢迎。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["晒青：日光下适度失水，为做青做准备。","做青：摇青与摊晾交替，做出品种香的基础。","杀青：高温钝化酶活性，固定做青成果。","揉捻：初步塑形，让叶片卷起。","包揉成球：用布巾包起反复揉压，收成紧结颗粒。","烘干：降低含水量，便于存放。","焙火：部分产品在烘干后再经焙火，得到更醇厚的口感。"]},{"type":"paragraph","text":"佛手的品种特点在工艺里会被放大。叶片大、内含物丰富，水浸出物含量高，这本是汤感醇厚的来源，但也意味着做青和杀青要拿捏得更准：做青不足则青气重，过头则苦涩明显。包揉成球同样是关键一步，闽南乌龙追求颗粒紧结，只有反复包揉才能成形，冲泡时内含物的释放也更均匀。整体氧化程度约25%—40%，风格介于清香与焙火之间，柔顺是它最突出的性格，也因此常被推荐给刚开始喝乌龙茶的人。包揉的力度也会影响汤感，揉得紧实的颗粒前几泡释放较慢，泡数更多，揉得松的则前段更足、后段下滑更快。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形颗粒紧结，色泽砂绿。汤色金黄清亮。香气是它最有辨识度的地方，雪梨香、佛手香清雅持久，属于品种本身的香气，闻起来偏清甜，不浓烈，冷香里也保持着这股清甜。滋味醇厚甘甜，汤感柔顺，回甘好，几乎没有锐利的棱角。与铁观音相比，佛手的香气更收敛、汤感更绵；与武夷水仙相比，它少了焙火带来的厚重，多了闽南乌龙的清爽。整体是一款很温和、对新手友好的乌龙。另外，佛手的雪梨香在温饮时最清楚，汤温降下来后甜感会更突出，凉了之后香气虽收，滋味反而更柔。"},{"type":"tip","tone":"info","title":"识茶提示","text":"先闻香再冲泡：雪梨香在干茶阶段就能辨认，这是佛手最直接的标记。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器与投茶","text":"白瓷盖碗或紫砂壶均可，投茶6—8克配120毫升水。"},{"title":"沸水高冲","text":"用100℃沸水。球形茶结构紧实，水温不足香气与汤感都出不来。"},{"title":"出汤时间","text":"第一泡10—20秒，球形茶可稍等舒展；之后每泡延长5至10秒。"},{"title":"续水","text":"可冲6—8泡。到后半程汤感转柔，回甘反而更清楚。"}]},{"type":"tip","tone":"warning","title":"两个常见误解","text":"一是以为雪梨香来自添加。它是品种本身的香气，不是香精。二是把它与铁观音混同。两者同属闽南乌龙，外形也接近，但主栽品种不同，佛手偏柔顺甘甜，铁观音偏兰花香与音韵，对比着喝一次就能分清。此外它虽然柔顺，咖啡因含量并不低，睡前6小时不宜再饮。"},{"type":"paragraph","text":"永春佛手适合餐后解腻、下午提神与秋冬暖饮，雪梨香的独特性也让它很适合待客，对不常喝茶的人来说接受度高。搭配微甜茶点与淡味坚果都合适，牛奶、浓糖浆与全糖奶茶会盖掉清甜的品种香，不建议。传统经验认为它性平味甘微苦，餐后饮用可提神、去腻生津，这属于传统表述，不等同于现代研究结论。存放上密封、避光、防潮、防异味即可，清香型可以低温保存，焙火型的保存要求则宽松一些。日常冲泡时如果觉得香气偏淡，多半是水温不够或第一泡出汤太快，把水烧足、多等几秒就能改善。"}]', '[]', 0, 490, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4996346501470601743', 'tea_zhengshan_xiaozhong', 'zhengshan-xiaozhong', '正山小种', '["拉普山小种"]', 'black', '福建省', '南平市', '武夷山市桐木关及正山范围', '小种红茶的代表，传统烟种带松烟香与桂圆汤感，无烟种转向花果蜜香，滋味醇厚甘甜、汤色红浓。', '["萎凋","揉捻","发酵","过红锅","复揉","熏焙或无烟干燥","复火"]', '["松烟香","花果香","蜜香"]', '["醇厚","甘甜","桂圆汤感"]', '["秋冬清饮","加奶调饮","油腻餐后","待客"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","玻璃壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"清饮宜快出汤；传统烟种可用95至100℃水温；调饮时把茶汤泡得比清饮更浓。"}', '密封、干燥、避光、防异味，常温保存。', '松烟香与花果蜜香都容易挥发，开封后尽早饮用更合算。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926292.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"正山小种产自福建省南平市武夷山市桐木关一带，茶园落在武夷山国家级自然保护区内。这里海拔较高、常年云雾缭绕、昼夜温差大，鲜叶的内含物积累因此比较充分，也是它汤感厚实、耐得住多次冲泡的底子。名称里的「正山」是产区限定词，指的是桐木关及其周边这同一片高山茶区，用来与外山仿制的小种茶相区别。它是小种红茶的代表，也被公认为世界红茶的鼻祖。条索肥壮、色泽乌黑油润是它的外形基调，茶多酚氧化程度通常在70%–90%之间。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：鲜叶摊放失水，叶片变软，为揉捻与发酵做准备。","揉捻：破坏叶细胞，让茶汁外溢、酶与底物充分接触。","发酵：多酚氧化酶催化儿茶素氧化，奠定红叶红汤的底子，是红茶的核心工序。","过红锅：短时高温处理，终止酶促氧化，把风味固定下来。","复揉：整理条索，让外形更紧结匀整。","熏焙：传统以松柴明火烟熏形成松烟香；现代也有不经烟熏的无烟工艺。","复火：进一步干燥、降低含水率并稳定香气。"]},{"type":"paragraph","text":"对正山小种来说，发酵与熏焙是最要紧的两道工序。发酵属于酶促氧化，与黑茶的渥堆微生物发酵在机理上完全不同，它决定了茶黄素和茶红素的生成量，也决定了汤色与醇厚度：发酵不足，汤色偏浅、滋味带青气；发酵过头，颜色暗沉并出现熟闷味。熏焙则决定风格走向：传统烟种以松柴明火烟熏，得到清晰的松烟香与桂圆汤感；无烟种省去烟熏环节，转为花果蜜香。这两条路径长期并存，都属于正山小种，选购前先弄清自己要的是哪一种。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"看外形，条索肥壮、色泽乌黑油润，净度好、碎末少，手感紧实不轻飘。看汤色，应当红浓而明亮，不该浑浊发暗。香气上，传统烟种是清晰的松烟香，无烟种偏花果蜜香，两者都不该有焦糊气或酸馊气，出现这类气味往往意味着烘焙过火或存放受潮。滋味醇厚甘甜，传统上常用「桂圆汤」来形容那种圆润的甜感，入口不尖不涩，回味偏长，泡到第四五泡仍能维持一定的厚度。"},{"type":"tip","tone":"info","title":"识茶提示","text":"留意条索是否肥壮匀整、色泽是否油润，这两点能大致反映原料与工艺水准。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"取5 g干茶配150 ml水，茶水比约1:30；白瓷盖碗最能看清汤色，玻璃壶则更适合调饮。"},{"title":"控温注水","text":"水温90–95 ℃。若喝的是传统烟种，可以升到95–100 ℃，把松烟香顶出来。"},{"title":"快出汤","text":"第一泡5–10秒即出，之后每泡延长5–10秒，一共可冲5–7泡；久闷会大量释放单宁，变得苦涩。"},{"title":"调饮加浓","text":"需要加奶时，把茶汤泡得比清饮更浓一些，否则奶会把风味冲淡。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"浓茶并不能抵消酒精的影响：咖啡因与酒精叠加会加重心脏负担，利尿作用还会加重脱水，所以酒后不宜拿浓茶代水。另一个常被夸大的说法是红茶对胃温和——红茶经过全发酵，对胃的相对刺激确实低于绿茶，但它仍会促进胃酸分泌，空腹浓饮反而容易不适。此外，贫血人群应避开餐中浓饮，加奶也并不能消除茶多酚对铁吸收的影响。"},{"type":"paragraph","text":"搭配上，正山小种是经典的奶茶底，加鲜牛奶后茶味依然立得住；想喝清爽一些，可以冷泡后加柠檬片与蜂蜜，冷泡按1 g茶配100 ml水的比例冷藏8–10小时，甜香更突出、涩感极低。但加奶的茶不建议再挤大量柠檬汁，柠檬酸会让乳蛋白絮凝，出现絮状沉淀。存放上注意密封、干燥、避光、防异味，常温保存即可；松烟香与花果蜜香都容易挥发，开封后尽早喝完更划算。"}]', '["product_zhengshan_xiaozhong_100"]', 1, 500, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1774819018337183817', 'tea_jinjunmei', 'jinjunmei', '金骏眉', '[]', 'black', '福建省', '南平市', '武夷山市桐木关正山产区', '桐木关正山产区的创新红茶，只采单芽制作，花果蜜香复合、汤色金黄透亮，滋味鲜活甘爽。', '["采摘单芽","萎凋","揉捻","发酵","干燥"]', '["花果蜜香","蜜香","桂圆香"]', '["鲜活甘爽","细腻","回甘悠长"]', '["上午提神","待客送礼","清饮细品"]', '{"teaGrams":3,"waterMl":150,"ratio":"1:30–1:50","temperatureC":{"min":85,"max":90},"vessel":["白瓷盖碗"],"firstSteepSeconds":{"min":10,"max":20},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"投茶3至5 g；芽头细嫩，忌沸水，也建议不加奶不加糖清饮。"}', '密封、避光、防异味，阴凉干燥处常温保存。', '芽头细嫩、香气易散，开封后尽量在短时间内喝完。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925633.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"金骏眉与正山小种同出福建省南平市武夷山市桐木关，用的是同一片正山产区的原料，但它是本世纪初创制的新名茶，走的是另一条路线。它只采单芽，往往要数万颗芽头才能制出一斤成茶，采摘成本高，这也是它外形细紧如眉、产量有限的由来。因为原料极嫩，它的风格从正山小种的沉稳转向鲜活，汤色也从红浓变成金黄透亮。同一片山水，两种做法，恰好把桐木关原料的两种可能都呈现了出来。也正因为产区重合，这两款茶经常被放在一起比较；但它们的选料等级与适合的喝法并不相同，各自对应不同的场合与预算，不存在谁替代谁的关系。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["采摘单芽：只取芽头，原料嫩度高、数量稀少，是成本的主要来源。","萎凋：让芽头均匀失水，便于后续成形，避免芽头破损。","揉捻：轻揉成条，尽量保持芽形完整，力道比大宗红茶轻得多。","发酵：酶促氧化生成茶黄素、茶红素，形成红茶的底子。","干燥：低温慢烘，锁住花果蜜香，避免高温把香气烤散。","全程无烟熏：不做松柴熏焙，这是它与传统正山小种最直接的工艺差别。"]},{"type":"paragraph","text":"金骏眉与正山小种最直接的分界，就在选料与烟熏这两处。正山小种多采一芽二三叶，金骏眉只取单芽；正山小种的传统烟种要经松柴熏焙，金骏眉则全程不熏。选料变化带来成分上的差异：全芽原料的氨基酸含量高，茶多酚相对低于大叶种，所以滋味更鲜甜、刺激性更低；但咖啡因因全芽而含量偏高，对睡眠的影响反而比一般红茶更明显，晚间饮用需要更谨慎一些。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"看外形，干茶金黑相间、细紧如眉，金毫明显却不过分扎眼，条索匀整度高。汤色是金黄透亮，而不是红茶常见的红艳——这一点常被拿来辨真伪，若汤色深红发暗、香气单薄，多半不是纯芽头原料做出来的。香气为花果蜜香复合，并带一点桂圆香；滋味鲜活甘爽、汤感细腻，回甘悠长。因为芽头嫩、内含物释放快，它在前两泡的表现尤其关键，也最能看出工艺水准。冲泡时不妨先用较低水温试一泡，再对比稍高水温的表现，就能明显感到鲜爽度与甜度的差别，也更容易找到自己喜欢的区间，这也是它可玩性比较高的一面。"},{"type":"tip","tone":"info","title":"识茶提示","text":"对照汤色判断：金骏眉应呈金黄透亮，红艳浓深反而是疑点。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"投茶3–5 g配150 ml水，茶水比约1:30–1:50；白瓷盖碗最能显香，也便于观察汤色。"},{"title":"控温","text":"水温85–90 ℃。芽头细嫩，用沸水容易把茶汤泡得发酸，也容易把鲜爽感烫掉。"},{"title":"出汤","text":"第一泡10–20秒，之后逐泡调整，可冲5–7泡；不宜久闷，久闷会盖住细腻的汤感。"},{"title":"清饮为上","text":"建议不加奶不加糖，花果蜜香与细腻汤感才不被掩盖。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"市面上常有人把金骏眉理解成「更高级的正山小种」，其实两者是选料与工艺都不同的两条产品线，价格差异主要来自单芽原料的采摘成本，而不是等级上的高下之分。另外金骏眉因全芽而咖啡因偏高，睡前6小时内不建议饮用，这一点比一般红茶更需要注意；对咖啡因敏感的人，上午饮用更为合适。"},{"type":"paragraph","text":"搭配上，金骏眉最适合清饮，配清淡微甜的茶点即可；想加蜂蜜，等茶汤降温后再加，避免高温破坏风味。它并不适合做奶茶底，牛奶会盖住花果蜜香与细腻汤感。存放上，芽头细嫩、香气易散，尤其要注意密封、避光、防异味，开封后尽量在短时间内喝完；久放会让花果蜜香明显走低，也会让汤色的通透度变差。如果一次买得较多，可以分成小份密封，只留近期要喝的量在外，减少反复开封带来的香气损失；分装时尽量挤出袋内空气，效果会更好。"}]', '["product_jinjunmei_50"]', 0, 510, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('910171288014757367', 'tea_keemun', 'qimen-black-tea', '祁门红茶', '["祁红","祁门工夫"]', 'black', '安徽省', '黄山市', '祁门县及黟县、石台、东至等周边传统产区', '中国十大名茶中唯一的红茶，蔷薇花香、果香与蜜香复合的「祁门香」，滋味醇厚鲜甜、汤色红艳带金圈。', '["萎凋","揉捻","发酵","毛火烘焙","足火","精制"]', '["蔷薇花香","果香","蜜香"]', '["醇厚","鲜甜","甜花香"]', '["下午茶","清饮待客","英式奶茶","早餐后"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"白瓷器皿更易观察红亮汤色并辨认复合香气；调饮时把茶汤泡浓再加鲜奶。"}', '密封、常温、干燥、避光、防异味。', '避免与香料同放，开封后及时封口。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925635.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"祁门红茶产自安徽省黄山市祁门县，黟县、石台、东至等周边县区也属于传统产区。祁门一带属亚热带湿润气候，山区林木茂密、云雾较多，这样的环境让鲜叶的香气物质积累得比较丰富，也是「祁门香」能够形成的产地基础。它是工夫红茶的代表，也是中国十大名茶中唯一的红茶。祁红的精制工序相当繁复，行业里有「十七道工序」之说，这套流程让毛茶的分级与拼配更细致，也让成茶的香气更稳定。选购时可以多留意包装上的具体产地与批次信息，而不是只看「祁门红茶」四个大字；同一名称之下，产区、等级与年份的差异都会反映在杯中，这一点对判断性价比尤其有用。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：鲜叶均匀失水，叶片变柔软，便于后续成条。","揉捻：成条并破坏叶细胞，为发酵创造条件。","发酵：酶促氧化形成茶黄素、茶红素，汤色与醇厚度在此定型。","毛火烘焙：高温快速脱水，终止酶促氧化，避免发酵过头。","足火：低温足干，进一步稳定并发展香气。","精制：筛分、拣剔、拼配等一整套流程，祁红以工序繁复著称。"]},{"type":"paragraph","text":"祁红最关键的是发酵与烘焙的配合。发酵不足，汤色偏浅、滋味寡淡；发酵过度，颜色暗沉并带熟闷味，香气的清透感也会一并丢失。烘焙则决定「祁门香」能不能留下来：毛火要快，抢在发酵过头之前把酶钝化；足火要稳，低温慢烘把香气慢慢养出来，温度过高会让香气物质在高温里散掉。祁红的香气以香叶醇、苯甲醇等成分为特征，这也是它区别于其他工夫红茶的化学基础。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索细紧、色泽乌润并带一层灰光，行内称「宝光」，这是精制到位的外在表现。汤色红艳明亮，优质的祁红在杯壁边缘常见一圈金黄色泽，也就是常说的「金圈」，它与茶黄素含量相关。香气是祁红的核心：蔷薇花香、果香与蜜香交织在一起，高长持久，这就是「祁门香」，它的特点是复合而非单一。滋味醇厚鲜甜，落口带一点甜花香的余韵，泡到后段香气仍能维持住。这种香气不像单一花香那样一眼可辨，需要多泡几道、对比着闻，才容易抓住花果蜜交织的那层感觉；这也是它耐得住细品、常被拿来反复比较的原因。"},{"type":"tip","tone":"info","title":"识茶提示","text":"冲泡后留意杯壁边缘是否有一圈金圈，它与茶黄素含量相关。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；白瓷盖碗最利于辨认「祁门香」，瓷壶也可以。"},{"title":"控温","text":"水温90–95 ℃，避免用滚沸的水直冲较嫩的芽叶，否则香气会显得粗糙。"},{"title":"快出汤","text":"第一泡5–10秒即出，之后每泡延长5–10秒，可冲5–7泡；工夫红茶忌久闷。"},{"title":"调饮","text":"想做英式奶茶，把茶汤泡浓些再加鲜牛奶，风味层次更清楚。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"别把「汤色越红越浓」当成品质标准。汤色红艳明亮确实是一项指标，但色泽深浅与品质高低没有必然关系，过度发酵或高火反而会带来暗沉汤色与熟闷味，判断祁红要香气、滋味、叶底一起看。另外，「红茶对胃温和」属于传统经验表述，现代研究证据不足，不能当作功效宣传，浓饮、空腹饮同样会带来不适。"},{"type":"paragraph","text":"搭配上，祁红与西式甜点适配度很高，司康、曲奇都不错；加鲜牛奶就是经典的英式奶茶，也可以加一点玫瑰或桂花呼应它的花香。要避开的是牛奶加大量柠檬的组合，柠檬酸会让乳蛋白絮凝，以及植脂末和高糖果浆。存放上密封、避光、防异味、常温即可，注意别和香料放在一起，祁红的香气吸附性较强，一旦串味很难恢复。冲泡前可以先用热水温一遍杯，热杯更有利于复合香气的层次释放；闻香时先闻杯盖、再闻公道杯，往往能感到香气在不同温度下的变化。"}]', '["product_keemun_100"]', 0, 520, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3804420247279721210', 'tea_dianhong', 'dianhong', '滇红', '["云南红茶","滇红工夫"]', 'black', '云南省', '临沧市', '凤庆县为核心产区，保山、西双版纳、普洱等地亦有生产', '云南大叶种红茶，条索肥壮、金毫显露，甜香蜜香浓郁并带焦糖香，滋味浓强鲜爽、汤感厚重。', '["萎凋","揉捻","发酵","干燥"]', '["甜香","蜜香","焦糖香"]', '["浓强","鲜爽","汤感厚重"]', '["早晨提神","奶茶基底","香料调饮","寒冷天气"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":95,"max":100},"vessel":["瓷壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"大叶种耐高温；红碎茶通常只冲1至2泡；调饮可用锅煮并适当加浓。"}', '密封、干燥、避光、防异味，常温保存。', '金毫显露的茶容易吸潮，开封后注意防潮。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925060.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"滇红即云南红茶，主产于云南省临沧市凤庆县一带，保山市、西双版纳州、普洱市等地也有生产。云南茶区纬度低、海拔高，大叶种茶树在这里生长旺盛，叶片厚、内含物多，与中小叶种形成了明显不同的原料基础，这也是滇红风格浓强的根本原因。滇红按产品形态可分为工夫红茶与红碎茶两类：前者讲究条索与金毫，后者切碎分级，多用于袋泡与调饮，两条路线各有各的场景。同一个产区、同一批鲜叶，最终做成什么形态，取决于它要出现在清饮杯里还是奶茶杯里；选购前先想清楚用途，往往比单纯比较价格更有效。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：大叶种叶片厚实，萎凋更讲究均匀，避免外干内湿。","揉捻：成条并充分破坏叶细胞，为发酵提供条件。","发酵：大叶种原料的发酵程度通常略重于中小叶种。","干燥：分批烘干，锁定浓强风味与金毫色泽。","分级整形：工夫红茶保持条索，红碎茶切碎分级，后者多用于袋泡与调饮。"]},{"type":"paragraph","text":"滇红最值得留意的是「发酵程度略重」这个选择。大叶种的茶多酚含量普遍更高，一般在三成以上，发酵不足会留下明显的涩感，把甜香压住；适度加重发酵，才能把浓强度转成醇厚感，并让甜香与焦糖香充分出来。也因为茶多酚基数大，滇红的茶黄素、茶红素生成量在红茶中属于靠前的一档，这是它汤感厚重、耐得住加奶稀释的原因，也让它成为奶茶基底的常见选择。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索肥壮，金毫显露，这是大叶种最直观的标志，也是「金芽」说法的来源。汤色红浓明亮。香气以甜香、蜜香为主，夹杂明显的焦糖香，冲泡时香气来得快、去得也快。滋味浓强鲜爽，汤感厚重，刺激性强于中小叶种红茶——喜欢浓一点的人会觉得过瘾，口味偏淡或胃部敏感的人则可以适当减少投茶量、缩短浸泡时间，同样能喝到它的甜香。挑选时可以留意条索是否完整、金毫是否自然；过度碎断的原料在清饮时表现会明显打折，但用于调饮反而更容易出味，选购前先想清楚用途更划算。"},{"type":"tip","tone":"info","title":"识茶提示","text":"金毫是否显露、条索是否肥壮，是判断大叶种原料的直观线索。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；瓷壶或盖碗都可以，调饮可直接用锅煮。"},{"title":"高温冲泡","text":"水温95–100 ℃，大叶种耐高温；水温不足反而会让浓强度出不来，显得寡淡。"},{"title":"快出汤","text":"第一泡5–10秒，之后每泡递增；工夫红茶可冲5–7泡，红碎茶通常1–2泡。"},{"title":"调饮思路","text":"做奶茶基底时把茶汤煮得浓一些，再按口味加鲜奶或炼乳，注意保持小火避免糊底。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"空腹喝浓滇红的刺激感会比一般红茶更明显，胃溃疡或反流人群尤其要避开浓饮。另外，市售奶茶的健康风险主要来自添加糖与植脂末，而不是茶本身，自己做时选鲜奶、少放糖更划算。热饮也要注意温度，超过65 ℃的热饮被 IARC 列为2A类「可能对人类致癌」，关键在温度而非茶，建议放到50–60 ℃适口再喝。"},{"type":"paragraph","text":"搭配上，滇红是奶茶基底的首选之一，加鲜牛奶、黑糖或炼乳都合适；想玩点变化，可以按中式改良的思路加肉桂、丁香、小豆蔻和姜煮成香料红茶，注意香料宜少不宜多，过量会压住茶香，牛奶也要保持小火慢热以免糊底。存放上密封、干燥、避光、防异味，常温保存就行，金毫显露的茶尤其怕潮，受潮后汤色和香气都会明显走低。如果是红碎茶，最好按一次用量分装，开封后尽快用完；它的香气散失速度比条索完整的工夫红茶更快，放久了甜香会先消失，只剩单薄的浓度。"}]', '["product_dianhong_100"]', 0, 530, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1244274594152324595', 'tea_yingde', 'yingde-hongcha', '英德红茶', '[]', 'black', '广东省', '清远市', '英德市', '粤北大叶种红茶，以英红九号为代表，甜香高锐并带花香与焦糖香，浓强鲜爽，本地惯用鲜奶调饮。', '["萎凋","揉捻","发酵","干燥"]', '["甜香","花香","焦糖香"]', '["浓强","鲜爽","花蜜香"]', '["早餐奶茶","下午茶","油腻餐后"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":95,"max":100},"vessel":["瓷壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":7},"methodTip":"大叶种耐高温；调饮时把茶汤泡浓再加鲜奶或炼乳。"}', '密封、干燥、避光、防异味，常温保存。', '香气衰减较快，开封后尽快喝完。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833472.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"英德红茶产自广东省清远市英德市，是粤北茶区的代表。粤北多丘陵山地，气候温暖湿润、雨量充沛，适合大叶种茶树生长，也让鲜叶的茶多酚积累得比较充分。英德红茶以大叶种原料为主，云南大叶种与凤凰水仙等品种都曾在这里广泛种植；历史上英德曾以红碎茶的形式出口，在国际市场上有过自己的位置。后来本地选育出的「英红九号」成为代表性产品，把英德红茶的风味特征固定了下来。选择时可以留意「英红九号」这个关键词：它既是品种名，也是当地长期的主力产品，表现稳定、可对照性强，比只看产地名更能反映杯中的实际风格。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：粤北山区湿度较高，萎凋要控制走水速度，避免叶片过早发红。","揉捻：大叶种叶片厚，需充分揉透以利发酵均匀。","发酵：发酵程度与滇红相近，走浓强路线。","干燥：锁定甜香与金毫色泽，稳定品质。","分级整形：工夫红茶保条索，红碎茶切碎分级，后者更常用于调饮与出口。"]},{"type":"paragraph","text":"英德红茶的工艺参数与滇红相近，因为二者都以大叶种为原料，酚氨比高，属于适制红茶的品种类型。它的辨识度更多来自品种：英红九号的香气物质丰富，做出来的茶甜香高锐，带花香与焦糖香，浓强鲜爽而收敛性适中。同样的工艺参数换一个品种，风味的落点就不一样，这是英德红茶与滇红最实际的区别，也是它值得被单独认识的理由，而不是谁的替代品。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结、金毫明显。汤色红艳明亮。香气上，甜香高锐是它的第一印象，花香与焦糖香跟在后面，英红九号的花蜜香尤其突出，冲泡后段仍能闻到。滋味浓强鲜爽，收敛性适中，比滇红略柔和一点，汤感厚实但不至于过分霸道。整体风格适合既要浓度、又要香气的喝法，加奶之后香气也不容易被完全盖住，这是它做奶茶的优势所在。它和滇红放在一起对比时，差别主要集中在香气的锐度与收敛性的轻重上：前者更张扬，后者更厚实，多泡几次、并排着喝就能分清。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；瓷壶或盖碗都合适，瓷壶更利于保温。"},{"title":"控温","text":"水温95–100 ℃，大叶种不怕高温；水温偏低会让浓强度出不来。"},{"title":"出汤","text":"第一泡5–10秒，之后每泡延长5–10秒，可冲5–7泡，忌长时间闷泡。"},{"title":"奶茶做法","text":"按广东本地的习惯，把茶汤泡浓后加鲜奶或炼乳，甜香会更清楚。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"英德红茶容易被当成「滇红的翻版」。两者工艺相近，但品种与产区不同，英德的红碎茶传统与英红九号的花蜜香是它自己的线索，不能只凭浓强程度就混为一谈。另外调饮时不要用植脂末代替鲜奶，那会带来反式脂肪酸与额外的游离糖，抵消了红茶本身低热量、无糖的优势。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配上，英德红茶与鲜奶、炼乳相性好，是广东常见的奶茶选择；也适合配微甜西点，或者按柠檬红茶的思路加柠檬，清爽解腻。要避开的是牛奶加大量柠檬的组合，柠檬酸会让乳蛋白絮凝，出现絮状沉淀。存放上密封、避光、防异味、常温保存，开封后尽快喝完，香气衰减会比较明显，金毫也容易因受潮而失去光泽。若习惯一次买半斤以上，建议分装成小份保存，每次只开一份；这样香气衰减的速度会比反复开合同一袋慢很多，取茶时也别忘了把袋口压紧。"}]', '[]', 0, 540, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('6914330199984209057', 'tea_chuanhong', 'chuanhong-gongfu', '川红工夫', '["川红"]', 'black', '四川省', '宜宾市', '筠连、高县、珙县等川南产区', '川南工夫红茶，甜香中带橘香与花香，滋味醇厚鲜爽，传统代表品种为早白尖，汤色红艳明亮。', '["萎凋","揉捻","发酵","毛火","足火","精制"]', '["甜香","橘香","花香"]', '["醇厚","鲜爽","甜醇"]', '["上午提神","川菜餐后","加奶调饮"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":6},"methodTip":"中小叶种不宜用沸水；清饮快出汤，调饮可适当加浓。"}', '密封、干燥、避光、防异味，常温保存。', '橘香类香气容易挥发，开封后尽早饮用。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832961.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"川红工夫产自四川省宜宾市，筠连、高县、珙县一带是主要产区。川南的茶园多分布在丘陵与低山之间，气候温和、雨量充沛，茶树发芽早，春季原料的嫩度与匀整度都不错。原料以中小叶种为主，也有一部分大叶种。传统代表品种是「早白尖」，川红甜香里那点橘香与花香，很大程度上与这个品种和这片产区的组合有关，也是它区别于其他工夫红茶的识别点。这个品种在川南种植的历史较长，发芽整齐、芽叶嫩度好；这也是川红外形细紧、金毫显露的另一层原因，与单纯靠工艺揉出来的紧结并不完全一样。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：中小叶种叶片较薄，萎凋时间相对好控制。","揉捻：成条并破坏叶细胞，条索细紧的基础在这一步。","发酵：酶促氧化生成茶黄素、茶红素，形成红汤红叶。","毛火：高温快速脱水并终止发酵，防止发酵过头。","足火：低温足干，发展甜香与橘香。","精制：拣剔、筛分、拼配，稳定批次风味与净度。"]},{"type":"paragraph","text":"川红的看点在于「甜香带橘香」这条风味线索，它主要由品种与产区的组合决定，而不是靠后期添加。工艺上，毛火与足火的火功把握是难点：火轻了香气不足、带青气；火重了橘香会被烤成焦味，甜感也会变钝。中小叶种原料的氨基酸含量较高，甜醇感的底子好，火功只要不压过头，滋味就容易做得厚而顺，这也是川红整体走甜润路线的原因。换句话说，川红的甜润不是靠降低发酵度换来的清淡，而是在发酵到位的前提下，用火功把甜感护住；这也是它与那些香气高但汤感偏薄的工夫红茶最不同的地方。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索细紧、金毫显露。汤色红艳。香气以甜香为主，橘香与花香是它的辨识点，但并不是每一年都同样明显，香气会随气候与批次有所浮动，这一点需要有心理预期。滋味醇厚鲜爽，甜感靠前，涩感比大叶种红茶弱。整体走的是甜润路线，与滇红、英德红茶那种浓强风格形成对照，适合不追求强烈刺激、更看重顺口的人。它对水温与时间的宽容度中等：泡得略淡时甜香更清楚，泡得略浓时厚度更足，两种风格都有人偏爱，可以按当天的口味随时调整。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；白瓷盖碗或瓷壶都可以，白瓷更便于看汤色。"},{"title":"控温","text":"水温90–95 ℃，中小叶种不必用沸水，高温会把橘香烤得发粗。"},{"title":"出汤","text":"第一泡5–10秒，之后每泡延长5–10秒，可冲5–6泡，久闷会明显发涩。"},{"title":"餐后饮","text":"传统上川红常放在川菜餐后饮用，用来解腻；注意别与重辣菜肴同时入口。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"「川红橘香」是品种与工艺共同形成的天然香气，不是加了橘子或香精，反过来也不能单靠香气就判断等级，还要看汤色、滋味与叶底。另外川红虽然口感甜润，空腹浓饮同样会刺激胃酸分泌，别因为柔顺就放任浓度，睡前6小时内也建议避开。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配上，川红适合配川式清淡茶点，餐后用来解腻；加鲜牛奶做成奶茶，或者加一点蜂蜜都不错。要避开的是与重麻辣菜肴同时入口，辣椒与花椒的强烈刺激会把甜香与橘香完全盖住，等于浪费了它的长处。存放上密封、干燥、避光、防异味即可，橘香类香气容易挥发，开封后尽早喝完，也不宜与气味重的食物同放。如果买的是散茶，建议分装后挤出袋内空气再密封；川红的橘香与甜香都属于容易散失的类型，存放环境的气味也容易被它吸附进来。"}]', '[]', 0, 550, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('8168318976575462662', 'tea_yixing', 'yixing-hongcha', '宜兴红茶', '["宜红"]', 'black', '江苏省', '无锡市', '宜兴市太华、张渚等山区', '江苏宜兴的工夫红茶，甜香蜜香清雅，滋味醇和甘润、汤感柔顺，刺激性弱于大叶种红茶。', '["萎凋","揉捻","发酵","烘焙","精制"]', '["甜香","蜜香","清雅花香"]', '["醇和","甘润","柔顺"]', '["紫砂壶慢饮","江南下午茶","上午提神"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["紫砂壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":6},"methodTip":"本地特色是用宜兴紫砂壶冲泡；紫砂壶保温性好，出汤要果断。"}', '密封、干燥、避光、防异味，常温保存。', '开封后密封防潮，香气明显减弱前饮用更佳。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833473.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"宜兴红茶产自江苏省无锡市宜兴市，太华、张渚等山区是主要产地。宜兴地处江南，山区竹林与林木覆盖率高、空气湿度大，茶树在这样的环境里生长得相对温和，鲜叶的刺激性物质积累不如大叶种产区那么突出。宜兴以紫砂壶闻名，同一片土地上既出茶器也出茶，本地品饮红茶的场景往往和紫砂壶绑在一起。原料以中小叶种为主，风格上不追求浓强，而是往醇和柔顺的方向走。同样的原料若放到大叶种产区去种，未必能做出这种柔和的口感；换句话说，宜兴红茶的风格有一半是产地给的，另一半才是工艺上的取舍。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：山区湿度大，走水要稳，避免叶片失水过快而发红。","揉捻：成条并适度破坏叶细胞，为发酵做准备。","发酵：程度适中，避免过重带来暗沉汤色与熟闷味。","烘焙：火功偏温和，保留清雅的甜香与蜜香。","精制：筛分拣剔，稳定条索与净度。"]},{"type":"paragraph","text":"宜兴红茶的关键选择是「不往浓强里做」。中小叶种原料的茶多酚基数低于大叶种，发酵与烘焙都取相对温和的路线，出来的茶刺激性低、汤感柔顺。这不是工艺上的妥协，而是有意的风格定位：想要一杯可以慢慢喝、不压口腔的红茶，中小叶种产区往往更合适。发酵程度控制在适中区间，也是为了保住香气的清雅，而不是用更重的发酵去换更多的醇厚。发酵、烘焙与原料三者之间需要彼此迁就：原料刺激性强就靠发酵压一压，原料偏柔就靠火功把香气提起来，宜兴红茶显然属于后者，工艺因此更偏向“护”而不是“攻”。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索细紧、色泽乌润，条索匀整、碎末少。汤色红亮。香气以甜香与蜜香为主，清雅不张扬，细闻有一点柔和的花香。滋味醇和甘润，汤感柔顺，刺激性明显弱于大叶种红茶，入口的涩感很轻。整体是一杯喝得久的红茶，配上紫砂壶慢饮更合它的性子，也适合作为刚接触红茶、还不太适应浓强口感的人的入门选择。它不太适合追求强烈冲击力的场合，更适合安静地坐着、一泡一泡慢慢喝；配一段午后时光或一本闲书，比配重口味的餐食更能显出它的好处。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；本地特色是用宜兴紫砂壶，白瓷盖碗也合适。"},{"title":"控温","text":"水温90–95 ℃，与中小叶种的嫩度相适应，不必追求沸水。"},{"title":"出汤","text":"第一泡5–10秒，之后每泡延长5–10秒，可冲5–6泡；紫砂壶保温好，出汤要果断。"},{"title":"慢饮","text":"用紫砂壶冲泡时可以适当留汤续水，让每泡的浓度更接近，口感更连贯。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"「刺激性低」不等于可以随便喝。宜兴红茶性味温和是相对大叶种红茶而言的，空腹浓饮、睡前饮用带来的不适并不会因此消失，它同样含咖啡因。另外，别把「宜兴产」直接等同于「紫砂名家壶」，茶与器是两件事，判断茶还是要回到外形、汤色、香气与滋味这四项。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配上，宜兴红茶适合配江南茶点，桂花糕、青团一类清淡微甜的都很合；加鲜牛奶也可以，只是会盖掉一部分清雅香气。要避开植脂末与重口味食物。存放上密封、干燥、避光、防异味、常温保存；另外紫砂壶用久了会吸附茶味，建议专壶专用，泡红茶与泡乌龙茶的壶最好分开，避免风味互相干扰。新买的紫砂壶建议先用开水烫洗、晾干再使用；长期只泡一种茶，壶身吸附的香气才会与茶味相合，而不是互相冲突。"}]', '[]', 0, 560, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7279107296683061403', 'tea_huhong', 'huhong-gongfu', '湖红工夫', '["湖红"]', 'black', '湖南省', '益阳市', '安化县为传统核心产区，新化、桃源、平江等地亦有生产', '湖南工夫红茶的统称，以安化为传统核心产区，蜜香纯正、滋味醇厚耐泡，汤色红浓明亮，曾为主要出口红茶。', '["萎凋","揉捻","发酵","烘焙","精制"]', '["甜香","蜜香","纯正"]', '["醇厚","甜醇","顺滑"]', '["早晨提神","湘菜餐后","冬日姜糖饮","待客"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":6},"methodTip":"冬日可加生姜与红糖煮饮，注意小火短时，不要久滚。"}', '密封、干燥、避光、防异味，常温保存。', '避免与香料、腊味等气味重的食物同放。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832962.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"湖红工夫是湖南红茶的统称，安化是传统核心产区，新化、桃源、平江等地也曾是重要产地。湖南多山多雾，安化一带的茶园分布在山区，湿度与云雾条件让鲜叶的内含物积累比较充分，发酵后的汤感自然偏厚。历史上湖红与祁红、建红并称，是中国主要的出口红茶之一，在旧时的国际茶市上占过一席之地，出口导向也影响了它后来的风格取向。正因为是统称，它覆盖的产区跨度较大，不同县域的原料基础不完全相同，成茶在厚度与香气上也会有差异，选购时不妨先少量试喝再决定。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：摊放失水，叶片柔软便于成条。","揉捻：成条并破坏叶细胞，为发酵准备。","发酵：酶促氧化，形成红汤红叶与醇厚底子。","烘焙：分段烘干，稳定香气并降低含水率。","精制：筛分、拣剔、拼配，统一出口与内销的批次品质。"]},{"type":"paragraph","text":"湖红的工艺走的是标准的工夫红茶通则，它真正的特点在产区与历史。安化一带的内含物基础好，发酵后的汤感就偏醇厚、偏浓；而作为曾经的出口茶，湖红长期以稳定的规格与醇厚耐泡为目标，而不是一味追求高锐的香气。这种取向带来一个实际好处：它的汤感经得起加奶稀释，做调饮时不容易被奶味完全盖住，耐泡度也比香高而汤薄的茶更实在。反过来说，如果追求的是高锐的香气，湖红未必是最合适的选择；它的长处在于稳，在于一壶泡下去几道之间的落差不大，这一点在待客时尤其省心。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结、色泽乌润，碎末少、净度好。汤色红浓。香气以甜香与蜜香为主，纯正不飘，没有祁红那种明显的蔷薇花香，也不需要。滋味醇厚，汤感实在，甜感在中后段慢慢出来，前段则以厚度为主，喉部的顺滑感比较明显。整体风格是踏实耐喝，配油腻一点的饭菜也不容易被压住，这也是它在湘菜餐桌上常见的原因。它的耐泡度通常不错，第五六泡仍能保持相当的厚度；这一点对习惯大壶冲泡、一次喝很久的人比较友好，也适合作为日常口粮茶。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；白瓷盖碗或瓷壶都合适，瓷壶更利于保温。"},{"title":"控温","text":"水温90–95 ℃，不必用沸水直冲，以免汤感发粗。"},{"title":"出汤","text":"第一泡5–10秒，之后每泡延长5–10秒，可冲5–6泡，久闷会带出涩感。"},{"title":"冬日喝法","text":"冷天可以按本地习惯加生姜与红糖一起煮饮，注意小火短时，不要久滚以免苦涩。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"湖红不像祁红、滇红那样有单一而鲜明的标签，市面上的产品品质落差也就更大，选购时不必迷信「湖红」二字，还是要看具体产区与批次。另外，加生姜红糖只是风味喝法，并不改变红茶含咖啡因这个事实，睡前同样不宜饮用，也不能因为加了姜糖就当成暖身功效来宣传。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配上，湖红适合湘式咸鲜菜肴的餐后，用来解腻；加鲜牛奶做成奶茶也合适，冬天加生姜红糖煮饮是常见做法。要避开的是与重辣食物同饮，辣椒会把甜香和醇厚感都压下去。存放上密封、干燥、避光、防异味、常温保存，避免与香料、腊味等气味重的食物同放，红茶的吸附性会让串味很快显现，且难以逆转。若住在潮湿地区，建议在密封罐里放一小包食品级干燥剂并定期更换；红茶受潮之后，香气与汤色都会明显下降，且很难通过复烘挽回。"}]', '[]', 0, 570, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('8868505717700512087', 'tea_ninghong', 'ninghong-gongfu', '宁红工夫', '["宁红"]', 'black', '江西省', '九江市', '修水县为核心产区，武宁、铜鼓等地亦有生产', '江西修水的工夫红茶，甜香高长并带花果香，滋味醇厚鲜爽、汤色红艳，历史上与祁红齐名。', '["萎凋","揉捻","发酵","烘焙","精制"]', '["甜香","花果香","高长"]', '["醇厚","鲜爽","甜润"]', '["上午提神","下午茶","加奶调饮","待客"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":6},"methodTip":"香气高长，出汤后可先闻杯盖与公道杯的留香。"}', '密封、干燥、避光、防异味，常温保存。', '香气高长易受异味影响，开封后及时封口。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832963.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"宁红工夫产自江西省九江市修水县，武宁、铜鼓等地也属于传统产区。修水地处赣西北山区，山林覆盖率高、云雾条件好，是宁红的核心产地。历史上宁红与祁红齐名，是工夫红茶中相当有分量的一支，在旧时的茶市交易中地位突出。它还有一些特色产品，比如做成特定形态的「宁红龙须茶」，在工夫红茶的谱系里算是别致的一路，也让宁红在形态上有了自己的记忆点。除了龙须茶，宁红在历史上还出现过其他形态的产品；这些做法合在一起，构成了它在工夫红茶中较为鲜明的辨识度，也让它在众多产区红茶中不容易被混淆。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：摊放失水，为揉捻创造条件。","揉捻：成条并破坏叶细胞，条索紧结的基础。","发酵：酶促氧化，形成红艳汤色与醇厚滋味。","烘焙：分段烘干，发展高长的甜香。","精制：筛分拣剔与拼配；特色产品另有专门的整形工序，多为手工。"]},{"type":"paragraph","text":"宁红的风味落点在香气上：甜香高长并带花果香，这是它区别于湖红、宜红那类「甜香清雅」路线的地方。香气要在烘焙阶段守住，火功偏轻则香气不足、带青气，偏重则花果香转为焦气，中间的窗口并不宽。精制环节对宁红同样重要，因为条索与净度直接影响外形观感，传统上宁红在这一环下的功夫不少，特色产品的整形更是近乎全靠手工完成。与同属江南茶区的其他工夫红茶相比，宁红在“香”上更主动，在“形”上也不肯将就；这两点合起来，才是它在旧时茶市里能与祁红并列的底气所在。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索紧结、色泽乌润，净度好。汤色红艳。香气甜香高长，花果香在冲泡后段更明显，这是宁红最值得留意的部分，也是它的记忆点所在。滋味醇厚鲜爽，甜润感靠前，涩感不重。整体风格是香气外放、滋味扎实，与同样产自江南地区的宜兴红茶放在一起对比，宁红的香会明显更飘扬，宜红则更内敛沉稳。如果偏爱香气型的红茶，可以在出汤后稍等片刻再喝；温度略降时花果香反而更集中，甜润感也会更清楚，与滚烫时入口的感受差别不小。"},{"type":"quote","text":"宁红不到庄，茶叶不开箱。","source":"旧时茶市谚语"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；白瓷盖碗或瓷壶都可以，白瓷更利闻香。"},{"title":"控温","text":"水温90–95 ℃，避免沸水直冲把花果香烫得发粗。"},{"title":"出汤","text":"第一泡5–10秒，之后每泡延长5–10秒，可冲5–6泡，忌久闷。"},{"title":"闻香","text":"出汤后先闻杯盖与公道杯的留香，宁红的花果香在温热器皿上更清楚。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"不要用那句茶市谚语当作选购依据，它描述的是旧时的历史地位而非今天的品质，具体还是要看产区、批次与存放条件。另外红茶含咖啡因，晚间浓饮同样会影响入睡，这一点不因为香气好闻而改变；睡前6小时内建议避开，对咖啡因敏感的人尤其要注意。"},{"type":"paragraph","text":"搭配上，宁红适合配江南茶点，加鲜牛奶或蜂蜜也都不错；因为花果香突出，配味道清淡的点心更能显出它的长处。要避开植脂末与重口味食物。存放上密封、干燥、避光、防异味、常温保存，香气高长的茶对异味尤其敏感，别和香料、咖啡豆放在一起，开封后及时封口才能保住那股飘扬的花果香。如果打算存一段时间，建议选未开封的原包装或真空小包装；开封后的宁红香气衰减会比较快，反复开合尤其伤香。"}]', '[]', 0, 580, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3042547318090957159', 'tea_tanyang', 'tanyang-gongfu', '坦洋工夫', '[]', 'black', '福建省', '宁德市', '福安市坦洋村及寿宁、周宁等闽东茶区', '闽红三大工夫之首，桂圆香与蜜香突出，滋味醇厚鲜甜、汤色红亮，历史上曾远销欧洲市场。', '["萎凋","揉捻","发酵","烘焙","精制"]', '["桂圆香","蜜香","甜香"]', '["醇厚","鲜甜","桂圆汤感"]', '["下午茶","英式奶茶","待客","早餐后"]', '{"teaGrams":5,"waterMl":150,"ratio":"1:30","temperatureC":{"min":90,"max":95},"vessel":["白瓷盖碗","瓷壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"后续每泡延长5至10秒","infusionCount":{"min":5,"max":6},"methodTip":"做英式奶茶时把茶汤泡浓再加鲜奶，桂圆香与奶香能叠在一起。"}', '密封、干燥、避光、防异味，常温保存。', '条索细长易吸味，开封后注意密封。', '红茶含咖啡因，避免空腹浓饮与睡前6小时内饮用；本内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195832964.jpg', '[]', '[{"type":"heading","level":3,"text":"产地与身份"},{"type":"paragraph","text":"坦洋工夫产自福建省宁德市福安市坦洋村，寿宁、周宁等闽东茶区也有生产。闽东多山地，兼有海洋性气候的湿润温和，茶树生长环境稳定，鲜叶的持嫩性较好，这也是它条索细长的前提。它是闽红「三大工夫」之首，历史上曾远销欧洲，在海外茶市上有过稳定的销路；这段以出口为主的经历，也让它在风味上有意贴近当时海外市场偏好的甜醇与顺滑，而不是走高锐香气的路线。坦洋工夫的条索细长匀整、色泽乌黑有光，外形在工夫红茶里算是相当规整的一路，净度好是它长期保持的传统优势。"},{"type":"heading","level":3,"text":"工艺路径"},{"type":"list","ordered":false,"items":["萎凋：闽东湿度高，萎凋要控制走水均匀，避免外干内湿。","揉捻：细长条索在这一步成形，揉捻力度直接影响外形。","发酵：酶促氧化，形成红亮汤色与桂圆香的底子。","烘焙：分段烘干，稳定香气与色泽。","精制：筛分拣剔，坦洋工夫对外形匀整度要求较高。"]},{"type":"paragraph","text":"坦洋工夫最值得记住的是「桂圆汤」这条传统描述。它并不是加了桂圆，而是指茶汤里那种圆润、带甜、微微近似桂圆干的香与味，由品种、发酵与烘焙共同塑造。烘焙阶段的火功对这条线索影响很大：火候到位，桂圆香与蜜香会一起出来；火候过了，甜感会被烤成焦苦，桂圆汤的感觉也就散了。这也是它工艺上最考验经验的一环，急不得也省不得。此外，坦洋工夫的外形之所以常年保持细长匀整，揉捻与精制两道的分寸同样关键：揉得太重条索会断碎，拣剔不细则净度下降，都会直接影响它在杯中的观感。"},{"type":"heading","level":3,"text":"识茶要点"},{"type":"paragraph","text":"外形条索细长匀整、色泽乌黑有光，净度好是它的传统优势，碎末与梗片都很少。汤色红亮。香气以桂圆香与蜜香为主，甜香垫底，冷了之后桂圆香依然能闻到。滋味醇厚鲜甜，汤感顺滑，桂圆汤感是传统品质描述里最常被提到的一点。整体风格圆润讨喜，加奶之后依然保有辨识度，因此常被拿来做英式奶茶的基底。与同为闽红的其他工夫茶相比，坦洋工夫的甜感更靠前、汤感更顺；喝不惯浓强风格的人通常更容易接受它，用它入门工夫红茶也比较友好。"},{"type":"heading","level":3,"text":"冲泡建议"},{"type":"steps","items":[{"title":"备器投茶","text":"5 g干茶配150 ml水，约1:30；白瓷盖碗或瓷壶都合适，白瓷更便于看汤色。"},{"title":"控温","text":"水温90–95 ℃，不必用沸水直冲，以免汤感发粗、甜感变钝。"},{"title":"出汤","text":"第一泡5–10秒，之后每泡延长5–10秒，可冲5–6泡，忌长时间闷泡。"},{"title":"英式喝法","text":"做英式奶茶时把茶汤泡浓再加鲜牛奶，桂圆香与奶香能叠在一起。"}]},{"type":"tip","tone":"warning","title":"常见误区","text":"「桂圆汤」是风味的比喻，不要理解成茶里加了桂圆，也不要把桂圆香当成等级的唯一标准，外形、汤色、叶底同样要看。另外坦洋工夫适配西式甜点与奶茶，但加奶的茶别再挤大量柠檬汁，否则乳蛋白会絮凝沉淀，口感与外观都会变差，这一点常被忽略。"},{"type":"heading","level":3,"text":"品鉴与搭配"},{"type":"paragraph","text":"搭配上，坦洋工夫适合配微甜西点，做英式奶茶是它最经典的用法；也可以直接配几颗桂圆干，让风味互相呼应。要避开植脂末与高糖果浆，那会把圆润的桂圆香压成单纯的甜腻。存放上密封、干燥、避光、防异味、常温保存，条索细长的茶吸味快，开封后注意及时封口，也不要与香料、咖啡等气味重的东西放在一起。如果一次买得较多，可以按半个月的用量分装，减少开封次数；桂圆香与蜜香才能留得更久，条索也不容易在反复取用中受潮。"}]', '[]', 0, 590, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('184649584603810829', 'tea_anhua_qianliang', 'anhua-qianliang', '安化千两茶', '["千两茶","花卷茶"]', 'dark', '湖南省', '益阳市', '安化县，资江沿岸为核心产区', '以竹篾花格篓踩压成柱的湖南黑茶，竹香与陈香并存，汤色橙黄转红浓，耐泡度极高，也可煮饮。', '["杀青","揉捻","渥堆","复揉","烘焙","筛分拼配","蒸软装篓与踩压","日晒夜露干燥"]', '["竹香","松烟香","陈香"]', '["醇厚","浓烈","回甘强"]', '["重油餐后","秋冬煮饮","办公室焖泡","围炉煮茶"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","煮茶壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"润洗后逐泡延长五到十秒，后段可整块转煮饮","infusionCount":{"min":10,"max":15},"methodTip":"柱体紧实，先分层撬成小块；沸水润洗一至两遍后快出汤。想喝得更厚可冷水入壶煮，煮沸转小火三到五分钟。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833474.jpg', '[]', '[{"type":"heading","level":3,"text":"资江边踩出来的茶柱"},{"type":"paragraph","text":"千两茶出在湖南益阳安化，资江沿岸是传统核心产区。它属于湖南黑茶里的花卷茶类，成型之后是一根紧实的圆柱，外面裹着竹篾编成的花格篓，篓内再衬粽叶。传统规格重约 36.25 公斤，也就是老秤的一千两，「千两茶」的名字由此而来，同类还有百两茶等规格。这套踩制技艺已被列入国家级非物质文化遗产名录。安化黑茶历史上是边销茶的主力，长期销往西北牧区，是当地肉食奶食饮食结构里的日常饮品。"},{"type":"heading","level":3,"text":"从杀青到日晒夜露"},{"type":"list","ordered":false,"items":["杀青、揉捻：让鲜叶失水软化、条索成形，为后续的深度转化打底。","渥堆：毛茶趁湿堆积，在微生物与湿热共同作用下深度转化，这是黑茶独有的工序。","复揉、烘焙：进一步整理条索并去水，稳定内质，也便于后续装篓。","筛分拼配：把不同批次、不同粗细的原料按比例拼合，统一成品风味。","蒸软装篓：汽蒸回软后装入竹篾花格篓，为踩压成型做准备。","人工踩压与杠压：反复踩、压、滚，靠人力把茶压成紧实的圆柱体。","日晒夜露：自然干燥约四十到五十天，竹篓与粽叶的气息在这段时间进入茶里。"]},{"type":"paragraph","text":"千两茶最要紧的是踩压与日晒夜露这两步。踩压决定柱体的紧实度，压得够紧，内部的转化才缓慢而均匀，也更经得起长期存放；日晒夜露则是长达四十到五十天的自然干燥，白天日晒、夜里吸露，水分缓慢走掉，竹香与粽叶香同时渗进茶里，形成它区别于其他黑茶的清正气息。也正因为做得紧实，喝之前需要花点力气撬茶，块形撬得越完整越耐泡。这类紧压茶建议拆散后放在紫砂罐或牛皮纸袋里醒茶一到两周，风味会有明显提升。"},{"type":"heading","level":3,"text":"怎么认千两茶"},{"type":"paragraph","text":"外形是紧实的圆柱，外裹竹篾花格篓与粽叶，篓上常捆扎竹箍。切开后茶体呈黑褐色，条索粗壮，带一定的梗。汤色由橙黄逐渐转为红浓，透亮不浑。香气以竹香、松烟香与陈香为主，篓香清晰是它最好认的辨识点。滋味醇厚浓烈，汤感饱满，回甘强，耐泡度在黑茶里也属于上乘——黑茶的耐泡度本就在六大茶类中居首，千两茶是其中代表。经过存放，陈香会更明显，汤感更顺，但前提是仓储得当。"},{"type":"paragraph","text":"关于千两茶，有两个常见说法要澄清。一是「黑茶就是普洱茶」——黑茶包括湖南黑茶、湖北青砖、四川边茶、云南熟普、广西六堡与陕西茯茶等，普洱熟茶只是其中一支，千两茶属于湖南黑茶，不能互相替代。二是把「越陈越香」当成必然规律，实际上陈化结果取决于原料、工艺与仓储三件事，年份只是其中一个变量，仓储不当的老茶并不比仓储得宜的新茶更好。"},{"type":"heading","level":3,"text":"冲泡与煮饮"},{"type":"steps","items":[{"title":"撬茶","text":"用茶刀顺着茶柱纹理分层撬下，尽量保持块形完整；柱体紧实，小块比碎末更耐泡。"},{"title":"润洗","text":"沸水快进快出润洗一到两遍，唤醒茶性并带走表面浮尘。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，全程沸水，第一泡五到十秒出汤，之后每泡延长五到十秒，可冲十泡以上。"},{"title":"煮饮","text":"想喝得更厚，取五到八克配五百到八百毫升冷水入壶，煮沸后转小火三到五分钟，可复煮两到三次。"}]},{"type":"tip","tone":"warning","title":"仓储安全","text":"千两茶的陈香应是清正舒适的竹篓气息，不是霉味。如果篓内出现可见霉斑、酸馊味或刺鼻异味，说明仓储出了问题，这类茶不能饮用，也不能靠加陈皮或调味去掩盖。此外千两茶含咖啡因且含量不低，「黑茶不影响睡眠」的说法缺乏依据，睡前六小时内不宜饮用，服药前后一到两小时也应避免饮茶。"},{"type":"paragraph","text":"千两茶适合大餐、火锅、烧烤之后喝，传统上也是围炉煮茶的主力用茶。搭配上陈皮是经典组合，也可以配淡味坚果或菊花清口，陈皮尤能衬出竹香与陈香；不建议加牛奶，奶会盖掉它的竹香。日常饮用不必都用工夫泡法，用保温杯投三到五克焖两三分钟、之后续水，就很适合办公室。存放要放在清洁、干燥、通风、避光、无异味的地方，远离潮湿地面与墙面，不与有气味物品同放。最后补充一点饮用温度：茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。另外要记住，陈化结果取决于原料、工艺与仓储，并不是年份越久就一定越好；仓储出了问题，再久的年份也没有意义。"}]', '[]', 0, 600, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3317797424962167599', 'tea_anhua_fuzhuan', 'anhua-fuzhuan', '安化茯砖茶', '["茯砖","茯茶","金花茶"]', 'dark', '湖南省', '益阳市', '安化县，益阳、临湘等地亦有生产', '以「金花」为品质特征的湖南砖茶，菌花香突出、滋味醇厚带甜，耐煮耐泡，煮饮风味最佳。', '["杀青","揉捻","渥堆","干燥","筛分","蒸压成砖","发花","复干"]', '["菌花香","陈香","甜香"]', '["醇厚","顺滑","甜醇"]', '["重油餐后","早晨温饮","秋冬煮饮","家庭共饮"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","煮茶壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"润洗后逐泡延长，后段转煮饮风味更完整","infusionCount":{"min":10,"max":15},"methodTip":"先撬散，沸水润洗一至两遍再快出汤；煮饮为最佳方式，五到八克配五百毫升冷水，煮沸转小火三到五分钟。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '砖茶类氟含量相对较高，不建议长期大量饮用熬煮的浓砖茶。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927405.jpg', '[]', '[{"type":"heading","level":3,"text":"「金花」从哪来"},{"type":"paragraph","text":"安化茯砖茶产在湖南益阳安化，益阳、临湘一带也有生产，属于黑茶里的砖茶类。它最鲜明的标志是砖体内部密布的「金花」——那是冠突散囊菌的闭囊壳，呈金黄色颗粒状。在茯砖的品评里，金花的多少与分布是一项重要的品质特征。历史上这类砖茶长期销往西北牧区，当地有「宁可三日无粮，不可一日无茶」的说法，讲的就是它在肉食奶食为主的饮食里的位置——牧区蔬菜少，砖茶是长期以来的日常饮品。"},{"type":"heading","level":3,"text":"渥堆之后还要「发花」"},{"type":"list","ordered":false,"items":["杀青、揉捻：鲜叶处理后初步成形，为后续转化做准备。","渥堆：微生物与湿热共同作用，完成黑茶特有的深度转化。","干燥、筛分：去水并把原料分出不同粗细，便于拼配。","蒸压成砖：汽蒸回软后压成紧实的砖块，砖形便于运输与长期存放。","发花：在烘房内控制温湿度，让冠突散囊菌生长，形成「金花」。","复干：把砖体水分降到安全范围，避免后期受潮劣变。"]},{"type":"paragraph","text":"发花是茯砖区别于其他黑茶的关键一步。它需要在烘房里精细控制温度与湿度，条件合适时冠突散囊菌（曾用学名 Eurotium cristatum，现分类学多采用 Aspergillus cristatus）才会在砖体内部生长，形成金黄色颗粒；条件不合适，要么发不出花，要么杂菌乘虚而入。也正因为这一步依赖环境，历史上才有「离了泾阳水、泾阳气候不能制」的说法。这属于传统经验总结，今天在合适的厂房条件下，湖南、陕西等多地都能生产茯砖。"},{"type":"heading","level":3,"text":"认砖先认花"},{"type":"paragraph","text":"砖形紧实，色泽黑褐，撬开后断面上金花呈金黄色颗粒，分布均匀。汤色橙红明亮。香气以菌花香最突出，夹杂陈香；滋味醇厚顺滑，甜感好，不苦不涩。这里要分清两件事：金花是金黄色、颗粒状、干爽的，闻起来是舒服的菌花香；霉变则是绿霉、黑霉或白色绒毛状，伴随刺鼻霉味或酸馊味。这两者在茯砖上尤其容易混淆，也是最需要留意的地方。"},{"type":"tip","tone":"info","title":"识茶提示","text":"金花是金黄色颗粒，闻起来是干净的菌花香；霉变则多呈绿霉、黑霉并带刺鼻气味。"},{"type":"heading","level":3,"text":"撬开、煮透"},{"type":"steps","items":[{"title":"撬茶","text":"沿砖体边缘用茶刀分层撬散，块形保持完整更耐泡；撬好后可先醒茶一到两周。"},{"title":"润洗","text":"沸水快进快出润洗一到两遍，去浮尘并唤醒茶性。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，沸水冲泡，第一泡五到十秒出汤，之后逐泡延长，可冲十泡以上。"},{"title":"煮饮","text":"五到八克配五百毫升冷水入壶，煮沸后转小火三到五分钟，菌花香与甜感释放得更完整。"}]},{"type":"tip","tone":"warning","title":"金花与霉变别弄混","text":"茯砖的仓储安全要单独说清楚：金花是受控发花形成的冠突散囊菌，属于正常品质特征，不是霉变；霉变是仓储受潮导致的劣变。出现可见霉斑、酸馊味或刺鼻异味，就不是正常陈香，这类茶不能饮用，也不能用调味去掩盖。另外砖茶类原料成熟度较高，氟含量相对偏高，不建议长期大量饮用熬煮的浓砖茶，更不要整天以浓砖茶代水。"},{"type":"paragraph","text":"茯砖传统上是重油餐后的主力用茶，早晨温热着喝比较温和，也很适合家庭共饮。搭配陈皮、菊花或咸香茶点都合适，加一点陈皮尤其能衬出菌花香；不建议加牛奶，奶会压住菌花香。日常用保温杯投三到五克焖两三分钟也很方便。存放要求清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。需要强调的是，茯砖的价值来自发花工艺与仓储，而不是年份数字——同样标注十年的两砖茶，仓储条件不同，风味可以相差很远；购买时看金花是否自然、香气是否干净，比只看年份更实际。茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '["product_fuzhuan_300"]', 0, 610, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('8256583128742200111', 'tea_ripe_puer', 'ripe-puer', '普洱熟茶', '["熟普","熟茶"]', 'dark', '云南省', '西双版纳州、普洱市、临沧市', '以勐海等传统加工地为代表', '经人工渥堆后发酵，陈香与木香明显，汤色红浓明亮，滋味醇厚顺滑、甜感明显，新茶略带堆味。', '["晒青毛茶","洒水渥堆","多次翻堆","干燥筛分","蒸压成型或散装"]', '["陈香","木香","熟果香"]', '["醇厚","顺滑","甜感明显"]', '["重油餐后","早晨温饮","秋冬煮饮","冷泡"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","白瓷盖碗","煮茶壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"润洗后快出汤，后续按汤色逐泡延长","infusionCount":{"min":10,"max":15},"methodTip":"紧压茶先撬成小块，沸水润洗一至两遍后快出汤，避免闷出沉重堆味；也可一比一百冷泡，冷藏约十二小时。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926809.jpg', '[]', '[{"type":"heading","level":3,"text":"渥堆造就的熟普"},{"type":"paragraph","text":"普洱熟茶产在云南，西双版纳、普洱、临沧、大理等地都有生产，勐海是传统的核心加工地。它以云南大叶种晒青毛茶（滇青）为原料，经人工洒水渥堆、微生物固态发酵而成，发酵过程大约四十到六十天，其间需要多次翻堆。这里要先说明一点：渥堆是受控的微生物发酵，参与的以黑曲霉、酵母、冠突散囊菌等为主，与受潮之后的霉变是两回事，不能因为「发酵」两个字就把熟普当成发霉茶。"},{"type":"heading","level":3,"text":"先有晒青，才有渥堆"},{"type":"list","ordered":false,"items":["晒青毛茶：云南大叶种鲜叶杀青揉捻后日光干燥，做成滇青。","洒水渥堆：毛茶补水后堆积，微生物参与的固态发酵就此开始。","多次翻堆：约四十到六十天里反复翻堆，让温湿度与转化保持均匀。","干燥筛分：结束发酵，并把原料分出不同粗细便于拼配。","蒸压成型：压成饼、砖、沱，或直接以散茶形式存放。"]},{"type":"paragraph","text":"熟普与生普的分岔就在渥堆这一步。生普靠时间缓慢自然后发酵，熟普则是用人工渥堆在几十天里把转化快速走完，所以新熟茶出来就是红浓的汤色与醇滑的口感，不必等许多年。代价是新茶往往带一点「堆味」——一种偏沉的发酵气息，通常会随适当存放逐渐减弱。醒茶也有帮助：把撬散的茶放在紫砂罐或牛皮纸袋里一到两周，堆味会散去一部分。冷泡对这种堆味的削弱更明显，是年轻群体接受度提升较快的一种喝法。"},{"type":"heading","level":3,"text":"红浓、醇滑、少苦涩"},{"type":"paragraph","text":"条索肥壮，色泽褐红。汤色红浓明亮。香气以陈香、木香为主，新茶阶段堆味比较明显。滋味醇厚顺滑，甜感明显，几乎不显苦涩，这是熟普相对好入口的地方。存放之后堆味减弱、陈香增强，汤感更顺。关于普洱茶与黄曲霉，食品安全研究表明黄曲霉主要滋生在高淀粉、高蛋白的食品里，而普洱茶含水量、淀粉与蛋白质含量都低，不利于其生长产毒，抽样检测也显示绝大多数样品未检出或远低于限量；真正的风险来自贮存不当造成的霉变，因此正规渠道购买与正确存放都很重要。"},{"type":"tip","tone":"info","title":"识茶提示","text":"看汤色是否红浓明亮、香气是否干净；堆味会随适当存放逐渐减弱。"},{"type":"heading","level":3,"text":"冲泡与冷泡"},{"type":"steps","items":[{"title":"撬茶","text":"沿饼面分层撬成小块，块形完整更耐泡，也避免碎末过多导致汤浑。"},{"title":"润洗","text":"沸水快速润洗一到两遍，唤醒茶性并带走表面浮尘。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，沸水冲泡，第一泡五到十秒出汤，之后逐泡延长，可冲十泡以上；老茶也可煮饮。"},{"title":"冷泡","text":"按一比一百的茶水比，冷水入瓶密封冷藏约十二小时，堆味大幅削弱，甜感与水感更突出。"}]},{"type":"tip","tone":"warning","title":"认清「堆味」与「霉味」","text":"新熟茶的堆味是受控发酵带来的气息，会随适当存放减弱；霉味则刺鼻、发酸发馊，往往还伴随可见霉斑。后者不可饮用，也不能靠调味去掩盖。还有一点：市面上的「糯米香」普洱，建议选择以天然糯米香叶窨制的产品，而不是添加人工香精的产品，购买时看配料表即可分辨。"},{"type":"paragraph","text":"熟普配陈皮是经典组合，冷泡也好搭：冷泡熟普二百毫升加陈皮丝一克，加冰即可，陈香与柑香相衬。调饮还可以做黑糖珍珠熟普奶茶——熟普浓缩液一百二十毫升配鲜牛奶一百二十毫升、黑糖八克，糖量比门店奶茶低不少，但属享受型饮品，不必高频喝。搭配菊花与淡味坚果也合适；生普不建议加牛奶，熟普调饮则相对合适。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。另外，熟普属于低热量饮品，用来替代含糖饮料有助于减少糖摄入，但体重管理仍要依靠饮食控制与运动，喝茶本身不承担这个功能；它含咖啡因且含量不低，睡前六小时内不宜饮用，缺铁性贫血人群避免餐中浓饮。茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '["product_ripe_puer_200"]', 1, 620, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7923980066954946164', 'tea_raw_puer', 'raw-puer', '普洱生茶', '["生普","生茶"]', 'dark', '云南省', '西双版纳州、普洱市、临沧市', '勐海、易武为两大核心产区', '以晒青毛茶蒸压成型，新茶花香与山野气明显、苦涩与回甘并存，随存放逐渐转向陈香与醇厚。', '["采摘","锅炒杀青","揉捻","日光干燥","蒸压成型","自然陈化"]', '["花香","蜜香","山野气"]', '["浓强","回甘快","生津"]', '["午后清口","新茶尝鲜","冷泡","陈茶品鉴"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":95,"max":100},"vessel":["白瓷盖碗","紫砂壶","煮茶壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"新茶极快出汤，陈年可适当坐杯，逐泡延长","infusionCount":{"min":10,"max":15},"methodTip":"新茶水温略降到九十五度、第一泡约五秒极快出汤以降苦涩；陈年可用一百度沸水并换紫砂壶。也可一比一百冷泡，冷藏约十二小时。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '新制生普对胃的刺激强于熟茶，胃部不适者避免空腹饮用。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927944.jpg', '[]', '[{"type":"heading","level":3,"text":"生普的分类难题"},{"type":"paragraph","text":"普洱生茶用云南大叶种晒青毛茶直接蒸压成型，产区以西双版纳的勐海、易武为两大核心，普洱、临沧等地也有生产。它的分类要在开头就说清楚：按加工工艺，生普属于晒青绿茶；但市场与饮用习惯上常把它和黑茶并论，原因是它在长期存放中会自然后发酵，风味向黑茶方向转化。这是行业公认的分类难点。顺带一提英文标注也容易出错：英文 Black Tea 指的是中国红茶，中国黑茶的对应词是 Dark Tea。"},{"type":"heading","level":3,"text":"保留酶活性的那条路"},{"type":"list","ordered":false,"items":["采摘：云南大叶种鲜叶，茶多酚与儿茶素等内含物质相对丰富。","锅炒杀青：温度低于绿茶，有意保留部分酶活性，为后续转化留出空间。","揉捻：整理条索，让细胞破损、物质更易浸出。","日光干燥：晒青，形成生普特有的日晒气息，也是它能继续转化的前提。","蒸压成型：压成饼、砖、沱，或以散茶形式存放。","自然陈化：在合适仓储下缓慢后发酵，香气与滋味逐年改变。"]},{"type":"paragraph","text":"生普与熟普的分岔点在渥堆。熟普用人工渥堆在几十天内完成深度发酵；生普没有这一步，靠的是时间与仓储条件下的缓慢自然后发酵。所以两者的起点就不同，生普无论放多久都不会「变成」熟普，它只会逐渐转化成风味独特的陈年生普——这是很常见的误解，值得单独记住。这也决定了生普新茶与陈年生普几乎像两种茶：新茶清冽、刺激感明显，陈茶转向醇厚顺滑。"},{"type":"heading","level":3,"text":"从墨绿到褐红"},{"type":"paragraph","text":"新茶色泽墨绿，条索肥壮。汤色黄绿明亮，随年份增加转为橙红。香气上，新茶是花香、蜜香与山野气，陈化后转向陈香、木香乃至药香。滋味浓强，苦涩明显但回甘快、生津强，这是生普标志性的体验；陈年之后苦涩减弱、汤感转醇。新制生普的茶多酚含量高，对胃的刺激明显强于熟茶，胃溃疡、胃炎、反流人群应避免空腹饮用，也不宜泡得过浓。"},{"type":"tip","tone":"info","title":"识茶提示","text":"新茶汤色黄绿、香气带花香与山野气，随年份会逐渐转向橙红与陈香。"},{"type":"heading","level":3,"text":"新茶与陈茶分开泡"},{"type":"steps","items":[{"title":"撬茶","text":"沿饼面分层撬成小块，尽量保持块形完整；紧压茶可先醒茶一到两周。"},{"title":"润洗","text":"沸水快速润洗一到两遍，去浮尘并唤醒茶性。"},{"title":"新茶冲泡","text":"水温可略降到九十五度，第一泡约五秒极快出汤以降苦涩，之后逐泡延长；器皿用白瓷盖碗便于看汤色。"},{"title":"陈茶冲泡","text":"可用一百度沸水，器皿换成紫砂壶更利于聚香；也可一比一百冷泡、冷藏约十二小时，风味清冽。"}]},{"type":"tip","tone":"warning","title":"仓储决定生普的下半程","text":"「越陈越香」是市场说法，不是必然规律，品质取决于原料、工艺与仓储。仓储不当会直接毁掉一饼茶：出现可见霉斑、酸馊味或刺鼻异味就不可饮用，务必从正规渠道购买。此外生普含咖啡因，严重失眠者下午之后应停饮；服药前后一到两小时避免饮茶，缺铁性贫血人群避免餐中浓饮。"},{"type":"paragraph","text":"新生普适合午后清口、尝鲜品鉴，陈年生普更适合餐后与秋冬品饮。搭配上以清淡茶点、淡味坚果为主，也可以冷泡，清冽的花香在冷泡里保留得比较好；不建议加牛奶，奶会盖掉鲜爽的山野花香，而且生普的涩感与奶结合容易发腥，空腹浓饮也要避免。存放要求清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。关于性味，生普新茶性偏凉、陈茶转平，这属于传统经验的性味说法，不作为现代医学结论，仅供参考。茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '["product_sheng_puer_200"]', 0, 630, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('1792334420373902975', 'tea_liubao', 'guangxi-liubao', '广西六堡茶', '["六堡茶"]', 'dark', '广西壮族自治区', '梧州市', '苍梧县六堡镇及周边产区，贺州、横州等地亦有生产', '以红、浓、陈、醇为风格特征，槟榔香与陈香并存，汤感醇厚甘爽，可煮饮也可冷泡。', '["杀青","揉捻","渥堆","复揉","烘干","蒸压装篓","陈化"]', '["槟榔香","陈香","松烟香"]', '["醇厚","甘爽","顺滑"]', '["重油餐后","潮湿季节","秋冬煮饮","冷萃气泡"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","煮茶壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"润洗后逐泡延长，后段也可转为小火煮饮","infusionCount":{"min":10,"max":15},"methodTip":"沸水润洗一至两次后快出汤；煮饮用五到八克配五百毫升冷水，煮沸转小火三到五分钟。冷泡按一比一百到一比一百五十冷藏约十二小时。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '传统经验中的说法不作为现代医学功效。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927406.jpg', '[]', '[{"type":"heading","level":3,"text":"六堡镇的槟榔香"},{"type":"paragraph","text":"六堡茶产在广西梧州苍梧县六堡镇，贺州、横州等地也有生产。它以「红、浓、陈、醇」为品质特征，最出名的是槟榔香——一种独特的陈香，部分传统工艺的产品还带松烟香。六堡茶的历史与两广的湿热气候关系密切，传统的泥屋、岩洞陈化是它形成风味的重要环节，也是它区别于其他黑茶的地方：别的黑茶讲陈化，六堡茶把陈化做成了产地传统的一部分。"},{"type":"heading","level":3,"text":"罨堆与陈化"},{"type":"list","ordered":false,"items":["杀青、揉捻：完成初步成形，为渥堆做准备。","渥堆：微生物与湿热共同作用，进入黑茶的深度转化。","复揉、烘干：整理条索并去水，稳定内质。","蒸压装篓：汽蒸后压入竹篓，竹篓既是传统形态，也是风味来源之一。","陈化：传统置于阴凉泥屋或岩洞中，历时数年乃至数十年，风味在此定型。"]},{"type":"paragraph","text":"六堡茶的两个关键点是罨堆与陈化。前者是渥堆阶段的处理，决定基础内质；后者是长时间的仓储转化，决定它最终的槟榔香与醇厚汤感。正因为陈化高度依赖仓储，六堡茶对存放环境格外敏感——同样是六堡茶，仓储条件不同，出来的风格可以差很多。也正因如此，购买渠道比年份标注更值得留意：来源清楚、仓储规范，比包装上写着多少年更重要。"},{"type":"heading","level":3,"text":"红浓陈醇"},{"type":"paragraph","text":"条索紧结，色泽黑褐。汤色红浓明亮。香气以槟榔香与陈香为主，部分传统产品带松烟香。滋味醇厚甘爽，回甘明显，汤感顺滑。所谓槟榔香并不是槟榔的味道，而是对这一类陈香的专门叫法。两广地区传统经验认为六堡茶有助于祛湿，这不属于现代医学结论，只是当地的饮用习惯与经验表述，了解即可，不必当作功效。"},{"type":"tip","tone":"info","title":"识茶提示","text":"槟榔香是对这类陈香的专门叫法，与槟榔本身无关。"},{"type":"heading","level":3,"text":"冲泡、煮饮与冷泡"},{"type":"steps","items":[{"title":"润洗","text":"沸水快进快出润洗一到两遍，唤醒茶性并去浮尘。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，沸水冲泡，第一泡五到十秒出汤，之后逐泡延长，可冲十泡以上。"},{"title":"煮饮","text":"五到八克配五百毫升冷水入壶，煮沸后转小火三到五分钟，汤感更厚，可复煮两到三次。"},{"title":"冷泡与冷萃气泡","text":"冷泡按一比一百到一比一百五十冷藏约十二小时；想喝气泡感，用冷泡液一百五十毫升兑无糖气泡水一百毫升，加冰并擦一片柠檬皮。"}]},{"type":"tip","tone":"warning","title":"仓储决定六堡茶的成败","text":"六堡茶的陈化依赖仓储，霉变与陈香的界限必须分清：出现可见霉斑、酸馊味或刺鼻异味，就不是正常陈香，这类茶不可饮用，也不能靠调味掩盖后继续喝。请从正规渠道购买。另外它含咖啡因且含量不低，睡前六小时内不宜饮用。"},{"type":"paragraph","text":"六堡茶适合重油餐后与潮湿季节饮用，秋冬煮饮也很常见。搭配陈皮、菊花或无糖气泡水都合适，咸香茶点也相宜；不建议加牛奶，也不要用强香精调味，陈香与槟榔香都容易被盖掉。冷萃气泡是偏猎奇的年轻喝法，做法是冷泡液兑无糖气泡水、加冰并擦一片柠檬皮；注意六堡陈香浓烈，冷泡时用一比一百五十的淡比例，风味才不会过重。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，也不要与有气味物品同放。茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。陈化结果取决于原料、工艺与仓储，年份本身不代表品质；六堡茶的陈化尤其依赖仓储环境，来源清楚、仓储规范，比包装上的年份数字更值得关注。"}]', '["product_liubao_250"]', 0, 640, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('4516697474157454316', 'tea_hubei_qingzhuan', 'hubei-qingzhuan', '湖北青砖茶', '["青砖茶","老青茶"]', 'dark', '湖北省', '咸宁市', '赤壁市羊楼洞、赵李桥一带', '湖北砖茶，以老青茶为原料蒸压成砖，陈香纯正、滋味醇厚偏粗犷，煮饮最能喝出味道。', '["杀青","揉捻","渥堆","筛分","蒸压成砖","烘干","陈化"]', '["陈香","木质香"]', '["醇厚","粗犷","回甘"]', '["重油餐后","秋冬煮饮","咸奶茶调饮","家庭共饮"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["煮茶壶","紫砂壶"],"firstSteepSeconds":{"min":10,"max":15},"laterSteepTip":"润洗后逐泡延长，粗老原料释放慢，后段可整块转煮","infusionCount":{"min":10,"max":15},"methodTip":"原料成熟度高，煮饮是最佳方式：五到八克配五百到八百毫升冷水，煮沸后转小火约五分钟。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '砖茶类氟含量相对较高，不建议长期大量饮用熬煮的浓砖茶。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833475.jpg', '[]', '[{"type":"heading","level":3,"text":"羊楼洞的边销砖茶"},{"type":"paragraph","text":"青砖茶产在湖北咸宁赤壁一带，羊楼洞古镇是历史上的茶码头，赵李桥镇也是传统产区。它以老青茶为原料，蒸压成砖，历史上主要销往蒙古与俄罗斯，是「万里茶道」上的主要贸易品之一。对牧区来说，这类砖茶是日常饮食的一部分——在肉食与奶食为主、蔬菜稀少的地方，砖茶长期是生活必需的饮品，也因此形成了「宁可三日无粮，不可一日无茶」的民间说法。"},{"type":"heading","level":3,"text":"老青茶压成砖"},{"type":"list","ordered":false,"items":["杀青、揉捻：原料成熟度较高，处理上更侧重后续转化。","渥堆：黑茶的核心工序，微生物与湿热共同完成深度转化。","筛分：分出粗细，稳定砖体结构与成品风味。","蒸压成砖：汽蒸回软后压成紧实的青砖，砖形便于长途运输。","烘干、陈化：降到安全水分，再经一段时间陈化稳定风味。"]},{"type":"paragraph","text":"青砖茶最值得注意的是原料与形制的对应关系。它用成熟度较高的老青茶，叶片粗老、带梗，压成砖之后结构紧实、导热慢，冲泡时物质释放得慢，所以煮饮才是它最合适的打开方式——长时间小火煮，粗老原料里的甜感与醇厚才出得来，单纯冲泡会显得寡淡。这也是砖茶类普遍的特点：形制为长时间熬煮而生，而不是为快出汤的工夫泡法准备的。"},{"type":"heading","level":3,"text":"陈香纯正、滋味偏粗犷"},{"type":"paragraph","text":"砖形紧实，色泽青褐。汤色红黄明亮。香气以陈香为主，干净纯正，没有杂味。滋味醇厚，因原料成熟度高而偏粗犷，回甘不算细腻但胜在厚重耐煮。它的风格不像安化黑茶那样细腻，更接近日常口粮茶：一壶煮开，全家分饮。这种粗犷本身就是它的定位，不必按名优茶的细度去要求它；喜欢细腻花果香的人，本来就不是它的目标口味。"},{"type":"paragraph","text":"有一个分类上的混淆要顺便澄清：青砖茶的「青」说的是原料老青茶与成砖色泽，并不是绿茶里的「青」；它属于黑茶，与青茶（乌龙茶）更是毫无关系。名字里的字眼很容易误导，认茶还是要看工艺——青砖茶走了完整的渥堆后发酵，这是黑茶的标志性工序。"},{"type":"heading","level":3,"text":"煮着喝最合适"},{"type":"steps","items":[{"title":"撬茶","text":"用茶刀沿砖体分层撬散，块形完整更耐煮；也可掰成小块后先醒茶一到两周。"},{"title":"润洗","text":"沸水快速润洗一到两遍，去浮尘并唤醒茶性。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，沸水冲泡，润洗后第一泡十到十五秒出汤，之后逐泡延长，可冲十泡以上。"},{"title":"煮饮","text":"五到八克配五百到八百毫升冷水入壶，煮沸后转小火约五分钟，这是最能出味的方式，可复煮两到三次。"}]},{"type":"tip","tone":"warning","title":"仓储与饮用量","text":"出现可见霉斑、酸馊味或刺鼻异味就不可饮用，也不能用调味去掩盖。另外砖茶类原料成熟度高，氟含量相对偏高，长期大量饮用熬煮的浓砖茶可能与氟摄入过量相关，这是有文献支持的风险；不建议整天以浓砖茶代水，普通消费者日常淡饮风险很低。"},{"type":"paragraph","text":"青砖茶适合重油餐后与秋冬煮饮，也可按牧区传统加鲜牛奶与少量盐调成咸奶茶——把煮好的浓茶滤出，兑入鲜奶加一点盐即可，是很有辨识度的喝法，也是当地人长期形成的饮用习惯。搭配陈皮或淡味坚果都合适，不建议用高糖香精调味，那会盖掉陈香。日常也可以用保温杯投三到五克焖两三分钟，续水即可，办公室喝很方便。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。陈化结果取决于原料、工艺与仓储，不是年份越久就越好；茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '[]', 0, 650, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2805967202008650511', 'tea_sichuan_tibetan', 'sichuan-tibetan', '四川藏茶', '["雅安边茶","南路边茶","藏茶"]', 'dark', '四川省', '雅安市', '雨城区、天全县、荥经县等地', '四川边茶中的南路边茶，多做康砖、金尖，含梗耐煮，陈香与木质香明显，常作酥油茶底。', '["杀青","渥堆","揉捻","拣梗","蒸压成型","干燥","陈化"]', '["陈香","木质香"]', '["醇和","甜润","顺滑"]', '["重油餐后","秋冬煮饮","酥油茶体验","家庭共饮"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["煮茶壶","紫砂壶"],"firstSteepSeconds":{"min":10,"max":15},"laterSteepTip":"润洗后逐泡延长，煮饮是主要喝法，可反复煮两到三次","infusionCount":{"min":10,"max":15},"methodTip":"砖体先掰成小块或适度碾碎，煮饮为最佳：五到八克配八百毫升冷水，煮沸后转小火五到十分钟。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '砖茶类氟含量相对较高，不建议长期大量饮用熬煮的浓砖茶。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833998.jpg', '[]', '[{"type":"heading","level":3,"text":"雅安的南路边茶"},{"type":"paragraph","text":"藏茶产在四川雅安，雨城区、天全县、荥经县等地是传统产区，属于四川边茶里的南路边茶，历史上专供藏区。成品多做成康砖、金尖这样的砖形——康砖与金尖是两种传统规格，原料拼配与砖形略有差异。藏区传统上把它与酥油、盐同煮成酥油茶，是高原饮食结构里长期存在的一部分，传统上也用于补充维生素。"},{"type":"heading","level":3,"text":"含梗耐煮的砖茶"},{"type":"list","ordered":false,"items":["杀青：钝化酶活性，固定基础内质。","渥堆：微生物与湿热共同作用，完成黑茶特有的深度转化。","揉捻：整理条索，让物质更易浸出。","拣梗：挑出不合规格的粗梗，同时整理原料，保留适度茶梗。","蒸压成型：压成康砖、金尖等砖形，便于运输与长期存放。","干燥、陈化：降到安全水分，并稳定风味。"]},{"type":"paragraph","text":"藏茶的茶梗不是瑕疵，而是刻意保留的部分。原料成熟度高、含梗，煮出来的甜感更好，也更耐煮，这正好对应高原上长时间熬煮的饮用方式。换句话说，它的原料等级与饮用方式是配套的：用嫩芽的标准去要求它并不合适，用煮饮的方式对待它才能喝出好来。同样地，把砖体掰成小块或适度碾碎后再煮，比整块下壶出味快得多，一般可反复煮两到三次。"},{"type":"heading","level":3,"text":"陈香与木质香"},{"type":"paragraph","text":"砖形紧实，色泽棕褐。汤色红褐明亮。香气以陈香与木质香为主，干净不闷。滋味醇和，甜感好，刺激性低，煮过之后汤感更饱满。它不像生普那样有明显的苦涩与回甘起伏，走的是平顺路线，适合不太追求刺激感的人，也适合家庭日常大口饮用。若喜欢更厚一点的口感，可以延长煮的时间，或者少加水、多投茶。"},{"type":"paragraph","text":"常见的混淆是把藏茶与云南普洱茶当成一回事。藏茶属于四川边茶中的南路边茶，历史上以供应藏区得名；普洱茶产在云南，两者的产区、原料与产品形制都不同，只是同属黑茶大类、都耐煮而已。了解这一点，在选购时就不容易被「藏茶就是普洱」这类说法带偏。"},{"type":"heading","level":3,"text":"煮饮为主"},{"type":"steps","items":[{"title":"撬茶","text":"把砖体掰成小块或适度碾碎，方便出味；也可先醒茶一到两周。"},{"title":"润洗","text":"沸水快速润洗一遍，去浮尘并唤醒茶性。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，沸水冲泡，润洗后第一泡十到十五秒出汤，可冲十泡以上。"},{"title":"煮饮","text":"五到八克配八百毫升冷水入壶，煮沸后转小火五到十分钟，这是它的主要喝法，可反复煮两到三次。"}]},{"type":"tip","tone":"warning","title":"仓储与饮用量","text":"出现可见霉斑、酸馊味或刺鼻异味就不可饮用，也不能靠调味掩盖。藏茶原料成熟度高、含梗，氟含量相对偏高，长期大量饮用熬煮的浓砖茶可能与氟摄入过量相关，这是有文献支持的风险；不建议整天以浓砖茶代水。此外它含咖啡因，睡前六小时内不宜饮用。"},{"type":"paragraph","text":"藏茶适合重油餐后与秋冬煮饮，也可以按藏区传统做酥油茶：把煮好的浓茶滤出，加入酥油与盐反复搅打至乳化，就是酥油茶，这是高原饮食里延续很久的搭配；或加鲜牛奶与盐调成咸奶茶，属于文化体验式的喝法。搭配陈皮也可以，清口解腻。不建议用高糖香精调味，也不要用调味去掩盖异味。煮好的茶汤若一次喝不完，可以保温存放并尽快喝完，反复长时间熬煮并不必要。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。陈化结果取决于原料、工艺与仓储，年份长不等于品质好；茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '[]', 0, 660, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('2797663033182469087', 'tea_jingyang_fucha', 'jingyang-fucha', '陕西茯茶', '["泾阳茯茶","泾阳茯砖"]', 'dark', '陕西省', '咸阳市', '泾阳县，传统加工与集散地', '泾阳传统茯砖，以「金花」为品质特征，菌花香突出、滋味醇厚顺滑，与安化茯砖风格相近。', '["筛分拼配","渥堆","蒸压成砖","发花","干燥","陈化"]', '["菌花香","陈香","甜香"]', '["醇厚","顺滑","甜醇"]', '["重油餐后","早晨温饮","秋冬煮饮","面食餐后"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","煮茶壶","白瓷盖碗"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"润洗后逐泡延长，后段转煮饮风味更完整","infusionCount":{"min":10,"max":15},"methodTip":"先撬散，沸水润洗一至两遍后快出汤；煮饮五到八克配五百毫升冷水，煮沸转小火三到五分钟。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '砖茶类氟含量相对较高，不建议长期大量饮用熬煮的浓砖茶。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833997.jpg', '[]', '[{"type":"heading","level":3,"text":"泾阳的茯砖"},{"type":"paragraph","text":"陕西茯茶产在咸阳泾阳一带。泾阳是茯茶传统的加工与集散地，历史上以湖南安化的黑毛茶为原料，运到泾阳之后再筑制成砖——原料从湖南来、成砖在陕西做，这是它历史上有意思的一点。它和安化茯砖同属以「金花」为品质特征的砖茶类，风格也相近，部分茶友认为泾阳茯砖的菌花香更显。历史上还有「离了泾阳水、泾阳气候不能制」的说法，这属于传统经验总结，今天在合适的厂房条件下，多地都能生产茯砖。"},{"type":"heading","level":3,"text":"先拼配，再发花"},{"type":"list","ordered":false,"items":["筛分拼配：把黑毛茶按比例拼合，稳定基础风味与砖体结构。","渥堆：微生物与湿热共同作用，完成深度转化。","蒸压成砖：汽蒸回软后压成紧实的砖块。","发花：在烘房内控制温湿度，促使冠突散囊菌生长形成「金花」。","干燥、陈化：降到安全水分，再经陈化稳定风味。"]},{"type":"paragraph","text":"发花是茯茶最要紧的一步。冠突散囊菌（曾用学名 Eurotium cristatum，现分类学多采用 Aspergillus cristatus）需要在合适的温湿度下才能在砖体内部生长，形成金黄色颗粒状的金花。这一步做成了，菌花香与甜醇就有了；做不成，砖体就只是压紧的黑茶。历史上泾阳依托当地气候与水完成这一过程，所以才有上面那句老话——那是经验总结，不是不可复制的条件；今天判断一砖茯茶好不好，还是看金花与香气本身。"},{"type":"heading","level":3,"text":"认花、认香、认甜"},{"type":"paragraph","text":"砖形紧实，色泽黑褐，撬开后断面金花密布、分布均匀。汤色橙红明亮。香气以菌花香最突出，夹着陈香。滋味醇厚顺滑，甜感好，不显苦涩。最需要分清的是金花与霉变：金花是金黄色、颗粒状、干爽的，闻起来是干净的菌花香；霉变多呈绿霉、黑霉或绒毛状，伴随刺鼻霉味或酸馊味。这两件事在茯砖上尤其容易被弄混，也是茯茶品控里最核心的一条常识。"},{"type":"paragraph","text":"至于陕西茯茶与安化茯砖怎么选，其实不必分出高下：两者同属一类工艺，风格取向接近，差别更多来自原料拼配与发花条件，属于不同产地的风味差异。可以说的是，陕西茯茶在本地饮食里的位置更明确——面食、泡馍之后来一壶，是当地很自然的搭配习惯。"},{"type":"heading","level":3,"text":"冲泡与煮饮"},{"type":"steps","items":[{"title":"撬茶","text":"沿砖体边缘分层撬散，块形完整更耐泡；也可先醒茶一到两周。"},{"title":"润洗","text":"沸水快进快出润洗一到两遍，去浮尘并唤醒茶性。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水，沸水冲泡，第一泡五到十秒出汤，之后逐泡延长，可冲十泡以上。"},{"title":"煮饮","text":"五到八克配五百毫升冷水入壶，煮沸后转小火三到五分钟，菌花香与甜感更完整。"}]},{"type":"tip","tone":"warning","title":"金花与霉变别弄混","text":"金花是受控发花形成的冠突散囊菌，属于正常品质特征，不是霉变；霉变是仓储受潮导致的劣变。出现可见霉斑、酸馊味或刺鼻异味，就不是正常陈香，这类茶不能饮用。此外砖茶类氟含量相对偏高，不建议长期大量饮用熬煮的浓砖茶。"},{"type":"paragraph","text":"茯茶适合重油餐后、早晨温饮与秋冬煮饮，陕西本地面食、泡馍之后喝也很合适，是当地很自然的搭配习惯。搭配陈皮、菊花或咸香茶点都相宜，陈皮尤能衬出菌花香；不建议加牛奶，奶会压住菌花香。日常用保温杯投三到五克焖两三分钟也很省事。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。陈化结果取决于原料、工艺与仓储，并非年份越久越好，判断茯砖还是先看金花与香气；茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '[]', 0, 670, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('7330552595416293242', 'tea_xiaguan_tuocha', 'xiaguan-tuocha', '下关沱茶', '["沱茶"]', 'dark', '云南省', '大理白族自治州', '大理市下关，气候干燥利于自然陈化', '创制于下关的碗臼形紧压茶，以拼配见长，陈香与烟香并存，小沱便携、一块一泡。', '["筛分拼配","蒸软","揉压成碗臼形","干燥","陈化"]', '["陈香","烟香"]', '["醇厚","回甘","顺滑"]', '["重油餐后","秋冬煮饮","办公室焖泡","出差携带"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":100,"max":100},"vessel":["紫砂壶","白瓷盖碗","煮茶壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"润洗后逐泡延长，生沱可略降水温并加快出汤","infusionCount":{"min":10,"max":15},"methodTip":"小沱可以一块一泡，大沱沿边缘撬散；沸水润洗一至两遍后快出汤。注意区分生沱与熟沱，生沱对胃的刺激更强。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '生沱对胃的刺激强于熟沱，胃部不适者避免空腹饮用。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164928531.jpg', '[]', '[{"type":"heading","level":3,"text":"碗臼形的沱"},{"type":"paragraph","text":"下关沱茶产在云南大理下关，沱茶这个形制就创制于下关。它做成碗臼形，中间凹陷，常见一百克或二百五十克两种规格。下关风大、气候干燥，这样的环境利于茶叶自然陈化，是当地做紧压茶的一个天然条件。沱茶的另一个特点是拼配——把不同产区、不同年份的原料按比例拼合，让不同批次的风味保持稳定，这也是它长期以来的一项工艺长项。"},{"type":"heading","level":3,"text":"拼配与揉压"},{"type":"list","ordered":false,"items":["筛分拼配：不同产区、年份的原料按比例拼合，稳定批次风味。","蒸软：汽蒸让原料回软，便于成型。","揉压成碗臼形：压出中间凹陷的沱形，这是沱茶的标志性形制。","干燥：降到安全水分，避免后期受潮劣变。","陈化：在干燥环境中缓慢转化，形成陈香。"]},{"type":"paragraph","text":"沱茶要分生沱与熟沱两条线来看。熟沱用渥堆熟茶压制，发酵度约在百分之八十五到九十五之间；生沱走的是晒青绿茶工艺，发酵度低，成分更接近晒青绿茶，茶多酚含量高。形制相同、工艺不同，风味与刺激感差别很大——熟沱醇厚温和，生沱清冽、对胃的刺激更强。买的时候要看清是生沱还是熟沱，不要只看「沱茶」两个字；这是沱茶最容易被弄混的地方。另外，沱茶压得紧、单位体积小，同样重量下比散茶更省地方，出差或旅行带上一两个都很方便。"},{"type":"heading","level":3,"text":"陈香、烟香与醇厚"},{"type":"paragraph","text":"碗臼形紧压，压制紧实，拿在手里能感到明显的重量。汤色橙黄至红浓，视生熟与年份而定。香气以陈香为主，部分传统产品带独特的下关烟香，这是当地产品的辨识点之一。滋味醇厚，耐泡度好。熟沱顺滑甜润；生沱清冽，苦涩与回甘都更明显，香气偏花香与山野气。生沱对胃的刺激强于熟沱，胃部容易不适的人不要空腹喝生沱，也不建议泡得过浓；初次尝试可以先从熟沱入手，接受度更高。"},{"type":"tip","tone":"info","title":"识茶提示","text":"碗臼形是沱茶的标志，中间凹陷；购买时注意区分生沱与熟沱。"},{"type":"heading","level":3,"text":"一块一泡"},{"type":"steps","items":[{"title":"撬茶或整沱","text":"小沱可以一块一泡，大沱用茶刀沿边缘撬散；撬开后可先醒茶一到两周。"},{"title":"润洗","text":"沸水快速润洗一到两遍，去浮尘并唤醒茶性。"},{"title":"冲泡","text":"投茶七到八克配一百到一百二十毫升水（或直接用一个小沱），沸水冲泡，第一泡五到十秒出汤，之后逐泡延长，可冲十泡以上。"},{"title":"调整","text":"生沱可略降水温并加快出汤，熟沱可适当坐杯，或整块转煮饮。"}]},{"type":"tip","tone":"warning","title":"仓储安全","text":"出现可见霉斑、酸馊味或刺鼻异味就不可饮用。沱茶压得紧，受潮后不易察觉，收到茶之后建议先闻一遍干茶、看一遍表面再收起来。另外它含咖啡因，睡前六小时内不宜饮用；服药前后一到两小时避免饮茶，也不可用茶水送服药物。"},{"type":"paragraph","text":"沱茶适合重油餐后与秋冬煮饮；小沱便携，也适合办公室焖泡与出差携带，一块一泡不用称量，这是它形制上最实用的一点。搭配陈皮、菊花或淡味坚果都可以；不建议加牛奶，生沱尤其不合适，高糖调味也要避免。生沱适合单独清饮，熟沱调饮空间更大一些，可以按熟普的思路加陈皮或少量鲜奶。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，整条或整提存放时不要与有气味物品同放。陈化结果取决于原料、工艺与仓储，年份本身不代表品质；茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '["product_tuocha_100"]', 0, 680, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO tea (id, business_key, slug, name, aliases, category, origin_province, origin_city, origin_district, summary, processes, aromas, flavors, scenes, brewing, storage_method, aging_note, drinking_note, cover_url, gallery_urls, content_blocks, related_product_keys, featured, sort, status, published_at, created_at, updated_at) VALUES ('3264163789956254853', 'tea_qizi_bing', 'qizi-bing', '云南七子饼茶', '["七子饼","七子饼茶"]', 'dark', '云南省', '西双版纳州、普洱市、临沧市', '勐海、易武等地为传统核心产区', '传统七饼一提的圆饼形制，生饼清冽、熟饼醇厚，汤色由黄绿转红浓，耐泡也耐存放。', '["筛分拼配","蒸软","紧压成圆饼","干燥","棉纸包装","陈化"]', '["花香","陈香","木香"]', '["醇厚","顺滑","回甘"]', '["重油餐后","秋冬煮饮","待客品鉴","生饼陈化观察"]', '{"teaGrams":8,"waterMl":110,"ratio":"约1:14","temperatureC":{"min":95,"max":100},"vessel":["紫砂壶","白瓷盖碗","煮茶壶"],"firstSteepSeconds":{"min":5,"max":10},"laterSteepTip":"生饼新茶极快出汤，熟饼与陈年生饼可适当坐杯、逐泡延长","infusionCount":{"min":10,"max":15},"methodTip":"生饼新茶水温略降到九十五度、第一泡约五秒极快出汤；熟饼与陈年生饼可用一百度沸水并换紫砂壶，也可煮饮。"}', '清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味物品同放。', '陈化结果取决于原料、工艺与仓储，并非年份越久越好；出现霉斑、酸馊味或刺鼻异味即不可饮用。', '生饼新茶对胃的刺激较强，胃部不适者避免空腹饮用。含咖啡因，避免空腹浓饮与睡前饮用；内容仅作茶文化科普，不构成医疗建议。', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926808.jpg', '[]', '[{"type":"heading","level":3,"text":"「七子」说的是形制"},{"type":"paragraph","text":"七子饼茶产在云南西双版纳、普洱、临沧等地，勐海与易武是传统核心产区。这里要先说明：「七子饼」指的是形制与规格——七饼为一提，传统每饼约 357 克——而不是某一种工艺。按工艺分，熟饼属于黑茶，生饼属于晒青绿茶。同样是七子饼，生熟两条线走的是完全不同的路，谈它的风味与存放方式，都要先说清是哪一种，否则很容易鸡同鸭讲。"},{"type":"heading","level":3,"text":"压饼之前，先分生熟"},{"type":"list","ordered":false,"items":["筛分拼配：原料按比例拼合，稳定风味。","蒸软：汽蒸回软，准备压制成型。","紧压成圆饼：传统规格每饼约 357 克，七饼为一提。","干燥：降到安全水分，避免后期受潮。","棉纸包装：传统以棉纸包裹，透气同时减少串味。","陈化：在合适仓储下缓慢转化，香气与滋味逐年改变。"]},{"type":"paragraph","text":"七子饼的形制与工艺是相互对应的：生饼用晒青毛茶压制，熟饼用渥堆熟茶压制。生饼压成饼之后仍在缓慢转化，新茶的花香与山野气会随年份转向陈香与木香；熟饼在压饼之前就已经完成了渥堆发酵，出来就是红浓醇厚的风格。棉纸包装也不只是传统，它透气而不透味，利于转化又能减少串味，是这套形制的一部分；因此存放时不必把棉纸拆掉。"},{"type":"heading","level":3,"text":"一饼两面"},{"type":"paragraph","text":"圆饼形制，传统以棉纸包装。生饼新茶色泽墨绿，汤色黄绿，香气是花香与山野气，滋味浓强、苦涩明显但回甘快；随年份增加，色泽转褐、汤色转橙红，香气转向陈香与木香，滋味转醇厚顺滑。熟饼色泽褐红，汤色红浓，香气以陈香、木香为主，滋味醇厚顺滑、甜感明显。两者都极耐泡，也都能煮饮；撬茶与冲泡的过程本身也有仪式感，适合待客。"},{"type":"tip","tone":"info","title":"识茶提示","text":"七饼为一提、传统每饼约 357 克，「七子饼」说的是形制而非工艺。"},{"type":"heading","level":3,"text":"撬茶与冲泡"},{"type":"steps","items":[{"title":"撬茶","text":"用茶针沿饼面分层撬成小块，尽量保持块形完整；撬开后可先醒茶一到两周。"},{"title":"润洗","text":"沸水快速润洗一到两遍，去浮尘并唤醒茶性。"},{"title":"生饼新茶","text":"水温可略降到九十五度，第一泡约五秒极快出汤以降苦涩，之后逐泡延长；器皿用白瓷盖碗便于看汤色。"},{"title":"熟饼与陈年生饼","text":"可用一百度沸水，器皿换成紫砂壶更利于聚香；也可煮饮，汤感更厚。"}]},{"type":"tip","tone":"warning","title":"仓储是普洱的下半程","text":"「越陈越香、越陈越值钱」部分属于市场概念。品质取决于原料、工艺与仓储，并非所有七子饼都会随年份变好；部分陈年茶价格高昂，市场炒作风险也不小，选购需要理性。出现可见霉斑、酸馊味或刺鼻异味就不可饮用，务必从正规渠道购买。"},{"type":"paragraph","text":"生饼新茶适合春夏清饮与尝鲜品鉴，熟饼与陈年生饼更适合秋冬与餐后。搭配上，熟饼配陈皮是经典组合，生饼配清淡茶点更合适，也可以用紫砂壶或盖碗慢慢泡；待客时撬茶、洗茶、分汤的过程本身就很有意思，这也是七子饼常被用来待客的原因。不建议加牛奶，生饼尤其不合适；高糖调味也会盖掉陈香。存放要清洁、干燥、通风、避光、防异味，整提存放时注意别与有气味物品同放，棉纸不必拆掉。生饼新茶对胃的刺激较强，胃部容易不适的人不要空腹喝；它含咖啡因，睡前六小时内不宜饮用。最后强调一句：陈化结果取决于原料、工艺与仓储，年份本身不等于品质。茶汤建议降到五十到六十度再饮；国际癌症研究机构将六十五度以上热饮列为 2A 类可能致癌，关键在温度而非茶本身。"}]', '[]', 0, 690, 'published', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('5254218018755990781', 'article_six_types', 'six-tea-types-at-a-glance', '一张表认识中国六大茶类', '六大茶类的分界不在茶汤颜色，而在杀青、萎凋、闷黄、做青、发酵与渥堆这几道关键工序。', 'tea_basics', '["六大茶类","入门","工艺"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124040891.jpg', '[]', '[{"type":"paragraph","text":"很多人第一次认真看茶单，都会先按颜色找规律：汤色发绿的叫绿茶，发红的叫红茶，颜色深得发黑的叫黑茶。这个印象只对了一半。真正把六大茶类分开的，是一片鲜叶在加工过程中被处理成了什么样子——哪些酶的活性被保留下来，哪些被高温钝化，有没有微生物参与，最后停在哪一个阶段。"},{"type":"heading","level":3,"text":"分水岭是工序，不是颜色"},{"type":"paragraph","text":"分类的第一依据是加工工艺，尤其是杀青与否，以及茶多酚被氧化的程度。同一片茶园采下来的鲜叶，用六种不同的做法，就能做出六类茶里的任何一类。所以「一棵树只能做一种茶」是误解；反过来，「汤色一样就是同一类茶」也不成立——清香型铁观音的汤色偏绿，它仍然是乌龙茶，分类看的是工艺而不是外观。"},{"type":"list","ordered":false,"items":["绿茶：杀青钝化酶，锁住清汤绿叶与鲜爽","白茶：只萎凋与干燥，不炒不揉，风格清雅","黄茶：杀青之后多一道闷黄，甜醇柔和","青茶（乌龙）：做青摇出花果香，氧化程度跨度最大","红茶：充分发酵，儿茶素大量氧化，甜香醇厚","黑茶：渥堆后发酵，微生物参与，陈香醇和"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124039709.jpg","alt":"六类茶的干茶与茶汤并排对比","caption":"把六类茶摆在一起看，工艺造成的差异比单看一款更直观。"},{"type":"heading","level":3,"text":"用「氧化程度」当一把尺子"},{"type":"paragraph","text":"行业里常用茶多酚氧化程度给六类茶排一条轴。绿茶几乎不氧化；白茶只有萎凋过程中内源酶带来的轻微氧化；黄茶因为闷黄多走了一小步；乌龙茶的跨度最大，从百分之十几到七成都做得出；红茶氧化得比较彻底；黑茶则在渥堆里被微生物接力改造，做成之后还会随贮存继续变化。需要提醒的是，这里的「发酵」主要指酶促氧化，和做酸奶、酿酒那种微生物发酵不是一回事，只有黑茶的渥堆才真正由微生物主导。"},{"type":"list","ordered":true,"items":["绿茶：氧化程度接近零，杀青是决定性工序","白茶：约百分之五到十，靠萎凋缓慢作用，不炒不揉","黄茶：约百分之十到二十，闷黄带来甜醇","乌龙茶：约百分之十五到七十，做青决定风味走向","红茶：约百分之七十到九十，发酵是核心工序","黑茶：约百分之八十以上，渥堆之后仍在持续转化"]},{"type":"heading","level":3,"text":"同一片叶子，能走六条路"},{"type":"paragraph","text":"理解了工艺这条主线，很多疑问会自己散开。决定风味的除了工艺，还有品种、产地、采摘嫩度与后期仓储，所以同属绿茶，西湖龙井是扁平挺直的糙米色，洞庭碧螺春却是卷曲显毫、带花果香；同属乌龙，安溪铁观音走清香路线，武夷大红袍则靠焙火撑起厚实的骨架。六大茶类是一张地图，地图上的坐标点还得靠一款款具体的茶去填。"},{"type":"quote","text":"六大茶类的区别，本质是一片叶子被酶和微生物改造到什么程度。","source":"茶一统内容整理"},{"type":"heading","level":3,"text":"这张表可以怎么用"},{"type":"steps","items":[{"title":"先认工艺","text":"遇到不认识的茶，先问它是杀青、萎凋、闷黄、做青、发酵还是渥堆，比看汤色可靠。"},{"title":"再定水温","text":"大体上越接近绿茶越需要柔和水温，越接近乌龙与黑茶越需要接近沸水。"},{"title":"最后看仓储","text":"以鲜为贵的茶要低温保鲜，可以继续转化的茶才谈常温存放，两者的存法完全不同。"}]},{"type":"tip","tone":"info","title":"三个分类提醒","text":"安吉白茶是绿茶，用的是白化品种；普洱生茶在严格工艺分类上属晒青绿茶，会随贮存自然后发酵；「老白茶」是市场通行说法，不是国家标准里的独立类别。"},{"type":"paragraph","text":"把六个关键词和那条氧化程度轴记住，再看茶单就不会心慌。剩下的细节——香气是高是低、汤感是厚是薄、回甘能留多久——交给舌头慢慢学，这比背术语有用得多。"},{"type":"heading","level":3,"text":"为什么同一类茶之间差别也很大"},{"type":"paragraph","text":"分类只解决「它属于哪一类」，不解决「它好不好喝」。同一类内部的差异，往往比跨类差异更让人意外。以绿茶为例，西湖龙井的豆香与糙米色来自扁平炒制的做形工艺，洞庭碧螺春的花果香与卷曲外形则来自揉捻与显毫；两者同属绿茶，水温都要压住，香气走向却完全不同。再比如白茶，白毫银针取单芽，毫香清鲜；寿眉原料成熟，汤感醇和，还能转出枣香。产地的小气候、土壤与品种，加上采摘嫩度与后期仓储，共同决定了同一类茶内部的这条光谱。"},{"type":"paragraph","text":"所以更实用的做法是两步走：先按工艺判断类别，据此定下大致的水温区间与仓储方向；再按具体的产地、嫩度与年份去微调。把这两步分开，既不会因为「都是绿茶」而用错水温，也不会因为「都是乌龙」就给清香型铁观音套上足火岩茶的手法。分类是起点，不是终点。"}]', '["tea_longjing","tea_biluochun","tea_baihao_yinzhen","tea_tieguanyin","tea_dahongpao","tea_zhengshan_xiaozhong","tea_ripe_puer"]', 8, 3286, 1, 10, 'published', '2026-09-01 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('3601086607411817109', 'article_water_temperature', 'water-temperature-guide', '水温不是越高越好：一份泡茶温度指南', '用同一款茶试三种水温，你会得到三杯不同的茶。水温按茶叶嫩度与加工方式定，不按个人习惯定。', 'brewing', '["冲泡","水温","新手"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124048340.jpg', '[]', '[{"type":"paragraph","text":"拿一款西湖龙井，分别用八十度、九十度和刚烧开的沸水各泡一杯：八十度那杯清甜柔和，九十度那杯香气更集中，沸水那杯多半会苦涩挂舌、汤色发黄。同一款茶、同样的投茶量，差别只出在水温上。所以在投茶量、浸泡时间、水温这三个变量里，水温是最先该定下来的那一个。"},{"type":"heading","level":3,"text":"水温究竟改变了什么"},{"type":"paragraph","text":"研究提示，茶多酚里的儿茶素类在高温下浸出速率明显快于氨基酸类。氨基酸贡献鲜甜，儿茶素带来收敛与苦涩。温度一高，苦味与涩感抢在鲜甜前面大量溶出，风味就失衡了，这是「好茶被泡坏」最常见的原因。温度还影响另外三件事：高温会加速叶绿素脱镁，汤色由绿转黄暗；低沸点的清香成分在高温下快速挥发，香气损失；焙火型茶里的高沸点香气物质，则要沸水才激发得出来。同一件事的两面，正是「有的茶怕烫、有的茶怕不烫」的由来。"},{"type":"list","ordered":false,"items":["苦涩物质：温度越高浸出越快，超过嫩芽能承受的范围就抢味","鲜甜物质：氨基酸类浸出相对平缓，低温长泡也能慢慢出来","叶绿素与维生素 C：高温下容易破坏，直接反映在汤色上","香气：低沸点清香怕高温，高沸点焙火香与花果香要沸水才出得来"]},{"type":"heading","level":3,"text":"一条按嫩度走的温度线"},{"type":"paragraph","text":"与其背六组数字，不如记住一条判断线：芽叶越嫩、氧化程度越低，水温越低；叶片越成熟、做青与焙火越重，水温越高。国标与行业通行做法给的水温区间大体是这样的——绿茶八十到八十五度，其中名优嫩芽茶可低到七十五至八十度；黄芽茶与绿茶相当，黄大茶可以到九十至九十五度；白毫银针与白牡丹八十五至九十度，寿眉与陈白茶则要九十五度到沸水；乌龙茶九十度到沸水，功夫泡常用沸水；红茶九十到九十五度，金骏眉这类芽头细嫩的可降到八十五至九十度；黑茶用沸水，紧压茶还可以煮。"},{"type":"steps","items":[{"title":"嫩芽型，先温柔一点","text":"绿茶、黄芽茶、白毫银针，从七十五至八十五度起步，嫩度越高水温越低。"},{"title":"中间地带，看原料","text":"红茶、白牡丹、贡眉多在八十五至九十五度之间，芽头细嫩的取低值，大叶种取高值。"},{"title":"紧结与焙火，需要足温","text":"乌龙与黑茶用九十五度到沸水，球形乌龙与紧压茶靠高温帮叶片舒展。"},{"title":"陈茶与粗老叶，直接沸水","text":"寿眉、陈白茶、砖茶这类原料成熟度高的茶，水温不够反而泡不出内容。"}]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124042100.jpg","alt":"盖碗功夫泡的出汤瞬间","caption":"投茶量偏大时，前几泡更要靠缩短时间而不是降低水温来控制浓度。"},{"type":"heading","level":3,"text":"手边没有温度计怎么办"},{"type":"paragraph","text":"最省事的办法是买一把带控温功能的电水壶，成本不高，收益最直接。没有的话，可以用「倒杯降温法」：把沸水倒进常温的公道杯或马克杯里静置，通常两到三分钟大约降到八十五度上下，三到五分钟大约降到八十度上下。这是经验估算，室温、器具材质和水量的差别都会影响结果，只能当参考。另一个常用技巧是「高冲低斟」——抬高水壶让水流在空气中多走一段路，也能带走一点热量。"},{"type":"tip","tone":"success","title":"调整参数的顺序","text":"觉得太苦涩时，先缩短浸泡时间，再小幅降低水温，最后才动投茶量。一次只改一个变量，才找得回上一次那杯好喝的味道。"},{"type":"heading","level":3,"text":"三个常见的水温误区"},{"type":"list","ordered":false,"items":["「好茶必须用沸水才泡得开」：对乌龙、黑茶成立，对绿茶、黄茶、嫩芽白茶恰好相反。","「所有茶都该用八十度」：低水温泡紧压黑茶，只会得到一杯寡淡的水。","「保温杯焖着更出味」：长时间高温密闭浸泡会把苦涩物质全部逼出来，不建议用来闷绿茶。"]},{"type":"paragraph","text":"还有一个容易被忽略的细节：水温不是泡到最后一泡都不变的。乌龙与黑茶越往后越可以升高水温、延长时间，而绿茶喝到第三泡时，往往要反过来适当降温，才能保住那点清甜。把水温当成一个可以随手微调的旋钮，而不是一条必须遵守的刻度，泡茶这件事就轻松多了。"},{"type":"tip","tone":"warning","title":"关于热饮温度","text":"国际癌症研究机构把温度高于六十五度的热饮列为 2A 类「可能对人类致癌」，关键在温度而不在茶本身。茶汤放到五十至六十度的适口温度再喝。"},{"type":"heading","level":3,"text":"把温度变成手感"},{"type":"paragraph","text":"温度计和控温壶解决的是准确问题，手感解决的是日常问题。几个可以直接用的参照：沸水倒进常温公道杯，二到三分钟大约八十五度，三到五分钟大约八十度；水壶离杯口越高、水流越细，降温越快。另一个可靠的信号是声音与气泡——壶底出现细密小气泡、伴随轻微响声时大约七八十度，气泡连成串往上升接近九十度，水面翻腾就是沸水。这些判断不算精确，但足够应付一杯日常茶。"},{"type":"paragraph","text":"还有一条常被忽略的细节：不同器具里的水温下降速度不一样。薄胎白瓷盖碗散热最快，紫砂壶与厚胎瓷壶保温更好。同一壶水倒进紫砂壶，实际冲泡温度会比倒进薄胎盖碗高几度。所以别人分享的参数只能当作起点——你的器具、你所在城市的室温，甚至当天的湿度，都会让结果偏移一点。"}]', '["tea_longjing","tea_baihao_yinzhen","tea_tieguanyin","tea_ripe_puer"]', 7, 2641, 1, 20, 'published', '2026-09-02 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('7076844221523099251', 'article_storage', 'tea-storage-basics', '茶叶储存：先分清保鲜还是陈化', '茶叶怕水、怕氧、怕光、怕热，还特别怕异味。动手之前先判断这款茶要保鲜还是要陈化。', 'storage', '["储存","保鲜","陈化"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124043337.jpg', '[]', '[{"type":"paragraph","text":"存茶这件事，最多人犯的错不是方法不对，而是用错了对象。把绿茶和普洱熟茶一起塞进冰箱，等于同时对两款茶做了错事：一款被加速劣变，一款被抑制转化。所以第一步不是找罐子，而是问一句——这款茶是「以鲜为贵」，还是「以陈为贵」。"},{"type":"heading","level":3,"text":"两条主线，先分类再谈方法"},{"type":"paragraph","text":"以鲜为贵的茶，目标是尽量把当下的香气和鲜爽「冻住」：绿茶、黄茶、清香型乌龙都属于这一类。以陈为贵的茶，目标是在适宜条件下缓慢转化：白茶、黑茶、焙火乌龙属于这一类。红茶介于两者之间——它不像绿茶那样急迫，但香气也容易散失，比较现实的做法是在保质期内喝完。同一句「越陈越香」，只对其中一部分茶成立。"},{"type":"list","ordered":false,"items":["绿茶与黄茶：低温冷藏、强密封、避光，开封后尽快喝完，不宜长期存放","清香型乌龙：近似绿茶，抽真空或铝箔袋密封后冷藏","焙火乌龙：常温密封避光即可，忌冷藏，可静置慢慢转化","白茶：常温密封、防潮为第一要务，可长期存放","红茶：常温密封避光，香气易散，按保质期安排饮用","黑茶（含普洱熟茶）：常温、干燥、通风、避光、防异味，密封但不抽真空"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124044618.jpg","alt":"密封罐与铝箔袋分装的茶叶","caption":"小份分装比大袋反复开合更管用，这是家庭存茶最容易被忽略的一步。"},{"type":"heading","level":3,"text":"茶叶到底怕什么"},{"type":"paragraph","text":"茶叶的敌人有四个半。水分是霉变的前提，含水率升高之后，后面的事都跟着来；氧气会让茶多酚自动氧化，汤色加深、滋味变淡；光照会让叶绿素脱镁由绿转褐，脂类也会氧化；高温则让所有化学反应一起加速。剩下那半个是异味——茶叶多孔、吸附性极强，周围有什么气味它就会记住什么气味。国家标准的绿茶水分限量一般在百分之七以下，行业里普遍认为含水率越低越耐放。"},{"type":"heading","level":3,"text":"冰箱能用，但有条件"},{"type":"steps","items":[{"title":"按一到两周的用量分装","text":"一次拆一小袋，避免大包装反复进出冰箱、反复结露。"},{"title":"排气后密封，袋外套罐","text":"铝箔复合袋尽量排出空气，再放进密封罐，可以加一小包食品级干燥剂。"},{"title":"贴标签写茶名与开封日期","text":"没有标签的冰箱等于没有存茶，三个月后你会认不出任何一袋。"},{"title":"放独立密封盒，远离生鲜与调味品","text":"葱蒜、海鲜、咖啡、香料是茶叶的天然对手。"},{"title":"取出后回温半小时再开封","text":"温差会让空气中的水汽在茶叶表面结露，这一步最容易被省掉也最要紧。"}]},{"type":"paragraph","text":"需要说清楚的是，冷藏只对保鲜型茶有利。低温会显著减慢氧化反应速率与酶活性，也会同时抑制黑茶、白茶需要的后期转化。黑茶的后发酵需要微量空气与适宜湿度，抽真空缺氧反而会把它按住不动，所以黑茶的存法是密封防异味、防潮，但保持适度透气。至于南方仓、北方仓哪一种更好，不同仓储流派做法不一，只谈原则不给定论。"},{"type":"heading","level":3,"text":"变质、串味、陈化、劣变不是一回事"},{"type":"list","ordered":false,"items":["霉变：出现丝状菌丝或粉状霉斑、结块发黏、有刺鼻霉味，属于食品安全问题，整批弃用","串味：吸附了肥皂、香料、油烟等气味，不可逆，香气已经被污染","陈化：黑茶与白茶在适宜条件下香气转陈、滋味转醇、汤色转深，是定向的正面变化","劣变：绿茶久放后香气散失、汤色暗黄、滋味发闷，是氧化与吸湿造成的负面变化"]},{"type":"tip","tone":"warning","title":"安全底线","text":"可见霉斑、酸馊味或刺鼻异味都不是正常陈香，不应继续饮用，也不能靠晾晒或调味挽救。茯砖茶上的「金花」呈颗粒状金黄色并带菌花香，与黄绿色丝状霉斑并带霉味的情况不同，但外观鉴别并不可靠——不确认就不喝。"},{"type":"heading","level":3,"text":"宿舍场景的三件套"},{"type":"paragraph","text":"密封夹、铝箔密封袋、一小包食品级干燥剂，放在阴凉避光的柜子里，远离洗衣液、香水和泡面，这就是宿舍存茶的完整方案。更根本的一条建议是按消耗速度买茶：一次买五十到一百克，比囤半斤名优绿茶划算得多。喝不完的茶，最有效的储存办法就是少买一点。"},{"type":"tip","tone":"info","title":"每月体检一次","text":"检查有无结块、异味、受潮迹象。轻微陈化的绿茶可以拿去做冷泡或煮茶叶蛋，风味虽有损失但不算浪费；霉变茶只能丢。"},{"type":"paragraph","text":"最后说一个反直觉但很实用的判断：买茶的速度比存茶的方法更重要。名优绿茶的最佳风味期往往只有几个月，一袋半斤的茶如果两个月喝不完，任何保存手段都只是延缓而不是阻止品质下降。可以给自己定一条线：以一个月左右的消耗量作为单次购买的基准，买得少、买得勤，把库存周转起来。如果确实收到一时喝不完的茶，可以做三件事——按一到两周的用量分装密封，标好日期先进先出，把当季要喝的那一份放在最容易拿到的位置。至于可以陈化的茶，反而要给它们留出静置的空间，不要频繁开箱翻动：每一次开箱都是一次温湿度波动，安静比关心更有用。"}]', '["tea_longjing","tea_biluochun","tea_baimudan","tea_ripe_puer","tea_liubao"]', 8, 1938, 1, 30, 'published', '2026-09-03 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('4111062982698837982', 'article_gaiwan', 'first-gaiwan', '新手的第一个盖碗，应该怎么选', '盖碗是宽容度最高的入门器具：不吸味、易清洗、出汤可控。选对器形比选贵材质重要得多。', 'teaware', '["盖碗","茶器","新手"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124037180.jpg', '[]', '[{"type":"paragraph","text":"如果只允许买一件茶器，答案多半是盖碗。它几乎能应付所有茶类，能看汤色、能看叶底，不吸味、好清洗，价格也不高。很多新手被「盖碗是专业器材」的印象吓住，其实它是所有器具里最宽容的一种——出汤快慢随手可控，泡坏了也容易找到原因。"},{"type":"heading","level":3,"text":"先定容量，一百到一百三十毫升"},{"type":"paragraph","text":"容量是盖碗最该先确定的参数。太小，投茶量稍多就泡出一碗浓汤；太大，注水过半就端不稳。日常功夫泡常用一百到一百三十毫升，这个区间对新手最友好：投三到五克茶，注水到七八分满，出汤时间好控制，一个人喝正好，两三个人也够分。审评用的标准白瓷杯是一百五十毫升，容量与它接近的盖碗也常见，但对新手来说稍大一点、稍重一点。"},{"type":"list","ordered":false,"items":["容量：一百至一百三十毫升适合日常功夫泡，一个人喝也不浪费","碗沿：外撇的撇口碗沿散热快、手指不易碰到热水线","盖钮：钮要高一些、远离碗口，食指压上去才不会烫","碗身：薄胎散热快，适合清香型茶；厚胎保温好，适合需要足温的茶"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164918990.jpg","alt":"白瓷盖碗与公道杯组成的日常茶席","caption":"白瓷釉面惰性、不吸香不染色，能最中性地反映茶汤本色。"},{"type":"heading","level":3,"text":"再说材质：白瓷上手最稳"},{"type":"paragraph","text":"新手不必先追求复杂材质。白瓷的釉面化学惰性、不吸香、不染色、易清洗，国家标准的感官审评也正是采用白瓷审评杯与碗，原因就是它能最中性地反映茶汤本色。相比之下，陶质器皿的气孔率更高，保温性更好，但会吸香，也看不清汤色与叶底；玻璃杯透明可观形，散热却快，适合绿茶与嫩芽白茶，泡乌龙与黑茶就偏吃力。器皿没有优劣，只有与该茶、该场景是否适配。"},{"type":"heading","level":3,"text":"出汤手法比器具贵贱更要紧"},{"type":"steps","items":[{"title":"持碗","text":"拇指与中指扶住碗沿两侧，食指轻压盖钮，其余手指自然收拢，别去托碗底。"},{"title":"留缝","text":"盖子与碗沿之间留一条两三毫米的细缝，缝太大茶叶会跟着冲出来。"},{"title":"出汤","text":"手腕发力快速倾倒，让茶汤一次性流尽；不要慢慢仰，那等于给茶叶加时。"},{"title":"归位","text":"出完汤立刻把盖子斜搁回去，别让余温把碗底那点茶汤继续闷着。"}]},{"type":"tip","tone":"info","title":"防烫三条","text":"注水不要超过碗沿；持碗时手指远离热水线；先用常温水练几次出汤动作，再上沸水。手感是练出来的，不是买出来的。"},{"type":"heading","level":3,"text":"配套与预算怎么排"},{"type":"list","ordered":false,"items":["百元以内：白瓷盖碗一只、玻璃公道杯一只约三百毫升、白瓷品茗杯两只，覆盖大多数日常场景","一百到三百元：加一把零点一克精度的电子秤、水温计或控温电水壶、茶巾与茶滤","三百元以上：按常喝的茶类再考虑紫砂壶（一壶一茶）或煮茶壶，先确定口味再买壶"]},{"type":"paragraph","text":"决定茶汤的第一变量始终是水温、茶水比和出汤时间，器皿主要负责保温、观感与香气修饰。所以预算的优先级很明确：把「控温电水壶 + 电子秤」排在前头。一只盖碗加一只公道杯加若干小杯，就能完成一次像样的茶席，不必凑齐全套「茶道六君子」。"},{"type":"tip","tone":"success","title":"买前三查","text":"一闻，有无刺鼻釉味或油漆味；二试，注入沸水静置五分钟，看是否渗漏、有无异味析出；三看标识，是否有食品接触用产品标识与相关标准号。陶瓷与玻璃制品分别参照食品接触材料的安全标准。"},{"type":"paragraph","text":"最后一句提醒给宿舍党：优先选不易碎、好收纳的。大件玻璃和高价紫砂摔一下就是一个月生活费，先用一只结实的白瓷盖碗把手感练熟，再谈升级。清洗用清水为主、用后即洗即可，不必泡在洗洁精里过夜。"},{"type":"heading","level":3,"text":"三个常见的翻车现场"},{"type":"paragraph","text":"第一个是注水太满。水面一旦高过碗沿，出汤时手指必然要越过热水线，端不稳也容易烫，稳妥的做法是注到七八分满，给碗沿留出干燥的抓握区。第二个是茶叶堵住出水缝，条索细碎与碎末较多的茶最容易堵，出汤前可以把盖子稍微抬高一点，或者提前用茶滤接住。第三个是出汤不彻底——很多人习惯把盖碗慢慢倾斜，觉得这样更文雅，实际上最后那几滴最浓，留在碗里等于让茶叶继续泡着，下一泡必然发苦。"},{"type":"paragraph","text":"这三个问题都不需要换器具来解决，练几次就有手感。真正需要换器具的信号只有两个：一是碗沿过窄，手指怎么放都会被烫；二是盖钮太矮，食指一压就碰到碗口。遇到这两种情况，换一只器形更友好的盖碗，比练一百次都管用。反过来，一只用着顺手的盖碗往往是这样的：注水七八分满时水面稳稳落在碗沿以下，持碗时拇指与中指各自有明确的落点，出汤口宽窄合适、水流连续不断线。这几条都能在店里用一壶温水试出来，比看任何参数都直接。"}]', '["tea_tieguanyin","tea_dahongpao","tea_keemun","tea_baihao_yinzhen"]', 7, 2257, 0, 40, 'published', '2026-09-04 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('7279681108591133657', 'article_tea_history', 'from-boiled-to-brewed-tea', '从煮茶、点茶到泡茶：饮茶方式的变化', '两千多年里，茶的形态从饼到末再到散，喝法从煮到点到泡，形态和动作一直在互相推动。', 'tea_history', '["茶史","点茶","泡茶"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124038455.jpg', '[]', '[{"type":"paragraph","text":"今天的我们习惯了抓一把散茶丢进杯子、冲上热水。但把时间线拉长看，这个动作其实相当晚才成为主流。中国饮茶经历过从食用、煮饮到点茶、瀹泡等多种形态，每一次转变都不是审美上的偶然，而是加工形态、器具、成本与生活节奏共同拉扯的结果。"},{"type":"heading","level":3,"text":"三条线索：形态、动作、器具"},{"type":"steps","items":[{"title":"唐以前与唐：煮饮","text":"茶常被煮成羹汤，早期还会与葱、姜、橘皮同煮；陆羽主张清饮，标志着茶从食物走向饮品。"},{"title":"宋：点茶","text":"团饼茶碾罗成末，注入沸水并击拂成沫饽，斗茶与茶百戏由此而来。"},{"title":"明以后：瀹泡","text":"散茶兴起，沸水直接冲泡全叶茶，壶、盖碗与杯成为主角。"}]},{"type":"heading","level":3,"text":"唐代：碾末入釜，煮出一碗青汤"},{"type":"paragraph","text":"唐代以蒸青饼茶为主，饮用时要把茶饼碾成末，投入釜中与水同煮，讲究水沸的程度。陆羽《茶经》约成书于八世纪后期，共三卷十节，从茶的源流、采制、器具一直讲到煮饮、史料与产区，是世界上第一部茶学专著，陆羽也因此被后世尊为茶圣。他在「四之器」里比较邢瓷与越瓷，提出「越瓷青而茶色绿」一类判断——器皿的颜色会改变人对汤色的感知，这在当时就已经是选器的依据。"},{"type":"quote","text":"其水，用山水上，江水中，井水下。","source":"陆羽《茶经·五之煮》"},{"type":"paragraph","text":"需要说明的是，《茶经》讲的是唐代的煎茶法，与今天的盖碗冲泡差异很大。读它要学的是体系与审美，以及「器为茶服务」的思路，而不是照搬操作步骤。"},{"type":"heading","level":3,"text":"宋代：把茶打成一层白色沫饽"},{"type":"paragraph","text":"到了宋代，主流变成精制团饼茶，饮用方式也从「煮」转向「点」。茶饼先炙、再碾、再罗，取细末入盏，先注入少量沸水调成均匀膏状，再用茶筅环击、边注水边击拂，直到形成细密持久的白色沫饽。蔡襄《茶录》主张「视其面色鲜白、著盏无水痕为绝佳」，评判标准是先看汤色再沫饽咬盏是否持久、盏壁水痕出现得早晚。宋人尚白，为此要在制茶时「榨茶」去汁，这属于特定审美目标下的工艺选择，代价是滋味变淡，不能理解为古人不懂做茶。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164919678.jpg","alt":"茶园中的茶行与远山","caption":"同一片茶园，在唐宋明清会被做成完全不同的形态，用来适配当时的饮法。"},{"type":"heading","level":3,"text":"明代：散茶与冲泡成为主流"},{"type":"paragraph","text":"元代民间已经出现散茶冲泡的做法，真正的大转折在明代。洪武二十四年，也就是一三九一年，诏令罢造龙团、惟采茶芽以进，团饼茶失去了官方支撑。这是一次制度层面的转折与加速器，但不是泡茶的起点。散茶之所以能站住脚，还有别的原因：团茶工序繁复、耗费巨大；为了汤色白而榨去茶汁，牺牲了真味；明代炒青绿茶技术成熟，散茶品质稳定、香气突出；冲泡简便，器具少，适应更广的人群；文人审美也偏向自然简素。"},{"type":"list","ordered":false,"items":["成本：龙团凤饼需蒸、榨、研、压模、焙等多道工序，贡茶征造耗费巨大","风味：为求汤色白而榨去茶汁，滋味变淡，散茶更能保留本味","工艺：明代炒青绿茶技术完善，散茶品质稳定、香气突出","制度：一三九一年罢造龙团、改贡芽茶，团饼茶失去官方支撑","生活：冲泡简便、器具少、易普及，契合更广泛人群与自然简素的审美"]},{"type":"tip","tone":"info","title":"三点阅读提示","text":"唐煮、宋点、明泡是主流饮法的分期概括，同一时期往往多种喝法并存；六大茶类的工艺定型是逐步完成的，红茶等成熟形态出现较晚，「自古六大类」属时代错置；「神农得荼而解之」是流传很广的传说性内容，不宜当作信史引用。"},{"type":"paragraph","text":"茶向世界扩散也有两条轴线：东传日本，荣西入宋后带回茶种与饮法，著《吃茶养生记》；西传欧洲与俄国，十七世纪起经海路与陆路展开，与后来那条万里茶道彼此呼应。今天茶席上的一套动作，身后其实叠着两千年的形态变化与器具更替。"},{"type":"heading","level":3,"text":"明清以后：工夫茶与两条外传路线"},{"type":"paragraph","text":"明清以后，饮茶方式并没有停在一处。闽南与潮汕地区发展出完整的工夫茶体系，讲究小壶小杯、高冲低斟、关公巡城与韩信点兵；江浙一带则流行用盖碗或玻璃杯直接冲泡散茶，追求看得到叶形与汤色。同一时期，茶还沿着两条路走向世界：一条东传日本，一条西传欧洲与俄国。器具与动作被重新组合了一次，只是这一次的主角已经是散茶。回看这条线，会发现一个规律：每一次饮法的更替，都不是单纯的审美转向，而是加工形态、器具条件、成本结构与生活节奏四者重新配平的结果。理解这一点，再看今天茶席上不断出现的新器具与新喝法，就不必急着判断高下——它们大多只是新的配平正在发生。"}]', '["tea_longjing","tea_tieguanyin","tea_zhengshan_xiaozhong","tea_dahongpao"]', 9, 1716, 0, 50, 'published', '2026-09-05 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('1342209305928218638', 'article_tasting_words', 'tea-tasting-vocabulary', '把「好喝」说清楚：六个基础审评词', '品茶不必堆砌玄妙词汇。先学会六个能重复感知的词，再比较水温、时间和器具带来的变化。', 'sensory', '["审评","风味","品鉴"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124045830.jpg', '[]', '[{"type":"paragraph","text":"「这茶挺好喝的」——这句话在茶桌上说了等于没说。不是因为它不真诚，而是因为它无法被验证、无法被比较、也无法被复现。审评术语的作用，就是把这种私人感受翻译成别人听得懂、自己下次还能对得上的描述。好消息是，入门的词其实只有六个。"},{"type":"heading","level":3,"text":"先看框架：五因子"},{"type":"paragraph","text":"国家标准《茶叶感官审评方法》把评价维度分为外形、汤色、香气、滋味、叶底五项。前四项是喝的时候就能判断的，叶底要等泡开之后再看。五因子的权重因茶类而异——绿茶常用的评分系数里滋味与香气占比较高，乌龙茶则进一步向香气与滋味倾斜，具体系数以现行标准文本的附录为准，不要照搬。"},{"type":"list","ordered":false,"items":["外形：条索松紧、颗粒、显毫、匀整、色泽，看的是干茶","汤色：嫩绿、杏绿、橙黄、红艳、红浓，同时看明亮与清浊","香气：香型、浓度、纯度、持久性，栗香、花香、蜜香、火功香、陈香各有归属","滋味：鲜爽、醇厚、醇和、甘醇、浓强、回甘，反面则是苦涩、粗涩、淡薄","叶底：嫩度、匀度、色泽、亮暗，柔软匀整与粗老暗杂是两端"]},{"type":"heading","level":3,"text":"六个能重复感知的词"},{"type":"paragraph","text":"五因子是框架，落到具体描述时，最先该掌握的是这六个词。它们好在都能被重复感知：换一款茶、换一天，你依然分得清哪个是哪个。"},{"type":"list","ordered":false,"items":["香气：闻到的花、果、焙火或木质等联想，先说香型再说高低","鲜爽：入口清活、轻快的感受，绿茶与嫩芽白茶里最突出","醇厚：茶汤饱满、有厚度且不刺激，注意它与「浓厚」不是一回事","回甘：咽下之后口腔里出现的甜感，重点在有没有、能留多久","收敛：口腔轻微发紧的感觉，关键看能不能化开、是否伴随回甘","耐泡：多次冲泡后仍保有风味的能力，是工艺与原料的综合体现"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125851214.jpg","alt":"两只品茗杯中的茶汤并排对比","caption":"并排对比比单独记忆更容易发现差异，这是最省力的训练方法。"},{"type":"heading","level":3,"text":"术语有三层，别只说了第一层"},{"type":"paragraph","text":"一个完整的评语包含三层信息：程度、性质与正负。程度是一把标尺，醇和小于醇厚，醇厚小于浓厚；性质是香型与风味的方向，是栗香还是蜜香，是鲜爽还是甘醇；正负则判断纯正还是有缺陷。只说「香」，别人不知道是清香还是烟焦气；只说「浓」，别人不知道是饱满还是苦涩不化。三层说完，才叫说清楚一款茶。"},{"type":"heading","level":3,"text":"小白的三段式描述法"},{"type":"steps","items":[{"title":"第一段：入口第一感觉","text":"是浓是淡，是鲜是涩，是甜是苦，先给出一个粗略的方向。"},{"title":"第二段：中段","text":"顺滑还是粗糙，有没有回甘，舌面与两颊是什么感觉，苦涩能不能化开。"},{"title":"第三段：尾段","text":"咽下之后口腔里留着什么、留了多久、是否口干。"},{"title":"加一句生活化类比","text":"像炒豆香、像桂花、像蒸玉米须，类比不必精准，能让对方搭上你的感受就够了。"}]},{"type":"tip","tone":"success","title":"三行记录法","text":"每泡只写香气、滋味、余韵三行，连续记录三泡即可。再补一栏「下次想改的参数」，一周之后你会明显感到进步。"},{"type":"heading","level":3,"text":"审评与日常品饮不是一回事"},{"type":"paragraph","text":"专业审评用沸水、长时间、固定比例，本质是一场刻意放大缺点的压力测试——浓度与温度拉满，缺陷就无处可藏。日常冲泡则是扬长避短，参数可以按个人喜好调整。所以同一款茶在两个场景下得出不同结论，完全正常。另外，审评要求环境无异味、光线均匀、器具统一，并且由经过训练的多人独立盲评后汇总，单人一句「不好喝」不能算审评结论。"},{"type":"tip","tone":"warning","title":"两个容易踩的坑","text":"其一，香气越高扬、滋味越浓不等于品质越好，审评看的是纯正、协调与持久，浓郁却带烟焦气、青气或酸馊味的是明显缺陷。其二，「岩韵」「音韵」这类描述性经验概念缺少可量化的统一定义，不宜作为品质的唯一判据，判断仍要回到五因子的具体表现。"},{"type":"paragraph","text":"最后一条练习建议：听到「大师手工」「古树纯料」「韵足」这类说法时，主动追问可验证的信息——产地、等级、年份、执行标准，把营销话术翻译成五因子语言。你会发现，能翻译的才是能比较的。"},{"type":"paragraph","text":"最后给一个可以立刻用上的改造练习。把「这茶挺好喝的」改写成「汤色杏绿明亮，香气以嫩栗香为主，入口鲜爽、苦涩轻、回甘明显，叶底嫩匀」——五因子各说一点，一句话就从感受变成了描述。再加一句生活化类比，比如「像刚炒好的青豆」，对方就真的能搭上你的感受。练习的诀窍是固定句式、只换内容：汤色什么样、香气是什么型、入口什么感觉、咽下留什么、叶底什么样。写满十条之后，你会发现自己已经不需要刻意对照术语表，也能把一款茶说得清楚、说得可比较、说得让下一次的自己看得懂。"}]', '["tea_biluochun","tea_baimudan","tea_huoshan_huangya","tea_dahongpao","tea_keemun","tea_liubao"]', 7, 2894, 1, 60, 'published', '2026-09-06 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('7810764759539251722', 'article_teaware_material', 'teaware-material-guide', '茶器选择：材质、保温与吸附性', '选器不是选贵，而是选适配。材质的三个底层变量是导热保温、吸附性与可视性，想清楚再买。', 'teaware', '["茶器","材质","选购"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125845057.jpg', '[]', '[{"type":"paragraph","text":"面对一只盖碗、一把紫砂壶、一个玻璃杯和一把瓷壶，很多人凭手感或价格做判断。其实材质真正决定的只有三件事：水与茶在什么温度下接触、香气是被留住还是被吃掉、你能不能看见茶汤和叶底。把这三个变量想清楚，选器就从审美题变成了应用题。"},{"type":"heading","level":3,"text":"三个底层变量"},{"type":"list","ordered":false,"items":["导热与保温：决定能不能维持萃取所需的温度，陶质气孔多、空气导热差，保温性优于薄胎瓷与玻璃","吸附性：决定香气被保留还是被「吃掉」，同一性质既带来聚香，也带来夺香","可视性：决定能不能观形、看汤色、看叶底，玻璃最好，陶器最差"]},{"type":"heading","level":3,"text":"四种常见器皿对比"},{"type":"list","ordered":false,"items":["盖碗（白瓷）：釉面惰性、几乎不吸味、易清洁，保温中等，可视性好，几乎通吃所有茶类，尤宜清香型乌龙、红茶、白茶与黄茶","紫砂壶：保温好，吸附明显会「留味」，可视性差，适合焙火乌龙、武夷岩茶、老白茶与黑茶","玻璃杯：透明不吸味、散热快，观形最佳，适合绿茶、黄茶与白毫银针这类嫩芽茶","瓷壶：釉面惰性不吸味，保温中等，可视性差，适合红茶、白茶、清香型乌龙与待客场景"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927942.jpg","alt":"茶席上的不同材质茶器","caption":"器无优劣，只有适配；把四件器皿放在一起对比，差异立刻可见。"},{"type":"heading","level":3,"text":"按茶选器的速查思路"},{"type":"paragraph","text":"嫩芽绿茶走玻璃杯或白瓷盖碗，看的是舒展的姿态与清亮的汤色；黄茶同理，玻璃杯还能欣赏君山银针的起落；新白茶用盖碗，陈白茶与寿眉可以换紫砂或煮茶壶；清香型乌龙配薄胎白瓷盖碗，才不会把细腻的兰花香吸走；焙火乌龙用盖碗或紫砂壶都行，紫砂能柔化口感；红茶用盖碗或瓷壶，大叶种滇红也可以用紫砂；黑茶用紫砂壶、盖碗或煮茶壶都合适。"},{"type":"heading","level":3,"text":"为什么白瓷是审评标准器"},{"type":"paragraph","text":"国家标准《茶叶感官审评方法》采用白瓷审评杯与审评碗，原因正是釉面的化学惰性——不吸香、不染色、易清洗，能最中性地反映茶汤本色。这条逻辑对日常选器同样成立：当你还不确定自己想喝什么、想把一款茶的本来面目看清楚时，白瓷是最不容易出错的起点。古人也早就注意到器色会影响观感，陆羽在《茶经·四之器》里比较邢瓷与越瓷，提出「越瓷青而茶色绿」一类判断，说的正是审美与物理共同作用的结果。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920873.jpg","alt":"紫砂壶与白瓷盖碗并列摆放","caption":"保温与聚香是紫砂的长处，吸香与不便观察是它要付的代价。"},{"type":"tip","tone":"warning","title":"三个常见误区","text":"紫砂壶不是「泡什么都行」的万能器，泡细嫩绿茶容易闷熟并吸走清香；盖碗不是专业器材，它恰恰是宽容度最高的入门器具；越贵的茶器并不会让茶更好喝——决定茶汤的第一变量是水温、茶水比和出汤时间，预算优先给控温电水壶与电子秤，收益大得多。"},{"type":"heading","level":3,"text":"容量、投茶与安全"},{"type":"paragraph","text":"容量和投茶量必须配套，否则再好的器具也白搭。盖碗常见一百到一百三十毫升，审评杯为一百五十毫升；投茶比上，绿茶常用三克对一百五十毫升上下，乌龙功夫泡常见五克对一百一十毫升上下，黑茶常见七到八克对一百五十毫升，具体应以各款茶的建议参数为准。玻璃器皿还分两种：高硼硅玻璃耐热冲击好，普通钠钙玻璃骤然冷热容易开裂，先温杯再注水是最省事的保险。"},{"type":"list","ordered":false,"items":["食品接触安全是底线：陶瓷参照 GB 4806.4，玻璃参照 GB 4806.5，需关注铅、镉迁移限量","避免无标识、有刺鼻气味、颜色异常鲜艳的廉价器皿","紫砂建议一壶一茶：长期泡不同茶类会互相串味，这是行业经验建议，不是标准强制要求","清洗用后即洗、清水为主，紫砂不用洗洁精浸泡，也不用钢丝球"]},{"type":"tip","tone":"success","title":"第一套器具的排序","text":"先买白瓷盖碗与公道杯，再买控温电水壶和电子秤，最后按常喝的茶类决定要不要添紫砂壶或煮茶壶。先确定口味再买壶，能避免闲置。"},{"type":"heading","level":3,"text":"容易被忽略的第二个变量：器形与出水"},{"type":"paragraph","text":"还有一种常被忽略的因素：器具的口沿形状与出水结构。同样材质的两只盖碗，碗沿外撇的角度差几度，持握的舒适度就完全不同；同样材质的壶，出水口是单孔还是球孔，出汤速度能差出一倍。这些跟材质无关，却直接决定你能不能在最佳时间点把茶汤倒出来。选购时与其盯着泥料与产地，不如先确认两件事：手指能不能稳稳地落在该落的位置，出水是否连续、能不能一次流尽。第二条建议是把器具当成可迭代的配置，而不是一次性采购。开始时一只白瓷盖碗加一只公道杯就够用；当你发现自己固定喝某一类茶，并且明确感到现有器具限制了发挥时，再针对性地增加。这条思路能避开两种浪费：买了一套用不上的器具，或者为了追求「全能」而买回一件样样都勉强的器具。"}]', '["tea_longjing","tea_tieguanyin","tea_dahongpao","tea_keemun","tea_ripe_puer"]', 8, 2452, 0, 70, 'published', '2026-09-07 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('3323175002769484752', 'article_water_quality', 'water-quality-and-temperature', '水质与水温：水决定下限，水温决定上限', '水里的矿物质决定茶汤能有多干净，温度决定香气能提到多高。顺序是先选对水，再定温度。', 'brewing', '["水质","水温","冲泡"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125843790.jpg', '[]', '[{"type":"paragraph","text":"同一泡茶，换一种水、换一个温度，可以是两种味道。这不是玄学。水里的矿物质决定了茶汤能有多干净、香气能不能立起来；温度决定了苦涩与鲜甜谁先出来。把这两件事分开看，泡茶的很多困惑会自己解开。"},{"type":"heading","level":3,"text":"古人怎么说，怎么读"},{"type":"paragraph","text":"陆羽在《茶经·五之煮》里写：「其水，用山水上，江水中，井水下。」这是唐代条件下对水源优劣的经验排序，价值在于指出水质与火候决定茶汤，而不是提供一份可以直接照搬的水源清单。山泉多为流动的活水、矿化度适中，但未经检测的天然水可能有微生物与污染物，不建议生饮；今日江河普遍存在污染风险，更不能直接饮用；井水静止、硬度常偏高，还可能含铁锰。现代选水的第一原则很简单：符合饮用水卫生标准、低矿化度、无异味。"},{"type":"heading","level":3,"text":"影响茶汤的五个水质指标"},{"type":"list","ordered":false,"items":["总硬度：钙镁离子偏高时，汤色变深发暗、滋味变淡或发涩、香气低闷","酸碱度与碱度：偏碱会加速茶多酚氧化，汤色加深、滋味变钝，偏中性有利于汤色明亮","铁、锰等金属离子：与茶多酚形成深色络合物，使茶汤发暗并带来铁腥味","余氯：与茶多酚反应生成氯味物质，破坏香气","矿化度：过高使风味粗糙，极低的纯水则汤感偏薄、香气飘而不聚"]},{"type":"paragraph","text":"综合起来，一般认为低矿化度的软水表现通常较好：汤色清亮、香气较扬；硬水则汤色暗、滋味钝；而极软的纯净水、蒸馏水虽然汤色最亮，却常出现汤感薄、香气不聚的问题。硬度分级在不同资料里的界限并不一致，只能当参考，不必当结论。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920306.jpg","alt":"控温电水壶与水温计","caption":"把水烧对、把温度定住，是投入最小、回报最直接的一步。"},{"type":"heading","level":3,"text":"温度：决定上限的那一半"},{"type":"paragraph","text":"研究提示，儿茶素类在高温下浸出速率显著快于氨基酸类，这是「沸水泡绿茶易苦涩」的核心解释。反过来，高温有利于高沸点香气物质挥发，乌龙与岩茶的焙火香、花果香需要沸水才激发得出来。所以温度没有统一答案，只有按茶类与嫩度定的一条线。"},{"type":"list","ordered":false,"items":["绿茶：八十至八十五度，嫩芽可低至七十五至八十度，忌沸水直冲","黄茶：黄芽茶八十至八十五度，黄大茶九十至九十五度","白茶：白毫银针与白牡丹八十五至九十度，寿眉与陈白茶九十五度至沸水","乌龙：九十五度至沸水，做青与焙火使叶组织紧实，需要高温激发","红茶：九十至九十五度，细嫩芽头八十五至九十度，大叶种与红碎茶可到沸水","黑茶：沸水，紧压茶可煮，先润洗一到两遍"]},{"type":"heading","level":3,"text":"煮水程度也算火候"},{"type":"paragraph","text":"《茶经》把沸腾分成三沸：如鱼目、微有声为一沸，缘边如涌泉连珠为二沸，腾波鼓浪为三沸，并说「已上水老，不可食也」。现代的解释是，水沸腾过久，溶解氧与二氧化碳逸出，茶汤口感会变「钝」、缺乏活性。至于反复长时间煮沸的水是否有害，不同资料结论并不一致，这里不下定量结论，实际影响主要落在口感与能耗上。"},{"type":"steps","items":[{"title":"先选水","text":"桶装纯净水或低矿化度矿泉水优先，可以看标签上的硬度或矿化度信息。"},{"title":"处理自来水","text":"煮沸后开盖续沸约一分钟，帮助余氯挥发，再静置降温使用。"},{"title":"再定温度","text":"用控温电水壶最省事，没有就用倒杯降温法：沸水入公道杯静置二至三分钟约到八十五度。"},{"title":"最后调时间","text":"水与温度定好之后，才轮到用出汤时间微调浓度。顺序不要颠倒。"}]},{"type":"tip","tone":"info","title":"一次只改一个变量","text":"固定投茶量，只改水温（比如八十度、九十度、沸水各一次），把三种结果写下来。一次实验胜过十篇经验帖。"},{"type":"tip","tone":"warning","title":"两个方向都不能走极端","text":"不是所有茶都该用八十度，也不是好茶就必须用沸水。嫩芽茶遇沸水会苦涩、汤色泛黄、香气损失；紧压黑茶用温水则寡淡无味。保温杯长时间闷泡绿茶尤其不建议，高温密闭会把苦涩物质全部逼出来。"},{"type":"heading","level":3,"text":"三个能立刻用上的判断"},{"type":"paragraph","text":"没有仪器的时候，可以用三条粗略但有效的判断。其一，看水壶底的水垢：烧一段时间就积起明显白色水垢的自来水，硬度通常偏高，泡出来的茶汤容易发暗、滋味发钝，建议改用低矿化度的桶装水。其二，闻与尝：有氯味的水一定要开盖续沸约一分钟再降温，否则气味会直接进入茶汤。其三，看汤色：同一款茶换了水之后汤色明显变暗或变浑，问题多半出在水上，而不是茶上。"},{"type":"paragraph","text":"还有一条经验值得记住：水的影响是全局的，温度的影响是局部的。水质不好，无论怎么调温度、怎么改时间，茶汤的上限都被封住了；而水质合格之后，温度的微调能让同一款茶在「鲜爽」与「醇厚」之间来回移动。这也正好解释了那句总结：水决定下限，水温决定上限。所以遇到怎么泡都不好喝的茶，先换水试试。"}]', '["tea_longjing","tea_biluochun","tea_baihao_yinzhen","tea_dahongpao","tea_ripe_puer"]', 9, 3107, 1, 80, 'published', '2026-09-08 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('6398829429132300117', 'article_tea_horse_road', 'tea-horse-road-and-ten-thousand-li-tea-road', '茶马古道与万里茶道：两条用脚走出来的茶路', '一条向西进藏区以茶易马，一条向北越草原直抵俄国。两条商路塑造了今天的边销茶地图。', 'tea_history', '["茶马古道","万里茶道","贸易史"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125848750.jpg', '[]', '[{"type":"paragraph","text":"中国茶走向边疆与域外，靠的不是一条路，而是两张网。一张向西，穿过横断山脉的河谷走廊进入藏区，用茶换马；一张向北，越过草原与戈壁抵达俄国，用茶换银。它们一个塑造了边销茶的形态，一个决定了今天很多人对红茶的认知。"},{"type":"heading","level":3,"text":"一张对比表看清差异"},{"type":"list","ordered":false,"items":["方向：茶马古道向西南进入康藏，并有甘青方向；万里茶道自东南产茶区向北，跨蒙古高原到俄国","时期：茶马互市自唐代已见，宋代制度化，延续至民国；万里茶道主要活跃于十七世纪末至二十世纪初","主导力量：前者是官方互市加民间马帮与背夫；后者以晋商为主体，俄商在十九世纪深度参与","主要茶类：前者是南路边茶、云南紧茶与沱茶、湖南黑茶等边销茶；后者是工夫红茶与各类砖茶","终点与交换物：前者到康定、拉萨及藏区各地，以茶易马与皮毛；后者经恰克图到莫斯科、圣彼得堡，以茶易银与呢绒"]},{"type":"paragraph","text":"需要先说明一个概念问题：「茶马古道」这个名称由国内学者在二十世纪九十年代初提出并逐步推广，此前多称茶马商道、驿道，它是现代学术命名，不是古代的固定专名。而且它是路网而不是一条路，主要干道包括川藏道、滇藏道与甘青方向，另有大量支线，具体走向在不同研究里表述不一。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926807.jpg","alt":"牧区饮用的酥油茶","caption":"砖茶经熬煮后调饮，形成藏族酥油茶、蒙古族咸奶茶等牧区饮俗。"},{"type":"heading","level":3,"text":"以茶易马：制度与地理的合力"},{"type":"paragraph","text":"中原王朝缺战马，边疆民族地区缺茶，于是形成了长期官方与民间并行的以茶易马贸易。宋代设专门机构管理，明清延续并演化为更广泛的边销茶贸易。从地理上看，这条走廊沿着横断山脉的河谷展开，是地形条件与物资互补共同作用的结果——不是谁规划出来的，而是被山和水逼出来的。"},{"type":"heading","level":3,"text":"为什么运的是砖茶"},{"type":"paragraph","text":"边销茶以黑茶类为主，原料相对粗老，压制成砖。这个形态不是将就，而是为长距离贸易专门设计的：压缩体积能显著降低运输成本，紧压之后耐候耐存，到了地方还可以分割交易与熬煮。雅安是南路边茶的产地与川藏道起点，下关承担紧茶与沱茶的加工集散，安化依托资江水运外运，羊楼洞以青砖、米砖著称，汉口开埠后成为茶叶集散与砖茶加工中心，被称为东方茶港。"},{"type":"heading","level":3,"text":"万里茶道：从武夷山到恰克图"},{"type":"paragraph","text":"万里茶道的起点之一是福建武夷山下梅村一带，经江西、湖南、湖北北上，过河南、山西，出张家口与归化，越蒙古高原至恰克图，再西延至莫斯科与圣彼得堡。一七二八年中俄《恰克图条约》之后，恰克图成为重要的边境互市点。这条路不只是中国人的生意，俄商在十九世纪深度参与，并在汉口、羊楼洞等地设厂压制砖茶，是一条真正的跨国贸易网络。二〇一九年三月，「万里茶道」被列入《中国世界文化遗产预备名单》。"},{"type":"quote","text":"宁可三日无粮，不可一日无茶。","source":"牧区流传的谚语，属传统经验表述"},{"type":"paragraph","text":"这句谚语说的是砖茶在牧区日常生活中的分量，仅此而已。它不能用来说明任何营养或健康方面的结论——牧区传统饮食多肉、多奶、少蔬果，砖茶经熬煮后调饮，是生活方式的一部分，不是功效承诺。"},{"type":"tip","tone":"warning","title":"砖茶的氟含量提示","text":"砖茶原料成熟度高，氟含量相对较高，国家标准《砖茶含氟量》对砖茶氟含量有限量要求。长期大量饮用浓煎砖茶与饮茶型氟中毒相关，儿童与孕期人群尤其需要注意，不建议全天以浓砖茶代水。普通消费者的日常淡饮风险很低。"},{"type":"steps","items":[{"title":"先撬散","text":"用茶刀或茶针顺着压制纹理撬成小块，块形尽量保持完整，更耐泡。"},{"title":"快速润洗","text":"沸水注满即出，一到两遍，去浮尘、唤醒茶性。"},{"title":"熬煮或长时间闷泡","text":"沸水熬煮，或按五克茶起步投量，从小量开始试，避免过浓。"},{"title":"调饮","text":"加入奶与少量盐，即为酥油茶或咸奶茶的基本思路。"}]},{"type":"tip","tone":"info","title":"记忆办法","text":"用「方向、主体、茶类、交换物、终点」五列做对比表，一次就能记住两条路线差异。把路线画在同一张中国地图上，一西一北，比读文字更容易记牢。"},{"type":"heading","level":3,"text":"两条茶路留下的东西"},{"type":"paragraph","text":"两条茶路留下的不只是贸易记录，还有一整片茶产区的性格。雅安、下关、安化、羊楼洞、汉口这些节点，因为承担了加工与集散的职能，各自发展出不同的产品形态与技术传统：有的擅长压制砖茶，有的擅长拼配与仓储，有的靠水运把茶送出去。今天茶单上的边销茶与砖茶，几乎都能在这些节点上找到源头。把地图与产品对照着看，比单独记忆年代要牢固得多。另一条更有意思的线索是运输经济学。砖茶的形态从来不是为了好看，而是被运输成本塑造出来的：能压多紧就压多紧，能少占多少体积就少占多少，到了地方还要方便分割与熬煮。同样地，万里茶道上的工夫红茶之所以成为主力，也是因为它耐存、耐运，并且在异国市场接受了检验。形态跟着路走，路跟着需求走——这是两条茶路最值得记住的一句话。"}]', '["tea_ripe_puer","tea_liubao","tea_zhengshan_xiaozhong","tea_keemun"]', 10, 1483, 0, 90, 'published', '2026-09-09 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('6063787464697137824', 'article_song_diancha', 'song-dynasty-whisked-tea', '宋代点茶：把茶打成一层白色沫饽', '炙碾罗候熁调击，七步工序只为一层细密沫饽。点茶是宋代最讲究的饮茶方式，也是末茶饮法的远祖。', 'tea_history', '["点茶","宋代","茶史"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125847554.jpg', '[]', '[{"type":"paragraph","text":"如果从今天的盖碗冲泡穿越回宋代，你多半会不知道该从哪里下手。宋代主流是点茶：茶要碾成细末，注入沸水后用茶筅快速击拂，直到茶汤表面浮起一层细密持久的白色沫饽。这套动作有七个步骤，每一步都有明确的目的，没有一步是仪式性的多余。"},{"type":"heading","level":3,"text":"点茶七步"},{"type":"list","ordered":true,"items":["炙茶：微火烘烤茶饼，去潮气、激发香气，便于碾碎","碾茶：用茶碾或茶磨把茶饼碾成碎末，末茶饮法必须先把茶变成粉","罗茶：用茶罗筛取细末，粗细均匀才能击拂出细腻沫饽","候汤：烧水并判断沸度，水未熟则沫浮，过熟则茶沉，水老水嫩都打不出好沫饽","熁盏：烤热茶盏，盏冷则茶末易沉、沫饽难起","调膏：取茶末入盏，注入少量沸水调成均匀膏状，先成膏才能均匀受水、避免结块","击拂：用茶筅环击，边注水边击拂，形成细密持久的白色沫饽"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925059.jpg","alt":"点茶用的茶筅与广口茶盏","caption":"茶筅与黑釉盏是点茶的核心器具，后者便于观察白色沫饽。"},{"type":"heading","level":3,"text":"七汤点法与斗茶的评判标准"},{"type":"paragraph","text":"宋徽宗赵佶在《大观茶论》里记载了分七次注水、逐次击拂的做法：第一汤调膏，后续逐次击拂，沫饽由疏到密、由薄到厚。这是宋代点茶技术的最高总结。蔡襄《茶录》则给出了评判标准——「视其面色鲜白、著盏无水痕为绝佳」。先看汤色，以白为贵；再看沫饽咬盏是否持久，看盏壁上的水痕出现得早晚，水痕先现者为负。"},{"type":"paragraph","text":"配套的器具清单也相当完整：茶焙与茶笼用于藏茶，茶钤夹饼上火，茶碾或茶磨负责碾碎，茶罗筛末，茶筅击拂，茶盏崇尚黑釉以便衬出白色的沫饽，汤瓶控制注水。蔡襄《茶录》下篇「论茶器」对这些器具逐一评述。再往后还有茶百戏，也叫分茶，在点好的沫饽上用清水或茶膏勾画文字与花鸟，北宋陶谷《荈茗录》中已见「茶百戏」之名。"},{"type":"heading","level":3,"text":"点茶与今天的抹茶，一样吗"},{"type":"list","ordered":false,"items":["原料形态不同：宋代多用蒸青后压榨、研膏、模压成形的团饼茶，现代抹茶以碾茶为原料，即覆盖栽培、蒸青后不揉捻直接烘干的叶茶","研磨方式不同：前者用茶碾茶磨加茶罗筛取细末，后者以石磨或机械研磨成微米级的粉","饮法相承：两者都击拂成沫饽、都连末一起喝下","风味取向不同：团茶经榨茶去汁，追求汤色白、滋味清；抹茶靠覆盖栽培提高氨基酸，色泽翠绿、鲜味突出","文化语境不同：前者连着斗茶与茶百戏的文人风尚，后者发展成日本的抹茶道体系"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925634.jpg","alt":"击拂后的抹茶沫饽特写","caption":"沫饽的细腻度由茶末细度、水温与击拂强度共同决定。"},{"type":"paragraph","text":"沫饽的物理本质并不神秘：茶汤中的可溶性蛋白、多糖等表面活性物质在剧烈搅打下形成气泡并稳定为泡沫层。所以茶末越细、水温越合适、击拂越有力，沫饽就越细腻持久。宋人尚白茶色，为此要在制茶时榨去茶汁使汤色趋白，同时降低苦涩——这是特定审美目标下的工艺选择，代价是滋味变淡，不能理解为古人不懂做茶。"},{"type":"heading","level":3,"text":"它为什么被泡茶取代"},{"type":"paragraph","text":"团茶工序繁复、耗费巨大；一次完整点茶动辄十几分钟，日常难以持续；榨茶去汁虽得白汤，却损真味；洪武二十四年诏罢造龙团、改贡芽茶，团饼茶失去官方支撑；冲泡简便、器具少，适应更广的人群；元代民间散茶冲泡已渐流行。这是渐进转变而非一夜替代，至于确切的衰落原因与时间，学界有不同解释，稳妥的说法是多因共同作用。"},{"type":"steps","items":[{"title":"准备","text":"市售抹茶粉一点五到两克，七十至八十五度的热水约六十至七十毫升，广口盏一只。"},{"title":"调膏","text":"先注入少量水，把茶粉调成无颗粒的均匀膏状，这一步决定后面有没有结块。"},{"title":"击拂","text":"用茶筅以 W 形快速击拂十五到三十秒，直到表面出现细密沫饽。"},{"title":"观察","text":"沫饽能挂住盏壁、无明显大气泡，就算成功。没有茶筅时可用小型电动打泡器应急，效果不同，仅作体验。"}]},{"type":"tip","tone":"info","title":"三条阅读提醒","text":"宋代茶末的细度、团茶榨汁的程度与现代抹茶的比较，学界与复原者表述并不一致，介绍时宜用「多为」「通常」这样的限定语；点茶与抹茶都连末饮用，但原料工艺不同，「以纯白为上」是宋代蒸青团茶在特定工艺条件下的审美，不能套用到今天的绿茶与红茶；点茶与泡茶是演变关系，不是水平升降。"},{"type":"heading","level":3,"text":"点茶留下的痕迹"},{"type":"paragraph","text":"点茶虽然退出了日常，但它留下的痕迹并不少。日本的抹茶道与宋代的末茶点饮相承——荣西入宋后带回茶种与饮法，著《吃茶养生记》，此后在日本独立发展成抹茶道体系。而在今天的中国，点茶正以体验课、复原演示与短视频的形式重新回到公众视野，一些产地有传承人从事复原与推广，具体名录批次可以另行核对。它成为一项可以被普通人亲手体验的技艺，本身就是一件有价值的事。"},{"type":"paragraph","text":"另一层影响在审美上。宋人尚白，讲究沫饽的细腻与持久，这套标准塑造了黑釉盏的流行，也塑造了一套以「观色」为核心的品饮方式。而当泡茶成为主流之后，审美重心转向了「观形」与「闻香」——今天我们用玻璃杯看绿茶舒展、用白瓷盖碗看汤色，与宋代人盯着盏面看沫饽，其实是同一件事的不同版本。饮法变了，看茶的习惯留了下来。"}]', '["tea_longjing","tea_baihao_yinzhen","tea_dahongpao"]', 10, 3629, 1, 100, 'published', '2026-09-10 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('1661316207401941516', 'article_tea_snacks', 'tea-and-snack-pairing', '茶点搭配：把茶点当味觉的节奏设计', '好搭配让茶更好喝，也让点心更好吃。四条原则加上一张对照表，足够应付九成日常场景。', 'sensory', '["茶点","搭配","茶席"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125852441.jpg', '[]', '[{"type":"paragraph","text":"很多人觉得喝茶配点心是件不专业的事，好像好茶必须清饮。恰恰相反，配茶点是世界性的传统：英式下午茶是红茶配司康，闽粤工夫茶有专门的茶配与茶食，藏蒙牧区把砖茶熬煮后配糌粑与奶食。清饮是文人的审美取向，配茶点是生活方式的选择，两者并不冲突，关键在搭配得是否互相成就。"},{"type":"heading","level":3,"text":"四条原则"},{"type":"list","ordered":false,"items":["浓配浓、淡配淡：茶与点的滋味强度要匹配，否则一方会被完全压住，清淡的白毫银针配重辣卤味就是典型反例","不夺香：茶点的气味不能盖过茶香，榴莲、臭豆腐、薄荷糖、重香精点心都不合适","口感互补：甜可缓冲苦涩，清爽可化油腻，咸香可衬回甘","便利性：小块、易取、不脏手、不发出大声响，大份汤粉与带壳带汁的食物不适合上茶席"]},{"type":"heading","level":3,"text":"六大茶类配什么"},{"type":"list","ordered":false,"items":["绿茶：走清淡清甜路线，绿豆糕、桂花糕、藕粉、青提与梨都合适","新白茶：清淡带米香，米糕、白云豆沙、淡味坚果","陈白茶与寿眉：可以略重一些，原味坚果、枣泥糕","黄茶：同绿茶而更宜清淡，苏式清甜茶食","清香型乌龙：清甜与果香向，凤梨酥、绿豆糕、低糖水果干","焙火乌龙与岩茶：坚果、咸香、耐咀嚼，花生、瓜子、肉干、蛋黄酥","红茶：甜点与奶制品，司康、磅蛋糕、蜜饯、黑巧克力","黑茶：配油腻重味与奶制品，肉干、月饼分小块、糍粑、奶食"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925636.jpg","alt":"茶席上的茶点摆盘","caption":"茶点是节奏而不是正餐，两到三样、小块上桌即可。"},{"type":"paragraph","text":"这张表属于经验整理，并非标准规定，各地传统各有来路：江南绿茶配绿豆糕，台湾乌龙配凤梨酥，闽粤工夫茶配咸甜小点与蜜饯，英式下午茶把红茶和司康绑定，藏蒙牧区把砖茶熬煮后配奶食。共同点是搭配者知道自己在做什么——让茶和点心里的一方去托住另一方，而不是互相抢戏。"},{"type":"heading","level":3,"text":"为什么这样配说得通"},{"type":"paragraph","text":"食品感官评价领域有三条一般结论可以解释大部分搭配经验。其一，甜味缓冲：甜可以降低苦味与涩感的感知强度，所以微甜的点心能让偏涩的茶变得顺口。其二，气味掩蔽：强挥发性气味会遮蔽茶香，这就是「不夺香」不是玄学的原因。其三，口腔清洁感：茶汤的收敛性与生津感能清除口腔里残留的油脂感，让下一口点心显得更清爽。这三条都是感知层面的机制，不涉及任何功效。"},{"type":"heading","level":3,"text":"现代场景怎么配"},{"type":"list","ordered":false,"items":["图书馆与自习：冷泡绿茶或冷泡白牡丹，配原味坚果、无糖饼干、水果沙拉，清爽无声便于携带","宿舍追剧：气泡茶或冷泡乌龙，配少量薯片与炸物，清爽感与气泡能平衡油腻","轻食下午茶：清香乌龙或红茶，配酸奶、芝士蛋糕、轻食三明治","控糖需求：纯茶配无糖坚果、水煮蛋、原味奶酪，避免游离糖叠加"]},{"type":"steps","items":[{"title":"先定茶","text":"今天想喝什么茶，先确定下来，再按强度找点心，而不是反过来。"},{"title":"再配点","text":"按浓配浓、淡配淡的原则锁定一到两样，宁少勿多。"},{"title":"控制分量","text":"点心切到一口能吃完的大小，一桌只放一到两样甜点。"},{"title":"看配料表","text":"糖排在前三位的点心慎选，优先清甜或无糖的选择。"}]},{"type":"tip","tone":"success","title":"茶席搭配的美学","text":"点心的颜色与茶汤形成对比更好看，绿茶配浅色点心、红茶配深色点心；用竹签或小夹子取用，比直接上手更方便。"},{"type":"tip","tone":"warning","title":"需要注意的几种搭配","text":"不用茶水送服药物，一般建议服药与饮茶间隔一小时以上；重辣、重蒜、重醋会掩盖茶香，对胃的刺激也较强；大量高糖高油点心配浓茶、尤其在空腹时，容易钝化味觉；清饮场景下不建议在绿茶里加牛奶，乳蛋白会与儿茶素结合，掩盖绿茶最宝贵的鲜爽感，这属于初步研究提示。"},{"type":"paragraph","text":"关于「解腻」，需要说清一层：传统上餐后饮茶用于解腻，这属于传统经验表述，不等于帮助消化，也不等于能抵消油脂摄入。真正落实在生活里的做法，是把含糖饮料换成纯茶，再配合饮食与运动的整体安排。至于奶茶，它是独立的产品类型，有稳定的风味逻辑与受众，评价它应该看糖量、奶源与茶底，而不是套用清饮的标准去否定它。"},{"type":"heading","level":3,"text":"分量、时间与场景的控制"},{"type":"paragraph","text":"茶点是节奏而不是正餐，这句话落到操作上有几条具体的线。数量上，一桌放两到三样就够，样数多了注意力会从茶上移开；分量的标准是「一口吃完」，需要动刀、需要吐壳、需要蘸汁的食物都不适合上茶席。时间上，第一泡通常先纯饮，让味觉记住茶的本味，之后再上点心；每换一款茶，可以让口腔空一会儿，或者用一杯温水过渡。"},{"type":"paragraph","text":"场景也是变量。自习与办公场景优先无糖、无声、不掉渣的点心，吃完不耽误翻书；朋友聚会的下午茶可以放开一些，允许有甜点与奶制品出现；正式一点的茶席则回到「不夺香」的原则上，宁可少放，也不要让点心的气味抢在前面。这些不是规矩，而是把注意力留给茶的一种安排方式。"}]', '["tea_baihao_yinzhen","tea_baimudan","tea_dahongpao","tea_keemun","tea_ripe_puer"]', 8, 2085, 0, 110, 'published', '2026-09-11 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('1713494359061566910', 'article_green_tea', 'green-tea-explained', '绿茶：不发酵的清鲜一路', '杀青是绿茶的决定性工序：用高温钝化酶，把绿色与鲜爽锁在叶子里。清汤绿叶是它的底色。', 'tea_basics', '["绿茶","杀青","不发酵"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125856085.jpg', '[]', '[{"type":"paragraph","text":"六大茶类里，绿茶出现得最早、产量最大、认知度也最高。它的技术核心只有一个动作：杀青。鲜叶采下来之后，趁新鲜用高温迅速钝化多酚氧化酶的活性，让氧化反应还来不及发生就被叫停。于是叶子保住了绿色，滋味保住了鲜爽，这就是「清汤绿叶」的来源。"},{"type":"heading","level":3,"text":"杀青是目的，炒蒸烘晒是手段"},{"type":"paragraph","text":"有一组概念最容易混淆。杀青指的是用高温钝化酶这个目的，而实现它的手段可以是锅炒、蒸汽或热风。干燥又是另一回事：炒干的是炒青绿茶，烘干的是烘青绿茶，晒干的是晒青绿茶，后者多作紧压茶的原料。把「烘青」说成一种杀青方式是常见错误。西湖龙井是锅炒杀青的炒青代表，洞庭碧螺春也是炒青，恩施玉露则走蒸汽杀青一路，六安瓜片是烘青工艺里的特殊代表。"},{"type":"list","ordered":false,"items":["鲜叶摊放：散去部分水分与青草气，为杀青做准备","杀青：高温钝化酶活性，锁住绿色与鲜爽，这是决定性工序","揉捻：塑造条索外形，同时让部分内含物附着在叶表","干燥：按炒、烘、晒三种方式收尾，直接决定香气类型"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926806.jpg","alt":"玻璃杯中的绿茶与舒展的芽叶","caption":"玻璃杯能看清芽叶在水中舒展的过程，这是绿茶最直观的欣赏方式。"},{"type":"heading","level":3,"text":"风味从哪里来"},{"type":"paragraph","text":"绿茶的核心风味是茶氨酸带来的鲜甜与茶多酚带来的收敛之间的平衡。行业里常用酚氨比判断适制性：酚氨比低的品种适制绿茶，做出来更鲜爽；比值高的更适合做红茶。工艺上还有一条分岔——炒青多带豆香、栗香，烘青更清雅，蒸青则更接近青草与海苔的气息。"},{"type":"paragraph","text":"识茶时可以按四维去看。外形上，西湖龙井讲扁平光滑、糙米色，洞庭碧螺春讲卷曲成螺、满身披毫，太平猴魁讲两叶抱芽、扁平挺直；汤色以嫩绿、杏绿、明亮为好，暗淡与浑浊是减分项；香气常见豆香、栗香、清香、嫩香；滋味以鲜爽、回甘明显为佳，苦涩持久不化则是缺陷。叶底看嫩度、匀度与明亮度，嫩匀明亮为上。"},{"type":"heading","level":3,"text":"冲泡：把水温压住"},{"type":"steps","items":[{"title":"投茶","text":"三克对一百五十毫升，约一比五十；用玻璃杯随手泡时两到三克一杯，宜淡不宜浓。"},{"title":"水温","text":"名优嫩芽茶七十五至八十度，较粗老的绿茶八十五至九十度，忌沸水直冲。"},{"title":"出汤","text":"盖碗第一泡二十到三十秒出汤，之后每泡递增十到十五秒；玻璃杯喝到剩三分之一时续水。"},{"title":"器具","text":"玻璃杯可观形，白瓷盖碗不吸香，这两种最合适。"}]},{"type":"tip","tone":"info","title":"新茶别急着喝","text":"新炒制的绿茶常带火气与生青气，香气滋味尚未稳定，密封存放一到两周后再喝会更协调。绿茶极不耐存，应密封避光低温保存，当年内喝完为宜。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927407.jpg","alt":"炒锅中的绿茶杀青工序","caption":"杀青的温度与时间，直接决定这款绿茶是鲜爽还是发闷。"},{"type":"heading","level":3,"text":"两个必须澄清的问题"},{"type":"paragraph","text":"第一，安吉白茶不是白茶。它用的是白化变异的茶树品种，按绿茶工艺杀青制成，属于不发酵茶，因叶色偏白得名。第二，绿茶「性寒」是传统中医的表述方式，属于传统经验，不能与现代研究结论混写；能确认的是绿茶保留了较多未经氧化的儿茶素与维生素 C，是低热量的日常饮品。部分研究提示儿茶素与咖啡因的组合可能对能量代谢有轻微影响，但幅度小、个体差异大，不能替代饮食控制与运动。"},{"type":"list","ordered":false,"items":["咖啡因含量约百分之二到四，空腹浓饮容易引起胃部不适，睡前四到六小时不宜饮用","茶多酚会与食物中的非血红素铁络合，缺铁性贫血人群应避免餐中与餐后立即饮浓茶","不建议用茶水送服药物，服药与饮茶间隔一到两小时","孕期与哺乳期需按每日咖啡因不超过二百毫克控制，儿童不建议大量饮用浓茶"]},{"type":"tip","tone":"success","title":"夏天与冷泡","text":"绿茶按一比一百的茶水比冷水浸泡，冷藏约四小时即可，是六大茶类里时间最短的。低温下苦涩物质浸出较少，甜感与清香更突出，冷藏密封并在二十四小时内喝完。"},{"type":"heading","level":3,"text":"挑绿茶时看什么"},{"type":"paragraph","text":"还有一个常被问到的问题：绿茶该怎么挑。在无法试喝的情况下，可以看三件事。一看外形是否符合该款茶的标准形——龙井讲扁平光滑、糙米色而不是翠绿，碧螺春讲卷曲成螺、满身披毫，太平猴魁讲两叶抱芽、扁平挺直；二看色泽是否自然，过于艳丽或过于枯暗都要打问号；三看净度与匀整度，断碎多、花杂多，往往说明原料或筛分环节不够细致。至于「毫多就是好」，只对碧螺春这类以毫为特征的茶成立，龙井并不以毫多为标准外形。冲泡上还有一条容易被忽略的时序建议：同一款绿茶，第一泡可以略降温，第二三泡维持，到了第四泡如果还要继续，反而可以稍微升温、延长时间。原因是前几泡出来得快的是鲜甜物质，越往后越需要更高的温度去推动剩余的内含物。当然，名优绿茶三泡之后滋味就明显下降，这时换茶比硬泡更明智。"}]', '["tea_longjing","tea_biluochun"]', 9, 4173, 1, 120, 'published', '2026-09-12 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('4190753969685434510', 'article_white_tea', 'white-tea-explained', '白茶：萎凋与干燥的两种路径', '不炒不揉是白茶最大的特点，工序只有萎凋与干燥两步。成败全在萎凋的时长与温湿度控制上。', 'tea_basics', '["白茶","萎凋","微发酵"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125858610.jpg', '[]', '[{"type":"paragraph","text":"把六大茶类的工序排一排队，白茶是最短的那一条：不炒、不揉，只做萎凋与干燥两步。正因为工序少，它对原料和天气的依赖就被放大了——没有杀青来兜底，没有揉捻来调整，成败几乎全压在萎凋这一段上。"},{"type":"heading","level":3,"text":"萎凋：让叶子慢慢走完一小段氧化"},{"type":"paragraph","text":"萎凋是把鲜叶摊开，让水分缓慢散失。在这个过程中，叶片内部的内源酶仍在活动，茶多酚发生轻微氧化，氧化程度约在百分之五到十之间，这就是白茶被归为微发酵茶的原因。传统做法是日光萎凋加文火烘焙，现代则有室内自然萎凋、加温萎凋与复式萎凋几种路径。时长与温湿度的控制直接决定风味：萎凋不足会有青气，过度则香气沉闷、汤色发暗。"},{"type":"list","ordered":false,"items":["萎凋：摊放让水分缓慢散失，内源酶带来轻微氧化，是风味的塑造期","干燥：终止酶活动、锁定香气，传统用文火烘焙，也有以日光收尾的做法","按国标产品类别分为白毫银针、白牡丹、贡眉、寿眉四个类别","新工艺白茶在传统萎凋后增加轻揉捻，滋味更浓强、汤色更深，是二十世纪六十年代为适应外销市场创制的"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927408.jpg","alt":"竹筛上摊晾萎凋的白茶鲜叶","caption":"萎凋的摊放厚薄与时间，是白茶风味差异最主要的来源。"},{"type":"heading","level":3,"text":"四个类别，两条路线"},{"type":"paragraph","text":"白毫银针取单芽，毫香与鲜爽为主；白牡丹一芽一二叶，花香与蜜韵更明显；贡眉与寿眉原料相对成熟，汤感更醇，随年份增加会转向枣香、药香与陈香。产地来源以福鼎、政和、建阳为主，云南景谷也有用大叶种制作的月光白。品种上的差别同样明显：福鼎大白茶与福鼎大毫茶芽头肥壮、毫色银白，政和大白茶芽头细长、毫色偏灰白。"},{"type":"paragraph","text":"识茶时看四点。外形上银针要满披白毫、挺直如针，白牡丹要芽叶连枝、叶背披毫；汤色杏黄清亮，随年份加深；香气新茶以毫香为主，陈茶转向陈香与木香，研究提示这与贮存过程中的氧化与转化有关，但不同研究结论并不完全一致；滋味新茶清鲜醇爽，陈茶转醇和顺滑。叶底看嫩度与匀度，银针以肥壮匀整为好。"},{"type":"heading","level":3,"text":"冲泡：新茶温一点，陈茶狠一点"},{"type":"steps","items":[{"title":"投茶","text":"新茶三到五克对一百五十毫升，陈茶与寿眉五到七克对一百五十毫升。"},{"title":"水温","text":"白毫银针与白牡丹八十五到九十度，寿眉、贡眉与陈白茶九十五到一百度。"},{"title":"出汤","text":"第一泡十五到三十秒，寿眉与陈茶可闷三十到四十五秒，之后每泡递增十到二十秒。"},{"title":"煮饮","text":"寿眉与陈白茶泡到六七泡后可以转煮，投茶五克配水五百毫升，煮沸后转小火三到五分钟。"}]},{"type":"tip","tone":"info","title":"白茶也有咖啡因","text":"白茶的咖啡因含量与绿茶接近甚至更高，芽头部位尤其如此，「白茶不影响睡眠」是误解。晚间若要饮用，可以选冷泡、减量并提前喝。新白茶偏凉，陈白茶性转平和，这是传统经验表述，实际选择仍要看个人感受。"},{"type":"heading","level":3,"text":"越陈越好，只在一部分白茶上成立"},{"type":"paragraph","text":"适合长期存放需要三个条件同时具备：原料有一定成熟度，寿眉、贡眉、白牡丹比银针更适宜；工艺到位；贮存环境规范，避光、密封、干燥、无异味、相对湿度低。「老白茶」是市场通行说法，国家标准里没有这个独立类别，市场通常以三年以上作为分界。市场上还有通过高温高湿加速陈化的「做旧」做法，可能出现品质劣变，购买时要留意有没有霉味、酸馊味。"},{"type":"tip","tone":"warning","title":"安全底线","text":"白茶越陈越香的前提是规范贮存。贮存不当会霉变，产生有害霉菌与毒素，这类茶必须丢弃、不可饮用。看到丝状霉斑、闻到霉味或酸馊味，不要犹豫，也不要试图用煮或调味掩盖。"},{"type":"paragraph","text":"最后澄清一句：「一年茶、三年药、七年宝」是民间谚语，属于传统经验表述，不能理解为白茶具有药效。至于市场上常说的「年份越久越好」，目前缺乏高质量人体研究支持，可以准确表述为：陈化会显著改变白茶的香气与滋味，使其更醇和，成分上儿茶素下降、茶褐素与部分黄酮类上升，但这些成分变化与健康效应的关系还需要更多研究。"},{"type":"heading","level":3,"text":"年份该怎么看"},{"type":"paragraph","text":"市场上流行的三年、七年分期是通行说法，不是国家标准里的分类。更实用的做法是看三件事：原料成熟度、仓储记录与当下的表现。原料偏成熟的寿眉、贡眉更适合长期存放；有明确仓储记录、包装密封完好、开袋时是干净的陈香而不是闷味或霉味，才谈得上转化；当下的香气与滋味是否协调，比年份数字更能说明问题。"},{"type":"paragraph","text":"冲泡时也可以借年份调整思路。新白茶嫩度高、内含物活跃，适合用略低的水温、较短的出汤时间，把清鲜保全；陈白茶与寿眉结构紧实、转化更深，可以用接近沸水的水温，甚至泡到后半程转煮。同一款白茶用两种水温各泡一次，你会更清楚自己偏好哪一个方向，这比记住任何年份口诀都有用。"}]', '["tea_baihao_yinzhen","tea_baimudan"]', 9, 2768, 1, 130, 'published', '2026-09-13 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('2926340118532754792', 'article_yellow_tea', 'yellow-tea-explained', '黄茶：闷黄到底是怎么发生的', '杀青之后趁热堆闷，让叶子在湿热里多走一小步，这就是闷黄。黄汤黄叶与甜醇口感都由它带来。', 'tea_basics', '["黄茶","闷黄","轻发酵"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125859840.jpg', '[]', '[{"type":"paragraph","text":"六大茶类里产量最小、认知度最低的一类是黄茶。它常被误解成「放久了变黄的绿茶」，这个说法完全站不住脚。黄茶的黄来自一道主动的工序——闷黄：把杀青揉捻后还带着热气的茶叶趁热堆积、覆盖保温，让它在湿热环境里多走一小步。"},{"type":"heading","level":3,"text":"闷黄改变了什么"},{"type":"paragraph","text":"闷黄过程中发生的主要是非酶促氧化，也就是自动氧化，同时伴随美拉德反应。结果是叶绿素被破坏，茶多酚部分氧化，酯型儿茶素部分水解，简单儿茶素的比例上升。直接的风味后果是苦涩感明显下降、醇和度上升，汤色与叶底转向黄色。这正是黄茶区别于绿茶的那道分水岭：绿茶靠杀青把酶按住，从此不再变化；黄茶在按住酶之后，用湿热让叶子自己再走一步。"},{"type":"list","ordered":false,"items":["杀青：与绿茶一样，先用高温钝化酶活性","揉捻：成形并让内含物附着叶表，为闷黄做准备","闷黄：趁热堆积覆盖保温，在湿热下发生非酶促氧化与美拉德反应，这是黄茶的标志性工序","干燥：固定风味，收住水分"]},{"type":"paragraph","text":"闷黄的方式不止一种：有湿坯闷黄，也就是把杀青揉捻后的湿茶直接堆闷；有干坯闷黄，把茶用纸包或篓装起来闷；也有堆积闷黄。时间从数小时到数天不等。方式与时长不同，黄的程度就不同，这也是黄茶内部风格差异的重要来源。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164928532.jpg","alt":"黄茶干茶与黄亮茶汤","caption":"黄汤黄叶是闷黄工序的直接结果，与绿茶存放变黄有本质区别。"},{"type":"heading","level":3,"text":"按芽叶分三类"},{"type":"list","ordered":false,"items":["黄芽茶：单芽或一芽一叶初展，君山银针、蒙顶黄芽、霍山黄芽属此类，嫩度最高、最怕烫","黄小茶：一芽一二叶，沩山毛尖、平阳黄汤属此类，甜醇与清香并重","黄大茶：一芽二三叶甚至更成熟，霍山黄大茶、广东大叶青属此类，叶大梗长，耐泡且可略提高水温"]},{"type":"paragraph","text":"识茶时也有几个抓手。外形上黄芽茶讲芽头肥壮、满披毫毛、色泽金黄，霍山黄芽讲条索紧细、色泽嫩黄；汤色以浅黄、杏黄、明亮为佳，黄汤黄叶是它的典型特征；香气常见锅巴香、清甜香与嫩香；滋味以甜醇不涩、柔和顺滑为突出特点，比绿茶少了明显的收敛感。叶底看嫩度与匀度，黄亮匀整为好。君山银针还有一个可视性的趣味点：在玻璃杯中冲泡时，芽头会因吸水与气泡的浮力反复起落，被称为「三起三落」。"},{"type":"heading","level":3,"text":"冲泡与冷泡"},{"type":"steps","items":[{"title":"投茶","text":"黄芽茶三克对一百五十毫升，黄大茶可以四到五克对一百五十毫升。"},{"title":"水温","text":"黄芽茶八十到八十五度，黄大茶九十到九十五度，嫩度定温度。"},{"title":"出汤","text":"第一泡二十到三十秒，之后每泡递增十到十五秒，忌久闷。"},{"title":"器具","text":"透明玻璃杯最合适，既能看汤色也能看芽头起落；白瓷盖碗亦可。"}]},{"type":"tip","tone":"info","title":"冷泡黄茶","text":"按一比一百的茶水比冷水浸泡，冷藏约五小时，时间介于绿茶的四小时与白茶的六小时之间。风味是极度柔和的甜醇，几乎没有苦涩与收敛感，适合完全不能接受茶苦味的人。"},{"type":"heading","level":3,"text":"三个常见误解"},{"type":"list","ordered":false,"items":["「绿茶放久了变黄就是黄茶」：黄茶的黄来自主动的闷黄工艺，是有控制的加工结果；绿茶变黄是贮存氧化劣变，往往伴随陈味与香气丧失","「黄茶只是颜色不同的绿茶」：在六大茶类分类体系里，黄茶是与绿茶并列的独立茶类，分类依据正是独有的闷黄工序","「黄茶温和，所以可以随便喝」：闷黄确实降低了刺激性，但空腹大量饮用浓黄茶仍可能引起不适，胃部急性不适期仍需避免"]},{"type":"paragraph","text":"最后一句实用提醒：黄茶产量小、小众，市场上存在以绿茶冒充的情况。真正的黄茶应有明显闷黄形成的甜醇感与黄汤黄叶；如果一款「黄茶」只有陈味、没有那种柔和的甜，多半是绿茶存放不当变了色，不是闷黄做出来的。"},{"type":"heading","level":3,"text":"为什么黄茶这么少见"},{"type":"paragraph","text":"黄茶产量在六大茶类里排在最末，这有工艺与市场两方面的原因。从工艺上看，闷黄对温度、湿度与时间的控制要求很细，做得不到位就会出现水闷气，风险高于同产区的绿茶；从市场看，黄茶的风味处在绿茶与乌龙之间，既没有绿茶的普及度，也没有乌龙的辨识度，长时间处在被误解的位置上。再加上一些围绕黄茶的传统经验表述被过度宣传，反而让消费者对它的定位更加模糊。"},{"type":"paragraph","text":"但对普通喝茶的人来说，黄茶有一个非常实用的价值：它是怕苦人群最友好的选项之一。同样是嫩芽茶，绿茶的收敛感在闷黄之后被削去大半，甜醇突出、刺激性下降，冷泡之后几乎只剩甜味。如果你一直觉得绿茶「有点苦」，黄茶值得专门试一次——它可能是六大茶类里最容易被低估的那一个。"}]', '["tea_junshan_yinzhen","tea_huoshan_huangya"]', 9, 1291, 0, 140, 'published', '2026-09-14 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('8774626582851994733', 'article_oolong_tea', 'oolong-tea-explained', '乌龙茶：做青与焙火之间的风味光谱', '做青是乌龙茶的灵魂工序，摇青与晾青反复交替，既摇出花果香，也摇出一整条风味光谱。', 'tea_basics', '["乌龙茶","做青","半发酵"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125857347.jpg', '[]', '[{"type":"paragraph","text":"六大茶类里工艺最复杂、氧化程度跨度最大的一类是乌龙茶。它的氧化程度大约在百分之十五到七十之间，行业里通常再分为轻发酵、中发酵与重发酵三段。跨度大意味着同样是乌龙，清香型铁观音和足火武夷岩茶喝起来几乎像两个物种。把它们串起来的，是同一道灵魂工序——做青。"},{"type":"heading","level":3,"text":"做青：摇与晾的反复交替"},{"type":"paragraph","text":"做青由摇青与晾青交替进行。摇青时叶片互相摩擦碰撞，叶缘细胞破损，酶与底物接触，氧化就从叶缘开始；晾青则让叶片静置，散失水分、重新分布内含物。这样反复几轮下来，传统上会形成「绿叶红镶边」的外观，同时激发出大量芳香物质，乌龙茶香气物质的丰富程度在六大茶类中位居前列，橙花叔醇、茉莉内酯等成分是「高香」的物质基础。需要补一句精确提示：现代清香型乌龙因为氧化程度低、焙火轻，红边常常不明显甚至缺失，不能把绿叶红镶边当成所有乌龙的必备特征。"},{"type":"list","ordered":false,"items":["萎凋：散失部分水分，为做青创造条件","做青：摇青与晾青交替，叶缘破损引发氧化，同时激发芳香物质，这是决定性工序","杀青：用高温终止氧化，把做青达到的状态固定下来","揉捻：塑形，球形乌龙靠包揉形成紧结颗粒","干燥与焙火：按风格决定焙火轻重，轻者保清香，重者出焙火香与厚实骨架"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922602.jpg","alt":"武夷山丹霞地貌间的茶园","caption":"产地的小气候与土壤条件，是武夷岩茶风格差异的重要来源。"},{"type":"heading","level":3,"text":"四大产区，四种性格"},{"type":"list","ordered":false,"items":["闽北乌龙：以武夷岩茶为代表，大红袍、肉桂、水仙是主力，重焙火，讲岩韵与厚实骨架","闽南乌龙：以安溪铁观音为代表，还有黄金桂、永春佛手、漳平水仙，清香型走兰花香路线","广东乌龙：以凤凰单丛为代表，蜜兰香、鸭屎香（银花香）、黄枝香等香型各成一格","台湾乌龙：文山包种、冻顶乌龙、东方美人、高山乌龙，其中东方美人是乌龙里氧化程度最重的一类，常被误认为红茶"]},{"type":"paragraph","text":"识茶时按四维看。外形上，铁观音讲颗粒紧结、砂绿油润，武夷岩茶讲条索紧结、色泽乌润，凤凰单丛讲条索挺直肥壮；汤色从金黄到橙红，跨度与氧化程度对应，以明亮为好；香气是乌龙最值得下功夫的一维——清香型的兰花与奶香、岩茶的焙火与果香、单丛的花蜜香、东方美人的蜜香与熟果香，层次丰富是它的标志；滋味讲醇厚、回甘与耐泡，苦涩能否化开是关键。叶底看柔软度与匀整度，岩茶讲「绿叶红镶边」的残迹与弹性。"},{"type":"heading","level":3,"text":"冲泡：高投茶、快出汤"},{"type":"steps","items":[{"title":"投茶要舍得","text":"功夫泡常用七到八克对一百至一百二十毫升，球形乌龙可五到七克，投茶量显著高于绿茶。"},{"title":"水温要足","text":"九十五度到沸水。做青与焙火使叶组织紧实，香气物质需要高温激发，焙火型还可以沸水高冲。"},{"title":"出汤要快","text":"第一泡五到十五秒即出，球形乌龙第一泡稍等舒展，之后每泡递增五到十秒。"},{"title":"器具看风格","text":"白瓷盖碗最通用，不吸香；武夷岩茶与浓香铁观音可用紫砂壶；凤凰单丛推荐薄胎白瓷盖碗。"}]},{"type":"tip","tone":"warning","title":"关于咖啡因与韵","text":"乌龙茶的咖啡因含量在六大茶类里偏高，加上投茶量大、泡数多，单次摄入总量常高于一杯红茶，「晚上可以放心喝」是误解。另外，「岩韵」「音韵」属描述性经验概念，缺少可量化的统一定义，不宜作为品质的唯一判据。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164919676.jpg","alt":"功夫茶冲泡中的盖碗与品茗杯","caption":"乌龙耐泡度居六大茶类前列，七到十泡仍能保有风味。"},{"type":"heading","level":3,"text":"三个必须说清的问题"},{"type":"paragraph","text":"第一，铁观音不是绿茶。它属于乌龙茶，汤色偏绿只是现代清香型工艺降低了氧化度与焙火度的结果，分类要看工艺而不是汤色。第二，大红袍母树仅存六株于武夷山九龙窠，二〇〇六年起已停止采摘，市售大红袍是母树无性繁殖的纯种后代或商品拼配茶，这是正常且合规的，任何宣称「母树大红袍」的销售都不可信。第三，氧化程度高低不决定品质优劣，它决定的是风味方向与刺激性高低；品质取决于原料、工艺与环境。"},{"type":"tip","tone":"success","title":"冷泡表现最好的一类","text":"乌龙按一比一百冷水浸泡，冷藏约八小时。热泡时的高香在冷泡中转为清冽的花果香，甜感突出、几乎无涩，被公认为冷泡效果最好的茶类之一。清香型铁观音、冻顶乌龙与凤凰单丛最适合冷泡。"},{"type":"heading","level":3,"text":"同一个名字下的两种茶"},{"type":"paragraph","text":"乌龙茶最容易被误解的一层是：同名之下往往是两种风格。以铁观音为例，清香型走低氧化、低焙火路线，汤色偏绿、兰花香突出；浓香型则经过焙火，汤色转金黄，香气往熟果与火功的方向走。武夷岩茶也类似，轻火与足火之间的差别，足以让同一款茶喝起来像两个不同的东西。所以买乌龙时，除了问产地与品种，还要问清氧化程度与焙火程度，这两个参数对风味的影响比产地标签更直接。"},{"type":"paragraph","text":"冲泡参数也要跟着风格走。清香型乌龙可以略微降低水温、缩短时间，把细腻的花香保住；焙火型与重发酵型则需要沸水高冲，让焙火香与厚实的滋味出来。这也解释了为什么同一套「乌龙茶怎么泡」的建议，套在不同风格的乌龙上效果会差很多——参数永远服务于风格，而不是反过来。"}]', '["tea_tieguanyin","tea_dahongpao"]', 10, 3846, 1, 150, 'published', '2026-09-15 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('138665992389302422', 'article_black_tea', 'black-tea-explained', '红茶：从正山小种到工夫红茶', '红茶的核心工序是发酵，实为酶促氧化。儿茶素大量转化为茶黄素与茶红素，成就红汤红叶。', 'tea_basics', '["红茶","发酵","全发酵"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125853707.jpg', '[]', '[{"type":"paragraph","text":"在中国六大茶类里，红茶的氧化程度排在前列，约百分之七十到九十。它的核心工序叫「发酵」，但这个说法容易引起误会：这里的发酵其实是酶促氧化，由多酚氧化酶催化儿茶素氧化聚合，而不是像做酱、酿酒那样靠微生物。理解这一点，红茶的一切风味特征就都有了着落。"},{"type":"heading","level":3,"text":"发酵时发生了什么"},{"type":"paragraph","text":"揉捻把叶细胞揉破之后，多酚氧化酶与儿茶素接触，氧化链式反应开始。儿茶素大部分被氧化聚合为茶黄素与茶红素，并进一步形成茶褐素。茶黄素是红茶发酵的特征产物，含量与红茶等级和品质密切相关；茶红素含量最高，贡献汤色红浓与醇厚口感；茶褐素是深度氧化聚合的产物，含量随发酵程度上升。加工中需要控制温度、湿度与时间，一般温度在二十二到二十八度之间，让茶多酚适度氧化到「红叶红汤」的程度——不足则青气重，过度则汤色暗沉、滋味发闷。"},{"type":"list","ordered":false,"items":["萎凋：散失水分、叶片变软，为揉捻做准备","揉捻：破坏叶细胞结构，让酶与底物接触","发酵：酶促氧化，儿茶素转化为茶黄素与茶红素，这是决定性工序","干燥：高温终止酶活动，固定品质并发展甜香"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164925057.jpg","alt":"红茶加工车间中的发酵工序","caption":"温湿度与时间是发酵的三个变量，过度与不足都会在汤色上留下痕迹。"},{"type":"heading","level":3,"text":"三大类型，各有来路"},{"type":"list","ordered":false,"items":["小种红茶：正山小种产自福建武夷山桐木关一带，传统上用松烟熏焙，带独特松烟香与桂圆汤感；烟小种是同类中的烟熏风格","工夫红茶：祁门红茶、滇红工夫、川红工夫、宜红工夫、闽红工夫等，条索细紧、工艺精细，祁门红茶以蔷薇花香、果香与蜜香交织的「祁门香」著称","红碎茶：国际主流的碎茶类型，多用于袋泡与调饮，出味快、一次出汤即可"]},{"type":"paragraph","text":"识茶时看四点。外形上，工夫红茶讲条索紧结、色泽乌润，滇红以金毫显露著称；汤色讲红艳明亮，注意「红艳明亮」与「暗红浑浊」是两回事，前者是品质表现，后者往往是发酵过度或高火造成的；香气上，祁门红茶走花香蜜香路线，正山小种带松烟香，滇红偏甜香与麦芽香；滋味讲甜香醇厚、浓强鲜爽，红碎茶则以浓强为特点。叶底看红匀明亮、柔软匀整，红梗红叶与焦斑是减分项。"},{"type":"heading","level":3,"text":"冲泡：别闷，也别用沸水冲嫩芽"},{"type":"steps","items":[{"title":"投茶","text":"五克对一百五十毫升，约一比三十；红碎茶三克对一百五十毫升即可。"},{"title":"水温","text":"大叶种滇红与红碎茶九十五到一百度，金骏眉这类芽头细嫩的红茶用八十五到九十度，沸水会把嫩芽冲出酸感。"},{"title":"出汤","text":"工夫红茶第一泡五到十秒即出，之后每泡递增五到十秒；红碎茶一次出汤。红茶不宜久闷，长时间高温浸泡会大量释放单宁，变得苦涩发涩。"},{"title":"器具","text":"白瓷盖碗最能体现祁门香，滇红可以用紫砂壶，调饮则用玻璃壶更方便。"}]},{"type":"tip","tone":"info","title":"英文名的一次澄清","text":"英文里的 Black Tea 指的是中国红茶，因为干茶色泽乌黑而得名；而英文的 Dark Tea 才对应中国黑茶。这是翻译上最容易出错的一处。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920305.jpg","alt":"红艳明亮的红茶茶汤","caption":"汤色红艳明亮与暗沉浑浊是两回事，前者是品质表现，后者通常是工艺或存放出了问题。"},{"type":"heading","level":3,"text":"关于调饮与健康代价"},{"type":"paragraph","text":"红茶是六大茶类里最适合调饮的一种，与牛奶、香料的兼容性好，英式下午茶与印度的香料奶茶都建立在它之上。但需要清楚的是，市售奶茶类饮品常含大量添加糖与植脂末，可能含反式脂肪酸，这类饮品的健康风险主要来自糖与脂肪，而不是茶本身。自己动手做的话，用鲜奶替代奶精、把糖量降到最低，一杯就能比门店版本清爽很多。另外，加奶并不能消除茶多酚对非血红素铁吸收的影响，贫血人群同样要避开餐中浓饮。"},{"type":"list","ordered":false,"items":["咖啡因约百分之二到四，与茶黄素等形成络合物，吸收相对平缓，但晚间浓饮同样影响入睡","不用茶水送服药物，服药与饮茶间隔一到两小时","不建议用红茶加大量柠檬汁配奶，酸性环境会使乳蛋白絮凝，口感与外观都变差","借浓茶应对饮酒后的不适是错误认知，酒精与咖啡因会加重心脏负担，不建议这样做"]},{"type":"tip","tone":"warning","title":"两个方向都要留意","text":"传统上有「冬饮红」的说法，也常听到「红茶温和」的评价，这些属于传统经验表述。要提醒的是：红茶仍会促进胃酸分泌，浓饮、空腹饮反而容易引起不适；热饮温度超过六十五度被列为 2A 类「可能对人类致癌」，关键在温度而不在茶，放至五十到六十度适口温度再喝。"},{"type":"tip","tone":"success","title":"冷泡红茶","text":"按一比一百冷水浸泡，冷藏八到十小时，睡前放进冰箱、次晨取出刚刚好。甜香突出、涩感极低、汤色红亮清透，几乎没有热泡久置后的闷味，很适合作为无糖日常饮品的基底。"},{"type":"paragraph","text":"最后补一句关于选购的实用建议。在不试喝的情况下可以看三点：条索是否紧结匀整、色泽是否乌润自然、有无明显的碎末与花杂；香气上，优质红茶应是纯正的花香、蜜香或甜香，出现烟焦气、酸馊味或陈气都是缺陷；汤色要红艳明亮，暗沉浑浊需要打问号。至于「越红越浓越好」，并不成立——汤色深浅与品质高低没有必然关系，过度发酵或高火反而会带来暗沉的汤色与熟闷味。判断一款红茶，仍然要把香气、滋味与叶底放在一起看。"}]', '["tea_zhengshan_xiaozhong","tea_keemun"]', 10, 3352, 1, 160, 'published', '2026-09-16 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('4477998870473173778', 'article_dark_tea', 'dark-tea-explained', '黑茶：后发酵与仓储的边界', '渥堆是黑茶的独有工序，由微生物与湿热共同推动。做成之后它仍在变化，仓储决定往哪走。', 'tea_basics', '["黑茶","渥堆","后发酵"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125854892.jpg', '[]', '[{"type":"paragraph","text":"六大茶类里，黑茶是唯一一个把微生物请进来参与加工的类别。它的关键工序叫渥堆：毛茶趁湿堆积，在微生物与湿热的共同作用下发生深度转化。这一步让黑茶与红茶的「全发酵」彻底区分开来——红茶靠的是茶叶自身的酶，黑茶靠的是黑曲霉、酵母、冠突散囊菌等微生物的接力改造。"},{"type":"heading","level":3,"text":"渥堆之后，转化还没停"},{"type":"paragraph","text":"黑茶的茶多酚氧化程度约在百分之八十到九十五之间，而且渥堆结束并不意味着变化终止——它会随贮存继续陈化。渥堆过程中，酯型儿茶素水解释放出没食子酸，含量显著上升；茶褐素成为汤色红浓的主要色素；茶多糖含量相对较高。成品之后的变化方向，则取决于仓储条件：干燥、通风、避光、无异味的环境下，香气转向陈香、滋味转向醇和；潮湿闷热的环境下，同样的时间只会带来劣变。同样一句「越陈越香」，只有在适宜仓储的前提下才成立。"},{"type":"list","ordered":false,"items":["杀青与揉捻：与多数茶类类似，先固定基础品质","渥堆：毛茶趁湿堆积，微生物与湿热共同作用，这是黑茶的决定性工序","干燥：收住水分，稳定品质","蒸压成型与陈化：部分产品会压成砖、饼、沱或千两茶形态，再进入陈化阶段"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164920308.jpg","alt":"撬开的紧压黑茶与茶刀","caption":"紧压形态便于运输与陈放，撬散之后块形保持完整更耐泡。"},{"type":"heading","level":3,"text":"产品版图与一个分类难点"},{"type":"list","ordered":false,"items":["湖南黑茶：安化黑茶，包括千两茶、百两茶、天尖、贡尖、茯砖、黑砖、花砖","湖北青砖茶：以羊楼洞一带为传统主产地","四川边茶：康砖、金尖、藏茶，是川藏道方向的边销主力","云南普洱茶（熟茶）：渥堆后发酵工艺，属黑茶类","广西六堡茶：有独特的槟榔香；陕西泾渭茯茶也属此类"]},{"type":"paragraph","text":"这里有一个行业公认的分类难点需要说清：普洱熟茶属于黑茶；而普洱生茶是晒青毛茶直接蒸压，在严格的工艺分类上属于晒青绿茶，但它在长期贮存中会自然后发酵，风味向黑茶方向转化，市场与消费习惯中常与黑茶并论。另外要澄清一个常见误会：生普放久了不会「变成」熟普。熟普是人工渥堆快速发酵的产物，生普走的是自然陈化的路，二者工艺路径不同，生普无论存多久都只会形成「陈年生普」的风味。"},{"type":"heading","level":3,"text":"冲泡与煮饮"},{"type":"steps","items":[{"title":"先醒茶","text":"紧压茶拆散后置于紫砂罐或牛皮纸袋中醒一到两周，风味会有明显提升，也便于检查有无受潮。"},{"title":"润洗","text":"沸水注满即出的方式润洗一到两遍，唤醒茶性、去浮尘。"},{"title":"高投茶快出汤","text":"七到八克对一百至一百二十毫升，第一泡五到十秒出汤，之后每泡递增五到十秒，可泡十泡以上。"},{"title":"煮饮","text":"三年以上的熟普、陈年茯砖或六堡茶，五到八克配水五百到八百毫升，冷水入壶煮沸后转小火三到五分钟，可反复煮两到三次。"}]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164921462.jpg","alt":"煮茶壶中翻滚的黑茶茶汤","caption":"老黑茶适合煮饮，但砖茶不宜长时间反复熬煮后大量饮用。"},{"type":"tip","tone":"warning","title":"霉变与霉菌不是一回事","text":"渥堆是受控的微生物固态发酵，与霉变有本质区别。茯砖茶上的「金花」是冠突散囊菌的闭囊壳，呈颗粒状金黄色并带菌花香，与产毒霉菌的黄绿色丝状菌丝并带霉味不同。但外观鉴别并不可靠——出现霉斑、霉味、酸馊味就整批弃用，不能用调味掩盖后继续饮用。"},{"type":"heading","level":3,"text":"三条要写清楚的话"},{"type":"paragraph","text":"第一，黑茶的咖啡因含量并不低，与红茶相当，「黑茶不影响睡眠」缺乏依据。第二，部分研究提示黑茶提取物对血脂与体重有影响，但以动物实验与体外实验为主，高质量人体研究有限，不能表述为具有体重管理方面的功效。第三，砖茶类原料成熟度高，氟含量相对较高，国家标准对砖茶含氟量有限量要求；长期大量饮用浓煎砖茶与饮茶型氟中毒相关，不建议全天以浓砖茶代水，儿童与孕期人群尤其需要注意。"},{"type":"tip","tone":"info","title":"冷泡熟普值得一试","text":"黑茶按一比一百冷水浸泡，冷藏约十二小时，是六大茶类里时间最长的。陈香与木香转清透，醇厚度降低但甜感与水感提升，几乎没有苦涩。热泡熟普里那股让人犹豫的堆味，在冷泡中被大幅削弱，是年轻群体接受度提升最快的黑茶喝法。"},{"type":"heading","level":3,"text":"仓储决定它往哪走"},{"type":"paragraph","text":"黑茶是少数需要消费者自己参与「完成」的茶类，仓储条件直接决定它最后的样子。基本要求有四条：干燥、通风、避光、无异味。密封是为了防异味与防潮，但不是抽真空——后发酵需要微量空气，缺氧反而会把转化按住不动。湿度上，过干转化慢，过湿则霉变风险陡增；不同仓储流派在温湿度上的做法并不一致，这里只给原则，不给定论。"},{"type":"paragraph","text":"对普通家庭来说，比方法更重要的是检查频率。每隔一两个月开箱看一眼，确认没有结块、没有异味、包装没有受潮迹象，就足够了。频繁开箱翻动反而会带来温湿度波动与交叉串味的风险。安静地放着，比经常关心它更有用。"}]', '["tea_ripe_puer","tea_liubao"]', 10, 1774, 1, 170, 'published', '2026-09-17 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('8769847664820286722', 'article_zisha', 'zisha-teapot-tradeoffs', '紫砂壶的取舍：什么时候该用它', '紫砂壶保温性好、能柔化口感，但吸香、也不便观察汤色与叶底。用对场景，它才算物有所值。', 'teaware', '["紫砂","茶器","取舍"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927201543037.jpg', '[]', '[{"type":"paragraph","text":"紫砂壶大概是被神化得最厉害的一件茶器。它确实有独到之处，但也确实有几项明确的短板。判断要不要用它，不需要背产地与壶型，只需要回答一个问题：这款茶需要的，是保温聚香，还是清晰通透。"},{"type":"heading","level":3,"text":"它的长处与代价是同一件事"},{"type":"paragraph","text":"紫砂属于陶质，气孔率较高，行业里通行「双气孔结构」的说法。气孔里的空气是热的不良导体，所以紫砂的保温性优于薄胎瓷与玻璃。同样的道理，气孔也让器壁能截留香气分子——吸附性既能让壶体「养」出茶味，也会把香气吃掉。聚香与夺香，是同一性质的两种结果。再加上陶体不透明，看不到汤色也看不到叶底，于是取舍就清楚了：适合滋味厚重、需要保温、不依赖观色的茶；不适合细嫩、依赖清香与观形的茶。"},{"type":"list","ordered":false,"items":["适合：焙火乌龙、武夷岩茶、老白茶、黑茶（熟普），保温聚香能把厚实的骨架撑起来","不适合：细嫩绿茶，容易闷熟并且吸走清香；高香型的清香乌龙也会被削去一部分锐气","可替代：同一场景中，白瓷盖碗的通用性更强，只是保温略逊","配套：紫砂壶出汤口普遍偏小，建议配一只公道杯接汤，避免久坐壶中"]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922600.jpg","alt":"紫砂壶与茶巾、茶针等配套器具","caption":"紫砂壶出汤后要立刻倒空并用热水冲淋壶身，这是日常养护的基本动作。"},{"type":"heading","level":3,"text":"一壶一茶是怎么回事"},{"type":"paragraph","text":"因为壶体会吸附香气，长期用同一把壶泡不同茶类，气味会互相串。所以行业里普遍建议一壶一茶，甚至一壶一类。这是经验建议而非标准强制要求，但如果你的壶已经开始「串味」，那多半是混泡造成的，且不可逆。老壶客常说的「养壶」，本质上是持续用同类茶让壶体吸附并稳定同一种气味，同时靠日常擦拭形成光泽，它并不意味着壶能改善茶汤的成分。"},{"type":"heading","level":3,"text":"历史与价格的两句实话"},{"type":"paragraph","text":"紫砂与散茶瀹饮是同步兴起的。相传明代正德年间供春始制紫砂壶，万历年间时大彬等名家推动成型工艺成熟，这属于通行说法。散茶冲泡需要保温、聚香、可控出汤的壶具，器具与工艺互为因果。但价格与品质并没有必然关系：影响茶汤的第一变量始终是水温、茶水比与出汤时间，把预算优先给控温电水壶与电子秤，收益远大于买一把贵壶；更重要的是，贵的壶摔一下代价也高。"},{"type":"steps","items":[{"title":"先确定常喝的茶类","text":"先明确自己一年里喝得最多的是岩茶、熟普还是绿茶，再决定买不买壶，能避免闲置。"},{"title":"到手先试壶","text":"注满沸水静置五分钟，检查有无渗漏、异味析出，同时试一次出汤是否顺手。"},{"title":"开壶不必复杂","text":"清水洗净、沸水冲淋即可，市面上流传的复杂开壶仪式没有标准依据。"},{"title":"日常养护","text":"用后即倒空，热水冲淋壶身内外，自然晾干。不用洗洁精浸泡，不用钢丝球，因为它会吸味。"}]},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164921464.jpg","alt":"盖碗与紫砂壶同席对比","caption":"器无优劣只有适配：同一款茶，用盖碗与用紫砂壶会得到两种风格。"},{"type":"tip","tone":"warning","title":"两个常见误区","text":"第一，紫砂壶不是「最好的茶具」，泡什么茶都行——泡细嫩绿茶容易闷熟并吸走清香，看不清汤色叶底也会影响判断。第二，「越贵越好喝」不成立，决定茶汤的是参数而不是价格，也要注意选出汤口顺畅、握持舒适的器形，而不是只看名头。"},{"type":"heading","level":3,"text":"怎么判断要不要买第一把"},{"type":"paragraph","text":"如果你已经有一段时间稳定在喝岩茶、浓香铁观音或熟普，而且发现自己反复因为盖碗散热快而泡不出想要的那种厚实感，那么紫砂壶会是一个明确的升级。反过来，如果你还在换着喝六大茶类、还在摸索口味，那一只白瓷盖碗更划算：它能让你看清每一款茶的本来样子，而不是替你加一层风格滤镜。"},{"type":"tip","tone":"success","title":"先降一档试手","text":"第一次买壶，可以在手感合适的价位里挑一把出汤口够大、壶盖严实、注水不溢的日用壶，用熟普或岩茶养一段时间。手感和出汤速度比壶型名目重要得多。"},{"type":"heading","level":3,"text":"用壶的三个具体动作"},{"type":"paragraph","text":"拿到一把壶，有三个动作决定你会不会用得顺手。第一是温壶：注满沸水静置一分钟再倒掉，既清洁又预热，之后投茶不会被冷壶壁拖住温度。第二是控制出汤：紫砂壶的出水口普遍偏小，投茶量要比盖碗略减，或者加快出汤速度，否则茶叶容易在壶里继续萃取。第三是及时倒空：出完汤立刻把壶内清空，不让余汤留在壶里，这是日常使用里最要紧的一条。"},{"type":"paragraph","text":"养护也不必仪式化。日常擦拭、用后冲淋、自然晾干，长期下来壶身自然会形成温润的光泽。市面上流传的复杂开壶仪式、用茶汤反复浇淋到壶身发亮之类的做法，没有标准依据，也不必当成必须完成的步骤。壶是工具，顺手的工具才是好工具。"}]', '["tea_dahongpao","tea_ripe_puer","tea_baimudan"]', 8, 2905, 0, 180, 'published', '2026-09-18 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('224202091014453445', 'article_cold_brew', 'cold-brew-tea-guide', '冷泡茶入门：时间、比例与安全', '一比一百、冷藏若干小时。冷泡靠时间替代温度，苦涩少、甜感强，但有两条不能省的规矩。', 'brewing', '["冷泡","夏天","冲泡"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125849979.jpg', '[]', '[{"type":"paragraph","text":"冷泡是另一条路。它不用水温去逼出内含物，而是用时间慢慢换。低温下苦涩物质的浸出明显少于高温，甜感与清香反而更突出，因此冷泡几乎不会「泡坏」——代价是需要提前准备，而且香气释放不如热泡充分。"},{"type":"heading","level":3,"text":"一条通用公式"},{"type":"list","ordered":false,"items":["茶水比：一比一百是基准，想浓一点调到一比八十，想更清淡调到一比一百二十","水温：常温水或冷藏的纯净水，不用热水","时长：绿茶约四小时，黄茶约五小时，白茶约六小时，乌龙约八小时，红茶八到十小时，黑茶约十二小时","容器：干净、可密封的玻璃瓶或水壶，先温洗一遍更放心"]},{"type":"paragraph","text":"时长为什么差这么多？规律是氧化程度越低，浸泡时间越短。绿茶未经氧化，苦涩物质最容易浸出，四小时足够；黄茶多走了闷黄一步，约五小时；白茶六小时；乌龙氧化程度跨度大，约八小时；红茶八到十小时，红碎茶可以缩到六小时；黑茶深度发酵又是紧压形态，物质浸出最慢，需要约十二小时。同样地，焙火重的岩茶冷泡容易显出燥感，清香型铁观音、冻顶乌龙和凤凰单丛才是冷泡乌龙里表现最好的。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922011.jpg","alt":"玻璃瓶中冷泡的茶汤","caption":"冷泡用时间替代温度，茶叶在瓶中的舒展过程本身也很好看。"},{"type":"heading","level":3,"text":"六步操作"},{"type":"steps","items":[{"title":"润洗","text":"用少量常温水快速润洗五秒后倒掉，去掉浮尘，这一步对紧压茶尤其有用。"},{"title":"投茶注水","text":"按一比一百的比例把茶叶放入干净水瓶，注入凉白开或纯净水。"},{"title":"密封冷藏","text":"盖上密封盖，放进冰箱冷藏，按茶类记录时间。"},{"title":"滤出","text":"到时把茶叶滤出，或直接带茶冷藏。建议八小时内喝完，滤出后口感更稳定。"},{"title":"保存","text":"冷藏密封，二十四小时内饮用完毕，不建议常温放置过夜。"},{"title":"调味","text":"可以加冰块与柠檬片、青提、雪梨等水果，控糖的话优先用水果本身带甜味。"}]},{"type":"paragraph","text":"风味上的收获值得一试。冷泡绿茶的苦涩感显著降低，鲜甜与清香更突出，汤色更清亮；冷泡白牡丹的花香与蜜韵更清透，寿眉的甜水感是白茶里年轻人接受度最高的喝法；冷泡乌龙的花果香转为清冽，几乎没有涩；冷泡红茶甜香突出，没有热泡久置后的闷味；冷泡熟普则把热泡时那股让人犹豫的堆味大幅削弱。另一个附带好处是：低温下咖啡因浸出较少，对睡眠的影响相对小一些，但它仍然含咖啡因。"},{"type":"tip","tone":"success","title":"两个好用的进阶做法","text":"其一，把冷泡茶冻成茶冰，加到杯中化开后不会稀释风味。其二，想做柠檬茶类饮品时，冷泡比例调到一比六十，茶汤浓一些才经得住柠檬与冰的稀释，捣柠檬时不要压碎白瓤，否则会发苦。"},{"type":"tip","tone":"warning","title":"两条不能省的规矩","text":"第一，冷泡茶必须冷藏，并在二十四小时内喝完。常温放置的冷泡茶是微生物容易繁殖的环境，不是「泡着泡着就好了」。第二，不要在冷水里泡一整天再想起来喝，时间过长不仅风味变差，风险也会上升。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922013.jpg","alt":"加冰与水果的冷泡茶饮","caption":"水果与冰块是冷泡茶最好的搭档，甜度可以来自水果本身。"},{"type":"heading","level":3,"text":"搭配与注意"},{"type":"list","ordered":false,"items":["适合冷泡：绿茶、黄茶、新白茶、寿眉、清香型乌龙、红茶、熟普与六堡茶","不建议冷泡：焙火重的岩茶冷泡容易显燥；新白毫银针嫩度高，久浸会失去层次","不建议加牛奶：乳蛋白与儿茶素结合会掩盖茶的鲜爽，这属于初步研究提示，风味上也不划算","含咖啡因：冷泡仍然含咖啡因，睡前不宜大量饮用；孕期与哺乳期需控制总量","服药期间：不用茶水送服药物，饮茶与服药间隔一到两小时"]},{"type":"paragraph","text":"如果只能记一句话：一比一百、按时取、冷藏喝完。冷泡的门槛低到几乎没有失败的可能，唯一需要的就是前一天晚上花两分钟把它放进冰箱。"},{"type":"heading","level":3,"text":"用冷泡处理那些不容易泡好的茶"},{"type":"paragraph","text":"冷泡还有一个被低估的用处：救那些热泡容易出问题的茶。碎茶与断茶热泡时出味极快，稍有迟疑就苦涩，冷泡的低浸出速率恰好把这层风险抹平；放过一段时间的绿茶热泡会显出陈味与闷味，冷泡能让它重新变得可用；熟普新茶的堆味、部分焙火茶的燥感，在冷泡里也会明显减弱。这不是让茶变好，而是换一种萃取方式，把它的短板压下去。"},{"type":"paragraph","text":"反过来，也有不适合冷泡的情况。嫩度极高、以香气层次取胜的茶，比如新的白毫银针，冷泡会让香气显得单薄，不如热泡来得立体；焙火很重的岩茶冷泡容易显出燥感。判断标准很简单：如果这款茶的价值在「香」与「层次」，热泡更能发挥；如果它的价值在「甜」与「顺」，冷泡通常更讨喜。"}]', '["tea_longjing","tea_baimudan","tea_tieguanyin","tea_zhengshan_xiaozhong","tea_ripe_puer"]', 8, 4618, 1, 190, 'published', '2026-09-19 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO article (id, business_key, slug, title, summary, category, tags, cover_url, gallery_urls, content_blocks, related_tea_keys, read_minutes, view_count_display, featured, sort, status, published_at, created_at, updated_at) VALUES ('4258387709505398557', 'article_tea_rhythm', 'tea-session-rhythm', '茶席上的节奏：从投茶到出汤', '泡茶真正难的不是参数表，而是节奏：投茶、注水、等待、出汤，每一步都在为下一步留余地。', 'sensory', '["茶席","冲泡节奏","品鉴"]', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125846301.jpg', '[]', '[{"type":"paragraph","text":"参数表好背，节奏难练。同一套数据，有人泡得干净利落、一泡比一泡好喝，有人泡到第三泡就走味。差别不在手法多花哨，而在于有没有把整场茶当成一条连贯的线来看：这一泡的浓淡，要为下一泡留出空间。"},{"type":"heading","level":3,"text":"先算清楚，再动手"},{"type":"list","ordered":false,"items":["人数与杯数：一个人三到五克，两三人五到八克，先按人数定总量再分泡","器具体积：一百至一百三十毫升的盖碗配三到八克茶，是大多数场景的安全区间","茶的紧结度：球形乌龙与紧压茶需要更长时间舒展，条索松散的茶出味更快","今天的口感目标：想喝清淡的就把投茶量往下压，而不是靠缩短到极限的出汤时间来救"]},{"type":"heading","level":3,"text":"第一泡决定整场的基调"},{"type":"paragraph","text":"第一泡的浓度，几乎决定了后面五泡的走向。泡太浓，后面只能一路缩短时间，节奏越走越急；泡太淡，后面要不断加时，容易把苦涩泡出来。比较稳妥的做法是让第一泡偏淡一点，留出往上加的空间。以绿茶为例，第一泡二十到三十秒出汤已经足够；乌龙则相反，五到十五秒快速出汤，因为投茶量大、水温高，浓度不需要靠时间堆。"},{"type":"image","src":"https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923892.jpg","alt":"茶席上的盖碗与品茗杯","caption":"出汤要一次流尽，不要让碗底那点茶汤继续闷着茶叶。"},{"type":"heading","level":3,"text":"出汤这一下，最见功夫"},{"type":"steps","items":[{"title":"抬高一点看流速","text":"出汤口与公道杯保持一点距离，观察水流是否连续，水流断续往往意味着茶叶堵住了缝隙。"},{"title":"一次流尽","text":"手腕发力快速倾倒到底，不要缓慢仰碗。慢慢仰等于给茶叶额外加时，最后几滴最浓。"},{"title":"立刻归位","text":"出完汤马上把盖子斜搁回去或让茶叶与水分分离，别让余温继续萃取。"},{"title":"分汤要匀","text":"用公道杯把茶汤混匀再分到杯中，否则第一杯与最后一杯浓度差会很明显。"}]},{"type":"paragraph","text":"关于出汤时间怎么加，有一条经验规则：越往后，递增幅度越小。第一泡五秒、第二泡十秒、第三泡十五秒是常见的起点，但到了第五六泡之后，往往需要递增到二十秒甚至三十秒才能维持同等浓度。乌龙和黑茶耐泡度高，可以撑到七到十泡甚至更多；绿茶三泡之后滋味就明显下降，这时与其硬泡，不如换茶。"},{"type":"heading","level":3,"text":"在茶席上边喝边判断"},{"type":"list","ordered":false,"items":["香气：热嗅闻香型，温嗅闻浓度，冷嗅闻持久性，三次嗅闻给出的信息不一样","滋味：入口先判浓淡，中段判顺滑与回甘，尾段判余韵长短与是否口干","汤色：每一泡都看一眼，汤色突然变暗或变浑，往往是出汤时间或水温出了问题","叶底：泡到最后一泡再翻看，嫩度、匀度与色泽能补上前面几泡看不出的信息"]},{"type":"tip","tone":"success","title":"只改一个变量","text":"觉得这一泡不理想时，下一泡只改一件事——要么缩短时间，要么降低水温，要么减一点投茶量。同时改两个，你永远不知道是哪一个起了作用。"},{"type":"paragraph","text":"需要提醒的是，茶席上的节奏与专业审评比的是两件事。审评用沸水、长时间、固定比例，目的是放大缺点、评定等级；日常冲泡是扬长避短，参数可以按喜好调整。所以听到「岩韵」「音韵」这类描述性概念时不必紧张，它们缺少可量化的统一定义，判断品质仍然要回到外形、汤色、香气、滋味、叶底这五个具体维度上。"},{"type":"tip","tone":"info","title":"给整场茶留一个收尾","text":"最后一泡可以刻意泡淡一些，或者换一款清爽的茶做过渡，让味觉有一个下降的坡度。结束时把器具洗净晾干，比留在壶里过夜要好得多——茶器养护从来不是靠泡着养出来的。"},{"type":"heading","level":3,"text":"一个人喝与几个人喝，节奏不一样"},{"type":"paragraph","text":"一个人喝茶，节奏可以完全跟着自己走：投茶量小一点，注水少一点，泡数少一点，喝到第三四泡就换茶，不必追求耐泡。器具也可以简化成一只盖碗加一只杯子，省去公道杯这一步，只要每次出汤都一次倒尽，浓度就不会失控。一个人喝的效率目标是「随时有一杯温度合适的茶」，而不是「完整地走完一套流程」。"},{"type":"paragraph","text":"几个人喝茶则是另一套逻辑。人数一多，出汤必须用公道杯混匀再分，否则第一杯与最后一杯的浓度差会很明显；每泡之间的等待变长，壶与碗里的茶叶容易继续萃取，所以出汤后要立刻让茶叶与水分分开；节奏上则要照顾在场的人——有人喝得快有人喝得慢，与其催，不如把每一泡的浓度控制得稳定一些，让每个人在自己那一口里都能得到差不多的东西。茶席上的节奏，最终是为在场的人服务的。如果中途要换茶，最好把器具冲洗一遍再投新茶，前一款茶的余味留在碗里，会直接影响你对下一款茶的判断。"}]', '["tea_longjing","tea_tieguanyin","tea_dahongpao","tea_keemun","tea_ripe_puer"]', 9, 2216, 0, 200, 'published', '2026-09-20 02:00:00.000000', '2026-09-20 02:00:00.000000', '2026-09-27 02:00:00.000000');
INSERT IGNORE INTO product_category (id, business_key, name, slug, sort) VALUES ('394928649089662440', 'tea', '茶叶', 'tea', 0);
INSERT IGNORE INTO product_category (id, business_key, name, slug, sort) VALUES ('1983613478798993133', 'teaware', '茶器', 'teaware', 1);
INSERT IGNORE INTO product_category (id, business_key, name, slug, sort) VALUES ('8774022059314172342', 'gift_box', '礼盒', 'gift_box', 2);
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('2865891739335655960', 'product_longjing_50', 'CYT-TEA-LJ-050', 'product_longjing_50', '394928649089662440', '8906796300054631801', '["tea_longjing"]', '西湖龙井·清鲜罐装', '豆香清鲜，适合玻璃杯轻泡', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125342846.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125342846.jpg"]', '["绿茶","春日鲜爽"]', '[{"type":"paragraph","text":"一罐走清鲜路线的西湖龙井。扁平挺直、糙米色，豆香和嫩栗香都在，用一只玻璃杯就能泡明白。想认真认识一杯绿茶、又不想被复杂手法劝退的人，从它开始最省事；当作日常口粮，50 g 大概够喝三周到一个月。"},{"type":"heading","level":3,"text":"西湖产区的炒青底子"},{"type":"paragraph","text":"龙井产自浙江省杭州市西湖区及西湖风景名胜区一带。工艺是典型炒青：鲜叶先摊放走水，再下锅青锅杀青，出锅回潮让水分重新分布，接着辉锅做形提香，最后筛分定级。决定龙井性格的是辉锅——在锅里用手掌把茶叶压成扁平挺直的样子，同时把豆香和嫩栗香逼出来。所以龙井的「扁」不是天生的，是炒出来的，形状里本身就带着火功。西湖产区茶园面积有限，原料比周边产区紧俏，这也是它价格的由来。这一罐选的是清鲜风格，不是重火那一路，香气偏轻盈，适合纯饮，不建议拿去煮或者做调饮。"},{"type":"heading","level":3,"text":"豆香在前，回甘在后"},{"type":"paragraph","text":"干茶扁平挺直、色泽糙米色带一点嫩黄。热水一激，先是清晰的豆香，随后浮出嫩栗香，尾上偶尔有一点兰花香。入口鲜醇甘爽，收敛感适中——不是没有涩，而是涩得干净、化得快，咽下去之后回甘才跟上来。汤色清亮微黄，叶底嫩匀成朵。茶汤放凉一点，香气会收敛，但甜感反而更清楚，这也是判断一款龙井做得干不干净的小办法。它不属于浓强型，投茶多了反而把鲜爽压掉，宁可少一点。"},{"type":"heading","level":3,"text":"玻璃杯轻泡，别直冲芽心"},{"type":"steps","items":[{"title":"温杯投茶","text":"3 g 茶配 150 ml 水，约 1:50，先把杯子烫一遍再投茶。"},{"title":"静置降温","text":"水烧开后放 2 至 3 分钟，降到 80 至 85℃ 再注水。"},{"title":"沿壁缓注","text":"水流沿杯壁缓缓注入，不要直冲芽心，免得把嫩芽烫熟。"},{"title":"出汤与续泡","text":"第一泡 20 至 30 秒，之后每泡延长 10 至 15 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"info","title":"关于水温","text":"芽头更嫩的明前茶，水温可以再降到 75 至 80℃。宁可淡一点，也不要闷出一杯熟汤气，熟汤气一旦出来这一泡就救不回来了。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["想认真喝一杯春茶的新手","上午办公时提神","午后清口","餐后解腻"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味。绿茶的鲜爽不耐放，短期内喝不完建议冷藏，取出后回到室温再开封，避免冷凝水打湿茶叶。新茶密封放一两周再喝，香气会更协调。每次取茶用干燥的茶匙，别用手抓，手上的水汽会被茶叶吸进去。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 1, 10, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('4431782651400464440', 'product_longjing_50:50g', '2865891739335655960', '50g罐装', 'CYT-TEA-LJ-050-50g', 16800, 21800, 1, 1, 86, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('8648998679384353590', 'product_biluochun_50', 'CYT-TEA-BLC-050', 'product_biluochun_50', '394928649089662440', '1666143067241565070', '["tea_biluochun"]', '洞庭碧螺春·花果香', '细嫩卷曲，上投法更显鲜爽', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124056917.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124056917.jpg"]', '["绿茶","花果香"]', '[{"type":"paragraph","text":"卷曲如螺、满披白毫的洞庭碧螺春，花果香轻盈，是绿茶里性子最嫩的一路。这一罐适合愿意用上投法慢慢看它舒展的人，也适合待客时泡一杯「看着就讲究」的茶；泡法不难，难的是别用沸水去对待它。"},{"type":"heading","level":3,"text":"洞庭东西山的搓团显毫"},{"type":"paragraph","text":"碧螺春产自江苏省苏州市吴中区洞庭东山与洞庭西山。工艺是拣剔、摊放、高温杀青、揉捻做形、搓团显毫、烘干。最要紧的是搓团显毫：锅温不高时用手把茶团轻轻搓揉，白毫在反复搓动中被保留并显出，条索也一点点卷成螺形。杀青要高温快炒，锁住清鲜；搓团要轻柔，毫毛才不掉。一锅茶的好坏多半落在这两步的手上，也正因为细嫩，它对水温比多数绿茶更敏感。原料越嫩，白毫越密，冲泡时越经不起滚水直冲。"},{"type":"heading","level":3,"text":"花果香轻盈，汤感偏柔"},{"type":"paragraph","text":"干茶纤细卷曲、满披白毫，色银绿隐翠。冲开后香气是花果香打头、清香托底，不冲不烈，闻着轻。入口鲜爽甘醇，汤感轻柔，苦涩感很低，咽下之后口腔里留下的是一点清甜。汤色浅绿明亮，叶底嫩匀，芽叶摊开后仍然完整。整体风格偏「细」，投茶多一点就容易显苦，宜少不宜多；续水时也别一次冲得太满，留点空间给它慢慢舒展。"},{"type":"heading","level":3,"text":"上投法，先水后茶"},{"type":"steps","items":[{"title":"温杯备水","text":"3 g 茶配 150 ml 水，约 1:50，水温控制在 75 至 80℃。"},{"title":"先注水","text":"采用上投法，先把水注到七分满，再等水面平静下来。"},{"title":"再投茶","text":"把茶叶轻轻撒在水面，让它自己吸水下沉，白毫不易脱落。"},{"title":"续泡","text":"第一泡 15 至 25 秒，之后每泡延长约 10 秒，一般可冲 3 泡。"}]},{"type":"tip","tone":"info","title":"水温提醒","text":"水别烧太老，75 至 80℃ 就够。沸水会把嫩芽烫出熟味，花果香也留不住；保温杯更不适合泡它，长时间高温闷着等于把香气煮掉。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["春茶尝鲜","上午提神","午后清口","待客时想露一手"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装。花果香最容易散失，务必密封、低温、避光、防潮，并远离气味浓烈的食材。开封后建议尽快喝完，不要放在灶台边或冰箱门格这种温度反复的位置。每次取完茶立刻盖紧，罐口别敞着聊天。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 0, 20, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('7833776537658157127', 'product_biluochun_50:50g', '8648998679384353590', '50g罐装', 'CYT-TEA-BLC-050-50g', 14800, 19800, 1, 1, 73, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('7451019272342012602', 'product_baihao_yinzhen_50', 'CYT-TEA-BHYZ-050', 'product_baihao_yinzhen_50', '394928649089662440', '1923150703997483324', '["tea_baihao_yinzhen"]', '白毫银针·毫香小罐', '芽头披毫，清鲜淡雅', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124054425.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124054425.jpg"]', '["白茶","毫香"]', '[{"type":"paragraph","text":"全芽披毫的白毫银针，是白茶里最清淡的一路。这一罐给想喝点清甜、又不想被苦涩打扰的人，也适合夏天当作一杯不需要讲究手法的日常茶。它的看点在香气的干净和汤感的细，不在浓强，所以别期待一入口就被抓住。"},{"type":"heading","level":3,"text":"福鼎与政和的单芽"},{"type":"paragraph","text":"白毫银针产自福建省宁德市、南平市，福鼎（太姥山、磻溪、点头）与政和是传统产区。工艺上它只采单芽，经日光萎凋或室内自然萎凋，长时间缓慢失水，再以文火烘焙收干，全程不炒不揉。不炒不揉意味着没有杀青，茶叶里的酶在萎凋阶段缓慢作用，毫香和蜜韵就是这么一点点养出来的。萎凋的时间长短、室内外的切换时机，直接决定成品是清透还是发闷。芽头肥壮、白毫越密，成茶越耐看，也越经得起慢慢喝。"},{"type":"heading","level":3,"text":"毫香与蜜韵，往上飘的清透"},{"type":"paragraph","text":"干茶芽头肥壮、满披白毫，色白如银。汤色浅杏黄、清亮。香气以毫香为主，后面跟着蜜香和一点清花香，整体是往上飘的清透感，不是厚重的那一种。入口清鲜醇爽，甜感明显，苦涩很轻，汤感细滑。叶底肥嫩、芽头完整，泡开之后一根根立着。它不适合追求「够味」的人，适合愿意慢下来、喝一口停一停的人，续泡到第四五泡甜感还在。"},{"type":"heading","level":3,"text":"玻璃杯或盖碗，85 至 90℃"},{"type":"steps","items":[{"title":"备茶","text":"4 g 茶配 150 ml 水，约 1:38，芽头占体积，看着不少是正常的。"},{"title":"控温","text":"水温 85 至 90℃，不要超过 90℃。"},{"title":"注水","text":"水流沿杯壁轻柔注入，不要直冲芽头。"},{"title":"出汤","text":"第一泡 15 至 30 秒，之后每泡顺延 10 至 15 秒，可冲 4 至 5 泡。"}]},{"type":"tip","tone":"info","title":"第一泡别急着下结论","text":"芽头紧实，第一泡往往还没完全舒展，甜感不明显是正常的，第二泡开始才是它真正的样子。玻璃杯泡的话，别搅动芽头。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["夏季消暑","午后清口","待客时赏形","口味清淡者的入门白茶"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，常温密封、避光、干燥、无异味保存，多层包装隔绝潮气与杂味。芽头蓬松、体积大，50 g 装起来看着不少，其实按每天 4 g 算大约两周就喝完了，别指望它能放很久。是否适合长期存放取决于原料、含水率与仓储条件，年份不能替代品质判断；不确定仓储来历的，就当普通白茶趁鲜喝掉更稳妥。每次取茶后立即封口，不要长时间敞着罐子。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 30, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('7697400765504101164', 'product_baihao_yinzhen_50:50g', '7451019272342012602', '50g罐装', 'CYT-TEA-BHYZ-050-50g', 22800, 29800, 1, 1, 45, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('5915884193757027089', 'product_baimudan_100', 'CYT-TEA-BMD-100', 'product_baimudan_100', '394928649089662440', '5945416550361215560', '["tea_baimudan"]', '白牡丹·清甜分享装', '毫香与花香兼具，冷泡也清甜', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124055679.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124055679.jpg"]', '["白茶","冷泡推荐"]', '[{"type":"paragraph","text":"绿叶夹着银白毫心、形似花朵的白牡丹，毫香与花香兼具，比银针更有层次，也比寿眉更清雅。这一袋 100 g 适合当日常口粮：热泡温柔，冷泡清甜，投茶多一点也不会苦，是白茶里最不挑人的一档。"},{"type":"heading","level":3,"text":"一芽一二叶的福鼎路子"},{"type":"paragraph","text":"白牡丹产自福建省宁德市、南平市，福鼎、政和、建阳，以及松溪、建瓯等地都有生产。原料采一芽一叶或一芽二叶，经日光或室内萎凋、复式萎凋、干燥而成，同样不炒不揉。所谓复式萎凋，是日光萎凋与室内萎凋交替进行，让水分走得慢一点、匀一点，花香就有机会留下来。原料比银针成熟，滋味自然更厚，也更耐泡，价格却比银针友好得多，这也是它在白茶里销量最大的原因之一。"},{"type":"heading","level":3,"text":"清甜里有层次"},{"type":"paragraph","text":"干茶芽叶连枝，绿叶夹银白毫心，形似花朵。汤色杏黄清亮。香气是毫香与花香并存，尾上带清甜香。入口清甜醇和，比银针更有厚度，层次也更多：前段是甜，中段浮出一点花香，后段落回甘。涩感轻，投茶稍多也不容易苦，是白茶里最好上手的一档。泡到后面几泡，汤色会转深一点，甜味反而更集中。"},{"type":"heading","level":3,"text":"热泡清甜，冷泡更甜"},{"type":"steps","items":[{"title":"备茶","text":"4 g 茶配 150 ml 水，约 1:38。"},{"title":"控温","text":"水温 85 至 90℃，不宜超过 90℃。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡顺延 10 至 20 秒，可冲 5 至 6 泡。"},{"title":"冷泡换法","text":"按 1 g 茶比 100 ml 水，冷藏约 6 小时，甜感更突出。"}]},{"type":"tip","tone":"success","title":"冷泡提示","text":"出门前一晚丢进冷水壶冷藏，第二天带着走。冷泡的甜感比热泡更直接，也更不容易苦，办公室没有热水也能喝。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["午后清口","餐后解腻","夏季冷泡","白茶入门"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 分享装，常温密封、避光、干燥、无异味保存，整袋存放时注意防潮，取完茶把袋口的密封条按紧。100 g 按每天 4 g 算大约能喝三周，几个人一起喝更划算，也更容易在香气最好的时候喝完。原料有一定成熟度，较适宜存放观察风味变化，但能否陈化良好取决于仓储条件；散茶比饼茶更容易受潮，别放在厨房或阳台。出现霉斑、酸馊或刺鼻异味即不可饮用。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 40, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('4527954020580325469', 'product_baimudan_100:100g', '5915884193757027089', '100g袋装', 'CYT-TEA-BMD-100-100g', 15800, 20800, 1, 1, 112, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('9021903971534806409', 'product_junshan_yinzhen_50', 'CYT-TEA-JSYZ-050', 'product_junshan_yinzhen_50', '394928649089662440', '2443959781945548466', '["tea_junshan_yinzhen"]', '君山银针·观芽礼罐', '黄汤黄叶，甜醇少涩', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125339192.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125339192.jpg"]', '["黄茶","观形"]', '[{"type":"paragraph","text":"黄汤黄叶、全芽挺直的君山银针，甜醇少涩。这一罐给想尝鲜黄茶的人，也给喜欢坐在桌边看芽头在杯里沉浮的人。礼罐装，送人自留都体面；黄茶产量本来就小，能拿它当日常茶喝的场合不多，更适合慢慢喝完这一罐。"},{"type":"heading","level":3,"text":"洞庭湖心的小岛茶"},{"type":"paragraph","text":"君山银针出自湖南省岳阳市君山区洞庭湖中的君山岛。工艺是采摘单芽、杀青、摊凉、初包闷黄、复炒、复包闷黄、足火干燥。黄茶的「黄」不来自原料，而来自闷黄这道工序：杀青或炒制后的芽头趁热包起来保温，在湿热里慢慢转黄，苦涩的收敛感下降，甜醇感上来。君山银针要闷两次，中间夹一道复炒，两次包闷的分寸都很难拿——第一次闷得短了转不过来，闷久了又会闷出浊味，这也是它产量一直不高的原因。"},{"type":"heading","level":3,"text":"甜香、嫩香与一点锅巴香"},{"type":"paragraph","text":"干茶全芽肥壮挺直、满披白毫，色泽银白微黄。汤色浅黄明亮。香气以甜香、嫩香为主，尾上有一点淡淡的锅巴香。入口甜醇鲜爽，苦涩很轻，汤感细软。用透明玻璃杯冲泡，还能看到芽头在杯中反复沉浮，这是黄芽茶里最有观赏性的一款，醒着喝比闷着喝有意思得多。它的甜不像加了糖那种甜，更像含在汤里的回甘，慢慢才浮出来。"},{"type":"heading","level":3,"text":"透明玻璃杯，80 至 85℃"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50，芽头轻，抓一小撮就够。"},{"title":"控温","text":"水温 80 至 85℃，忌沸水。"},{"title":"注水","text":"沿杯壁缓注，别把芽头冲散，也别用勺子搅。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡延长约 10 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"warning","title":"别闷","text":"芽头细嫩，最忌沸水和久闷。闷久了甜香会变成闷浊气，一泡好茶就浪费了，茶汤也会变浑。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["茶龄短者的黄茶入门","上午清饮","待客时观形","餐后淡饮"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 礼罐装，密封、避光、防潮、防异味，短期喝不完可冷藏，取出后回到室温再开封，避免罐身结露打湿茶叶。以清甜鲜醇为品饮目标，开封后宜尽早喝完，别为了等一个特殊日子放到香气散掉。原料是单芽，50 g 大约能泡十六七次，按每周两三杯算能喝一个多月，节奏刚好。礼罐本身密封性一般，长期存放建议套一层自封袋。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 50, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('8089714074211137538', 'product_junshan_yinzhen_50:50g', '9021903971534806409', '50g礼罐', 'CYT-TEA-JSYZ-050-50g', 25800, 32800, 1, 1, 38, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('2179248427897749582', 'product_huoshan_huangya_50', 'CYT-TEA-HSHY-050', 'product_huoshan_huangya_50', '394928649089662440', '3272000355873956807', '["tea_huoshan_huangya"]', '霍山黄芽·栗香小罐', '清香带熟栗，甜感柔和', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125337935.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125337935.jpg"]', '["黄茶","甜醇"]', '[{"type":"paragraph","text":"形似雀舌的霍山黄芽，清香里带熟栗香，甜感柔和。它比绿茶多一点甜、少一点刺激，很适合想从绿茶往前再走一步的人；如果你平时喝绿茶觉得「有点扎」，换成它通常就顺了。它不适合追求强烈回甘和冲击力的老茶客，但对刚从绿茶转过来的人几乎零门槛。"},{"type":"heading","level":3,"text":"大别山北麓的干坯闷黄"},{"type":"paragraph","text":"霍山黄芽产自安徽省六安市霍山县大化坪、漫水河、太阳乡等地。工艺顺序是杀青、毛火、足火做形、摊放闷黄、拣剔、复火。和君山银针不同，它的闷黄是在干坯阶段完成的：先做成形、烘到一定程度，再摊放让它自己转色转味。这种做法保留了更多鲜爽，同时把甜醇感提了上来，所以喝起来既像绿茶那样清，又比绿茶更甜。工序里没有长时间的湿热包闷，成茶的香气也更干净、更容易辨认。"},{"type":"heading","level":3,"text":"清香在前，熟栗在后"},{"type":"paragraph","text":"干茶形似雀舌、色泽嫩黄。汤色黄绿明亮，用白瓷衬底最容易看出来。香气以清香为主，中间是清晰的熟栗香，尾上带甜香。入口鲜醇甘爽，甜感明确，苦涩轻微。整体走温和路线，不像高火绿茶那样有冲击力，即使多喝几杯口腔也不觉得发紧。叶底嫩黄匀整，冲开后一根根立着，看着也舒服。"},{"type":"heading","level":3,"text":"玻璃杯或盖碗，80 至 85℃"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"控温","text":"水温 80 至 85℃，水烧开后稍等再注。"},{"title":"注水","text":"沿杯壁注水，芽叶舒展得更整齐。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡延长约 10 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"info","title":"选器看你想看什么","text":"想看清黄绿明亮的汤色，用白瓷盖碗比玻璃杯更明显；想看得见芽叶舒展，就换玻璃杯，两种泡法味道差别不大。第一泡的水温宁低勿高，淡一点反而更甜。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["春日清饮","办公桌边常备","餐后淡饮","与绿茶对比品鉴"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、干燥、避光、防异味。开封后尽量减少空气接触，量大可以按周分装成小份，喝哪份开哪份，避免整罐反复开合受潮。以清新鲜甜为主要品饮目标，宜趁鲜饮用，放到第二年香气会明显变淡，甜感也跟着退。黄茶与绿茶一样怕高温高湿，别放在暖气边或阳光能晒到的架子上。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 60, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('1948470579410241318', 'product_huoshan_huangya_50:50g', '2179248427897749582', '50g罐装', 'CYT-TEA-HSHY-050-50g', 13800, 17800, 1, 1, 64, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('5891784194646204727', 'product_tieguanyin_100', 'CYT-TEA-TGY-100', 'product_tieguanyin_100', '394928649089662440', '4051196457869679063', '["tea_tieguanyin"]', '安溪铁观音·兰香罐', '清香鲜爽，七泡仍有余韵', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125346543.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125346543.jpg"]', '["乌龙茶","兰花香"]', '[{"type":"paragraph","text":"颗粒紧结、兰花香高扬的安溪铁观音，清香型鲜爽带音韵。100 g 罐装是日常功夫泡的稳妥选择，折算下来单泡成本比绿茶低；想先试口感的，可以拿 50 g 尝鲜装，不用一上来就买大罐。"},{"type":"heading","level":3,"text":"安溪的摇青与包揉"},{"type":"paragraph","text":"铁观音产自福建省泉州市安溪县西坪、感德、祥华、剑斗等乡镇。工艺是晒青、晾青、摇青做青、杀青、揉捻、包揉、烘干，浓香型还要再焙火。摇青做青是它的灵魂：叶片在摇动中边缘轻微破损，走水与氧化同时发生，兰花香就是这一步做出来的。包揉则把茶叶揉成紧结的颗粒，冲泡时需要给它一点时间舒展，否则头两泡会显得淡。同样是铁观音，清香与浓香是两条路，这一款走的是清香路线，香气更外放，汤色更浅，保存上也更需要低温。"},{"type":"heading","level":3,"text":"兰花香高扬，七泡有余韵"},{"type":"paragraph","text":"干茶颗粒紧结、砂绿油润。汤色金黄明亮。香气以兰花香为主，高扬清晰，尾上是清花香或焙火香，看焙火程度而定。入口鲜爽，汤感醇厚，回甘明显。它的耐泡度在乌龙里算好的，正常可以冲到七泡以上，尾水仍有甜味，这一点比很多绿茶划算。第一泡因为颗粒还没展开，滋味会偏淡，别急着下判断；第二三泡才是香气最足的时候。"},{"type":"heading","level":3,"text":"沸水快出汤"},{"type":"steps","items":[{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14，颗粒紧结，量看着少是正常的。"},{"title":"温器","text":"盖碗或紫砂壶先用沸水烫透，茶汤温度更稳。"},{"title":"注水","text":"全程 100℃ 沸水，第一泡可稍等它舒展。"},{"title":"出汤","text":"第一泡 5 至 15 秒，之后每泡延长 5 至 10 秒，可冲 7 至 10 泡。"}]},{"type":"tip","tone":"success","title":"宁可快，不要闷","text":"球形茶最怕闷。宁可出汤快一点、多冲两泡，也别一次坐杯太久，闷出来的涩味压不住，后面几泡也跟着变差。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["秋日品饮","油腻餐后","功夫茶待客","午后需要专注的时候"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"两个规格可选：50 g 尝鲜装与 100 g 罐装。清香型建议密封后低温保存，浓香型密封、避光、防潮、防异味即可，具体以产品包装标注为准。清香型的香气衰减比浓香型快，开封后别放太久，最好三个月内喝完；先买 50 g 尝鲜装试口感，合口味再上 100 g 更稳妥。颗粒茶取用方便，用干茶匙舀就行，不用手抓，避免手上的水汽进罐。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 70, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('3816794497180375102', 'product_tieguanyin_100:50g', '5891784194646204727', '50g尝鲜装', 'CYT-TEA-TGY-100-50g', 10800, 13800, 1, 0, 120, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('7528497605336148000', 'product_tieguanyin_100:100g', '5891784194646204727', '100g罐装', 'CYT-TEA-TGY-100-100g', 18800, 24800, 1, 1, 82, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('8696468709072989976', 'product_dahongpao_100', 'CYT-TEA-DHP-100', 'product_dahongpao_100', '394928649089662440', '4823801346719822543', '["tea_dahongpao"]', '武夷大红袍·焙火岩韵', '焙火与花香交织，汤感醇厚', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124058143.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124058143.jpg"]', '["乌龙茶","焙火香"]', '[{"type":"paragraph","text":"焙火与花香交织的武夷大红袍，汤感醇厚、喉韵深长。这一罐 100 g 给想认真喝一道岩茶的人，也适合秋冬晚上有时间的场合，慢慢泡、慢慢聊。它不靠第一口的惊艳留住人，靠的是后半段的厚度。"},{"type":"heading","level":3,"text":"武夷山的焙火功夫"},{"type":"paragraph","text":"大红袍产自福建省南平市武夷山市，核心正岩产区是三坑两涧。工艺是萎凋、做青、杀青、揉捻、初焙、复焙、炖火。岩茶的性格一半在做青、一半在焙火：做青决定香气走向，焙火决定汤感的厚度与稳定度。炖火用低温长时间慢炖，把火气吃进茶叶里，退火之后香气更沉稳，汤感也更顺。刚焙好不久的茶会带一点火气，这是正常的，不是缺陷，放一放就好。三坑两涧的原料紧俏，市面上带「正岩」字样的价格区间很大，买之前问清山场比看包装更有用。"},{"type":"heading","level":3,"text":"焙火香与醇厚汤感"},{"type":"paragraph","text":"干茶条索紧结乌润。汤色橙红明亮。香气是焙火香与花香交融，中间带一点焦糖香。入口醇厚甘活，汤感有厚度，喉韵深长——喝下去之后喉咙里留着一点甜和凉。它不靠香气取胜，靠的是汤里的厚度和回甘的持久度，所以泡的时候别追求第一口的惊艳，第三泡往后才是它真正展开的地方。叶底软亮，冲泡后仍然有韧性。"},{"type":"heading","level":3,"text":"沸水高冲，快出汤"},{"type":"steps","items":[{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"醒茶","text":"沸水快速润洗一遍，让紧结的条索先松开。"},{"title":"注水","text":"沸水高冲，激发焙火香。"},{"title":"出汤","text":"第一泡 5 至 10 秒，之后每泡延长 5 至 10 秒，可冲 8 至 10 泡。"}]},{"type":"tip","tone":"info","title":"退火再喝更好","text":"密封放一段时间让它退火，香气会更沉稳、汤感更顺。急着开罐喝，火气会盖住花香，还容易觉得口干。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["大餐餐后","秋冬暖饮","商务待客","有时间的晚上慢慢泡"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、避光、防潮、防异味，阴凉处存放。焙火型岩茶退火后香气更沉稳，具体期限以产品包装标注为准。岩茶相对耐放，但开封后仍建议一年内喝完，别放在有阳光直射的架子上。100 g 按每次 8 g 算能冲十二三次，刚好够认真喝一阵子；开罐后前两周火气会慢慢散掉，滋味一天比一天顺。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 80, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('4271984064351343244', 'product_dahongpao_100:100g', '8696468709072989976', '100g罐装', 'CYT-TEA-DHP-100-100g', 23800, 30800, 1, 1, 59, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('350330966536208889', 'product_zhengshan_xiaozhong_100', 'CYT-TEA-ZSXZ-100', 'product_zhengshan_xiaozhong_100', '394928649089662440', '4996346501470601743', '["tea_zhengshan_xiaozhong"]', '正山小种·桂圆香', '醇厚甘甜，清饮调饮皆宜', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125347772.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125347772.jpg"]', '["红茶","桂圆香"]', '[{"type":"paragraph","text":"醇厚甘甜的正山小种，清饮能喝到花果蜜香，加一点鲜奶也不打架。这一罐 100 g 是秋冬的常备款，也是家里来客人时最不容易被挑毛病的一杯红茶——不苦不涩、凉了也能喝，泡法容错率高。100 g 一罐，按每次 5 g 算能冲二十次，够喝一个季度。"},{"type":"heading","level":3,"text":"桐木关的小种红茶"},{"type":"paragraph","text":"正山小种产自福建省南平市武夷山市桐木关及正山范围。工艺是萎凋、揉捻、发酵、过红锅、复揉、熏焙或无烟干燥、复火。传统烟种用松柴熏焙，带松烟香与桂圆汤感；无烟种省去熏焙，转向花果蜜香。这一款走的是花果蜜香路线，接受度更广，也更好搭——不常喝红茶的人通常第一口就能接受，不会觉得烟味重。桐木关是正山的核心范围，「外山」的原料做不出同样的细腻度，这也是这一带红茶价格偏高的原因。"},{"type":"heading","level":3,"text":"醇厚甘甜，汤感圆"},{"type":"paragraph","text":"干茶条索紧结乌黑。汤色红艳明亮。香气以花果香与蜜香为主。入口醇厚甘甜，汤感圆润，尾上有一点桂圆似的甜。它不像大叶种红茶那样浓强，而是柔和顺口的一路，放凉一点喝也不显涩，这一点很适合当办公室的常备茶。加鲜奶之后茶味还在，不会被奶完全盖住，这是它比很多红茶更适合调饮的地方。"},{"type":"heading","level":3,"text":"90 至 95℃，快出汤"},{"type":"steps","items":[{"title":"备茶","text":"5 g 茶配 150 ml 水，约 1:30。"},{"title":"控温","text":"水温 90 至 95℃；传统烟种可以用到 95 至 100℃。"},{"title":"出汤","text":"第一泡 5 至 10 秒，之后每泡延长 5 至 10 秒，可冲 5 至 7 泡。"},{"title":"调饮","text":"想做奶茶，把茶汤泡得比清饮更浓，再按口味加鲜奶。"}]},{"type":"tip","tone":"info","title":"清饮和调饮是两套泡法","text":"清饮宜快出汤，泡久了会发酸；调饮则相反，需要泡浓一点，奶香才不会把茶味盖住。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["秋冬清饮","加奶调饮","油腻餐后","待客"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、干燥、避光、防异味，常温保存。松烟香与花果蜜香都容易挥发，开封后尽早饮用更合算，别一次囤太多。取茶时用干勺，罐口随手盖紧；如果打算做奶茶，可以单独分出一小罐专门用来调饮，免得反复开合影响清饮的香气。100 g 大约能冲二十次，家里常备一罐够喝一个季度。红茶含咖啡因，避免空腹浓饮与睡前 6 小时内饮用。"}]', 1, 90, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('6791406361469372261', 'product_zhengshan_xiaozhong_100:100g', '350330966536208889', '100g罐装', 'CYT-TEA-ZSXZ-100-100g', 12800, 16800, 1, 1, 144, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('2436706822650458706', 'product_keemun_100', 'CYT-TEA-QMHC-100', 'product_keemun_100', '394928649089662440', '910171288014757367', '["tea_keemun"]', '祁门红茶·甜花香', '花果蜜香复合，下午茶友好', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125340395.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125340395.jpg"]', '["红茶","祁门香"]', '[{"type":"paragraph","text":"花果蜜香复合的祁门红茶，甜花香清晰、汤感鲜甜。这一罐 100 g 适合下午茶，也适合做低糖奶茶的底。它的香气比多数红茶更「有内容」，清饮最能喝出差别，加奶反而会浪费掉一部分香。"},{"type":"heading","level":3,"text":"祁门的工夫红茶"},{"type":"paragraph","text":"祁门红茶产自安徽省黄山市祁门县及黟县、石台、东至等周边传统产区，是中国十大名茶里唯一的红茶。工艺是萎凋、揉捻、发酵、毛火烘焙、足火、精制。发酵决定香气的走向，烘焙决定香气的干净度，最后还要靠精制筛分定级。所谓「祁门香」，是蔷薇花香、果香与蜜香复合出来的一层香气，不是单一香型，所以不同批次闻起来会有细微差别，这是正常的，不代表品质不稳定。工夫红茶的精制环节繁复，等级划分细，同是祁红，价位可以从口粮到礼品拉开很大差距。"},{"type":"heading","level":3,"text":"祁门香与鲜甜汤感"},{"type":"paragraph","text":"干茶条索细紧乌润、金毫显露。汤色红艳明亮。香气层次比较丰富：蔷薇花香打头，果香与蜜香跟上，茶汤冷却之后香气依然清楚。入口醇厚鲜甜，汤感柔顺，甜花香留在口腔里。它既适合清饮，也扛得住加奶，是红茶里使用场景最宽的一档。叶底红亮匀整，续泡到第五泡香气才慢慢减弱。"},{"type":"heading","level":3,"text":"白瓷盖碗，90 至 95℃"},{"type":"steps","items":[{"title":"备茶","text":"5 g 茶配 150 ml 水，约 1:30。"},{"title":"选器","text":"白瓷器皿更容易看清红亮的汤色、辨认复合香气。"},{"title":"出汤","text":"第一泡 5 至 10 秒，之后每泡延长 5 至 10 秒，可冲 5 至 7 泡。"},{"title":"调饮","text":"泡浓一些再加鲜奶，做成低糖奶茶，糖可以少放或不放。"}]},{"type":"tip","tone":"success","title":"闻冷香","text":"想让祁门香更明显，出汤后稍微放一放再闻杯底，冷下来的香气反而更清楚，这也是审评时常用的做法。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["下午茶","清饮待客","英式奶茶","早餐后"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、常温、干燥、避光、防异味。避免与香料同放，开封后及时封口，否则花果香会先跑掉。祁门香是复合香气，对异味特别敏感，和咖啡豆、花椒放在同一层柜子里很快就串味。放在阴凉柜子里比放在灶台边合适得多。100 g 按每次 5 g 算大约能冲二十次，是下午茶用量最合适的一档。红茶含咖啡因，避免空腹浓饮与睡前 6 小时内饮用。"}]', 0, 100, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('3817001359991106430', 'product_keemun_100:100g', '2436706822650458706', '100g罐装', 'CYT-TEA-QMHC-100-100g', 14800, 19800, 1, 1, 108, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('1305905369764269901', 'product_ripe_puer_200', 'CYT-TEA-SP-200', 'product_ripe_puer_200', '394928649089662440', '8256583128742200111', '["tea_ripe_puer"]', '普洱熟茶·醇香小饼', '陈香木香，红浓顺滑', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125344116.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125344116.jpg"]', '["黑茶","醇厚"]', '[{"type":"paragraph","text":"陈香木香明显、红浓顺滑的普洱熟茶小饼，200 g 一饼。撬开就能泡，也适合煮，是家里最不容易放坏、最不挑人的一类茶。一饼大概能喝一个多月，折算下来单泡成本并不高。第一次接触熟茶的人，从它入手比从生茶入手更容易接受。"},{"type":"heading","level":3,"text":"渥堆做出来的醇厚"},{"type":"paragraph","text":"普洱熟茶产自云南省西双版纳州、普洱市、临沧市，以勐海等传统加工地为代表。工艺是晒青毛茶经洒水渥堆、多次翻堆、干燥筛分，再蒸压成型或散装。渥堆是熟茶的关键：毛茶堆起来洒水保温，靠微生物与湿热作用快速转化，几个月里就走完自然陈化很多年的路。新茶常带一点堆味，密封放一段时间会淡下去，这也是熟茶比生茶更好上手、更适合马上喝的原因。"},{"type":"heading","level":3,"text":"陈香木香，红浓顺滑"},{"type":"paragraph","text":"干茶饼面紧结、色泽褐红。汤色红浓明亮。香气以陈香、木香为主，尾上有熟果香。入口醇厚顺滑，甜感明显，几乎没有苦涩，汤感是往下沉的那种厚。它不挑人，也不挑时间，凉了喝也不难入口，所以很适合放在办公室当作一整天的那一壶。撬茶的时候尽量顺着饼面的纹理走，条索完整一些，泡出来的汤也更干净。"},{"type":"heading","level":3,"text":"沸水润洗，快出汤"},{"type":"steps","items":[{"title":"撬茶","text":"紧压茶先撬成小块，尽量保持条索完整，撬好的茶可以放在小罐里备用。"},{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"润洗","text":"沸水润洗一至两遍，快速倒掉，避免闷出沉重的堆味。"},{"title":"出汤","text":"润洗后快出汤，之后按汤色逐泡延长，可冲 10 至 15 泡。"}]},{"type":"tip","tone":"warning","title":"仓储安全","text":"熟茶靠仓储养出来，但仓储不等于越久越好。出现霉斑、酸馊味或刺鼻异味的茶不可饮用，直接丢掉。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["重油餐后","早晨温饮","秋冬煮饮","冷泡一比一百，冷藏约十二小时"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"200 g 小饼。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味的物品同放。整饼不喝时保持原包装密封，撬开的部分装进小罐尽快用完，别让碎茶在敞口容器里放上半个月。陈化结果取决于原料、工艺与仓储，并非年份越久越好，仓储干净比年份重要。200 g 按每次 8 g 算能冲二十五次左右，一饼足够喝上一两个月。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 110, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('2710478936183334483', 'product_ripe_puer_200:200g', '1305905369764269901', '200g小饼', 'CYT-TEA-SP-200-200g', 19800, 26800, 1, 1, 76, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('9041432522602952371', 'product_liubao_250', 'CYT-TEA-LB-250', 'product_liubao_250', '394928649089662440', '1792334420373902975', '["tea_liubao"]', '广西六堡茶·竹篓装', '红浓陈醇，适合煮饮', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125341645.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125341645.jpg"]', '["黑茶","陈香"]', '[{"type":"paragraph","text":"红浓陈醇的广西六堡茶，250 g 竹篓装。既能泡也能煮，还适合冷泡，是黑茶里喝法最多的一款，潮湿季节尤其受欢迎。喜欢熟普的人通常会喜欢它，但两者的香气走向并不一样，值得对比着喝。"},{"type":"heading","level":3,"text":"六堡镇的渥堆与陈化"},{"type":"paragraph","text":"六堡茶产自广西壮族自治区梧州市苍梧县六堡镇及周边产区，贺州、横州等地亦有生产。工艺是杀青、揉捻、渥堆、复揉、烘干、蒸压装篓、陈化。渥堆让它快速转出红浓的汤色与醇厚的口感，装篓之后的陈化再慢慢把棱角磨平。它传统上归为黑茶，风格特征就是红、浓、陈、醇四个字。竹篓装的做法保留了传统的透气性，既方便取茶，也让茶叶在存放中继续缓慢变化。"},{"type":"heading","level":3,"text":"槟榔香与陈香并存"},{"type":"paragraph","text":"干茶色泽黑褐油润。汤色红浓明亮。香气里槟榔香与陈香并存，有时带一点松烟香，传统经验认为这种槟榔香与当地仓储环境有关，这里只作风味描述，不是品质承诺。入口醇厚甘爽，汤感顺滑，回甘舒服，耐泡度很好，泡到十几泡仍然有味道。凉了之后汤色会更深，滋味依旧顺口，所以也适合一次多泡一些放着慢慢喝。"},{"type":"heading","level":3,"text":"泡、煮、冷泡三种喝法"},{"type":"steps","items":[{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"润洗","text":"沸水润洗一至两次后快出汤，把表面的浮尘和杂味带走。"},{"title":"续泡","text":"之后逐泡延长，可冲 10 至 15 泡。"},{"title":"煮饮与冷泡","text":"煮饮 5 至 8 g 配 500 ml 冷水，煮沸后转小火 3 至 5 分钟；冷泡按 1:100 至 1:150 冷藏约 12 小时。"}]},{"type":"tip","tone":"warning","title":"仓储安全","text":"六堡茶的风味来自陈化，但霉斑、酸馊味或刺鼻异味说明仓储出了问题，这样的茶不能喝，别舍不得扔。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["重油餐后","潮湿季节","秋冬煮饮","冷萃气泡茶"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"250 g 竹篓装。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，梅雨季注意别挨着外墙放。竹篓的透气性好，适合长期存放，但前提是环境本身干燥；如果家里湿度大，建议先套一层密封袋再放回篓里。250 g 按每次 8 g 算能冲三十次上下，煮饮的话用量更省，一篓能喝小半年。陈化结果取决于原料、工艺与仓储，并非年份越久越好。传统经验中的说法不作为现代医学功效。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 120, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('3878072761407666795', 'product_liubao_250:250g', '9041432522602952371', '250g竹篓装', 'CYT-TEA-LB-250-250g', 21800, 28800, 1, 1, 51, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('8837549666622925335', 'product_gaiwan_set', 'CYT-WARE-GW-001', 'product_gaiwan_set', '1983613478798993133', NULL, '["tea_tieguanyin","tea_dahongpao","tea_baihao_yinzhen"]', '月白釉盖碗三件套', '素雅器形，适合日常功夫泡', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125336709.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125336709.jpg"]', '["茶器","新手友好"]', '[{"type":"paragraph","text":"一只月白釉盖碗、一只碗、一只托，110 ml 的容量。这是功夫泡里最省心的入门器形，也是很多人买的第一件茶器——因为它几乎能泡所有茶，买回来不用担心「配不上家里的茶」。110 ml 的容量对一人独饮和两三人共饮都合用，聚会时也能轮着用。"},{"type":"heading","level":3,"text":"三件套各管什么"},{"type":"paragraph","text":"盖碗由盖、碗、托三件组成，各有分工：盖用来拨茶和闻香，碗用来容纳茶叶与水，托用来隔热、接住溢出的水。110 ml 是市面上最通用的容量，配大多数乌龙、红茶、黑茶的投茶量都合适，不会因为太大而让茶汤凉得快，也不会因为太小而施展不开。素雅的月白釉不抢戏，放在任何一张茶桌上都不突兀，也不像深色釉那样容易看出水渍。"},{"type":"heading","level":3,"text":"为什么新手适合盖碗"},{"type":"paragraph","text":"盖碗没有壶嘴，出汤快、能看清叶底、清洗也方便，还不像紫砂那样一壶只伺一茶。釉面致密不吸味，泡完绿茶接着泡红茶也不会串味，一只碗就能伺候全家人的口味。开口大、散热快，泡嫩芽茶时比壶更容易控制温度。缺点也有：出汤手法需要练一练，拇指与食指捏住盖钮两侧的碗沿，盖子别掀太大，不然容易烫手也容易把茶叶冲出来。摔过一两次就熟练了。"},{"type":"heading","level":3,"text":"开器与用法"},{"type":"steps","items":[{"title":"开器","text":"新器先用温水洗净，再用沸水烫一遍，去掉窑灰和包装气味。"},{"title":"温器","text":"每次冲泡前用沸水把盖碗烫透，茶汤温度更稳。"},{"title":"投茶注水","text":"按茶类投茶，注水到八分满即可，留出出汤的余量。"},{"title":"出汤","text":"出汤时留一条细缝，别整个掀开盖子，避免茶叶跟着冲出来。"}]},{"type":"tip","tone":"warning","title":"瓷器怕急冷急热","text":"薄胎瓷器温差过大容易炸裂，冬天用之前先用温水过一遍；清洗用软布，别用钢丝球刮釉面。"},{"type":"heading","level":3,"text":"适合泡什么"},{"type":"list","ordered":false,"items":["乌龙茶：铁观音、岩茶、单丛","红茶：正山小种、祁门红茶","黑茶：普洱熟茶、六堡茶","白茶：白牡丹、寿眉"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"110 ml 盖碗套装，含盖、碗、托。瓷器易碎，日常收纳避免叠压，最好单独放在格子里；发生磕碰出现裂纹后不建议继续用于冲泡，以免烫伤。收到后先用温水泡洗一遍再使用，去掉运输中沾上的浮尘。110 ml 是通用容量，配 5 至 8 g 茶都能施展开，这也是它适合新手的原因之一。易碎品加固包装发出。"}]', 1, 130, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('8835479301032976817', 'product_gaiwan_set:110ml', '8837549666622925335', '110ml盖碗套装', 'CYT-WARE-GW-001-110ml', 16800, 22800, 1, 1, 66, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('8002116020902622525', 'product_six_tea_gift', 'CYT-GIFT-SIX-001', 'product_six_tea_gift', '8774022059314172342', NULL, '["tea_longjing","tea_baihao_yinzhen","tea_junshan_yinzhen","tea_tieguanyin","tea_zhengshan_xiaozhong","tea_ripe_puer"]', '六色茶韵·六大茶类礼盒', '一次认识六大茶类的代表风味', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125345339.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125345339.jpg"]', '["礼盒","六大茶类","店内主推"]', '[{"type":"paragraph","text":"六只小罐，绿、白、黄、青、红、黑各一款代表茶。想一次把六大茶类喝明白，或者想送一份不挑口味的茶礼，这个盒子是最省事的选择。每罐 20 g，够泡四五次，够建立印象，又不会剩下喝不完。六罐之间的口味差异很明显，适合边喝边对照，比只看文字讲解记得牢。"},{"type":"heading","level":3,"text":"盒子里有哪六款"},{"type":"paragraph","text":"礼盒装的是六大茶类的代表：绿茶的西湖龙井、白茶的白毫银针、黄茶的君山银针、青茶的安溪铁观音、红茶的正山小种、黑茶的普洱熟茶。每一款都选了能代表这一类风格的路线，不是随手拼凑，所以按顺序喝一遍，就能大致分清六类的差别到底在哪里。比起单买六罐，礼盒的单价更低，也省去了一样样挑的工夫，送人时还自带一个「有说法」的理由。"},{"type":"heading","level":3,"text":"六类茶差在哪里"},{"type":"list","ordered":false,"items":["绿茶：不发酵，清汤绿叶，以鲜爽为主。","白茶：不炒不揉，毫香清甜，六类里最清淡。","黄茶：多一道闷黄，甜醇少涩，比绿茶温柔。","青茶：半发酵，香气高扬，耐泡度最好。","红茶：全发酵，红汤甜香，清饮调饮都行。","黑茶：后发酵，陈香醇厚，适合煮饮。"]},{"type":"heading","level":3,"text":"建议的品鉴顺序"},{"type":"steps","items":[{"title":"先清后浓","text":"从绿茶、白茶开始，味觉干净的时候最容易分辨它们的细腻。"},{"title":"再黄再青","text":"黄茶承接绿茶的清，青茶把香气推到高点。"},{"title":"后红后黑","text":"红茶、黑茶放到最后，滋味最重，也不容易把前面的味道盖掉。"},{"title":"一天一款","text":"不建议一天之内连着喝六款，分几天喝，感受会更清楚。"}]},{"type":"tip","tone":"info","title":"购买须知","text":"礼盒为加固包装发出。"},{"type":"heading","level":3,"text":"适合谁"},{"type":"list","ordered":false,"items":["刚开始喝茶、想快速建立味觉坐标的人","需要一份不挑口味的茶礼","家里来客时按口味挑一罐","当作茶类对比的样品"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"标准礼盒，6 罐 × 20 g。绿茶与黄茶建议密封冷藏并尽快喝完；白茶、红茶、青茶常温密封、避光、防潮即可；黑茶注意通风防潮，出现霉斑、酸馊或刺鼻异味即不可饮用。六罐的保存要求不一样，别一股脑全塞进冰箱，冷藏的取出后要回到室温再开罐，免得冷凝水打湿茶叶。每罐 20 g 按每次 4 g 算大约能喝五次，六罐够感受一轮完整的茶类对比。所有茶都含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 140, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('5972178082153376589', 'product_six_tea_gift:standard', '8002116020902622525', '标准礼盒·6罐×20g', 'CYT-GIFT-SIX-001-standard', 39800, 52800, 1, 1, 42, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('1232070612881933513', 'product_huangshan_maofeng_50', 'CYT-TEA-HSMF-050', 'product_huangshan_maofeng_50', '394928649089662440', '6404999874162051223', '["tea_huangshan_maofeng"]', '黄山毛峰·兰香罐装', '形似雀舌，鲜浓醇和', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834568.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834568.jpg"]', '["绿茶","兰花清香"]', '[{"type":"paragraph","text":"形似雀舌、白毫披身的黄山毛峰，兰花香与清鲜栗香并存。这一罐 50 g 是烘青绿茶里最不容易出错的一路，适合当日常口粮，也适合当作认识安徽绿茶的起点。口味上它比龙井柔、比碧螺春厚，处在中间那一档，谁喝都不会觉得别扭。"},{"type":"heading","level":3,"text":"黄山风景区的烘青路子"},{"type":"paragraph","text":"黄山毛峰产自安徽省黄山市，黄山风景区及周边汤口、充川、岗村一带。工艺是杀青、揉捻、毛火、足火，属烘青绿茶。和炒青的龙井不同，它靠烘干而不是炒干成形，所以条索是微微卷曲的雀舌形，不是扁平状，白毫也因此保留得更多。烘青的火功比炒青轻，香气走的是清鲜一路，喝起来更柔。这一带的茶园多在山高雾重的环境里，芽叶长得慢，成茶的鲜浓感通常比平地茶园更足。"},{"type":"heading","level":3,"text":"兰花香与清鲜栗香"},{"type":"paragraph","text":"干茶形似雀舌、白毫披身、色微黄绿。汤色清碧微黄。香气是兰花香与清鲜栗香并存，闻起来清而不薄。入口鲜浓醇和，回甘持久，收敛感比炒青温和。叶底嫩黄成朵，冲开之后一根根立着，看着很舒服。它的耐泡度在三到四泡左右，第三泡香气会转向清甜，别泡到没味才换茶。"},{"type":"heading","level":3,"text":"水烧开后放两三分钟"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"控温","text":"水烧开后静置 2 至 3 分钟再注水，约 80 至 85℃。"},{"title":"注水","text":"沿杯壁缓注，便于观赏白毫与芽叶舒展。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡延长 10 至 15 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"info","title":"用玻璃杯","text":"玻璃杯最能看清白毫在水中浮动的样子，这也是这款茶最直观的一个看点；想闻香更集中，换成白瓷盖碗就行。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["上午工作学习","午后清口","春游户外后温饮"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，短期喝不完建议冷藏。绿茶氧化快，开封后当年内喝完为宜，放久了鲜爽会先走掉，剩下的只有苦涩。每次取茶用干勺，别用手抓。烘青绿茶对异味很敏感，别和香料、咖啡放在同一个格子里。50 g 按每天 3 g 算大约能喝两到三周，正好在风味最好的一段时间里喝完。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 0, 150, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('4941612647372570189', 'product_huangshan_maofeng_50:50g', '1232070612881933513', '50g罐装', 'CYT-TEA-HSMF-050-50g', 12800, 16800, 1, 1, 92, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('4406773509760064187', 'product_taiping_houkui_50', 'CYT-TEA-TPHK-050', 'product_taiping_houkui_50', '394928649089662440', '2426254520602417580', '["tea_taiping_houkui"]', '太平猴魁·猴坑兰香', '两叶抱一芽，极耐泡', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835685.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835685.jpg"]', '["绿茶","兰花香","耐泡"]', '[{"type":"paragraph","text":"两叶抱一芽、扁平挺直的太平猴魁，兰花香高长、极耐泡。这一罐 50 g 给喜欢「一条茶泡一下午」的人，也适合待客——外形特别，摆在杯里就有话说，不用你费劲介绍。50 g 看着不多，但耐泡度好，实际能喝的次数比同重量的绿茶多。"},{"type":"heading","level":3,"text":"猴坑的捏尖工艺"},{"type":"paragraph","text":"太平猴魁产自安徽省黄山市黄山区新明乡猴坑、猴岗、颜家一带。工艺是拣尖、杀青、捏尖整形、头烘、二烘、三烘三晾。最特别的是捏尖：杀青后的叶片要趁热一根根理直、捏平，两叶抱一芽，再反复烘晾定型。这也是它在绿茶里外形独一份的原因——别的绿茶讲究小和嫩，它偏偏又长又平，反着来。猴坑是传统核心产地，产量有限，市面上标着猴魁的茶价格差距很大，看外形是否扁平挺直、有没有断碎，比看包装管用。"},{"type":"heading","level":3,"text":"兰花香高长，极耐泡"},{"type":"paragraph","text":"干茶扁平挺直、苍绿匀润，两叶抱一芽。汤色清绿明亮。香气以兰花香为主，高而长，好几泡之后还在。入口鲜爽醇厚，收敛感明显但不刺，尾上回甘足。耐泡度在绿茶里算拔尖的，正常能冲到四五泡，这也是它单价高但折算下来不算贵的原因。投放时茶条立起来，续水也不会散，一整个下午看着它慢慢舒展本身就是乐趣。"},{"type":"heading","level":3,"text":"高身玻璃杯，根朝下"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"选器","text":"用高身透明玻璃杯，茶条才能立起来。"},{"title":"投茶","text":"根朝下、叶朝上直立投放，沿杯壁注水，别把茶条冲倒。"},{"title":"出汤","text":"第一泡 30 至 40 秒，之后逐次延长，可冲 4 至 5 泡。"}]},{"type":"tip","tone":"warning","title":"胃敏感者宜淡饮","text":"这款茶的茶多酚总量相对偏高，胃敏感的人建议淡饮，不要空腹喝浓的，投茶从 2 g 试起更稳妥。淡饮也更能喝出它的兰花香。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["待客","长时间办公","餐后解腻"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，冷藏保存更好。内含物丰富、相对耐存，但开封后仍建议当年内喝完。茶条长而扁平，罐子要够高，取茶时轻拿轻放，别把叶片压碎，碎末多了汤会浑。50 g 大概能冲十五六次，耐泡度摆在那里，折算下来单泡成本并不比口粮绿茶高。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 0, 160, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('2030305639212554462', 'product_taiping_houkui_50:50g', '4406773509760064187', '50g罐装', 'CYT-TEA-TPHK-050-50g', 16800, 21800, 1, 1, 48, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('7928109036518274841', 'product_luan_guapian_50', 'CYT-TEA-LAGP-050', 'product_luan_guapian_50', '394928649089662440', '540863087991848985', '["tea_luan_guapian"]', '六安瓜片·拉老火罐装', '无芽无梗，浓醇带栗炭香', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835104.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835104.jpg"]', '["绿茶","高火香"]', '[{"type":"paragraph","text":"唯一无芽无梗的单片叶绿茶，瓜子形、宝绿上霜，高火香与栗炭香突出。这一罐 50 g 是给喜欢浓醇口感的人准备的，口味清淡的人可能会觉得它有劲，第一次泡建议少投一点试试。它是绿茶里少见的「浓口」选项，配油腻的饭菜也不容易被压住。"},{"type":"heading","level":3,"text":"扳片与拉老火"},{"type":"paragraph","text":"六安瓜片产自安徽省六安市裕安区、金寨县、霍山县，齐头山与鲜花岭为核心产区。工艺是采摘扳片、炒生锅、炒熟锅、毛火、小火、拉老火。它是绿茶里唯一去掉芽和梗、只留单片叶的茶——「扳片」就是把叶片从嫩梢上掰下来。最后一道拉老火用很高的火温快速烘，叶面因此起了白霜，栗炭香也出来了，这道火是瓜片的招牌，火候不到就出不来那股香。因为没有芽头，它的滋味比一般绿茶更厚、更扛泡。"},{"type":"heading","level":3,"text":"高火香与栗炭香"},{"type":"paragraph","text":"干茶瓜子形、宝绿上霜、叶缘微翘。汤色黄绿明亮。香气以高火香与栗炭香为主，直接、有辨识度，闻一次就记得住。入口浓醇鲜爽，回甘强，滋味比多数绿茶更饱满。叶底黄绿匀亮，没有芽头也没有梗，展开来是一片片完整的叶。它不适合用太高的水温长时间闷，那会把火香变成焦苦味，快出汤反而更能喝出层次。"},{"type":"heading","level":3,"text":"别闷，闷了就苦"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"选器","text":"白瓷盖碗或瓷壶都合适。"},{"title":"出汤","text":"第一泡约 30 秒，之后逐次延长，可冲 4 至 5 泡。"},{"title":"注意","text":"不要长时间高温闷泡，闷久了苦涩会明显上升。"}]},{"type":"tip","tone":"warning","title":"火香型滋味偏浓","text":"胃敏感的人建议减量，别一上来就投 5 g，从 2 至 3 g 试起更稳妥，水温也可以略降一点。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["夏季消暑","餐后解腻","长时间办公","熬夜后次日上午温饮"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，远离气味浓烈的食材。拉老火后含水量很低，相对耐存，但仍建议当年内喝完。叶片薄而脆，取茶时别用力碾，碎末多了汤会浑，也更容易苦。打开后如果闻到明显的焦火味，可以敞开放半天再封起来，火气会散一些。50 g 按每次 3 g 算大约能喝十六七次，口味重的人用量会省一些。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用，且不能替代睡眠。"}]', 0, 170, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('6904268296185628590', 'product_luan_guapian_50:50g', '7928109036518274841', '50g罐装', 'CYT-TEA-LAGP-050-50g', 13800, 17800, 1, 1, 76, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('7731518694206293576', 'product_xinyang_maojian_50', 'CYT-TEA-XYMJ-050', 'product_xinyang_maojian_50', '394928649089662440', '1141951895934751295', '["tea_xinyang_maojian"]', '信阳毛尖·熟栗香罐装', '细圆光直，浓醇回甘', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195836277.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195836277.jpg"]', '["绿茶","熟栗香"]', '[{"type":"paragraph","text":"细圆光直多白毫的信阳毛尖，熟栗香清晰、回甘明显。这一罐 50 g 是北方茶区里最有代表性的针形炒青，滋味比江南绿茶更厚实，适合口味偏重、总觉得绿茶「不够味」的人。50 g 罐装按每天 3 g 算能喝半个月以上，价格也是日常口粮的水平。"},{"type":"heading","level":3,"text":"生锅与熟锅"},{"type":"paragraph","text":"信阳毛尖产自河南省信阳市浉河区、平桥区、罗山县、光山县等地，五云两潭一寨是核心山头。工艺是摊放、生锅杀青、熟锅理条抓条、初烘、摊凉、复烘、拣剔。它的条索是「理」出来的：熟锅里用手把茶叶一根根理直、抓条，细圆光直的外形和满披的白毫都靠这一手，机器做不出那种紧细的针形。河南茶区生长期比江南晚，芽叶积累的内含物多，这也是它滋味更浓的原因。"},{"type":"heading","level":3,"text":"熟栗香清晰，浓醇回甘"},{"type":"paragraph","text":"干茶细圆光直、白毫明显。汤色嫩绿明亮。香气以熟栗香为主，清晰扎实，尾上有清香。入口浓醇鲜爽，回甘明显，收敛感适中。它的滋味比江南的龙井、碧螺春更厚实一些，泡浓了也不容易散，所以很适合习惯喝浓茶的人。第三泡之后栗香会转淡，甜感浮上来，这时候别急着倒掉，尾水的甜是它的加分项。"},{"type":"heading","level":3,"text":"先润茶，再沿壁注满"},{"type":"steps","items":[{"title":"润茶","text":"先注少量水润茶，让茶条吸水舒展。"},{"title":"注水","text":"再沿杯壁注满，避免沸水直冲，使毫香尽失。"},{"title":"控温","text":"水温 80 至 85℃，水烧开后稍等再注。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡延长 10 至 15 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"info","title":"玻璃杯还是盖碗","text":"想看清白毫就选玻璃杯，想闻香更集中就用白瓷盖碗，两种器皿泡出来的味道差别不大。盖碗出汤更快，更适合在办公室用。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["上午提神","午后容易犯困的时候","餐后解腻","出差办公常备"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，冷藏可延长保鲜期。白毫与栗香容易散失，开封后建议当年内喝完。出差带着的话，用小罐分装比整罐带走更靠谱，少开合、少受潮。玻璃杯泡完记得及时清洗，针形茶的碎末容易挂在杯壁上，影响下一次的味道。50 g 按每天 3 g 算大约能喝半个月以上。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 0, 180, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('3366249355178227375', 'product_xinyang_maojian_50:50g', '7731518694206293576', '50g罐装', 'CYT-TEA-XYMJ-050-50g', 12800, 16800, 1, 1, 104, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('3943482287062246249', 'product_anji_baicha_50', 'CYT-TEA-AJBC-050', 'product_anji_baicha_50', '394928649089662440', '6061920329024784346', '["tea_anji_baicha"]', '安吉白茶·鲜爽小罐', '名为白茶实为绿茶，几乎不苦', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833999.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195833999.jpg"]', '["绿茶","鲜爽入门"]', '[{"type":"paragraph","text":"名为白茶、实为绿茶的安吉白茶，几乎喝不到苦涩。如果身边有人总说「绿茶太苦」，这款大概是最适合递过去的一杯；它也是很多人的第一罐绿茶，喝完之后再回头喝别的，会更容易分辨差别。"},{"type":"heading","level":3,"text":"白化品种配绿茶工艺"},{"type":"paragraph","text":"安吉白茶产自浙江省湖州市安吉县溪龙乡、天荒坪等地。它叫白茶，但按工艺分类属于绿茶：原料来自白化品种，春季气温低时新芽呈玉白色，采下后走的是摊放、杀青、理条做形、初烘、摊凉、复烘这套绿茶工艺。白化期芽叶里的氨基酸比例偏高，这就是它鲜甜、几乎不苦的原因，也是它名字容易让人误会的地方。白化期很短，采摘窗口集中，所以真正的安吉白茶上市时间紧、产量也不算大。"},{"type":"heading","level":3,"text":"极鲜爽，几乎无苦涩"},{"type":"paragraph","text":"干茶挺直略扁、色泽翠绿间玉白。汤色清澈明亮，近乎浅绿。香气是清香与淡淡兰花香。入口极鲜爽、甘甜，苦涩感很低，即使泡得稍久也不容易苦。汤感柔，回甘清甜。它是那种不常喝茶的人也能一口喝下去的绿茶，对初学者非常友好。也正因为不苦，它不太适合追求浓强口感的场合，用来做冷泡反而更出彩。"},{"type":"heading","level":3,"text":"75 至 80℃，别用沸水"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"控温","text":"水温 75 至 80℃，过高的水温会破坏它的鲜甜感。"},{"title":"注水","text":"用透明玻璃杯，沿杯壁缓注，别直冲芽心。"},{"title":"出汤","text":"第一泡 20 至 25 秒，之后每泡适当延长，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"success","title":"怕苦的人从这里开始","text":"水温下调到 75℃、投茶减到 2 g，鲜甜感还在，苦涩几乎没有；想更甜就用一比一百的冷水冷藏六小时。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["怕苦涩人群入门","上午提神","午后清口","待客"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，冷藏可延长保鲜期。鲜爽是它的核心优势，开封后建议当年内喝完，否则甜感会一点点退掉，只剩平淡。冷藏取用时先让罐子回到室温再打开，避免冷凝水打湿茶叶。50 g 按每天 3 g 算大约能喝两到三周，正好在最好喝的那段时间里消耗完。它的刺激性相对普通绿茶更低，但并非没有咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 0, 190, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('1937162057119135521', 'product_anji_baicha_50:50g', '3943482287062246249', '50g罐装', 'CYT-TEA-AJBC-050-50g', 14800, 18800, 1, 1, 88, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('8736398593056797357', 'product_zhuyeqing_50', 'CYT-TEA-EMZYQ-050', 'product_zhuyeqing_50', '394928649089662440', '841804795849658707', '["tea_emei_zhuyeqing"]', '峨眉竹叶青·嫩栗香罐装', '扁平似竹叶，高山鲜醇', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195836278.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195836278.jpg"]', '["绿茶","嫩栗香"]', '[{"type":"paragraph","text":"扁平挺直、两端尖细似竹叶的峨眉竹叶青，嫩栗香清雅、回甘明显。这一罐 50 g 来自海拔 800 至 1200 米的茶园，走的是清雅一路，不冲不抢，办公室泡一杯能安安静静喝一上午。50 g 按每天 3 g 算大约能喝两到三周，是这几款绿茶里最适合常备的一档。"},{"type":"heading","level":3,"text":"峨眉山的高海拔茶园"},{"type":"paragraph","text":"峨眉竹叶青产自四川省乐山市峨眉山市，茶园分布在峨眉山海拔 800 至 1200 米的区域。工艺是摊放、杀青、理条整形、挥锅做形、筛分定级。理条整形和挥锅做形决定了它两头尖细、扁平挺直的竹叶形——名字里的「竹叶」说的就是形状。高海拔茶园昼夜温差大，芽叶生长慢，成茶的鲜醇度通常更整齐，涩感也更容易压住。采摘期集中在春季，芽叶匀整度高，这也是它外形好看的原因之一。"},{"type":"heading","level":3,"text":"嫩栗香清雅，回甘明显"},{"type":"paragraph","text":"干茶扁平挺直、两端尖细、色翠绿。汤色黄绿清澈。香气是嫩栗香为主，清雅不冲，不追求第一下的冲击力。入口鲜醇爽口，汤感干净，回甘明显，苦涩轻微。整体风格介于龙井的豆香和毛峰的兰花栗香之间，属于清雅那一档。叶底嫩绿匀整，泡开后形态仍然挺直，不像有些绿茶一泡就散。"},{"type":"heading","level":3,"text":"玻璃杯或盖碗，80 至 85℃"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"控温","text":"水温 80 至 85℃，别用刚烧开的沸水。"},{"title":"注水","text":"沿杯壁缓缓注水，避免直冲芽心。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡延长 10 至 15 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"warning","title":"别配重麻辣的菜","text":"麻辣会盖掉嫩栗香，建议餐后隔一会儿再泡，或者留到两餐之间喝。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["上午提神","川菜餐后解腻","办公常备","待客"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，冷藏更好。绿茶不耐存，开封后尽量当年内喝完；罐子别放在窗台或车内，光照和高温会让它很快变味。50 g 按每天 3 g 算大约能喝半个月到三周，正好在一个保鲜周期内喝完。办公室常备的话，可以分装一小罐放在抽屉里，其余冷藏，减少反复开合。含咖啡因，避免空腹浓饮，睡前 4 至 6 小时不宜饮用。"}]', 0, 200, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('6425896509058248379', 'product_zhuyeqing_50:50g', '8736398593056797357', '50g罐装', 'CYT-TEA-EMZYQ-050-50g', 15800, 20800, 1, 1, 67, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('6055128975272617517', 'product_shoumei_100', 'CYT-TEA-SM-100', 'product_shoumei_100', '394928649089662440', '5117341104257652868', '["tea_shoumei"]', '寿眉·陈韵小饼', '甜水感突出，煮饮更出味', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835684.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835684.jpg"]', '["白茶","煮饮推荐"]', '[{"type":"paragraph","text":"梗叶连枝、甜水感突出的寿眉，100 g 压成小饼。新茶清甜，放几年转枣香，煮着喝最有味道，也是这几款白茶里单价最低、最不费钱的一档日常口粮。"},{"type":"heading","level":3,"text":"白茶里产量最大的品类"},{"type":"paragraph","text":"寿眉产自福建省宁德市、南平市，福鼎、政和、建阳等地。原料采一芽三叶至四叶，或抽针后的对夹叶，经日光或室内萎凋、干燥，再压制成饼。它不炒不揉，工艺看着简单，但萎凋的时长与温湿度控制决定了成品是清甜还是青气。压饼之后体积小了，也方便存放观察风味变化，是白茶里最适合拿来「放着看」的一档。原料成熟度高、梗叶比例大，反而让它比银针更耐煮，也更适合大壶泡。"},{"type":"heading","level":3,"text":"从青草香到枣香"},{"type":"paragraph","text":"干茶饼面梗叶连枝、色泽黄褐带绿。新茶汤色浅黄，香气偏青草香与清甜香；存放之后汤色转橙红，香气转向枣香。入口醇厚顺滑，甜水感是它最突出的地方，不苦不涩，汤感有厚度。传统经验认为存放久了会出药香，这里只作风味描述，不代表任何功效。同一饼茶拆开分几次喝，前后段的滋味也会有变化，前几泡偏香，后几泡偏甜。"},{"type":"heading","level":3,"text":"煮饮是它最好的呈现方式"},{"type":"steps","items":[{"title":"备茶","text":"6 g 茶配 150 ml 水，约 1:25，投茶量比多数白茶大。"},{"title":"冲泡","text":"沸水 95 至 100℃，第一泡 20 至 30 秒，之后每泡顺延 10 至 20 秒，可冲 6 至 8 泡。"},{"title":"煮饮","text":"5 g 茶加 500 ml 水，煮沸后转小火 3 至 5 分钟，可复煮 2 至 3 次。"},{"title":"陈茶","text":"存放较久的可以适当闷到 30 至 45 秒，滋味出得更足。"}]},{"type":"tip","tone":"warning","title":"仓储安全","text":"寿眉较适宜长期存放，但前提是仓储干净。出现霉斑、酸馊或刺鼻异味的茶必须丢弃，不可饮用，别拿「老茶」当借口。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["秋冬煮饮","油腻餐后","冷泡","围炉煮茶"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 饼装。常温避光、密封、干燥、无异味、低湿保存；茶饼与散茶都要防潮，避免与气味浓重的物品同放。撬饼时沿着压制纹理下针，尽量保持叶片完整，撬开的部分装进小罐尽快用完。100 g 大约能煮十几次，家里人多的时候一饼消耗得很快；一个人喝或者喝得慢，建议分一半单独密封收着。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 210, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('2284998880854596672', 'product_shoumei_100:100g', '6055128975272617517', '100g饼装', 'CYT-TEA-SM-100-100g', 9800, 12800, 1, 1, 118, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('2390718231656874602', 'product_mengding_huangya_50', 'CYT-TEA-MDHY-050', 'product_mengding_huangya_50', '394928649089662440', '6201100048852134144', '["tea_mengding_huangya"]', '蒙顶黄芽·甜香罐装', '闷黄偏长，甜香带花香', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835105.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835105.jpg"]', '["黄茶","甜香"]', '[{"type":"paragraph","text":"扁直显毫、甜香浓郁的蒙顶黄芽，闷黄时间偏长，是一款把甜感做得很足的黄芽茶。产量一直不大，想尝黄茶里偏甜的那一路，可以从它开始；它也是这几款黄茶里最适合拿来给不常喝茶的人试的一杯。50 g 大约能泡十六七次，想认真认识黄茶，这一罐够建立完整的印象。"},{"type":"heading","level":3,"text":"蒙顶山的黄芽做法"},{"type":"paragraph","text":"蒙顶黄芽产自四川省雅安市名山区蒙顶山。工艺是采摘单芽或一芽一叶初展，经杀青、初包闷黄、复锅、复包闷黄、三炒、摊放、烘焙。它要闷两次、炒三次，闷黄时间比多数黄茶都长，所以甜香更浓、苦涩更低。工序多、手工重，产量一直不大，同价位里愿意做这一路的厂家并不多。闷黄每多一次，风险也多一分——温度偏高会闷出浊味，所以做得好的蒙顶黄芽，甜得很干净。"},{"type":"heading","level":3,"text":"甜香浓郁，带花香"},{"type":"paragraph","text":"干茶扁直显毫、色泽嫩黄。汤色黄亮清澈。香气是甜香为主，带花香与嫩香，浓度明显，比多数黄茶更外放。入口甘醇鲜爽，甜感贯穿始终，苦涩感非常轻。整体比霍山黄芽更甜、更厚一些，泡到第三泡甜味还在，这是它比较讨喜的地方。叶底嫩黄匀亮，芽叶完整，泡开后不散。"},{"type":"heading","level":3,"text":"玻璃杯观形，盖碗衬色"},{"type":"steps","items":[{"title":"备茶","text":"3 g 茶配 150 ml 水，约 1:50。"},{"title":"控温","text":"水温 80 至 85℃，忌沸水、忌久闷。"},{"title":"选器","text":"玻璃杯可观形，白瓷盖碗更衬黄亮的汤色。"},{"title":"出汤","text":"第一泡 20 至 30 秒，之后每泡延长约 10 秒，可冲 3 至 4 泡。"}]},{"type":"tip","tone":"info","title":"给不常喝茶的人","text":"甜感足、苦涩轻，接受门槛比绿茶低。不常喝茶的人可以从这款入门，第一杯别泡太浓就行。续水时水温保持稳定，甜感会更连贯，别用刚烧开的沸水直接冲。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["上午温和提神","下午茶","餐后淡饮","不常喝茶者的入门选择"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防潮、防异味，短期喝不完可冷藏，避免与香料、咖啡同放。甜香与鲜爽是主要看点，宜趁鲜饮用，别放到第二年才想起来。闷黄工序多的茶香气偏外放，也更容易散，开封后尽量三个月内喝完。50 g 大约能泡十六七次，按每周三四杯算能喝一个多月，刚好在一个保鲜周期内。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 220, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('557404475768720493', 'product_mengding_huangya_50:50g', '2390718231656874602', '50g罐装', 'CYT-TEA-MDHY-050-50g', 17800, 22800, 1, 1, 43, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('7888070500073259047', 'product_rougui_100', 'CYT-TEA-WYRG-100', 'product_rougui_100', '394928649089662440', '2466608346967166575', '["tea_wuyi_rougui"]', '武夷肉桂·桂皮香罐装', '辛锐突出，回甘快，岩茶进阶之选', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835106.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835106.jpg"]', '["乌龙茶","桂皮香"]', '[{"type":"paragraph","text":"桂皮香辛锐突出的武夷肉桂，回甘快、收敛性强。这一罐 100 g 是岩茶里最能喝出「品种香」的一款，适合已经喝过几款乌龙、想再往前走一步的人；第一次喝建议把投茶量减到 6 g 左右。100 g 按每次 8 g 算能冲十二三次，足够把前中后段的变化完整喝一遍。"},{"type":"heading","level":3,"text":"正岩山场与炭焙"},{"type":"paragraph","text":"武夷肉桂产自福建省南平市武夷山市正岩产区，牛栏坑、马头岩、慧苑坑等都是有名气的山场。工艺是萎凋、做青、杀青、揉捻、初焙、复焙、炭焙炖火。它的辨识度来自品种本身的桂皮香，做青把这份辛锐的香气提出来，炭焙再把香气压进汤里，让它不只是闻着香，喝下去也有。山场不同，辛锐的程度和回甘的速度会有差别，这也是岩茶讲究山场的原因；同是肉桂，坑涧里的往往更细，岗上的更直白。"},{"type":"heading","level":3,"text":"辛锐、回甘快"},{"type":"paragraph","text":"干茶条索紧结乌褐油润。汤色橙黄明亮。香气以桂皮香为主，辛锐突出，中间带焙火香。入口辛锐，收敛性强，回甘来得快，几泡之后喉部有明显的留存感。它不像大红袍那样以醇厚见长，个性更鲜明，第一口就能分辨出和别的岩茶不一样。泡到五六泡之后，辛锐感会退一些，桂皮香转成更柔的甜香，这一段反而是很多人最喜欢的部分。"},{"type":"heading","level":3,"text":"沸水高冲，前几泡快出"},{"type":"steps","items":[{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14，口味轻的可以减到 6 g。"},{"title":"选器","text":"紫砂壶或白瓷盖碗都合适。"},{"title":"注水","text":"沸水高冲，激发桂皮香。"},{"title":"出汤","text":"第一泡 5 至 10 秒，之后每泡延长 5 至 10 秒，前几泡一定要快。"}]},{"type":"tip","tone":"warning","title":"辛锐感偏强","text":"肉桂的辛锐刺激感较强，胃敏感的人宜减量，不要空腹喝浓的，也别在睡前喝。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["重油餐后","秋冬暖饮","进阶品鉴","待客"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、避光、防潮、防异味，阴凉处存放。焙火程度不同，退火时间也不同，以产品包装标注为准。刚开罐如果闻到明显火味，密封放两三周再喝会更顺。肉桂的香气辛锐，建议单独存放，别和清香型乌龙挤在一个罐子里互相串味。100 g 按每次 8 g 算能冲十二三次，够把前中后段的变化完整喝一遍。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 230, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('6873879643078276849', 'product_rougui_100:100g', '7888070500073259047', '100g罐装', 'CYT-TEA-WYRG-100-100g', 21800, 28800, 1, 1, 54, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('5341559883380627643', 'product_dancong_100', 'CYT-TEA-FHDC-100', 'product_dancong_100', '394928649089662440', '7565560547837918852', '["tea_fenghuang_dancong"]', '凤凰单丛·蜜兰香罐装', '高香耐冲，快出汤更显香', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834000.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834000.jpg"]', '["乌龙茶","蜜兰香"]', '[{"type":"paragraph","text":"天然花果香极高长的凤凰单丛，蜜兰香是其中最经典的香型。这一罐 100 g 给喜欢高香型乌龙的人，也适合想拿它试试冷泡的人——香型外放，冷泡之后香气依然清楚，不容易被水稀释掉。100 g 按每次 8 g 算能冲十二三次，耐泡度高，一罐能喝上一阵子。"},{"type":"heading","level":3,"text":"凤凰山的一树一香"},{"type":"paragraph","text":"凤凰单丛产自广东省潮州市潮安区凤凰镇凤凰山，乌岽山是核心产区。工艺是晒青、晾青、碰青摇青、杀青、揉捻、初焙、复焙足火。单丛的「单」来自传统做法——单株采制、单株成茶，不同株系的香气各不相同，蜜兰香、银花香、黄枝香各成一格。碰青摇青做得足，香气才高长，这也是它比多数乌龙更「香得外放」的原因。同一个山头，不同株系的价格能差好几倍，香型名字就是它的身份证。"},{"type":"heading","level":3,"text":"花果香高长，浓醇回甘"},{"type":"paragraph","text":"干茶条索紧结挺直、色泽乌褐。汤色橙黄明亮。香气是这款茶的核心：花果香极高长，蜜兰香型带明显的甜花香，落杯之后香气仍在。入口浓醇鲜爽，山韵明显，回甘强，耐泡度高。它和岩茶的区别在于——岩茶重在汤里的厚度，单丛重在香气的高与长。泡到后面几泡香气会递减，但汤里的甜感还在，尾水不难喝。"},{"type":"heading","level":3,"text":"薄胎白瓷盖碗，极快出汤"},{"type":"steps","items":[{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"选器","text":"薄胎白瓷盖碗最利显香，紫砂会吃掉一部分香气。"},{"title":"控温","text":"全程 100℃ 沸水。"},{"title":"出汤","text":"第一泡约 5 秒，高香型宜极快出汤，之后每泡延长 5 至 10 秒，可冲 10 至 12 泡。"}]},{"type":"tip","tone":"success","title":"先闻盖香，再喝茶汤","text":"高香型的香气最怕闷。出汤之后先闻盖香，再喝茶汤，一杯茶能喝出两种体验，这也是潮汕功夫泡的乐趣所在。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["油腻餐后","下午提神","冷泡调饮","待客"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、避光、防潮、防异味，阴凉处存放。炭焙型退火后香气更稳，以产品包装标注为准。高香型的香气衰减比汤感快，开封后建议半年内喝完，放久了香型会变模糊。泡单丛别用紫砂，紫砂会吸走一部分香气，白瓷盖碗最合适。100 g 按每次 8 g 算能冲十二三次，耐泡度高，一罐够喝上一阵。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 240, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('6441419241258606145', 'product_dancong_100:100g', '5341559883380627643', '100g罐装', 'CYT-TEA-FHDC-100-100g', 19800, 25800, 1, 1, 61, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('8655877227278988410', 'product_dongding_100', 'CYT-TEA-DDWL-100', 'product_dongding_100', '394928649089662440', '4126276344076852981', '["tea_dongding_oolong"]', '冻顶乌龙·焙火球茶', '醇厚甘润，喉韵足', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834566.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834566.jpg"]', '["乌龙茶","焙火香"]', '[{"type":"paragraph","text":"半球形紧结墨绿的冻顶乌龙，焙火香里带花香，醇厚甘润、喉韵佳。它是台湾中发酵中焙火的代表，冲泡宽容度高，新手也不容易泡坏，很适合当作每天下午的那一壶。100 g 按每次 7 g 算大约能冲十四五次，一周泡三次能喝一个多月。"},{"type":"heading","level":3,"text":"鹿谷乡的布球揉捻"},{"type":"paragraph","text":"冻顶乌龙产自台湾南投县鹿谷乡冻顶山，海拔约 700 至 1200 米。工艺是日光萎凋、室内萎凋与搅拌做青、杀青、揉捻、初干、布球揉捻、复干与焙火。布球揉捻是它成形的关键：用布把茶叶包成球反复揉压，茶叶因此变成紧结的半球形，也更容易在焙火后保住香气。中发酵配中焙火，让它既有乌龙的香，又比清香型乌龙更稳；因为揉得紧，它的耐泡度和耐存放度都更好，也不容易因为水温高一点就发苦。"},{"type":"heading","level":3,"text":"焙火香、米香与花香"},{"type":"paragraph","text":"干茶半球形紧结、墨绿油润。汤色金黄明亮。香气是焙火香打头，中间有米香，尾上是花香，三层比较分明。入口醇厚甘润，喉韵佳，回甘慢但持久。它比清香型乌龙更耐放，也更不容易因为水温高一点就发苦，日常泡起来压力小。冷掉之后汤感会略收紧，但甜味还在，不像有些清香乌龙凉了就发涩。"},{"type":"heading","level":3,"text":"95 至 100℃，第一泡稍等"},{"type":"steps","items":[{"title":"备茶","text":"7 g 茶配 120 ml 水，约 1:17。"},{"title":"温器","text":"盖碗或紫砂壶烫透，让紧结的球茶更容易舒展。"},{"title":"注水","text":"保持 95 至 100℃，第一泡可稍等它舒展。"},{"title":"出汤","text":"第一泡 10 至 20 秒，之后每泡延长 5 至 10 秒，可冲 7 至 8 泡。"}]},{"type":"tip","tone":"info","title":"第一泡别急着加时间","text":"半球形的茶第一泡不容易展开，别急着延长坐杯，第二泡开始滋味才真正出来，那时的汤感最完整。第二泡起再考虑逐泡加时间。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["餐后解腻","下午提神","秋冬暖饮","待客"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、避光、防潮、防异味，阴凉处存放。焙火型退火后风味更稳，以产品包装标注为准。球茶比条索茶更耐放，开封后一年内喝完基本没问题。半球形紧结，一罐 100 g 按每次 7 g 算大约能冲十四五次，日常一周泡两三次，够喝一个多月。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 250, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('4815020231539387670', 'product_dongding_100:100g', '8655877227278988410', '100g罐装', 'CYT-TEA-DDWL-100-100g', 18800, 24800, 1, 1, 72, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('322321113596279292', 'product_jinjunmei_50', 'CYT-TEA-JJM-050', 'product_jinjunmei_50', '394928649089662440', '1774819018337183817', '["tea_jinjunmei"]', '金骏眉·单芽小罐', '花果蜜香，汤色金黄透亮', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835103.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835103.jpg"]', '["红茶","单芽"]', '[{"type":"paragraph","text":"只采单芽制作的金骏眉，花果蜜香复合、汤色金黄透亮。这是桐木关正山产区里最细嫩的一路红茶，也是红茶里送礼最体面的选择之一；自己喝的话，建议清饮，别辜负了它的香气。50 g 按每次 3 g 算能冲十六七次，送礼体面，自己慢慢喝也不至于放坏。"},{"type":"heading","level":3,"text":"桐木关的单芽红茶"},{"type":"paragraph","text":"金骏眉产自福建省南平市武夷山市桐木关正山产区，是当地在传统正山小种基础上做出的创新红茶。工艺是采摘单芽、萎凋、揉捻、发酵、干燥——工序看着不复杂，但原料只用单芽，几万颗芽头才做一斤茶，成本主要高在这里。也因为没有熏焙这道工序，它的香气是清爽的花果蜜香，不带松烟，和传统烟种完全是两种风格。同产区同样叫金骏眉的茶，芽头匀整度差别很大，看干茶是否细紧、金毫是否自然，比看包装上的字管用。"},{"type":"heading","level":3,"text":"花果蜜香，汤色金黄"},{"type":"paragraph","text":"干茶条索细紧、金毫显露。汤色金黄透亮，不是常见的红艳，这是它比较好认的一点。香气是花果蜜香复合，蜜香与桂圆香在尾上。入口鲜活甘爽、细腻，汤感轻，回甘悠长。它不是靠浓强度取胜的茶，胜在细——投茶多了反而会把那份细腻压掉，三克就够。续泡到第五泡香气转淡，甜感仍在，尾水别急着倒。"},{"type":"heading","level":3,"text":"芽头细嫩，忌沸水"},{"type":"steps","items":[{"title":"备茶","text":"投茶 3 至 5 g，配 150 ml 水，约 1:30 至 1:50。"},{"title":"控温","text":"水温 85 至 90℃，芽头细嫩，忌沸水。"},{"title":"选器","text":"白瓷盖碗最合适，能看清金黄的汤色。"},{"title":"出汤","text":"第一泡 10 至 20 秒，之后每泡延长 5 至 10 秒，可冲 5 至 7 泡。"}]},{"type":"tip","tone":"success","title":"清饮就好","text":"建议不加奶不加糖清饮，加料会把花果蜜香盖住，这款茶的价值就在香气里，加奶反而可惜。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["上午提神","待客送礼","清饮细品"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"50 g 罐装，密封、避光、防异味，阴凉干燥处常温保存。芽头细嫩、香气易散，开封后尽量在短时间内喝完，别一次买太多囤着。取茶用干勺，避免手汗沾到芽头，芽头一旦受潮就很难恢复。50 g 按每次 3 g 算能冲十六七次，作为待客和送礼用刚好，自己每天喝也差不多能撑三周。红茶含咖啡因，避免空腹浓饮与睡前 6 小时内饮用。"}]', 1, 260, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('2920793726993209886', 'product_jinjunmei_50:50g', '322321113596279292', '50g罐装', 'CYT-TEA-JJM-050-50g', 26800, 35800, 1, 1, 40, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('7207106408208741123', 'product_dianhong_100', 'CYT-TEA-DH-100', 'product_dianhong_100', '394928649089662440', '3804420247279721210', '["tea_dianhong"]', '滇红·金毫罐装', '浓强鲜爽，奶茶基底好选', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834565.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834565.jpg"]', '["红茶","浓强"]', '[{"type":"paragraph","text":"金毫显露、甜香蜜香浓郁的滇红，浓强鲜爽、汤感厚重。这一罐 100 g 是奶茶基底里最稳的一档，也适合早晨需要一杯有分量的茶的时候；同样泡法，它比小叶种红茶更经得起加奶加糖。100 g 按每次 5 g 算大约能冲二十次，家里常备一罐够喝一个季度。"},{"type":"heading","level":3,"text":"云南大叶种的底子"},{"type":"paragraph","text":"滇红产自云南省临沧市，凤庆县是核心产区，保山、西双版纳、普洱等地亦有生产。工艺是萎凋、揉捻、发酵、干燥。它用的是云南大叶种，叶片肥厚、内含物足，所以汤感厚重、浓强度高，金毫也特别明显。同样是红茶，滇红走的是「浓」这条路，和走「细」的金骏眉正好互补，喝茶口味重的人往往更认它。大叶种的耐高温特性，让它即使水温高一些也不容易出酸味，泡法上比细嫩红茶宽松得多。"},{"type":"heading","level":3,"text":"甜香蜜香，汤感厚重"},{"type":"paragraph","text":"干茶条索肥壮、金毫显露。汤色红浓明亮。香气是甜香与蜜香为主，带焦糖香。入口浓强鲜爽，汤感厚重，回甘明显。它经得起高温，也经得起加奶加香料，泡浓了也不容易发涩，所以是很多人家里常备的那一罐红茶。用它做奶茶，茶味能压得住奶，不必靠多放茶叶来补。"},{"type":"heading","level":3,"text":"95 至 100℃，大叶种耐高温"},{"type":"steps","items":[{"title":"备茶","text":"5 g 茶配 150 ml 水，约 1:30。"},{"title":"控温","text":"95 至 100℃，大叶种耐高温。"},{"title":"出汤","text":"第一泡 5 至 10 秒，之后每泡延长 5 至 10 秒，可冲 5 至 7 泡。"},{"title":"调饮","text":"做奶茶可以下锅煮并适当加浓，茶味才压得住奶。"}]},{"type":"tip","tone":"info","title":"先看清是哪种滇红","text":"红碎茶类的滇红通常只冲 1 至 2 泡，条索完整的工夫红茶可以冲到 5 至 7 泡，买之前留意形态。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["早晨提神","奶茶基底","香料调饮","寒冷天气"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 罐装，密封、干燥、避光、防异味，常温保存。金毫显露的茶容易吸潮，开封后注意防潮，梅雨季尤其别敞着口放。它耐高温也耐调饮，是家里常备最不容易浪费的一罐，凉了、浓了都还能入口。100 g 按每次 5 g 算大约能冲二十次；做奶茶的话用量会大一些，两三次就是一份茶底。红茶含咖啡因，避免空腹浓饮与睡前 6 小时内饮用。"}]', 0, 270, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('7168731502656531119', 'product_dianhong_100:100g', '7207106408208741123', '100g罐装', 'CYT-TEA-DH-100-100g', 11800, 15800, 1, 1, 120, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('3981331203991140186', 'product_fuzhuan_300', 'CYT-TEA-AHFZ-300', 'product_fuzhuan_300', '394928649089662440', '3317797424962167599', '["tea_anhua_fuzhuan"]', '安化茯砖·金花砖装', '菌花香明显，煮饮最佳', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834567.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195834567.jpg"]', '["黑茶","菌花香"]', '[{"type":"paragraph","text":"以「金花」为品质特征的安化茯砖，菌花香突出、滋味醇厚带甜。300 g 一砖，能泡能煮，是一家人一起喝最划算的一档黑茶；一砖可以喝很久，取茶时按需撬散就行。"},{"type":"heading","level":3,"text":"发花是它的一道工序"},{"type":"paragraph","text":"安化茯砖产自湖南省益阳市安化县，益阳、临湘等地亦有生产。工艺是杀青、揉捻、渥堆、干燥、筛分、蒸压成砖、发花、复干。发花是茯砖区别于其他黑茶的关键一步：砖体在特定温湿度下培养出冠突散囊菌，也就是常说的「金花」，菌花香就是这么来的。金花多、分布均匀，是判断品质的直观依据之一，也是茯砖最有辨识度的外观特征。这一步对环境要求很严，温度湿度不对就发不出花，所以茯砖的门槛其实比多数黑茶都高。"},{"type":"heading","level":3,"text":"菌花香与醇厚甜感"},{"type":"paragraph","text":"干茶砖面平整、色泽黑褐，掰开能看到分布的金黄色颗粒。汤色红黄明亮。香气以菌花香为主，带陈香与甜香，辨识度很高，闻过一次就记得住。入口醇厚顺滑、甜醇，几乎没有苦涩，汤感厚实，耐煮耐泡。煮出来的汤比泡的更完整，也更容易让一家人分着喝；泡到后段再转煮，一砖能出很多水。"},{"type":"heading","level":3,"text":"先撬散，煮饮最完整"},{"type":"steps","items":[{"title":"撬茶","text":"沿砖面纹理撬散，尽量保持叶片完整，撬好的茶放在小罐里防潮。"},{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"冲泡","text":"沸水润洗一至两遍，再快出汤，之后逐泡延长，可冲 10 至 15 泡。"},{"title":"煮饮","text":"5 至 8 g 配 500 ml 冷水，煮沸转小火 3 至 5 分钟，后段转煮风味更完整。"}]},{"type":"tip","tone":"warning","title":"饮用与仓储提醒","text":"砖茶类氟含量相对较高，不建议长期大量饮用熬煮的浓砖茶；出现霉斑、酸馊或刺鼻异味的砖茶不可饮用。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["重油餐后","早晨温饮","秋冬煮饮","家庭共饮"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"300 g 砖装。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味的物品同放。整砖不喝时保持原包装，撬开的部分装进小罐尽快用完，别让碎茶长期敞着。金花是发花工序的结果，不是越放越多，别把长毛的砖当成年份的证明。300 g 按每次 8 g 算能冲三十多次，煮饮用量更省，一砖够一家人喝很久。陈化结果取决于原料、工艺与仓储，并非年份越久越好。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 1, 280, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('3753036855644133516', 'product_fuzhuan_300:300g', '3981331203991140186', '300g砖装', 'CYT-TEA-AHFZ-300-300g', 13800, 18800, 1, 1, 58, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('3786075591240560165', 'product_tuocha_100', 'CYT-TEA-XGTC-100', 'product_tuocha_100', '394928649089662440', '7330552595416293242', '["tea_xiaguan_tuocha"]', '下关沱茶·碗臼小沱', '一块一泡，陈香带烟香', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835686.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835686.jpg"]', '["黑茶","便携"]', '[{"type":"paragraph","text":"碗臼形的下关沱茶，100 g 小沱，一块一泡。陈香与烟香并存，出差带着最方便，也是这几款黑茶里单价最低的一款，想试试紧压茶的风味可以从它入门。100 g 一沱能泡十几次，出差时揣几块也不占地方。"},{"type":"heading","level":3,"text":"下关的拼配与压制"},{"type":"paragraph","text":"下关沱茶产自云南省大理白族自治州大理市下关。工艺是筛分拼配、蒸软、揉压成碗臼形、干燥、陈化。它最有特点的是拼配——不同产区、不同等级的毛茶按比例拼在一起，取长补短，风格因此比较稳定，不同批次之间不会差太远。下关气候干燥，利于自然陈化，这也是当地做紧压茶的一个天然条件。碗臼形中间凹、边缘厚，压制得紧实，既方便运输，也让茶叶在后期的转化更慢、更均匀。"},{"type":"heading","level":3,"text":"陈香与烟香"},{"type":"paragraph","text":"干茶碗臼形紧结、色泽褐润。汤色橙黄明亮。香气里陈香与烟香并存，烟香不是缺陷，是这一类紧压茶的传统风格之一，喜欢的人正是冲着它来的。入口醇厚、回甘、顺滑，汤感有厚度。要注意生沱与熟沱的风格差别很大，买之前看清标注，别把生沱当成熟沱来喝。小沱一块一泡省去了撬茶的麻烦，出差时随身带几块也不占地方。"},{"type":"heading","level":3,"text":"一块一泡，沸水润洗"},{"type":"steps","items":[{"title":"取茶","text":"100 g 小沱可以一块一泡，大沱沿边缘撬散。"},{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"润洗","text":"沸水润洗一至两遍后快出汤。"},{"title":"续泡","text":"之后逐泡延长，可冲 10 至 15 泡。"}]},{"type":"tip","tone":"warning","title":"生沱与熟沱不一样","text":"生沱对胃的刺激强于熟沱，胃部不适的人应避免空腹饮用；出现霉斑、酸馊或刺鼻异味的茶不可饮用。存茶的地方别挨着厨房，油烟和潮气都会串进来。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["重油餐后","秋冬煮饮","办公室焖泡","出差携带"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"100 g 沱装。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面。沱茶压得紧，短期不喝的话整沱密封放着即可，撬开的部分尽快喝完。出差带几块小沱很方便，一块一泡不用带茶具，在酒店用马克杯也能泡出像样的味道。如果一次买两沱，一沱现喝、一沱收着，过一年再对比，能直观感受到陈化的差别。陈化结果取决于原料、工艺与仓储，并非年份越久越好。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 290, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product_sku (id, business_key, product_id, sku_name, sku_code, price_fen, original_price_fen, enabled, is_default, stock_on_hand, created_at, updated_at) VALUES ('6791049825900533773', 'product_tuocha_100:100g', '3786075591240560165', '100g沱装', 'CYT-TEA-XGTC-100-100g', 8800, 11800, 1, 1, 110, '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
INSERT IGNORE INTO product (id, business_key, product_code, slug, category_id, primary_tea_id, related_tea_keys, name, subtitle, cover_url, gallery_urls, tags, detail_blocks, featured, sort, status, created_at, updated_at) VALUES ('5329408682701892180', 'product_sheng_puer_200', 'CYT-TEA-SSP-200', 'product_sheng_puer_200', '394928649089662440', '7923980066954946164', '["tea_raw_puer"]', '普洱生茶·山野小饼', '花香回甘，新茶宜快出汤', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835683.jpg', '["https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927195835683.jpg"]', '["黑茶","生茶"]', '[{"type":"paragraph","text":"花香与山野气明显的普洱生茶，新茶苦涩与回甘并存。200 g 小饼，可以边喝边看它变化，适合喜欢「同一款茶每年味道不一样」这种乐趣的人；想要当下就好喝的，建议先看看熟茶。"},{"type":"heading","level":3,"text":"晒青毛茶压成饼"},{"type":"paragraph","text":"普洱生茶产自云南省西双版纳州、普洱市、临沧市，勐海、易武是两大核心产区。工艺是采摘、锅炒杀青、揉捻、日光干燥、蒸压成型、自然陈化。关键在于它用日光干燥而不是烘炒，保留了后续继续转化的空间，所以生茶放着放着，会慢慢从花香转向陈香。也正因为要留转化空间，新茶不追求一上来就顺口。勐海与易武的风格差别常被拿来对比：一个偏刚猛，一个偏柔甜，买之前可以先弄清自己偏好哪一种。"},{"type":"heading","level":3,"text":"花香、山野气与回甘"},{"type":"paragraph","text":"干茶饼面紧结、色泽墨绿带毫。新茶汤色黄绿明亮。香气以花香、蜜香与山野气为主。入口浓强，苦涩与回甘并存，生津明显——苦化得快不快，是判断新茶好不好的直观感受。随存放年份增加，汤色转深、苦涩减弱、陈香渐显，这也是很多人愿意买新茶放着的原因。仓储干净的茶，放几年之后柔顺度会明显提升，但前提是原料和工艺本身站得住。"},{"type":"heading","level":3,"text":"新茶 95℃、五秒快出汤"},{"type":"steps","items":[{"title":"撬茶","text":"沿饼面撬成小块，尽量保持条索完整。"},{"title":"备茶","text":"8 g 茶配 110 ml 水，约 1:14。"},{"title":"新茶","text":"水温略降到 95℃，第一泡约 5 秒极快出汤，以降苦涩。"},{"title":"陈茶","text":"存放较久的可用 100℃ 沸水，换紫砂壶，适当坐杯并逐泡延长，可冲 10 至 15 泡。"}]},{"type":"tip","tone":"warning","title":"新茶偏烈，注意仓储","text":"新制生普对胃的刺激强于熟茶，胃部不适的人避免空腹饮用；出现霉斑、酸馊或刺鼻异味的茶不可饮用。"},{"type":"heading","level":3,"text":"适合谁，什么时候喝"},{"type":"list","ordered":false,"items":["午后清口","新茶尝鲜","冷泡一比一百，冷藏约十二小时","陈茶品鉴"]},{"type":"heading","level":3,"text":"规格与保存"},{"type":"paragraph","text":"200 g 饼装。存放要清洁、干燥、通风、避光、防异味，远离潮湿地面与墙面，不与有气味的物品同放。整饼不喝时保持原包装，撬开的部分装进小罐尽快用完。200 g 按每次 8 g 算能冲二十五次左右，一饼够喝上一两个月；想观察转化的话，建议一次买两饼，一饼现喝、一饼收着。陈化结果取决于原料、工艺与仓储，并非年份越久越好，别把发霉当成陈香。含咖啡因，避免空腹浓饮与睡前饮用。"}]', 0, 300, 'ON_SALE', '2026-09-26 01:00:00.000000', '2026-09-26 01:00:00.000000');
