INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3567862787410087756', 'post_001', '6985242927401465158', 'seed_post_001', '992a138ccf1d9701d66dc0879ded466a10eab08cf4d3bdbe108e4db1e306985d', '又添了一只110毫升的白瓷盖碗，家里大大小小已经五只了。用下来最顺手的还是这个容量：投8克岩茶不挤，投3克绿茶也不空，出汤时手指刚好卡住碗沿，稳。之前贪大买过150毫升那只，泡岩茶还行，泡绿茶就得少放水，一泡下去味道全散了。新手真的不用一上来就买大器型，容量选对了，出汤速度自然就顺，练手效率也高。', 'teaware', '["盖碗","容量"]', NULL, 'published', 186, 2, '2026-09-27 13:47:00.000000', '2026-09-27 13:47:00.000000', '2026-09-27 13:47:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('7182568769300674033', 'seed_post_001_image_0', '6985242927401465158', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_001_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123521761.jpg', 'image/jpeg', 1, '245aadaad340fa5ada31732e7f64b8be141e12a9cb34779815d01534bd987a70', 'BOUND', 'post', 'post_001');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('2813719899021448251', '3567862787410087756', '7182568769300674033', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2443276696096353910', 'post_001:c001', '3567862787410087756', '6145446396741542357', 'seed_post_001:c001', 'c2c01e57cb5301ad6d479486dcc47907d2d4cc23c5083023d222bf427b42a8d4', '学生党预算有限，我买的是90毫升的小盖碗，一个人喝刚好，也不占地方。', '2026-09-27 13:47:00.000000', '2026-09-27 13:47:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('6643286472897809155', 'post_001:c002', '3567862787410087756', '9023244926509495270', 'seed_post_001:c002', 'f7d2986c444bfdfcad14b1bd0b42133ec05beeea0d248e53d5319f459cfcfa0d', '白瓷还有个好处是能看汤色，一只碗泡遍所有茶，不用按茶类换器皿。', '2026-09-27 13:48:00.000000', '2026-09-27 13:48:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3182464079820165376', 'post_002', '3362323610915856443', 'seed_post_002', '8158a123a309f93177b6d665e0da451dd83dae02f82bbbf82eedc6f1689a12eb', '周末把白牡丹和寿眉摆在一起对比。同样4克、150毫升：白牡丹用90℃水，第一泡20秒，花香很跳，汤色浅杏黄，入口清甜还有层次；寿眉得6克、100℃才出味，枣香重，汤更稠厚。结论是这两者没法共用一套参数。白牡丹适合快出汤喝香，寿眉耐闷，后面几泡还能拿去煮。以前我拿一个标准套所有白茶，白喝了不少。', 'tasting', '["白牡丹","寿眉"]', '5945416550361215560', 'published', 58, 1, '2026-09-27 00:12:00.000000', '2026-09-27 00:12:00.000000', '2026-09-27 00:12:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('7126958470111142635', 'seed_post_002_image_0', '3362323610915856443', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_002_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125350232.jpg', 'image/jpeg', 1, '488c91a7471a338a9151aa3a679583d1493e532fe6613a607c94caee2a17dd43', 'BOUND', 'post', 'post_002');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('9127766516596712087', '3182464079820165376', '7126958470111142635', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('6158451673570034818', 'post_002:c003', '3182464079820165376', '478822843046667138', 'seed_post_002:c003', '11b821c456046af4925676fdc1b1bc7ff7ead9545a815ff4716b5c78cd627d89', '同感。寿眉我一般第五泡以后才转煮，前面几泡还是泡着喝更清楚。', '2026-09-27 00:12:00.000000', '2026-09-27 00:12:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3461490316440436767', 'post_003', '9163151771867722325', 'seed_post_003', 'e0caef46cb0bb2a82589a7a5e56061dd98eda6e223b72eaf3913074bfecbc80f', '同一泡大红袍，8克、110毫升盖碗、沸水，只改出汤时间。5秒那杯焙火香干净，焦糖感在中段，第三泡开始有花香浮上来；闷到15秒那杯汤色深一号，香气被压住，尾端还发粗。岩茶是真的怕闷，快出汤不是玄学。叶底摊开看蛤蟆背明显，火吃得不轻，估计再放两个月退退火会更顺。今天把每泡时间都记进备忘录了。', 'tasting', '["大红袍","出汤时间"]', '4823801346719822543', 'published', 127, 2, '2026-09-26 14:35:00.000000', '2026-09-26 14:35:00.000000', '2026-09-26 14:35:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('6812685100476830973', 'seed_post_003_image_0', '9163151771867722325', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_003_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125352684.jpg', 'image/jpeg', 1, 'deca3979a0cc50334eb680106e78db1ef3c9588310e4bd36e414e65d140482b3', 'BOUND', 'post', 'post_003');
