INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('8647202760326814408', 'seed_post_003_image_1', '9163151771867722325', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_003_image_1', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164922603.jpg', 'image/jpeg', 1, 'ce4b2a6f3fbafdd28f1274bbd12174ff12841777c583c3c40f98e73e5e8b37d7', 'BOUND', 'post', 'post_003');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('1891084518965207845', '3461490316440436767', '8647202760326814408', 'IMAGE', 1);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('7353913345971166701', 'post_003:c004', '3461490316440436767', '9097300908732787732', 'seed_post_003:c004', '3d40a2fe9b57ad22704ae46495db152907acfe956fe84a78391e6ea38c3b051d', '退火这事急不得，中足火我一般放三个月再开，香气会收得更拢。', '2026-09-26 14:35:00.000000', '2026-09-26 14:35:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('4593596103632985796', 'post_003:c005', '3461490316440436767', '1211497131852067716', 'seed_post_003:c005', 'e7df8b28744a8546cb237795b64621f1d0cc1aa3481be1a7d38494caf6d517e4', '8克对110毫升已经很满了，出汤慢一点就容易闷，水别注太满会好一些。', '2026-09-26 14:36:00.000000', '2026-09-26 14:36:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('7781191121506733967', 'post_004', '2695012176419462861', 'seed_post_004', '8d954f13e78652dde5cf6ba87fabe6a9753fe3ec6cb4542c66bf95e07c13272c', '拿同一罐西湖龙井做了三组对照：75℃、85℃、100℃，都是3克、150毫升、第一泡25秒。75℃那杯最甜，豆香清楚，几乎没有涩感；85℃香气更扬，嫩栗香明显，尾端有一点点收敛；100℃那杯苦涩一下就上来了，芽叶还被烫得发黄。数据摆在这儿，龙井用沸水确实吃亏。以后我固定85℃以下，明前的再降到75℃。', 'brewing', '["西湖龙井","水温"]', '8906796300054631801', 'published', 241, 2, '2026-09-26 03:04:00.000000', '2026-09-26 03:04:00.000000', '2026-09-26 03:04:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('8713067222513734240', 'seed_post_004_image_0', '2695012176419462861', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_004_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123526718.jpg', 'image/jpeg', 1, '1e6a55192d9cc7ee3f3401753e15bdc663549645e991fe58143acb32809f0035', 'BOUND', 'post', 'post_004');
