INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('329710546967441935', 'post_004:c006', '7781191121506733967', '2518829047458234563', 'seed_post_004:c006', '24cbcb3229b940549b68a244c566007085c4a16096c5b17f633e2193098af0f9', '越嫩的水温越低，这个规律挺稳，我泡碧螺春也是75℃。', '2026-09-26 03:04:00.000000', '2026-09-26 03:04:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('7263363948876091879', 'post_004:c007', '7781191121506733967', '9023244926509495270', 'seed_post_004:c007', 'a44fd5fa6269b9eb05d3febbe2f96361433db192b414925ac1e894d2711c6e70', '注水方式影响也大，沿杯壁下去比直冲芽心柔和很多，可以再加一组对照。', '2026-09-26 03:05:00.000000', '2026-09-26 03:05:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('4168067657390586764', 'post_005', '1308343745175861320', 'seed_post_005', '3ef85d0773f84cc3323c781012649488eb4779308807397abbad888d14547d4d', '长辈给的碧螺春，说明前的。3克、150毫升玻璃杯，水温放到75℃，上投法——先注水再放茶，白毫也不容易掉。芽叶慢慢往下落，一分多钟才全沉底。香气是很轻的花果香，有点像刚剥开的枇杷。入口鲜爽，回甘来得快，一点不冲。之前我图省事用沸水泡过一次，又苦又涩，完全不是一个东西。细嫩的绿茶是真经不起高温。', 'tasting', '["碧螺春","花果香"]', '1666143067241565070', 'published', 47, 1, '2026-09-25 08:23:00.000000', '2026-09-25 08:23:00.000000', '2026-09-25 08:23:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('912044174498767450', 'seed_post_005_image_0', '1308343745175861320', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_005_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125351494.jpg', 'image/jpeg', 1, 'd42906fa00c2cca36e522396f0765103ac0cc259e481a9dc7d9250d1b8747384', 'BOUND', 'post', 'post_005');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('4760683718040803832', '4168067657390586764', '912044174498767450', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2250877427469513258', 'post_005:c008', '4168067657390586764', '3860898468910505689', 'seed_post_005:c008', 'eeecdd2927b7c9274c530f366f93a19cda9bab773d98893b95294b7ff4c46699', '75℃是对的，我一般水烧开后开盖等三四分钟再注，比兑凉水稳。', '2026-09-25 08:23:00.000000', '2026-09-25 08:23:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('4574842089818576261', 'post_006', '7988564989891008107', 'seed_post_006', '150416b2aa40c05aa058d77a21b213c872b48d162807b685ab5f0fa0ca41a397', '茶山上带回来的一罐滇红，干茶金芽多，摊在白瓷盘里看着就舒服。5克、150毫升、95℃水，第一泡5秒。汤色橙红明亮，甜香和焦糖香一起上来，汤感厚，是那种含在嘴里有分量的厚。滇红的浓强不是苦，是滋味足。这几年凤庆那边的工艺精细了不少，金芽比例高，香气比以前干净。放凉了会有一点点酸，趁热喝最好。', 'tasting', '["滇红","金芽"]', '3804420247279721210', 'published', 76, 1, '2026-09-24 23:48:00.000000', '2026-09-24 23:48:00.000000', '2026-09-24 23:48:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('3880250108952077483', 'seed_post_006_image_0', '7988564989891008107', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_006_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123532266.jpg', 'image/jpeg', 1, 'f84480579f386ebdb47f118f2d992809974b55404d88536cc640394d7f6bf60a', 'BOUND', 'post', 'post_006');
