INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('6602895064087417607', 'seed_post_006_image_1', '7988564989891008107', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_006_image_1', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926294.jpg', 'image/jpeg', 1, '075e113ec3529b314080f2c80879df40630478b4caf270fd483d6adf04c5e314', 'BOUND', 'post', 'post_006');
