INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2050133912733961182', 'post_006:c009', '4574842089818576261', '478822843046667138', 'seed_post_006:c009', 'ee3896b059f93da25a2fc24e9d35218e597a8f7a5598b769ca90850885aaf48d', '滇红加一小片陈皮一起泡也不错，不过别多，多了会盖住蜜香。', '2026-09-24 23:48:00.000000', '2026-09-24 23:48:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3931648472230133083', 'post_007', '7812127570244669596', 'seed_post_007', '4f557de949e1d2d760c1b624b95dceb0556a334535dcfb860d211f7718c8891c', '宿舍没冰箱，我把冷泡瓶放在阳台水槽里用凉水泡了一夜。500毫升水放4克白牡丹，大概8小时。早上倒出来喝，花香比热泡更清楚，一点苦涩都没有，特别顺口。缺点是太顺了，一口气喝掉半瓶。室友说这样放一夜不太稳妥，我打算以后改用楼里的公共冰箱，6小时就取出来，茶叶也滤掉。冷泡是真适合懒人。', 'brewing', '["白牡丹","冷泡"]', '5945416550361215560', 'published', 63, 2, '2026-09-24 15:19:00.000000', '2026-09-24 15:19:00.000000', '2026-09-24 15:19:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('3353228668770282830', 'post_007:c010', '3931648472230133083', '1211497131852067716', 'seed_post_007:c010', '8bdbfb96aac8911b94e6e3713f5042d7c88ab95bf1acf88440b9f61a02c92207', '4克500毫升、6到8小时是合适的区间，但一定要全程冷藏，室温放一夜不建议。', '2026-09-24 15:19:00.000000', '2026-09-24 15:19:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('7352519862450466039', 'post_007:c011', '3931648472230133083', '7658308781467042749', 'seed_post_007:c011', '808f63bf51bace4fbe0de9822c65f350d235dd76026d3f25af44412a3dbbca6f', '冷泡我还会丢两片柠檬，白牡丹的花香和柑橘很搭，你试试。', '2026-09-24 15:20:00.000000', '2026-09-24 15:20:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2791190673675924469', 'post_008', '8124788550923163179', 'seed_post_008', '2cf1b28d0ee7ce68278055435279ee824d656aaf894a6acb891950446f9d8198', '存了四年的六堡，今天认真泡一次。8克、110毫升、沸水快出。第一泡润洗不喝，第二泡5秒，汤色红浓，槟榔香很清楚，底下还有一点松烟。第五泡以后转小火煮三分钟，汤感变得更圆，木质香和陈香都出来了。干净的陈香是舒服的、有回甘的；要是闻到霉味、酸味，那就不是陈香，别硬喝。这罐仓储干净，我放心。', 'tasting', '["六堡茶","槟榔香"]', '1792334420373902975', 'published', 89, 1, '2026-09-24 06:37:00.000000', '2026-09-24 06:37:00.000000', '2026-09-24 06:37:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('7822512506847270130', 'seed_post_008_image_0', '8124788550923163179', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_008_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125357632.jpg', 'image/jpeg', 1, 'e84e98e451c54da120c8ca9396e66daf670e449d333ecb702e3c940fce1e3280', 'BOUND', 'post', 'post_008');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('8313321369299602813', '2791190673675924469', '7822512506847270130', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('6254647431840665601', 'post_008:c012', '2791190673675924469', '9023244926509495270', 'seed_post_008:c012', 'c15c9a8d1ce981fe2335edfee30d29fced3eb1c18cc04a8709525e20d0b218e3', '煮之前先用沸水快速润洗一遍，煮出来更干净，也不容易出杂味。', '2026-09-24 06:37:00.000000', '2026-09-24 06:37:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('6888474859791287382', 'post_009', '432700423800032448', 'seed_post_009', '5038ee8bcab34c55c2a37280dd5ea9071652f7a33543fbc82774b44a6eaae81d', '下午在工位泡祁门红茶，5克、150毫升、90℃水。刚出汤是明显的甜花香，有点像蔷薇；等它凉到温热，果香反而更清楚，蜜香垫在底下。这个变化挺有意思，所以我故意留了小半杯放到完全凉——香气是散了，但甜感还在。以后喝祁红我都不急着喝完，放一放再闻。配了块低甜度的饼干，两边都没抢味。', 'tasting', '["祁门红茶","闻香"]', '910171288014757367', 'published', 44, 1, '2026-09-23 10:05:00.000000', '2026-09-23 10:05:00.000000', '2026-09-23 10:05:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('5140995149186918050', 'seed_post_009_image_0', '432700423800032448', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_009_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125356452.jpg', 'image/jpeg', 1, 'b303fdd153af8d62c3ea940b56fa48af10b4c24d55910bcbe0b940063eb40476', 'BOUND', 'post', 'post_009');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('1204766557850548977', '6888474859791287382', '5140995149186918050', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2486973351056643517', 'post_009:c013', '6888474859791287382', '4735821010926833252', 'seed_post_009:c013', 'f73eba02e8a5617b6b8743336afb25bc6111483b5b2ce00b4a05f20bb4154341', '杯口宽一点散香更明显，我用敞口杯比盖碗闻得清楚。', '2026-09-23 10:05:00.000000', '2026-09-23 10:05:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('4337072236447392975', 'post_010', '8749336954246075687', 'seed_post_010', '925af4c8e10f1ac34abcd9060a4b75547cebcdaf14c9e357a21f4b5f8e530740', '第一次认真喝白毫银针。4克配150毫升盖碗，水温放到85℃。第一泡15秒，汤色浅得几乎像白水，但凑近闻是清楚的毫香，有点像晒过太阳的干草。第二泡25秒，蜜香才慢慢出来，入口清甜，一点都不苦。以前觉得白茶淡，现在明白是我一直用沸水猛冲，把细嫩的部分烫坏了。记下来：银针要低温、要快出，别煮。', 'tasting', '["白毫银针","毫香"]', '1923150703997483324', 'published', 52, 1, '2026-09-23 01:26:00.000000', '2026-09-23 01:26:00.000000', '2026-09-23 01:26:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('760941781647011061', 'seed_post_010_image_0', '8749336954246075687', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_010_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125348986.jpg', 'image/jpeg', 1, '735c29aace740517316c0ad905c41e75d4684119ba47566d2b63799a0e00b09b', 'BOUND', 'post', 'post_010');
