INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('3788146841764321106', 'post_010:c014', '4337072236447392975', '9023244926509495270', 'seed_post_010:c014', 'c43acac7d5e8fd61ebe068c6536beb4aec86cb0d7f45f528c3e0b0305194d5d6', '银针用玻璃杯更直观，芽头一根根立起来，水温还是85℃左右别高。', '2026-09-23 01:26:00.000000', '2026-09-23 01:26:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('1856362579245413681', 'post_011', '9163151771867722325', 'seed_post_011', '5adb4ad45292a2d651cc7a8b0fd520646c242f2da2a7ba12c1ae88abd73549c2', '肉桂的桂皮香要留住，关键是别闷。8克、110毫升、沸水，第一到第三泡我都压在5秒，出汤手要快，盖子斜开一条缝就倒。这样前三泡是辛锐的桂皮香，很冲但不苦；第四泡加到8秒，回甘开始明显，喉部还有一点凉意。要是第一泡就闷到15秒，那股辛香会被焙火味盖住，后面几泡也救不回来。这泡底子不错。', 'brewing', '["武夷肉桂","快出汤"]', '2466608346967166575', 'published', 86, 1, '2026-09-22 13:53:00.000000', '2026-09-22 13:53:00.000000', '2026-09-22 13:53:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('5306441035237165035', 'seed_post_011_image_0', '9163151771867722325', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_011_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164924481.jpg', 'image/jpeg', 1, '4c41f6d088a8cf6a28240be68633d316e18813c782069929057be6d5735fe624', 'BOUND', 'post', 'post_011');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('495282853064243806', '1856362579245413681', '5306441035237165035', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('5920888328802839208', 'post_011:c015', '1856362579245413681', '1211497131852067716', 'seed_post_011:c015', '3c82fd6975ea517a2e6861bcdab7503d7be0c592d7ee5058823019141e112839', '5秒确实对，我用计时器试过，超过10秒辛锐感掉得很快。', '2026-09-22 13:53:00.000000', '2026-09-22 13:53:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('1238249338056916201', 'post_012', '6985242927401465158', 'seed_post_012', 'efe557a8443fa6e264bfad98c83fca525a13942eb78fbbb75b236408867104ff', '泡君山银针我坚持用玻璃壶，就为了看芽头在壶里一根根立起来、再慢慢沉下去。3克、150毫升、80℃水，第一泡20秒。玻璃壶的毛病是散热快，第二泡得补一点热水提温，不然汤会薄。瓷壶保温好，可看不见里面，泡黄茶就少了点意思。所以我的用法很简单：好看的茶用玻璃，讲究口感的用瓷，各有各的用处。', 'teaware', '["玻璃壶","君山银针"]', '2443959781945548466', 'published', 68, 1, '2026-09-22 04:41:00.000000', '2026-09-22 04:41:00.000000', '2026-09-22 04:41:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('1294113752947180251', 'seed_post_012_image_0', '6985242927401465158', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_012_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123533518.jpg', 'image/jpeg', 1, '7efc8f5309f8b16b0a8ea23345f9af8206c3ae71463ab9658bf5ecab36ca417a', 'BOUND', 'post', 'post_012');
