INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8538933706229824441', 'post_012:c016', '1238249338056916201', '3860898468910505689', 'seed_post_012:c016', '56827a7c47b7bb4fe5fe0009d0f3282e68ca191fdf0629201e819c4c001246ae', '银针用玻璃杯竖着看更过瘾，一只杯子就够，不用壶。', '2026-09-22 04:41:00.000000', '2026-09-22 04:41:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3929362569405038301', 'post_013', '2695012176419462861', 'seed_post_013', '116e70e20f59745411c9e8770c70e76c205f867679311b7bdc9f6ce1fe19a892', '单丛我一直用沸水，今天试了95℃。8克、110毫升薄胎盖碗，第一泡5秒。95℃那杯蜜兰香更圆，入口柔，但香气收着；沸水那杯银花香冲得很开，香得更高，代价是第二泡开始有点涩。结论：想要香气就沸水快出，想要顺口就降5℃再延长一两秒。另外薄胎盖碗散热快，实际温度比想象中低，这个变量也得算进去。', 'brewing', '["凤凰单丛","水温"]', '7565560547837918852', 'published', 78, 1, '2026-09-21 12:17:00.000000', '2026-09-21 12:17:00.000000', '2026-09-21 12:17:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('2780986762727552442', 'seed_post_013_image_0', '2695012176419462861', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_013_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124047075.jpg', 'image/jpeg', 1, '2c4028c534cc7dea37dfef2c59458e52e810e03dbba19897d7929a574e1da843', 'BOUND', 'post', 'post_013');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('421204142935854843', '3929362569405038301', '2780986762727552442', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('3660655847331917156', 'post_013:c017', '3929362569405038301', '2516273971438976548', 'seed_post_013:c017', '7e279de1983226c1f0a13b9ff1d59a0484032b37c2dc8b5599e9007d5af3c334', '薄胎盖碗确实降温快，注水前多温一遍碗，温度会稳定一些。', '2026-09-21 12:17:00.000000', '2026-09-21 12:17:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2035740935818991561', 'post_014', '8124788550923163179', 'seed_post_014', 'aaf2223f929c5ad1dbc71658141843c62bc6bfa8e972ebb917be3c4f47d38b59', '千两茶用茶刀撬下一块，8克配110毫升盖碗先泡三泡，5秒出汤。竹香和松烟香很直接，汤色橙红，浓但不苦。第四泡以后我把叶底倒进煮茶壶，加水煮三分钟，那一壶汤色更深，醇厚度翻了一倍，回甘也长。黑茶确实适合先泡后煮，直接煮反而前段出不来。注意别煮太久，会发苦。撬茶顺着纹理下刀，碎得也少。', 'brewing', '["安化千两茶","煮饮"]', '184649584603810829', 'published', 74, 1, '2026-09-20 22:52:00.000000', '2026-09-20 22:52:00.000000', '2026-09-20 22:52:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('3182860233607251010', 'seed_post_014_image_0', '8124788550923163179', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_014_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123535938.jpg', 'image/jpeg', 1, '1311c4678561cd82733f5d2bb5a333bf1841611fb35d9c344b4ed6e29ab80e49', 'BOUND', 'post', 'post_014');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('3330393264633296292', '2035740935818991561', '3182860233607251010', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('945243069664990662', 'post_014:c018', '2035740935818991561', '9097300908732787732', 'seed_post_014:c018', 'f67b07e8c17099a8093a39f3cfbb07d4536280830fc0eb6703a665582581001a', '撬茶顺着纹理下刀，别横着切，条索不容易碎，出汤也干净。', '2026-09-20 22:52:00.000000', '2026-09-20 22:52:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('4980125257042794297', 'post_015', '1308343745175861320', 'seed_post_015', 'f166d96ddd90a99cba0f3d9d446f5c2643fecfd78edb9f7583ea1f6ca4bd2726', '猴魁的条索又长又扁，普通盖碗放不下，换了高身玻璃杯才舒展开。3克、150毫升、85℃水，第一泡30秒。兰花香很清，汤色浅绿明亮，鲜爽里带一点厚度，喝下去喉部有回甜，这大概就是他们说的猴韵。第二泡我延到40秒，还是很耐泡。这茶外形太有辨识度了，泡的时候一根根立着，光看着就高兴。', 'brewing', '["太平猴魁","高身杯"]', '2426254520602417580', 'published', 61, 1, '2026-09-20 07:38:00.000000', '2026-09-20 07:38:00.000000', '2026-09-20 07:38:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('5059702607911882499', 'seed_post_015_image_0', '1308343745175861320', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_015_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164918991.jpg', 'image/jpeg', 1, '368b0470a01374870b2fe8b89b8c9a214304d8ac32b188e76f3853b2dab9a1f8', 'BOUND', 'post', 'post_015');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('7426709342797206601', '4980125257042794297', '5059702607911882499', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('6209787040790276450', 'post_015:c019', '4980125257042794297', '9097300908732787732', 'seed_post_015:c019', 'd5759d4e699d6bd3c3bf0dea3faf3e3904ade8bd16e098ea779387ba9ce1e133', '猴魁得用高杯，盖碗压着它展不开，香气也出不来。', '2026-09-20 07:38:00.000000', '2026-09-20 07:38:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('5379015527636020512', 'post_016', '432700423800032448', 'seed_post_016', '86d39ecf7ac61ad5482863f448ff61f81c7bfa094e145e039f5ccdf483bd2fae', '办公室只有饮水机，水温大概85℃，本来担心泡不好金骏眉，试下来居然正合适。3克、150毫升，第一泡15秒。花果蜜香很细，汤色金黄，入口鲜活甘爽，一点都不涩。以前我用沸水泡过一次，香气虽然更冲，但细腻感全没了。看来细嫩的红茶也不必用沸水。今天下午连泡五泡，第五泡还是甜的，比咖啡省心。', 'brewing', '["金骏眉","办公室"]', '1774819018337183817', 'published', 72, 1, '2026-09-20 02:09:00.000000', '2026-09-20 02:09:00.000000', '2026-09-20 02:09:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('7310492233975306203', 'seed_post_016_image_0', '432700423800032448', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_016_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123525464.jpg', 'image/jpeg', 1, '61f2c29f5f16b59034be751eafc4c59526b431d9d8d7008f82adfc3af2edb98c', 'BOUND', 'post', 'post_016');
