INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8057463830354940158', 'post_016:c020', '5379015527636020512', '4735821010926833252', 'seed_post_016:c020', 'c82d051b488e2ed9629c03a9b2af2ef7f7834dfc115957fd2305acae471df9e8', '金骏眉投茶别多，3克够了，多了容易苦。', '2026-09-20 02:09:00.000000', '2026-09-20 02:09:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3886586061233268069', 'post_017', '7988564989891008107', 'seed_post_017', 'd2bbb72c82f9a20044b9da313831eb7fc492e14abacf8f14947e50279c2e18ec', '熟普撬开别急着泡。这次我把茶块摊在茶则上放了两天，让它透透气，再装罐。同样的8克、110毫升、沸水，醒过的那泡第一道就没有堆味，陈香直接出来，汤色红浓透亮，入口顺滑，甜感很清楚；没醒的那泡前两道还有点闷。撬茶也一样，顺着压制的层理下刀，条索碎得少，出汤更干净。醒两天不麻烦，效果看得见。', 'brewing', '["普洱熟茶","醒茶"]', '8256583128742200111', 'published', 152, 2, '2026-09-19 11:44:00.000000', '2026-09-19 11:44:00.000000', '2026-09-19 11:44:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('7731401584679405015', 'seed_post_017_image_0', '7988564989891008107', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_017_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123529126.jpg', 'image/jpeg', 1, 'aba0517e9e4ee1429256edf58f58372a28f67bee0d53db6391f4ac77ff4cc56f', 'BOUND', 'post', 'post_017');
