INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('893195643435262567', 'seed_post_017_image_1', '7988564989891008107', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_017_image_1', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125840153.jpg', 'image/jpeg', 1, '769159090123aae471de1672f77f20ff80c7c9b83a76ba7a869168e81c5ee15a', 'BOUND', 'post', 'post_017');
