INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8825519800726880101', 'post_017:c021', '3886586061233268069', '172930623173972133', 'seed_post_017:c021', '867ac161a5924e85e47001549a67f16d21b937e3013c528d40914b38eef5303a', '醒茶确实管用，我一般撬好放紫砂罐里一周，变化更明显。', '2026-09-19 11:44:00.000000', '2026-09-19 11:44:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('4250297920122406334', 'post_017:c022', '3886586061233268069', '9023244926509495270', 'seed_post_017:c022', 'e9a18b0961564af0214cd3925959553b51b5e6cbc6719b8ebb183eee917f3e02', '南方潮湿天摊两天要注意防潮，我是放在茶盘上盖一层纸。', '2026-09-19 11:45:00.000000', '2026-09-19 11:45:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('8471414127504521783', 'post_018', '432700423800032448', 'seed_post_018', 'd498978b6f8f091d83c30032d1a776c1095710147768e9c2f86bb08116a862d7', '在工位泡茶，我最常用的是带滤网的飘逸杯，一百多块，按键出汤，不用摆一整套。缺点也明显：容量大、散热快，第一泡还行，第二泡就温吞了，香气起不来。后来我改成少放水、只泡小半杯，出汤勤一点，反而好喝多了。办公室喝茶不用追求仪式感，能稳定出汤、不洒不漏、同事路过不觉得奇怪，这三点满足就够了。', 'teaware', '["办公杯","飘逸杯"]', NULL, 'published', 39, 1, '2026-09-19 00:31:00.000000', '2026-09-19 00:31:00.000000', '2026-09-19 00:31:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('80393332731385899', 'post_018:c023', '8471414127504521783', '6145446396741542357', 'seed_post_018:c023', '725c3c0f29116e7cf4b6287b0268594733b4a8ff2a313ab690ed4b0fa78a8d35', '宿舍同理，我用的是带滤网的保温杯，只敢放3克，多了会苦。', '2026-09-19 00:31:00.000000', '2026-09-19 00:31:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2295435551740448838', 'post_019', '7812127570244669596', 'seed_post_019', 'b35a4500418e2b15788432c79519f613fdeee60a92ca3192c32555c0339bef73', '入坑半年，宿舍茶具一共花了不到两百：90毫升白瓷盖碗一只、玻璃公道杯一个、两个小茶杯、一块吸水茶巾，够用了。踩过的坑是贪便宜买的十几块钱盖碗，碗沿薄、口沿不圆，倒汤时沿着碗壁往下流，桌上全是水；换了一只三十多的就好了。所以预算有限的话，先把手感最直接的盖碗买好一点，其他可以慢慢加。', 'teaware', '["宿舍","入门茶具"]', NULL, 'published', 27, 1, '2026-09-18 14:08:00.000000', '2026-09-18 14:08:00.000000', '2026-09-18 14:08:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('1344532450861809615', 'seed_post_019_image_0', '7812127570244669596', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_019_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927124035988.jpg', 'image/jpeg', 1, '603ec2a9d98aac25120156aa62e0c1871dceff72d269f83ba0223d5cf92ccb39', 'BOUND', 'post', 'post_019');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('5058047711031531416', '2295435551740448838', '1344532450861809615', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('98959166166356944', 'post_019:c024', '2295435551740448838', '4735821010926833252', 'seed_post_019:c024', 'cdf46df793050acd8077e7132fa4dcf8918c0c032b39f4a9f49187206fbde210', '盖碗看口沿和碗沿的弧度，倒汤顺不顺主要靠这个，不是越厚越好。', '2026-09-18 14:08:00.000000', '2026-09-18 14:08:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('4387945079326363967', 'post_020', '8599731799452723918', 'seed_post_020', '6c538614ddbba8c5175c1b43e8d08543fcd918ad5aa992bccde52e1761ae1a52', '冷泡瓶换了三个，最后留下的是窄口玻璃瓶加一个硅胶滤网。塑料瓶便宜但会留味，泡过柠檬之后再泡茶全是柠檬味；宽口瓶好清洗，可是倒茶时茶叶容易跟着冲出来。窄口瓶配滤网出茶干净，缺点是茶叶塞进去费劲，我一般先把茶叶放进去再注水，晃一晃就行。想常年冷泡的话，瓶子比茶叶更值得挑一挑。', 'teaware', '["冷泡瓶","玻璃瓶"]', NULL, 'published', 19, 1, '2026-09-18 08:57:00.000000', '2026-09-18 08:57:00.000000', '2026-09-18 08:57:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8368544486345907048', 'post_020:c025', '4387945079326363967', '6145446396741542357', 'seed_post_020:c025', '70b0dca08506f27d5af116f1fab9e6f9e345b7f4169d98e9a5716f979d5f90bf', '我把茶叶装进无纺布茶包再丢进瓶里，取出来特别方便，也不用洗滤网。', '2026-09-18 08:57:00.000000', '2026-09-18 08:57:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2565936949613674009', 'post_021', '9163151771867722325', 'seed_post_021', '074daa04b3c78bf611baddcb445423061d8e862511b736802ceac15290716cac', '泡岩茶到底用紫砂还是盖碗，我的答案是看你想喝什么。盖碗不吸味，能如实反映一泡茶的优缺点，茶样对比、试新茶我都用盖碗；紫砂壶保温好、出水稳，老丛水仙那种绵柔稠滑的汤感更容易被托起来，但壶会吸香，换茶前得养一段。日常我的做法是盖碗打头阵，确认这泡茶好喝，再换壶慢慢喝。', 'teaware', '["紫砂壶","盖碗"]', '7680583177376719619', 'published', 84, 2, '2026-09-17 05:22:00.000000', '2026-09-17 05:22:00.000000', '2026-09-17 05:22:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('3386123435687938115', 'seed_post_021_image_0', '9163151771867722325', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_021_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123534708.jpg', 'image/jpeg', 1, '04e9130f327cfa21d79a4841d73b25a761637daa63e9111d02ec02f8be904374', 'BOUND', 'post', 'post_021');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('6074045017366345870', '2565936949613674009', '3386123435687938115', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('6842692972494955786', 'post_021:c026', '2565936949613674009', '4735821010926833252', 'seed_post_021:c026', '8828f0b71b75b8e4bf4e15fa16e956e1990db1cb126c64edac037fe67301f517', '同意。另外壶的容量最好贴着你的杯子来，110毫升壶配两个小杯刚好。', '2026-09-17 05:22:00.000000', '2026-09-17 05:22:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8879708058449532906', 'post_021:c027', '2565936949613674009', '1211497131852067716', 'seed_post_021:c027', '530991bb9b8e2dd82b335600dccbd314a2e1c4f8c3fc24e9965ace525486d528', '我做过对照，同一泡茶盖碗的香气强度确实更高，壶的汤感更厚。', '2026-09-17 05:23:00.000000', '2026-09-17 05:23:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('1335074447415652162', 'post_022', '3362323610915856443', 'seed_post_022', 'e3aaa753bb2f3a219d662e8fb6dbca1dff4630c1b06fd73aeb296df4088a5d05', '以前觉得茶巾是可有可无的东西，直到我把木茶盘换成陶盘才发现不对——陶盘不留水，出汤时滴的几滴全积在盘面上，得靠茶巾随时擦。现在我的习惯是茶巾叠成三折放在右手边，出汤后顺手按一下壶底。买茶巾别挑太厚的，吸水可以但干得慢，容易留味；薄的棉麻料两三天洗一次，晒干就好。小东西，但影响桌面整洁度。', 'teaware', '["茶巾","茶盘"]', NULL, 'published', 56, 1, '2026-09-16 23:35:00.000000', '2026-09-16 23:35:00.000000', '2026-09-16 23:35:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('5668103186405256012', 'post_022:c028', '1335074447415652162', '4735821010926833252', 'seed_post_022:c028', '4855589db469e68e6625848cd67d123745daf6fc4003b9d4692b4cfc7b46eea4', '茶巾我备两条轮换，一条用一条洗，比一条用到底省心。', '2026-09-16 23:35:00.000000', '2026-09-16 23:35:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('5940911709636232512', 'post_023', '8749336954246075687', 'seed_post_023', '7de6704894f6b88174c46d0c83863456882d2784dfb15b8cd72d2949e8579162', '黄茶喝得少，今天开一泡霍山黄芽。3克、150毫升、80℃水，第一泡20秒。汤色是浅浅的黄绿，香气里有熟栗子的味道，还有点甜。和绿茶比，它的鲜爽度低一点，但甜感更清楚，苦涩几乎感觉不到，闷黄这道工序看来真有用。唯一的问题是我水放多了，第二泡就有点薄，下次减到120毫升试试。', 'tasting', '["霍山黄芽","黄茶"]', '3272000355873956807', 'published', 33, 1, '2026-09-16 09:41:00.000000', '2026-09-16 09:41:00.000000', '2026-09-16 09:41:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('1962370248587895266', 'seed_post_023_image_0', '8749336954246075687', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_023_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125353909.jpg', 'image/jpeg', 1, 'bb3c9f2564fb55cae2f7ba964fedb505ee17b35219e02005f8bcbe2701b4d82e', 'BOUND', 'post', 'post_023');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('4737062848368342055', '5940911709636232512', '1962370248587895266', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8654500466861915095', 'post_023:c029', '5940911709636232512', '2518829047458234563', 'seed_post_023:c029', '30a8d47f947d32d72be965e97d012862f18488d5769afb8832f077f2ce322138', '黄茶投茶量可以稍微多一点，3克对120毫升会更饱满，香气也聚得住。', '2026-09-16 09:41:00.000000', '2026-09-16 09:41:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('251497939473362325', 'post_024', '8599731799452723918', 'seed_post_024', 'e283a9c90813231ddbd6d9a5ae2ce49f1febfb1e3a0df45960a5d7a287fde904', '下班回家太热，随手做了杯冷泡：凤凰单丛4克，500毫升凉白开，冷藏6小时，倒出来加了两块冰和一小片柠檬皮。单丛的蜜兰香和柑橘皮挺搭，不加糖也够甜。注意柠檬皮别泡太久，十分钟内捞出来，久了会发苦。这杯比奶茶清爽，也不用额外加糖，缺点是喝惯浓的会觉得略淡，可以把茶量加到5克。', 'daily', '["冷泡","调饮"]', '7565560547837918852', 'published', 24, 1, '2026-09-16 03:58:00.000000', '2026-09-16 03:58:00.000000', '2026-09-16 03:58:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2435200128860848545', 'post_024:c030', '251497939473362325', '2516273971438976548', 'seed_post_024:c030', '9b4915e99cd928d07dca149e41969ba0bcd5269bc7eef4d148ebda8aca0c3410', '单丛冷泡确实好喝，我一般挑蜜兰香这类香气偏甜的，银花香冷泡反而发青。', '2026-09-16 03:58:00.000000', '2026-09-16 03:58:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('1909297691401714230', 'post_025', '1308343745175861320', 'seed_post_025', 'd9e74582a150d7311427ac593afb0ce0d2b288e00b4609e4f1d821d6814c07d6', '上午开会前给自己泡了一杯安吉白茶。3克、150毫升玻璃杯，75℃水，第一泡20秒。干茶是嫩黄绿色的，泡开之后叶片几乎半透明，汤色很浅。入口特别鲜爽，几乎喝不到苦涩，回甘带一点甜，是我目前喝过最不挑人的绿茶。缺点是耐泡度一般，第三泡就明显淡了。所以我现在都用大杯少投茶，一口气喝到中午。', 'daily', '["安吉白茶","办公"]', '6061920329024784346', 'published', 41, 1, '2026-09-15 12:46:00.000000', '2026-09-15 12:46:00.000000', '2026-09-15 12:46:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('741011083012722919', 'seed_post_025_image_0', '1308343745175861320', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_025_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927122417890.jpg', 'image/jpeg', 1, 'a1c24096a1f7a46cdb9ca9347551ff0f9b55a436a8cb807dff3da103a6c00240', 'BOUND', 'post', 'post_025');
