INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('3821597065662544015', 'post_025:c031', '1909297691401714230', '3860898468910505689', 'seed_post_025:c031', '3dad8ea7a1f2e37583bf5ff7c9beb307f029531b42a0a5617c6392de106950fe', '安吉白茶其实属于绿茶，氨基酸含量高所以鲜，水温千万别超80℃。', '2026-09-15 12:46:00.000000', '2026-09-15 12:46:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('6500848702297080172', 'post_026', '8124788550923163179', 'seed_post_026', '51de3ef57c58dbb63ebeb0d2935242f3f8072a00f3ee08357d859444aebb6d46', '朋友送了一饼普洱生茶的七子饼，第一次自己存，有点拿不准。现在的做法是：原包装的棉纸不拆，放进纸箱，箱子里再放一小包食品级干燥剂，摆在书房柜子最上层，避光、离墙、离地。南方湿度大，我每周开箱看一次。想请问各位：要不要再套密封袋？听说完全密封反而不利于后期转化，可敞着又怕受潮，你们是怎么处理的？', 'question', '["七子饼","存茶"]', '3264163789956254853', 'published', 67, 2, '2026-09-15 01:13:00.000000', '2026-09-15 01:13:00.000000', '2026-09-15 01:13:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('3996021484602730843', 'seed_post_026_image_0', '8124788550923163179', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_026_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123537157.jpg', 'image/jpeg', 1, '3d3d5242b29e5877f9897904b5689dda8eb7283860b0e66bdfa15ec20ed14a4d', 'BOUND', 'post', 'post_026');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('5555691434148293577', '6500848702297080172', '3996021484602730843', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2299171475210519753', 'post_026:c032', '6500848702297080172', '9097300908732787732', 'seed_post_026:c032', '2536c9a1a399050cfa4a93016d00284c6daf2dfc047e02f352222be0afb6dcaf', '别用完全密封的塑料袋。纸箱加干燥剂，湿度控制在60%上下就行，太干转化会停。', '2026-09-15 01:13:00.000000', '2026-09-15 01:13:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('5835048199155376530', 'post_026:c033', '6500848702297080172', '2516273971438976548', 'seed_post_026:c033', '32c6a603abc20282939efde855336d0b6b2e5c6e82fca54b0dc2ff8943c2efd9', '我是纸箱外面套一层防潮袋但不封口，回南天收口，平时敞开，可以参考。', '2026-09-15 01:14:00.000000', '2026-09-15 01:14:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2405782762099910547', 'post_027', '432700423800032448', 'seed_post_027', '4a1cb1072bf2574a67def7434eb6a8cf415bd2794c59fa04f6a8fdeebf27d050', '周六下午把茶具摆到餐桌上，一壶祁红配一碟绿豆糕和几块原味饼干。经验是茶点要挑低甜度的：甜度高的点心会把茶的花香全压下去，吃完再喝茶只剩涩。绿豆糕这种清淡的刚好，能垫一下肚子又不抢味。另外先吃一口点心再喝茶，比空口喝茶舒服。摆一桌看着挺隆重，其实前后也就洗两个碟子。', 'daily', '["下午茶","茶点"]', NULL, 'published', 49, 1, '2026-09-14 07:27:00.000000', '2026-09-14 07:27:00.000000', '2026-09-14 07:27:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('7638411741366042195', 'seed_post_027_image_0', '432700423800032448', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_027_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123527929.jpg', 'image/jpeg', 1, '5a2bab91b7e51758a819a805d698c948a3f8b878b41e91fa791f4abd63eedf16', 'BOUND', 'post', 'post_027');
