INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8773581818101014402', 'post_027:c034', '2405782762099910547', '4735821010926833252', 'seed_post_027:c034', 'fab3883c05677bec2d2396732f7ef17b441013a107648acdf32bdab2482b5391', '茶点摆盘我一般只放两样，多了桌面乱，也容易吃撑。', '2026-09-14 07:27:00.000000', '2026-09-14 07:27:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('7075016310842031903', 'post_028', '1308343745175861320', 'seed_post_028', 'ea2647efc12d02271997dd36c27871a051d0eebed8b2c3f96fda2fc1e4b08d86', '阴天在家烧了一壶正山小种。5克、150毫升、90℃水，第一泡5秒，松烟香先出来，后面跟着桂圆干似的甜，汤色红艳，一杯下去整个人都松下来了。配了一碟坚果和几块原味饼干，烟熏味和坚果挺搭。这茶凉了以后烟味会更突出，所以我一般趁热喝。一壶六泡，配着窗外的雨坐了一下午。', 'daily', '["正山小种","茶席"]', '4996346501470601743', 'published', 82, 1, '2026-09-13 22:41:00.000000', '2026-09-13 22:41:00.000000', '2026-09-13 22:41:00.000000');
