INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('568171562085922918', 'post_028:c035', '7075016310842031903', '9097300908732787732', 'seed_post_028:c035', '7b5acc3a6b6b4ba5607c4674d50d54607eaded5d54f069834e4be943529b7816', '无烟种和有烟的可以都买点对比，桐木关那边的花果香更清楚。', '2026-09-13 22:41:00.000000', '2026-09-13 22:41:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('1290426088960839831', 'post_029', '7812127570244669596', 'seed_post_029', '873e211d6c2b807f90ced2927e63bf6d259f9f1c2133a9dd7688b0562a10ce20', '赶作业到十一点半，不想喝咖啡了，用小盖碗泡了3克六安瓜片。85℃水，30秒出汤。高火香很直接，浓醇、回甘强，喝完整个人清醒了一点，又不像咖啡那样心跳加速。宿舍条件有限，我就用保温杯装热水当水源，一个盖碗一个杯子，桌面也就占半张A4纸的地方。喝完把碗冲干净，明天还能接着用。', 'daily', '["深夜","宿舍"]', '540863087991848985', 'published', 16, 1, '2026-09-13 15:36:00.000000', '2026-09-13 15:36:00.000000', '2026-09-13 15:36:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('1127458569378597975', 'post_029:c036', '1290426088960839831', '9023244926509495270', 'seed_post_029:c036', '1dee06145fcd34967ad2201f60daf22e463be08fa3d9761866aff129ac52dc59', '瓜片耐泡，第二泡可以延到40秒，夜里别喝太多，免得睡不着。', '2026-09-13 15:36:00.000000', '2026-09-13 15:36:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('6937110700334165262', 'post_030', '3362323610915856443', 'seed_post_030', '05ee8deacf5ec44a1ddc590601b77bc871f80adb5e83d8e04526c5e5282ec023', '外面下了一整晚的雨，窗台上的灯照得雾蒙蒙的。煮了一壶寿眉，6克、150毫升盖碗先泡到第五泡，再把叶底倒进煮茶壶煮了三分钟。枣香混着一点陈香，汤色橙黄，稠稠的，捧在手里温度刚好。雨天喝茶的乐趣大概就在这儿——不急着喝出什么层次，就是想手里有个热杯子。这一壶喝到雨小。', 'daily', '["寿眉","雨夜"]', '5117341104257652868', 'published', 83, 2, '2026-09-13 11:02:00.000000', '2026-09-13 11:02:00.000000', '2026-09-13 11:02:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('438285879294287517', 'seed_post_030_image_0', '3362323610915856443', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_030_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123524250.jpg', 'image/jpeg', 1, '1ecba1b69a1b071260f789d1c4f5c5341f7ba4bc1f70937846ff41bbc71a3ab7', 'BOUND', 'post', 'post_030');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('5037615765083232272', '6937110700334165262', '438285879294287517', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('4830441728396356126', 'post_030:c037', '6937110700334165262', '172930623173972133', 'seed_post_030:c037', '88f8ee3233315500ab69db14effbffe42606eaee8e10c9b09b5eb4a3c9a1759b', '寿眉煮之前先用沸水润洗一遍，煮出来更甜，也不会浑。', '2026-09-13 11:02:00.000000', '2026-09-13 11:02:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2694685040008618393', 'post_030:c038', '6937110700334165262', '478822843046667138', 'seed_post_030:c038', 'c583081df37ebd67886221f9712839ae2d9ea74fb41b33cd411d07956c5013a8', '看你这条我也想煮壶白茶了，明天就安排上。', '2026-09-13 11:03:00.000000', '2026-09-13 11:03:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('7945307556135689223', 'post_031', '7988564989891008107', 'seed_post_031', '524073bf69c6683a2c3daff5697e86aa02a5c736baa70d9c7369f19433f44e70', '店里早上开门第一壶茶，我一般泡黄山毛峰。3克、150毫升、85℃水，第一泡25秒。兰花香和清鲜的栗香，汤色浅绿，回甘持久，一上午能续到第四泡。有客人问我为什么不用沸水，我说嫩芽经不起烫——这话我跟人说了快十年。今天这批是汤口那边的，芽头匀齐，喝下来比上一批更清透。', 'daily', '["黄山毛峰","茶馆日常"]', '6404999874162051223', 'published', 71, 1, '2026-09-12 02:44:00.000000', '2026-09-12 02:44:00.000000', '2026-09-12 02:44:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('442626790867158773', 'seed_post_031_image_0', '7988564989891008107', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_031_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927122609379.jpg', 'image/jpeg', 1, '21dbfa7f0fa836425c1b0f6587600824834cb151c10f13c1dee31b6dc0121ff7', 'BOUND', 'post', 'post_031');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('6582153568121249022', '7945307556135689223', '442626790867158773', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2692076444404696178', 'post_031:c039', '7945307556135689223', '2518829047458234563', 'seed_post_031:c039', 'd940298c31cd888605ebe059bd46a47c701b085e0833f0361990a224cdcd718f', '毛峰的回甘是慢慢上来的那种，喝完过一会儿才觉得嘴里甜。', '2026-09-12 02:44:00.000000', '2026-09-12 02:44:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('554571621738513646', 'post_032', '3362323610915856443', 'seed_post_032', '44ea7c91ead1e032e2028934c333ddd1596194cf23c01dfd1efff91a2a73faf1', '第一次买冻顶乌龙，拆开倒在白瓷盘里有点懵：干茶是紧结的半球形，颜色偏深，闻着是明显的焙火味混着一点米香，跟我印象里清香型的台湾乌龙差挺多。7克、120毫升、95℃水，我泡了第一泡20秒，汤色金黄，入口醇厚甘润。想问一下常喝台湾茶的朋友：这种焙火程度算正常的吗？后面几泡时间应该怎么调？', 'question', '["冻顶乌龙","干茶"]', '4126276344076852981', 'published', 54, 2, '2026-09-11 23:29:00.000000', '2026-09-11 23:29:00.000000', '2026-09-11 23:29:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('4147895352589785220', 'seed_post_032_image_0', '3362323610915856443', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_032_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123522996.jpg', 'image/jpeg', 1, 'df4241bcd2cc6cb3f425acb4c48d5ef7173aada07e958723ba0c7918a71a147b', 'BOUND', 'post', 'post_032');
