INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('254645213566090871', 'seed_post_032_image_1', '3362323610915856443', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_032_image_1', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164923292.jpg', 'image/jpeg', 1, '56a51d5baff7181cf45b7bdab23fb80291ce2146e27300cbbbdca0209528780d', 'BOUND', 'post', 'post_032');
