INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('1431676346461551367', 'post_032:c040', '554571621738513646', '2516273971438976548', 'seed_post_032:c040', '4e2de6784ec5ca454650e054749696be5aec3bb4d7dea2b6be1df44756417b7e', '正常，冻顶本身就是中焙火的球形乌龙。第一泡醒茶可以快出，正式从20秒起，后面每泡加10秒。', '2026-09-11 23:29:00.000000', '2026-09-11 23:29:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2126645852437215951', 'post_032:c041', '554571621738513646', '1211497131852067716', 'seed_post_032:c041', '826c5073a613c40edeb72abfdde9ae6a0b2eaf9016e9e76b4240f26b2256f04c', '球形乌龙建议先温润一遍再正式计时，不然第一泡容易偏淡。', '2026-09-11 23:30:00.000000', '2026-09-11 23:30:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('8903357771433774242', 'post_033', '6985242927401465158', 'seed_post_033', '9b699662dc7fb4b4e05e746b1f5cedbbbef6cdc0bbfd0e4102c675be49314dd9', '新买的竹茶荷到了，顺手拿铁观音试了试。茶荷这东西以前我觉得是摆设，用起来才发现有用：干茶倒在上面，一眼能看出条索是否匀整、有没有碎末，还能递给别人闻香，比抓着袋子倒体面。缺点也直接——竹的会吸味，用过几次味道就串了，所以我只用来盛乌龙，绿茶还是用白瓷碟。买之前想清楚用途，别只看好看。', 'teaware', '["茶荷","赏茶"]', '4051196457869679063', 'published', 38, 1, '2026-09-11 06:16:00.000000', '2026-09-11 06:16:00.000000', '2026-09-11 06:16:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('8614717549770926808', 'seed_post_033_image_0', '6985242927401465158', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_033_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125841360.jpg', 'image/jpeg', 1, 'b4ad7201858d8b3cd264706806d7181ac95e822f5a31126f9dc6ce847f9f1dfa', 'BOUND', 'post', 'post_033');
