INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('8107954195135977285', 'post_033:c042', '8903357771433774242', '6145446396741542357', 'seed_post_033:c042', 'd2b70b41f46a40345112a15983da6c6a3ef4f5bfb8785064e6bdacd8c1c851e2', '我用的是白瓷小碟，几块钱一个，洗起来也方便，不吸味。', '2026-09-11 06:16:00.000000', '2026-09-11 06:16:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2401609602232663490', 'post_034', '2695012176419462861', 'seed_post_034', '667eca622468d7641f0806f6ef17457406a561d0a6ce40d3be5cc68d3f267823', '最近在做注水手法的对照，遇到一个问题想请教：同样8克岩茶、110毫升、沸水、5秒出汤，高冲（壶嘴离碗口15厘米绕圈）和低斟（贴着碗沿慢慢注）出来的汤，香气强度差别挺明显，高冲那杯更扬，但第二泡苦涩也更早出来。我猜是高冲让茶叶翻滚得更厉害。想问问大家平时怎么注水？定点还是绕圈？这个变量你们会固定下来吗？', 'question', '["注水","手法"]', NULL, 'published', 46, 2, '2026-09-11 00:53:00.000000', '2026-09-11 00:53:00.000000', '2026-09-11 00:53:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('3136567000094959785', 'post_034:c043', '2401609602232663490', '2516273971438976548', 'seed_post_034:c043', '7df9ada6e3c56fa0e737a3bbe0d661159f888fb75aa246774fb89afa88e49cee', '岩茶我基本定点低斟，注水不冲叶心，第一泡不建议高冲，容易把碎末翻起来。', '2026-09-11 00:53:00.000000', '2026-09-11 00:53:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('5730788702358573758', 'post_034:c044', '2401609602232663490', '9097300908732787732', 'seed_post_034:c044', '0b772c96fefb8b0c04e7db8de9eaed3743e21cd567576a1c913aefccd56da081', '高冲适合香型张扬的单丛，沉稳的岩茶和老白茶还是低斟更稳，我一般两种都用。', '2026-09-11 00:54:00.000000', '2026-09-11 00:54:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('4519505795705625595', 'post_035', '9163151771867722325', 'seed_post_035', 'f977dbe317af9745b2e1d1b875c9a1834aa909bc244511cdba8c6ddccbb3a5f3', '有个困惑想跟各位聊聊。都说肉桂讲“辛锐”，我手上这一泡桂皮香很冲，第一口甚至有点呛，但回甘确实快，四泡之后喉部发凉。朋友那泡肉桂香气内敛，喝起来柔，他觉得我那泡是火功不到位。我的看法是辛锐不等于越冲越好，不同山场本来就有差别。想听听常喝肉桂的朋友怎么看：辛锐感到底该怎么判断？', 'question', '["肉桂","辛锐感"]', '2466608346967166575', 'published', 62, 2, '2026-09-10 14:47:00.000000', '2026-09-10 14:47:00.000000', '2026-09-10 14:47:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('1560349389012970584', 'seed_post_035_image_0', '9163151771867722325', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_035_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927123531040.jpg', 'image/jpeg', 1, 'a8920547e5d9e17cc8c810053e67bbb752149d9ebc28c48e6f8c1fe84e7bf4ed', 'BOUND', 'post', 'post_035');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('525250344901195543', '4519505795705625595', '1560349389012970584', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('1458535598760760116', 'post_035:c045', '4519505795705625595', '9097300908732787732', 'seed_post_035:c045', '6f64ef982cc11aa6fa3780d32ca4196e546a87d4043616d85c3b7ce22e263c3e', '辛锐是香气有穿透力、收得住，不是刺鼻。呛口多半是火没退净或者投茶太多，放一个月再试。', '2026-09-10 14:47:00.000000', '2026-09-10 14:47:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('5901140925226078683', 'post_035:c046', '4519505795705625595', '1211497131852067716', 'seed_post_035:c046', 'c754f8556857976acddbfd75151de6d475f82817f814c183b8cbb0ceb8542cf5', '同一泡茶换个薄胎盖碗对比一下，器皿对辛香的呈现影响挺大。', '2026-09-10 14:48:00.000000', '2026-09-10 14:48:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('3707714630686180608', 'post_036', '8124788550923163179', 'seed_post_036', '8f389183632dad8e2277ddbb53ed0f0cb6e204fd355c181c21118376a0fd546f', '第一次买下关沱茶，拿到手是个紧实的碗形，完全不知道怎么下手。我用茶针从侧面扎了几下，只掉了几片碎末，还把手蹭了一道。想请教：沱茶应该从哪个方向下针？需不需要先用蒸汽蒸软一点再撬？另外它压得这么紧，是不是要醒茶更久？我打算先撬够两泡的量试试，8克、110毫升、沸水。盼各位指点。', 'question', '["下关沱茶","撬茶"]', '7330552595416293242', 'published', 29, 2, '2026-09-10 04:19:00.000000', '2026-09-10 04:19:00.000000', '2026-09-10 04:19:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('3246346919375814796', 'seed_post_036_image_0', '8124788550923163179', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_036_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164927945.jpg', 'image/jpeg', 1, '3af10071c8c25985488e9d820b13de406032347277e2da7be3ca14eab593d573', 'BOUND', 'post', 'post_036');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('8626110909097799188', '3707714630686180608', '3246346919375814796', 'IMAGE', 0);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2712155883487091621', 'post_036:c047', '3707714630686180608', '9097300908732787732', 'seed_post_036:c047', '0b0d82e7c86b36a51ad0edfbf31bd68d71fe7c889a6cdc7fec69e4cd8b560995', '从沱茶侧面凹处往中心斜着下针，别直捅。蒸软会伤茶，用茶针慢慢剔就好。', '2026-09-10 04:19:00.000000', '2026-09-10 04:19:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2290394749654477281', 'post_036:c048', '3707714630686180608', '2516273971438976548', 'seed_post_036:c048', '86989cb45ab27dc1463d715362b15015a8fb85b1d5dfb68851be66592e5f3078', '压得紧的陈化慢，撬好后摊一天再泡，前两泡快出，第三泡才开始出味。', '2026-09-10 04:20:00.000000', '2026-09-10 04:20:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('342854029281717208', 'post_037', '8749336954246075687', 'seed_post_037', 'ba1a680a3a21f8131213c7c80f90d2dbd84bce2af1754c83f7e2a6f7b1e26633', '买了包正山小种，第一次泡有点意外——松烟香特别重，像冬天烧柴的味道，我以为是坏了。查了才知道桐木关那边传统做法会用松柴熏焙，现在也有不熏的“无烟种”，我这包应该是传统工艺。想问问大家：这种烟熏味是不是放一放会柔一些？另外烟种和无烟种在冲泡上要不要区别对待？我现在是5克、150毫升、95℃、5秒出汤。', 'question', '["正山小种","烟熏"]', '4996346501470601743', 'published', 57, 2, '2026-09-09 08:34:00.000000', '2026-09-09 08:34:00.000000', '2026-09-09 08:34:00.000000');
INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('1777191065203296466', 'seed_post_037_image_0', '8749336954246075687', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_037_image_0', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927125842596.jpg', 'image/jpeg', 1, '19bddf281bc71a2296c4eb717e412af67e6bed913da259bd64860dcaf2d0ab0c', 'BOUND', 'post', 'post_037');
