INSERT IGNORE INTO media_file (id, media_id, owner_user_id, purpose, media_type, storage_provider, object_key, external_url, mime_type, size_bytes, sha256, status, bound_type, bound_id) VALUES ('9152003825525388862', 'seed_post_037_image_1', '8749336954246075687', 'post', 'IMAGE', 'EXTERNAL', 'seed_post_037_image_1', 'https://zhangyue311-1434539871.cos.ap-beijing.myqcloud.com/picgo/20260927164926293.jpg', 'image/jpeg', 1, '0770187fef3c23eb687cd1965e674f8e54d1c657c28f3b913106cd167034661a', 'BOUND', 'post', 'post_037');
INSERT IGNORE INTO post_media (id, post_id, media_pk, media_role, sort_order) VALUES ('4776319946998327559', '342854029281717208', '9152003825525388862', 'IMAGE', 1);
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('1914089430836601317', 'post_037:c049', '342854029281717208', '9097300908732787732', 'seed_post_037:c049', 'a9b9ea4ce27dfb041a84a7f2ce98734b4ea1ffd0fc654169584219a85fae95d2', '熏焙的放半年烟味会柔下来，参数不用改。无烟种也是90℃上下、快出汤，香气偏花果，水温高了会闷。', '2026-09-09 08:34:00.000000', '2026-09-09 08:34:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('4552894308278578492', 'post_037:c050', '342854029281717208', '478822843046667138', 'seed_post_037:c050', '69b62444a810e04b3e71d96216f121c51ab9773f5ac4d9ab3c71f4647d821d32', '烟种我一般第一泡润洗一下就倒掉，第二泡开始烟味干净很多，你可以试试。', '2026-09-09 08:35:00.000000', '2026-09-09 08:35:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('2384619461903208226', 'post_038', '7812127570244669596', 'seed_post_038', '44c6df1319b2cb87186ec154b870cf823e5b6c9d571a6c6a0333d9da7e2bc0fd', '在茶城被推荐了一款云南月光白，老板说也算白茶。我不太确定：它用的是云南的大叶种，工艺上是萎凋加干燥，那到底该算白茶还是别的类别？我喝着是蜜香和花果香，汤感比福鼎白茶更饱满，也更甜。想请教一下：月光白和白毫银针、白牡丹在分类上是怎么区分的？冲泡参数要不要按白茶来，还是有别的讲究？', 'question', '["月光白","白茶分类"]', '6682326238763754120', 'published', 13, 2, '2026-09-09 01:48:00.000000', '2026-09-09 01:48:00.000000', '2026-09-09 01:48:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('9026818338975361283', 'post_038:c051', '2384619461903208226', '9023244926509495270', 'seed_post_038:c051', 'c89a6c84558e5a6e063c1cf0ea632107f1ecae73eb76dbf425bdfee3337d5a3d', '按工艺归到白茶是说得通的。冲泡可以按白茶来，但它是大叶种、条索粗，4克150毫升、90到95℃、20到30秒起，比银针耐泡。', '2026-09-09 01:48:00.000000', '2026-09-09 01:48:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2057603239187022778', 'post_038:c052', '2384619461903208226', '9097300908732787732', 'seed_post_038:c052', 'eebc8612fb846067f95878f278832ad818edae8a16dcc0518f2aee71795b37fb', '云南那边习惯叫它月光白，别跟福鼎的银针放一起比，风格本来就不同。', '2026-09-09 01:49:00.000000', '2026-09-09 01:49:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('896604630712953931', 'post_039', '7988564989891008107', 'seed_post_039', '954a0b193fc5dba6d63959032419fef698219d4513b1126965cfbc52a6ae36c8', '店里陆续收到几位客人寄放的生茶，存放条件差得挺远，所以想问个实在的问题：你们判断一饼生茶值不值得继续放，主要看什么？我现在看三点——闻干茶有没有杂味、汤色是否透亮、回甘能不能撑到第五泡。但我见过的样本还是少，尤其南北方仓的差别心里没底。各位存茶多年，有没有更直接的经验可以分享？', 'question', '["普洱生茶","存放"]', '7923980066954946164', 'published', 43, 2, '2026-09-08 12:11:00.000000', '2026-09-08 12:11:00.000000', '2026-09-08 12:11:00.000000');
