INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2888780495456121185', 'post_039:c053', '896604630712953931', '172930623173972133', 'seed_post_039:c053', '38cd852d150a583bd0ae3b23279d310048d396fda7d92c2c429a6c086270d8e1', '我加一条：看叶底。泡开后叶片有没有弹性，比香气更能说明原料底子，硬邦邦的一般不值得久放。', '2026-09-08 12:11:00.000000', '2026-09-08 12:11:00.000000');
INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('2399843195494838531', 'post_039:c054', '896604630712953931', '2516273971438976548', 'seed_post_039:c054', '90518d20a317df23b56aa78a65970b0d79e4efb703a3aea80db409ed3c0e0174', '同样一批茶，北方仓香气清楚但转化慢，南方仓转得快但要盯紧湿度，看你想要哪种风格。', '2026-09-08 12:12:00.000000', '2026-09-08 12:12:00.000000');
INSERT IGNORE INTO post (id, business_key, author_id, client_request_id, request_hash, content, topic, tags, related_tea_id, status, like_count, comment_count, published_at, created_at, updated_at) VALUES ('5427936861845629524', 'post_040', '8599731799452723918', 'seed_post_040', '854f6dce4cb78a53ebd8117fe0079f47a2106253ae54cbd0811f51ac9a577f21', '被茶友安利了永春佛手，说是有雪梨香，我直接拿来冷泡。7克茶、700毫升凉白开，冷藏8小时，倒出来第一口就懂了——清甜的雪梨味，几乎没有苦涩，比热泡更明显。热泡我也试过，100℃水、10秒出汤，香气更丰富，能喝到一点佛手柑的意味，但冷泡的甜更干净。夏天我的结论是：香气细的茶冷泡更讨喜，浓强的茶还是热泡。', 'daily', '["永春佛手","冷泡"]', '2143286490671301799', 'published', 22, 1, '2026-09-07 23:26:00.000000', '2026-09-07 23:26:00.000000', '2026-09-07 23:26:00.000000');
