INSERT IGNORE INTO post_comment (id, business_key, post_id, author_id, client_request_id, request_hash, content, created_at, updated_at) VALUES ('7400212673036778514', 'post_040:c055', '5427936861845629524', '2518829047458234563', 'seed_post_040:c055', 'a2034d8e29c59a9987076dbc3323bd526a90f85f8323bed311b04c5c738eb7d1', '佛手冷泡确实甜，不过8小时有点久，6小时香气更清，你可以试试。', '2026-09-07 23:26:00.000000', '2026-09-07 23:26:00.000000');
