UPDATE quiz_definition SET questions = '[{"key":"taste","title":"你更想在茶汤里遇见什么？","note":"先从第一印象开始，不必懂专业术语。","options":[{"value":"fresh","label":"清鲜","detail":"像春风拂过嫩叶"},{"value":"sweet","label":"甜润","detail":"入口柔和，回味有甜"},{"value":"soft","label":"柔和","detail":"轻松舒展，不急不躁"},{"value":"rich","label":"醇厚","detail":"层次深，茶汤有骨架"}]},{"key":"aroma","title":"哪种香气最容易让你停下脚步？","note":"凭直觉选，不用管它属于哪一类茶。","options":[{"value":"floral","label":"清香与花香","detail":"兰花香、栀子、桂花"},{"value":"fruity","label":"果香与蜜香","detail":"桂圆、荔枝、蜜甜"},{"value":"roasted","label":"焙火与焦糖","detail":"炭焙、炒米、焦糖"},{"value":"aged","label":"陈香与木香","detail":"老木、干药香、陈韵"}]},{"key":"texture","title":"你更在意茶汤的哪种口感？","note":"同样是茶，入口的质地可以差很远。","options":[{"value":"crisp","label":"清爽利落","detail":"入口干净，收得快"},{"value":"smooth","label":"顺滑柔和","detail":"像丝绸一样滑过去"},{"value":"thick","label":"稠厚有骨架","detail":"舌头能感到重量"},{"value":"brisk","label":"微涩而后回甘","detail":"先紧一下，再转甜"}]},{"key":"strength","title":"你喜欢怎样的滋味浓度？","note":"没有标准答案，按当下的偏好选。","options":[{"value":"light","label":"淡一些","detail":"清透、轻盈、留香"},{"value":"medium","label":"刚刚好","detail":"有滋味但不压口"},{"value":"rich","label":"浓一些","detail":"喜欢饱满和回甘"}]},{"key":"aftertaste","title":"你更喜欢哪一种余韵？","note":"咽下去之后留在嘴里的那部分。","options":[{"value":"clean","label":"干净利落","detail":"喝完口腔清清爽爽"},{"value":"sweet","label":"清甜回甘","detail":"甜味慢慢返上来"},{"value":"deep","label":"喉韵绵长","detail":"咽下之后还有东西留着"},{"value":"warm","label":"醇厚留香","detail":"香气在口腔里停很久"}]},{"key":"temp","title":"你更常怎么喝？","note":"同一款茶，温度不同像两种味道。","options":[{"value":"hot","label":"趁热喝","detail":"冒着热气的时候最好"},{"value":"warm","label":"温热就好","detail":"不烫口就行"},{"value":"cooled","label":"放凉也喝","detail":"凉了照样喝得下"},{"value":"cold","label":"冷泡","detail":"冰过的更舒服"}]},{"key":"time","title":"你通常什么时候喝茶？","note":"选择最接近你的日常节奏。","options":[{"value":"morning","label":"清晨与上午","detail":"让一天有清爽的起笔"},{"value":"afternoon","label":"午后时光","detail":"在工作与生活间留白"},{"value":"evening","label":"傍晚与夜间","detail":"把节奏放慢一些"}]},{"key":"scene","title":"这盏茶最想陪你做什么？","note":"想想你最常出现的那个喝茶场景。","options":[{"value":"work","label":"工作间隙","detail":"快而不乱，随手也能泡"},{"value":"ritual","label":"专注品饮","detail":"享受完整的冲泡过程"},{"value":"meal","label":"餐后慢饮","detail":"与一顿饭好好收尾"},{"value":"share","label":"待客分享","detail":"几个人分着喝"}]},{"key":"vessel","title":"你手边最常用的是哪一件？","note":"按你实际会用的选，不是最贵的那件。","options":[{"value":"glass","label":"玻璃杯","detail":"看得见叶形和汤色"},{"value":"gaiwan","label":"白瓷盖碗","detail":"什么茶都能应付"},{"value":"zisha","label":"紫砂壶","detail":"聚香保温"},{"value":"tumbler","label":"飘逸杯或马克杯","detail":"方便为主"}]},{"key":"effort","title":"你愿意为一泡茶花多少时间？","note":"诚实一点，这会影响推荐的上手难度。","options":[{"value":"quick","label":"一两分钟","detail":"越快越好"},{"value":"normal","label":"三五分钟","detail":"按部就班就好"},{"value":"slow","label":"慢慢来","detail":"愿意为它等"}]},{"key":"season","title":"想循着哪个季节的味道喝茶？","note":"不一定是现在，也可以是你偏爱的那个季节。","options":[{"value":"spring","label":"春天","detail":"尝一口新发的鲜"},{"value":"summer","label":"夏天","detail":"要清爽不压口的"},{"value":"autumn","label":"秋天","detail":"香气层次最经得起细闻"},{"value":"winter","label":"冬天","detail":"要一杯温厚的"}]},{"key":"pairing","title":"喝茶的时候你通常会？","note":"搭配会改变你对一款茶的印象。","options":[{"value":"nothing","label":"什么都不配","detail":"专心喝茶"},{"value":"snack","label":"配点清淡茶点","detail":"绿豆糕、坚果、时令水果"},{"value":"heavy","label":"配饭或重味的菜","detail":"需要一杯茶来换个口"}]},{"key":"explore","title":"你更愿意从哪一类开始？","note":"没有高下之分，只是路径不同。","options":[{"value":"classic","label":"公认的经典款","detail":"龙井、铁观音、祁红这样的名字"},{"value":"niche","label":"相对小众的一路","detail":"黄茶、老白茶、六堡这样的角落"}]},{"key":"experience","title":"你的冲泡经验更接近哪一项？","note":"我们会据此调整推荐的上手难度。","options":[{"value":"new","label":"刚开始喝","detail":"希望步骤简单、容易成功"},{"value":"familiar","label":"已经熟悉","detail":"愿意尝试更多器具与手法"}]},{"key":"focus","title":"你最想先从哪一面认识茶？","note":"最后一题。选一个你现在最好奇的。","options":[{"value":"bud","label":"鲜嫩的芽头","detail":"满披白毫的那一种"},{"value":"leaf","label":"舒展的叶片","detail":"冲泡时会慢慢打开"},{"value":"cake","label":"紧压的茶饼","detail":"撬茶本身就是一道仪式"},{"value":"fire","label":"焙火的功夫","detail":"火候如何改变一款茶"}]}]' WHERE quiz_version = 'v1';
